WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[10912] = { title = "The Hound-Master", description = "Baelmon the Hound-Master must die!  He maintains the ritual that keeps the portal functioning.\n\nThe Death's Door portal is located at the north end of the canyon.  When you find it, you will find Baelmon.\n\nYou're going to need help on this one, so take this wand.  When you battle the Hound-Master, use it and a couple of my friends will come to your aid.\n\nAfter you have defeated Baelmon, return to Wildlord Antelarion.\n\nAnd, {name}, thank you for all that you've gone through for us here.", objectives = "Slay Baelmon the Hound-Master.", progress = "It is over then?  Has the danger at Death's Door been averted?", completion = "You are truly an amazing <race>!  If I thought that we were indebted to you before, then now there is simply no way in which we could ever repay you.\n\nBut we'll give it a try.  Thank you, hero of Evergrove!" }
WordHunterWoW_QuestEN[10913] = { title = "An Improper Burial", description = "Is there nothing that can be done to stem the tide of corruption? My soldiers have been battling the Auchenai for days now with no end in sight. Each casualty, whether Auchenai or Sha'tar, is snatched from the battlefield - their souls lifted and taken to parts unknown.\n\nI will not have it! A proper burial is out of the question but those fiends will not have their souls! Take this torch and travel to the field of battle, directly east of here. Burn every corpse you see! We will not fuel their rituals.", objectives = "Commander Ra'vaj at the Sha'tari Base Camp in the Bone Wastes of Terokkar Forest wants you to burn 8 Slain Auchenai Warriors and 8 Slain Sha'tar Vindicators.", progress = "It's a terrible thing to ask, I know...", completion = "<Commander Ra'vaj holds his head in his hands.>\n\nIt's not enough... It's just not enough." }
WordHunterWoW_QuestEN[10914] = { title = "A Hero Is Needed", description = "It is not enough. A hero is needed. Our forces are overwhelmed as the Auchenai continue to grow in number.\n\n<Commander Ra'vaj looks at you.>\n\nWill you be the hero? Return to the field of battle and strike at their soldiers. Keep them occupied so that my scouts can get behind their lines and see what they are creating.", objectives = "Commander Ra'vaj at the Sha'tari Base Camp in the Bone Wastes of Terokkar Forest wants you to slay 12 Auchenai Initiates and 5 Auchenai Doomsayers.", completion = "You've done it, <name>! Because of you, we have made a new discovery..." }
WordHunterWoW_QuestEN[10915] = { title = "The Fallen Exarch", description = "They are feeding the souls they steal to a coffin that they have dragged out from the Auchenai Crypts. My scouts believe the contents of the coffin to contain the first exarch of the crypts. They seek to resurrect the ancient one!\n\nYou must battle your way to the western side of Auchindoun and disturb the contents of that coffin before they feed it enough souls. Should you lose your way, follow the walking souls.\n\nDestroy whatever is inside that coffin!", objectives = "Commander Ra'vaj at the Sha'tari Base Camp in the Bone Wastes of Terokkar Forest wants you to destroy the contents of the Auchenai Coffin.", completion = "Victory is ours! This defeat will set the Auchenai back several weeks." }
WordHunterWoW_QuestEN[10916] = { title = "Digging for Prayer Beads", description = "Anchorite Barada plans to exorcise the corruption from Colonel Jules, and will require an assistant for the task.  Such an assistant must be prepared...\n\nI am ashamed to admit that my prayer beads were lost in Honor Hold's courtyard.  I believe the dog Fei Fei stole them and buried them, but I do not know where.  If you speak with his master, Warrant Officer Tracy Proudwell, perhaps she will know where Fei Fei hides his stolen treasures.", objectives = "Recover the Draenei Prayer Beads and bring them to Assistant Klatu in Honor Hold.", progress = "Have you found the prayer beads, <name>?  Their powers are crucial to many holy rites... including the rite of exorcism.", completion = "You found the prayer beads!  Well done, <name>.  You are a wonder, indeed -- you slay the horrors of Hellfire Peninsula one moment and find lost treasures the next.  Your people truly inspire!\n\nIt is good that you recovered these beads... for they will be invaluable in the exorcism ritual to come." }
WordHunterWoW_QuestEN[10917] = { title = "The Outcast's Plight", description = "As an outcast, I am marked for death by arakkoa loyal to the city of Skettis.  I cannot leave these walls for fear of my life, but that doesn't mean I cannot strike at them in retaliation.\n\nI have a small cache of treasure that I'm willing to part with, should you help me strike back at my would-be assassins.  Bring me feathers from the denizens of the various Veils of Terokkar as proof of their demise.", objectives = "Bring 30 Arakkoa Feathers to Vekax in Shattrath's Lower City.", progress = "Do you bring the feathers I asked for, <name>?", completion = "<Vekax squawks in glee as you present him with proof of his enemies' demise.>\n\nYes, that will show Skettis that we Outcasts will not take their punishment lying down.  Here is the reward I promised you.  I can arrange for more, should you provide me with additional feathers." }
WordHunterWoW_QuestEN[10918] = { title = "More Feathers", description = "", objectives = "Skettis's lapdogs still keeps a close watch over us, outcasts.  The moment any of us sets foot outside Shattrath we'll be as good as dead.\n\nBring me more feathers as proof of your victory over them.", progress = "Skettis's lapdogs still keeps a close watch over us, outcasts.  The moment any of us sets foot outside Shattrath we'll be as good as dead.\n\nBring me more feathers as proof of your victory over them.", completion = "<Vekax squawks in glee as you present him with proof of his enemies' demise.>\n\nYes, that will show Skettis that we Outcasts will not take their punishment lying down.  Here is the reward I promised you.  I can arrange for more, should you provide me with additional feathers.\n\n<This quest can be repeated up to Honored reputation.>" }
WordHunterWoW_QuestEN[10919] = { title = "Fei Fei's Treat", description = "", objectives = "Fei Fei looks at you expectantly...", progress = "Fei Fei looks at you expectantly...", completion = "<Fei Fei barks happily and grabs the doggy treat.  He looks left and right... deciding where he should hide this new treasure...>" }
WordHunterWoW_QuestEN[10920] = { title = "For the Fallen", description = "When the dreadfang widows attacked our outpost we heard the voice of the naaru calling us to battle.  We pursued the creatures into the night.  Some of our people we found dead in the dark, others we could hear struggling against their captors. \n\nBy morning we had come to this place and we fought a fierce battle but we were beaten.  Dreadfang poison will soon take my companions and I cannot last long.  Before I die I must know that the dreadfang widows were beaten.", objectives = "Vindicator Haylen wants you to slay 20 Dreadfang Widows and then return to him just west of Netherweb Ridge.", progress = "I can feel the poison flowing through my veins.  The naaru call to me, I can see the light.  Are the dreadfang widows defeated?", completion = "I heard the sounds of your battle from here, <class>.  The sounds of your victory filled my heart with hope.  If you can win against such terrible odds, perhaps I can find the strength to drag my companions from this terrible place." }
WordHunterWoW_QuestEN[10921] = { title = "Terokkarantula", description = "You have slain many of the dreadfang widows but they will continue to spawn and soon they will strike at us again.  Deep within Netherweb Ridge is the lair of the Terokkarantula, the brood-mother of these gruesome creatures.  If we are to be safe, she must die.  ", objectives = "Vindicator Haylen wants you to kill the Terokkarantula and then return to him west of Netherweb Ridge.", progress = "Has Terokkarantula been slain?", completion = "The dreadfangs are beaten.  You have killed many and even their foul mother has fallen before you.  I am too poisoned to fight my way to freedom.  \n\nPlease, take some of my equipment.  It will lighten my load and give you the tools you need to make the journey back to Sha'tar Outpost." }
WordHunterWoW_QuestEN[10922] = { title = "Digging Through Bones", description = "Oy! You look like you can take care of yerself, {race}. Me and the crew here are looking for a bodyguard to watch over us while we hit a dig site to the north. The pay is pretty good and all you gotta do is make sure no nasty creatures kill me or any of my employees.\n\nIf you successfully make it back without any casualties, Dwarfowitz over there will pay ya.", objectives = "Escort Letoll and his crew and protect them while they make their dig. Return to Dwarfowitz at the Sha'tari Base Camp if you succeed.", completion = "A bone wurm! Fantastic! This may actually be the first time in recorded history that Letoll has actually made a discovery." }
WordHunterWoW_QuestEN[10923] = { title = "Evil Draws Near", description = "Now you must use the Dread Relic in a foul necromantic ritual if you wish to challenge Teribus the Cursed.  To the northeast, beyond Auchindoun, is the Writhing Mound, a place where necromancers gather.  \n\nThe auchenai death-speakers and doomsayers carry doom skulls that are laced with powerful necro-enchantments.  If you collect enough skulls you can use their power along with the power of the Dread Relic to command Teribus to face you.", objectives = "Oakun wants you to take the Dread Relic to the Writhing Mound. Once there, kill Auchenai Death-Speakers and Auchenai Doomsayers to collect 20 Doom Skulls. Then find the Writhing Mound Summoning Circle and use the Dread Relic to summon and destroy Teribus the Cursed. Return to Oakun when the deed is done.", progress = "Has Teribus the Cursed been purged from the skies of Terokkar?", completion = "A great evil has been cleansed from Terokkar.  The Sha'tar are in your debt." }
WordHunterWoW_QuestEN[10924] = { title = "Bloody Imp-ossible!", description = "The blood of the warp chasers in this area is a powerful and rare reagent. It's one of my biggest sellers.\n\nNormally, I take my imp, Zeppit, out to help me gather it. Warp chaser blood is simply too caustic to be handled safely by you or I, but it doesn't bother Zeppit.\n\nThings are getting busier here at the shop, so if I send Zeppit with you, will you help gather the blood? Zeppit's attention tends to wander, so you'll need to be close to the chaser when it dies for Zeppit to do his work.", objectives = "Bring 8 vials of Warp Chaser Blood to Sab'aoth at Cosmowrench.", progress = "Did Zeppit cooperate enough for you to get all the blood I'll need?", completion = "This should prove a large enough supply for my needs.\n\nI hope the imp didn't give you too much trouble. He has a bit of a nasty mouth on him." }
WordHunterWoW_QuestEN[10925] = { title = "Evil Draws Near", description = "", objectives = "" }
WordHunterWoW_QuestEN[10926] = { title = "Return to Sha'tari Base Camp", description = "We will not make it back on our own.  The dreadfang poison is too strong. You must return to Sha'tari Base Camp for us.  Scout Navrin will send a rescue party out to find us.", objectives = "Vindicator Haylen wants you to return to the Sha'tari Base Camp in the Bone Wastes and speak with Scout Navrin.", completion = "It is good to know that some of our warriors fought well against the dreadfang widows.  We will send a rescue party immediately." }
WordHunterWoW_QuestEN[10927] = { title = "Killing the Crawlers", description = "Commander Skyshadow wants this tunnel cleared out so we can expedite trade with the Harborage. I must not leave my post here so I am leaving the task in your hands. Clear the tunnel and report to Commander Skyshadow at once!\n", objectives = "Slay 6 Cavern Crawlers.", completion = "Good work, <class>. That tunnel is our lifeline to the swamp." }
WordHunterWoW_QuestEN[10928] = { title = "Killing the Crawlers", description = "Tor'chunk Twoclaws wants this tunnel cleared out so we can expedite trade with Swamp Rat. I must not leave my post here so I am leaving the task in your hands. Clear the tunnel and report to Tor'chunk Twoclaws at once!\n", objectives = "Slay 6 Cavern Crawlers.", completion = "Good work, <class>. That tunnel is our lifeline to the swamp." }
WordHunterWoW_QuestEN[10929] = { title = "Fumping", description = "How would you like to do a little more work for the Explorers' League? These bone worms have us all quite intrigued.\n\nI've got a drum right here that you can use out in the Bone Wastes. Just bang on the damned thing and see what you get. If it's a worm, kill it and bring back the carcass for us to study. We'll need a good lot of carcasses to get a valid testing sample.", objectives = "Dwarfowitz at the Sha'tari Base Camp in the Bone Wastes wants you to bring him 8 Mature Bone Sifter Carcasses.", progress = "We think the one that popped up at the dig was actually a baby worm!", completion = "Sand gnomes? Yea, sure... The desert can do strange things to a person.\n\nI think we're about to make a breakthrough here with these worms!" }
WordHunterWoW_QuestEN[10930] = { title = "The Big Bone Worm", description = "I was right! These carcasses you brought me belong to maturing worms. Do you know what that means? It means that somewhere out there is a big one! I think we can get it to come out if we can provide the right kind of food. Let's see... something big! Yes!\n\nI remember seeing clefthooves east of here on the other side of the Bone Wastes. Get out there and kill a clefthoof. Once it's dead, use the drums. Hopefully the big one will come up to feed. If you manage to kill it, bring me its organs!", objectives = "Dwarfowitz at the Sha'tari Base Camp in the Bone Wastes wants you to recover Enormous Bone Worm Organs.\n\nHe wants his Fumper back too.", progress = "Take a friend with you!", completion = "Amazing! Look at this stuff! The thing-a-ma-whatever has some sort of dust inside its whatcha-ma-bobber. Bah! I won't bore you with all this scientific jargon. I did manage to pull a few teeth from the little ones to make these incredibly sharp knives. Want one?" }
WordHunterWoW_QuestEN[10931] = { title = "Return to the Exodar", description = "Your master Caedmos of the Exodar has requested to see you.  It concerns your training, but I don't really know anything beyond that.Upon completion of this quest you will gain:", objectives = "Speak with Caedmos at the Exodar.Your master Caedmos of the Exodar has requested to see you. It concerns your training, but I don't really know anything beyond that.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[10932] = { title = "Return to the Exodar", description = "Your master Caedmos of the Exodar has requested to see you.  It concerns your training, but I don't really know anything beyond that.Upon completion of this quest you will gain:", objectives = "Speak with Caedmos at the Exodar.Your master Caedmos of the Exodar has requested to see you. It concerns your training, but I don't really know anything beyond that.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[10933] = { title = "Return to Silvermoon", description = "Your master Aldrae in Silvermoon City has requested to see you.  It concerns your training, but I don't really know anything beyond that.Upon completion of this quest you will gain:", objectives = "Speak with Aldrae in Silvermoon City.Your master Aldrae in Silvermoon City has requested to see you. It concerns your training, but I don't really know anything beyond that.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[10934] = { title = "Return to Silvermoon", description = "Your master Aldrae in Silvermoon City has requested to see you.  It concerns your training, but I don't really know anything beyond that.Upon completion of this quest you will gain:", objectives = "Speak with Aldrae in Silvermoon City.Your master Aldrae in Silvermoon City has requested to see you. It concerns your training, but I don't really know anything beyond that.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[10935] = { title = "The Exorcism of Colonel Jules", description = "{name}, it is time to save Colonel Jules.  His condition has worsened and Barada fears that, if we do not cleanse him of his corruption,  he will be lost to us.\n\nTake the prayer beads you found and speak with Anchorite Barada to begin the ritual.  Let no disruptions stop the ritual... and if all goes well, Colonel Jules will be saved.  Speak with Jules when he is saved, then return to me.", objectives = "Speak with Anchorite Barada. Use the prayer beads to help with the ritual, and then speak with Colonel Jules when he is saved. Finally, return to Assistant Klatu.", progress = "Go to Anchorite Barada, <name>.  He must succeed with his ritual if the colonel is to be saved.", completion = "You have done it, <name>.  You have saved Colonel Jules' soul and cast the darkness within him back to where it came.  A great, noble deed this is!  A hero's day!" }
WordHunterWoW_QuestEN[10936] = { title = "Trollbane is Looking for You", description = "While we were busy, a messenger was waiting out in the hall.  I suppose he grew tired, or perhaps he simply ran away at the sight of Jules floating around the room.\n\nEither way, Force Commander Danath is looking for you.  I suggest that you seek an audience with him inside the barracks as quickly as possible!", objectives = "Assistant Klatu has informed you that Force Commander Danath Trollbane has been seeking you. Speak to him in the barracks at Honor Hold in Hellfire Peninsula.", completion = "It's about time!  I heard all about what you've been up to with that draenei priest. You totally freaked my messenger out!\n\nNow that you're done with that, I have a little mission planned for you to Hellfire Citadel." }
WordHunterWoW_QuestEN[10937] = { title = "Drill the Drillmaster", description = "I'm receiving reports that the Shattered Hand fel orcs, out in front of Hellfire Citadel, are organizing for what looks like an all-out assault.  No doubt, they're not happy about your successes against all of the clans.\n\nGet to the base of the citadel, where the Path of Glory ends.  You'll find the fel orcs busy with their preparations, but you're going to catch them with their pants down.\n\nEliminate the one that's in charge of that force.  Kill Drillmaster Zurok!", objectives = "Force Commander Danath Trollbane has ordered you to kill Drillmaster Zurok with all due haste. Return to the force commander at Honor Hold in the Hellfire Peninsula once the drillmaster is dead.", completion = "I wasn't going to believe it until I heard it from you, personally.  Already our scouts are trickling in with information that the Shattered Hand are in disarray without their precious drillmaster to tell them what to do.\n\nYou've traveled a long road, <name>.  I trust that you will accept this armor along with my thanks.  Wear it proudly, you've earned it!" }
WordHunterWoW_QuestEN[10938] = { title = "Darkmoon Blessings Deck", description = "Now that you have gathered all of the Blessings cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", objectives = "Return the Blessings Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a deck of Blessings!   Congratulations!", completion = "So you have put together a deck of Blessings.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation." }
WordHunterWoW_QuestEN[10939] = { title = "Darkmoon Storms Deck", description = "Now that you have gathered all of the Storms cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", objectives = "Return the Storms Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a deck of Storms!   Congratulations!", completion = "So you have put together a deck of Storms.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation." }
WordHunterWoW_QuestEN[10940] = { title = "Darkmoon Furies Deck", description = "Now that you have gathered all of the Furies cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", objectives = "Return the Furies Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a deck of Furies!   Congratulations!", completion = "So you have put together a deck of Furies.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation." }
WordHunterWoW_QuestEN[10941] = { title = "Darkmoon Lunacy Deck", description = "Now that you have gathered all of the Lunacy cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", objectives = "Return the Lunacy Deck to the Darkmoon Faire when it comes to town.", progress = "I see that you have managed to complete a deck of Lunacy!   Congratulations!", completion = "So you have put together a deck of Lunacy.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation." }
WordHunterWoW_QuestEN[10942] = { title = "Children's Week", description = "One special little girl is going to be very happy to have you as a friend, even if it is for a short while.\n\nTake this whistle.  With it, you will be able to call for the child that you have agreed to sponsor.  It will only last for a limited time - not much longer than Children's Week itself, in fact.\n\nPlease, {name}, call upon your orphan.  I know that she will be more than excited to meet you and have the opportunity to venture out of the city!", objectives = "Use the Blood Elf Orphan Whistle to call for the ward that you will be looking after during Children's Week.\n\nProvided item:", completion = "Hmph, you're my sponsor?  I'm Salandria!  I've been here ever since I was a little baby.  My parents were taken by the war, so I have to live here at the orphanage.\n\nIt's not that bad, but I always wanted to go places -- I haven't ever stepped foot outside of the city.  I've already made a list of all the cool places that I want to go, and the awesome things that I want to do.\n\nI'm ready to go when you are!" }
WordHunterWoW_QuestEN[10943] = { title = "Children's Week", description = "One special little girl is going to be very happy to have you as a friend, even if it is for a short while.\n\nTake this whistle.  With it, you will be able to call for the child that you have agreed to sponsor.  It will only last for a limited time - not much longer than Children's Week itself, in fact.\n\nPlease, {name}, call upon your orphan.  I know that she will be more than excited to meet you and have the opportunity to venture out of the city!", objectives = "Use the Draenei Orphan Whistle to call for the ward that you will be looking after during Children's Week.\n\nProvided item:", completion = "You must be the adventurer who's going to be my big brother for Children's Week!  I'm Dornaa, pleased to meet you.\n\n<She looks sad for a moment.>\n\nMother and father were killed in the war, and I've lived in the orphanage all my life.  It's nice, actually, but I've always wanted to go places and see things.\n\nI've already made a list of places we could visit, if that's okay?  I just know that we're going to have a great time together!\n\nI'm ready to go when you are!" }
WordHunterWoW_QuestEN[10944] = { title = "The Secret Compromised", description = "Thanks again, {name}.  I recognize your name.  Akama has entrusted you with his plans and so I will trust you as well.\n\nThe naga discovered I was working against Illidan and tried to get me to speak by torturing me.  I did not tell them a thing - Akama himself taught me to master pain through meditation.\n\nIllidan asked the naga to bring me to him.  He would have seen right through my flesh and into my soul's deepest secrets.\n\nAkama must be warned.  Our plans are in jeopardy!", objectives = "Travel to the Warden's Cage in Shadowmoon Valley and speak to Akama.", completion = "I thank you, <name>.  Olum is one of my dearest friends and most trusted followers.  His contributions have been of vital importance to our plans." }
WordHunterWoW_QuestEN[10945] = { title = "Hch'uu and the Mushroom People", description = "I had a friend named Hch'uu.  She told me that she ended up in the orphanage because she had to run away from an evil fungal giant and got lost.\n\nWe had great fun until her people came and took her away last year.  I think she said she was going to live at a place called Sporeggar.\n\nI'd like to go to see her and have a look at her mushroom village.  The orphan matron told me that it is on the west side of Zangarmarsh, between the Sporewind and Marshlight lakes.\n\nCan we go?  Can we go?  Please?!", objectives = "Take your orphan, Salandria, to Sporeggar in Zangarmarsh. Make sure to call for her if she is not present when you arrive. Then, speak with Hch'uu.", progress = "You're the adventurer that brought her here?", completion = "Thank you for this chance to once again see Salandria.  I have missed her so much this past year, but we are still good friends.\n\nWe agreed that when we grow up, we're both going to be brave adventurers, just like you!" }
WordHunterWoW_QuestEN[10946] = { title = "Ruse of the Ashtongue", description = "Olum's sacrifice was tremendous.  I would never have asked him to give up his life myself.  But it is done.\n\nIf we're to lure Illidan back into a false sense of security, we need to do his bidding - at least for now.\n\nI command a vast army of Ashtongue, but - aside from the Deathsworn - none can be trusted.\n\nYou are to perform the deed that Illidan demands.  Take this cowl; it is magical in nature.  You will appear to be one of my men to any who see you slaying Kael's phoenix, Al'ar.", objectives = "Travel into Tempest Keep and slay Al'ar while wearing the Ashtongue Cowl. Return to Akama in Shadowmoon Valley once you've completed this task.", progress = "Is the deed done, <name>?  Illidan is not a patient master!", completion = "You've done well, <name>.  This will bring us a step closer to shifting Illidan's focus away from us and from...\n\n\n\nMore work remains to be done, <name>." }
WordHunterWoW_QuestEN[10947] = { title = "An Artifact From the Past", description = "Illidan's attention is now on Kael'thas, thanks to you.  The time has come to make our move.\n\nI've had a vision of an artifact that will aid us in our final struggle - the phylactery of a lich known as Winterchill.  Unfortunately its power was lost forever after his defeat in the Battle of Mount Hyjal.\n\nThere might be a way to retrieve this artifact, however.  Legend speaks of a place in Azeroth guarded by bronze dragons...  a place where past and present meet.  It is there you will find what we seek.", objectives = "Go to the Caverns of Time in Tanaris and gain access to the Battle of Mount Hyjal. Once inside, defeat Rage Winterchill and bring the Time-Phased Phylactery to Akama in Shadowmoon Valley.", progress = "Have you retrieved the phylactery yet, <name>?", completion = "My vision... it all becomes clear now.  The powers this artifact has over a soul.... to contain it... to siphon it into itself... I will use those powers to reclaim what belongs to me!  The time has arrived for us to take the fight to Illidan!" }
WordHunterWoW_QuestEN[10948] = { title = "The Hostage Soul", description = "You might wonder why I go to such lengths to hide my intentions.  Why not throw my lot in openly with the naaru?\n\nMy very essence - my soul - is held prisoner inside the Black Temple.  Illidan could destroy me any moment... until now!  This phylactery will allow me to regain control of my soul.\n\nThe time has come, {name}.  I'll lead Maiev and my Deathsworn to Illidan's doorstep.\n\nSpeak to A'dal and and tell him of our plan.  If we strike together we'll break through Illidan's defenses.", objectives = "Travel to Shattrath City to tell A'dal about Akama's request.", completion = "<A'dal's light surrounds you as he welcomes you back.  You have a feeling he knows what you're about to ask of him.>" }
WordHunterWoW_QuestEN[10949] = { title = "Entry Into the Black Temple", description = "<A'dal shows you an image of a naaru outside of the Black Temple, fighting alongside draenei vindicators and blood elf magisters.  You immediately understand that this is the distraction Akama is waiting for.>", objectives = "Travel to the entrance to the Black Temple in Shadowmoon Valley and speak to Xi'ri.", completion = "<Xi'ri appears to acknowledge your presence.  He seems to be focused on the battle in the surrounding area.>" }
WordHunterWoW_QuestEN[10950] = { title = "Auchindoun and the Ring of Observance", description = "One of the priests that comes to visit told a story about a place nearby.  It's called Auchindoun, and it's supposed to be very important to the draenei.\n\nHe said it used to be the place where the bodies of the draenei were taken when they died.  But some time ago, something bad blew it up.\n\nI'd like to see its Ring of Observance.  The orphan matron told me that it is in the middle of the Bone Wastes, on the south side of the Terokkar Forest.\n\nPlease, Mr. {name}, can we go?", objectives = "Take your orphan, Dornaa, to the Meeting Stone at the Ring of Observance in the middle of Auchindoun. Auchindoun, in turn, is in the middle of Terokkar Forest's Bone Wastes. Make sure to call for her if she is not present when you arrive.", progress = "Are we there yet?  Just protect me from all the spooky ghosts, okay?", completion = "Oh, it's just wonderful!  I mean, it looks pretty old... and yeah, someone sure did blow it up.  But just look at it!\n\nOoh, and did you look up at the sky?\n\nNeato!" }
WordHunterWoW_QuestEN[10951] = { title = "A Trip to the Dark Portal", description = "How can we look at all of these interesting places and not see the Dark Portal?!\n\nThe grown-ups are always trying to tell us scary stories about it and how it's so dangerous, with lots of demons, and stuff.\n\n<Salandria rolls her eyes.>\n\nBut you're here, so it can't be too bad, right?\n\nI want to see for myself.  You remember where it is on the east edge of Hellfire Peninsula?", objectives = "Take your orphan, Salandria, up the steps of the Stair of Destiny to stand before the Dark Portal in Hellfire Peninsula. Make sure to call for her if she is not present when you arrive.", progress = "This is soooo exciting!", completion = "The stories don't even come close to how cool this place is.  It's amazing!\n\nIs it true that a powerful wizard named Medivh created it?\n\nI wonder what's on the other side?  You've been there, right?  Hmm, we should definitely go someplace on the other side of the Dark Portal!" }
WordHunterWoW_QuestEN[10952] = { title = "A Trip to the Dark Portal", description = "There's one place that if we don't go anywhere else, we have to go to: the Dark Portal!\n\nThe orphan matrons are always trying to scare us with stories about how dangerous it is, with lots of demons, and people like you coming through it.\n\n<Dornaa rolls her eyes.>\n\nBut you're here, and nice, so it can't be too bad, right?\n\nI want to see it for myself.  You remember where it is on the eastern edge of Hellfire Peninsula?", objectives = "Take your orphan, Dornaa, up the steps of the Stair of Destiny to stand before the Dark Portal in Hellfire Peninsula. Make sure to call for her if she is not present when you arrive.", progress = "What do you know about the Dark Portal?", completion = "The orphan matron's stories don't even come close to how cool this place is.  It's amazing!  She said that it was created by a powerful wizard named Medivh.\n\nWhat's on the other side of it?  You've been there, right?  We should most definitely go someplace on the other side of the Dark Portal!" }
WordHunterWoW_QuestEN[10953] = { title = "Visit the Throne of the Elements", description = "Have you heard of the Throne of the Elements?  It's supposed to be this place in Nagrand where there are these powerful elementals.\n\nOne day soon, I'm going to be a powerful mage, or maybe a warlock.  I'm gonna have to learn about some of the elemental forces!\n\nDo you think maybe that we could go there?\n\n<Salandria looks at you slyly.>\n\nYa know, it would be educational to go there.  It's supposedly just north of Garadar, on the other side of Skysong Lake.", objectives = "Take your orphan, Salandria, to the Throne of the Elements in Nagrand. Make sure to call for her if she is not present when you arrive. Then, speak with Elementalist Sharvak.", progress = "The Earthen Ring sees you, <class>.", completion = "You bring a child here?  Foolhardy, but I promise that she will come to no harm, at least as long as she doesn't get too close to Incineratus.\n\nHmm, unfortunate that she's a blood elf.  Were she capable of a deep connection to the world, we could teach her some things so that she might aid us to heal its wounds.  But, perhaps her exposure to the elements here will give her some insight into their workings.\n\nGo in peace and see to it that you take good care of her." }
WordHunterWoW_QuestEN[10954] = { title = "Jheel is at Aeris Landing!", description = "I miss my brother, Jheel.  He's a couple of years older than me, so they let him start an apprenticeship with the ethereal in Nagrand.\n\nIt sure would be nice to go visit him.  He loves geology and stuff, so I bet he's having a great time.\n\nThe orphan matron told me that he's training at a place called Aeris Landing in Nagrand.  It's supposed to be along the road, far to the west of Telaar, and northwest of the great mountain, Oshu'gun.", objectives = "Take your orphan, Dornaa, to Aeris Landing in Nagrand. Make sure to call for her if she is not present when you arrive. Then, speak with Jheel.", progress = "Did you bring her here?", completion = "Oh, I've missed Dornaa so much.  Thank you for bringing her to visit.  It gets lonely here with only the ethereal around.  And they're so serious all the time with this Oshu'gun business.\n\nBut I get to go back and visit the orphanage after I pass my gemcutting exams.  I almost passed them last week, but I'm sure that I'll do better on the test tomorrow!" }
WordHunterWoW_QuestEN[10955] = { title = "Morthis Whisperwing", description = "Before all of the druidic orders coalesced into the Cenarion Circle, the Druids of the Talon were responsible for teaching promising young druids the mysteries of flight. With the dissolution of the order, former members teach the skill sparingly.\n\nEven now, Morthis Whisperwing continues his search for a suitable apprentice. Few druids have truly mastered all the forms available to them, but you show the promise Morthis requires of his students. Seek him out at the Cenarion Refuge in Zangarmarsh.Upon completion of this quest you will gain:", objectives = "Seek out Morthis Whisperwing at the Cenarion Refuge in Zangarmarsh.Before all of the druidic orders coalesced into the Cenarion Circle, the Druids of the Talon were responsible for teaching promising young druids the mysteries of flight. With the dissolution of the order, former members teach the skill sparingly.\n\nEven now, Morthis Whisperwing continues his search for a suitable apprentice. Few druids have truly mastered all the forms available to them, but you show the promise Morthis requires of his students. Seek him out at the Cenarion Refuge in Zangarmarsh.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[10956] = { title = "The Seat of the Naaru", description = "Do you know anything about the naaru?  They're these angelic beings that have been helping the draenei for a really long time.  I've seen a bunch around Shattrath.\n\nThey say that one naaru, O'ros, was with the Exodar when it traveled to your homeworld.  I should like to see for myself.\n\nCan you take me there?  I bet we could get there fast by using one of the portals inside the Temple of the Moon in Darnassus!  When we get there, if you get lost, we could always just look at your map.", objectives = "Take your orphan, Dornaa, to stand before O'ros at the bottom of the Seat of the Naaru inside of the Exodar, which is on Azuremyst Isle. Make sure to call for her if she is not present when you arrive.\n\nRemember that you can use your map inside the city.", progress = "I have been expecting you.", completion = "<You feel, more than hear, the musical voice of O'ros chiming in your mind.>\n\nThank you for bringing this child to me, <name>.  She is very special indeed, and will grow up one day to be an important figure amongst the draenei.  This is in no small part due to the kindness that you have shown her, and the impression that you have made." }
WordHunterWoW_QuestEN[10957] = { title = "Redemption of the Ashtongue", description = "When Illidan obtained the Broken's allegiance, Akama was our wisest.  He knew that openly opposing the Betrayer would lead to the extinction of our race.\n\nInstead he has plotted and schemed for this very moment under utmost secrecy.  Failure would be catastrophic... not just for Akama, not just for the Broken, but for all of Outland.  No one this close to Illidan has ever been able to deliver such a terrible blow to him.\n\nHelp Akama free his soul and he will grant you access to Illidan's sanctum.", objectives = "Help Akama wrest control back of his soul by defeating the Shade of Akama inside the Black Temple. Return to Seer Kanai when you've completed this task.", progress = "Yes, <name>?", completion = "It is done, <name>.  The time to strike at Illidan has come." }
WordHunterWoW_QuestEN[10958] = { title = "Seek Out the Ashtongue", description = "<As you look up at Xi'ri, your mind becomes focused and your will determined.  Your work here is not done; you must go inside the Black Temple and find Akama's followers.>\n\n<Much depends on Akama's success.>", objectives = "Find Akama's Deathsworn inside the Black Temple.", completion = "We've been expecting you, <name>.  Akama is in great need of your help." }
WordHunterWoW_QuestEN[10959] = { title = "The Fall of the Betrayer", description = "With Illidan's lieutenants defeated, Akama will be able to force open the doors to Illidan's sanctum.  Be ready to bring your force inside as soon as Akama does.\n\nWe still do not know what has become of Maiev, but we must make our move without her.\n\nI hope your force is up to the task.  Illidan will not be pleased to see Akama.", objectives = "Seer Kanai wants you to defeat Illidan inside the Black Temple.", progress = "Yes, <name>?", completion = "It is as it was foretold, <name>.  One by one, Illidan's lieutenants have fallen... and now the Betrayer himself has met his demise!\n\nKnow this, <name>: every decision Akama made and every moment of his life since Illidan arrived, Akama planned for this moment.  Illidan is finally dead and our people... are free!" }
WordHunterWoW_QuestEN[10960] = { title = "When I Grow Up...", description = "When you were my age did you know that you wanted to be a {class} when you grew up?\n\nI'm not sure what I want to be.  Maybe a mage or a warlock, like I said before?  Or maybe a paladin Blood Knight?  Yeah, definitely a Blood Knight!\n\nThey say that the true ones are trained in Silvermoon City on your world.  Could you take me there?  The stories that I've heard say that the paladin trainers reside in the Farstriders' Square in that city.\n\nPlease take me there.  Please!", objectives = "Take your orphan, Salandria, to the paladin trainers in Silvermoon City's Farstriders' Square. Make sure to call for her if she is not present when you arrive. Then, speak with Lady Liadrin, the Blood Knight Matriarch.\n\nRemember that you can use your map inside the city, and speak to the guards to find the paladin trainers." }
WordHunterWoW_QuestEN[10961] = { title = "The Ward of Wakening", description = "Long ago, the relics used to teach the ways of the stormcrow were entrusted to an ancient druid.\n\nYour training requires these relics, so we must wake their guardian from his slumber.\n\nI will prepare a potion you can use to ease the process. The mixture requires common herbs, as well as bogblossom, which usually grows atop the tallest mushrooms in the marsh. Fly up there and pursue them but take care, as they're quite fragile and may explode violently if mishandled.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Bring 10 Bogblossoms, 10 Ancient Lichen, and 10 Dreaming Glory to Morthis Whisperwing at the Cenarion Refuge." }
WordHunterWoW_QuestEN[10962] = { title = "Time to Visit the Caverns", description = "In the orphanage, the old priest that comes by told us stories about the Caverns of Time.  He said that it sits in the middle of time, and is really important for keeping things straight.\n\nI don't know what that means, but he said that there were dragons there that were helping to save the world!  I want to see a dragon!\n\nDo you think that we could go there?  He said that the entrance was on the eastern edge of a great desert named Tanaris.\n\nMaybe you could buy me a souvenir while we're there?", objectives = "Take your orphan, Dornaa, to stand before Zaladormu, the dragon on the dais in the middle of the Caverns of Time. Make sure to call for her if she is not present when you arrive.\n\nThen, purchase a Toy Dragon for her from the Keepers of Time Quartermaster, Alurmi, near the bottom of the entrance tunnel.", progress = "You think it's true what they say about the Caverns of Time?", completion = "Neato!  A dragon of my very own!  One day I hope that I'm lucky enough to have a dragon as a friend.\n\n<Dornaa bounces up and down with joy, fiercely hugging her new toy.>\n\nThis has been the best trip ever!  I hope it never ends." }
WordHunterWoW_QuestEN[10963] = { title = "Time to Visit the Caverns", description = "In the orphanage, the old stinky priest that comes by told us stories about the Caverns of Time.  He said that it sits in the middle of time, and is really important for keeping things straight.\n\nI don't know what that means, but he said that there were dragons there that were helping to save the world!  I want to see a dragon!\n\nI think we should go there.  He said that the entrance was on the eastern edge of a great desert named Tanaris.\n\nYou could buy me a souvenir while we're there!", objectives = "Take your orphan, Salandria, to stand before Zaladormu, the dragon on the dais in the middle of the Caverns of Time. Make sure to call for her if she is not present when you arrive.\n\nThen, purchase a Toy Dragon for her from the Keepers of Time Quartermaster, Alurmi, near the bottom of the entrance tunnel.", progress = "If what they say about the Caverns of Time is true, then it must be a place of great power.", completion = "Awesome!  A dragon of my very own!  Someday I plan to own a real one.\n\n<Salandria slyly eyes her new toy, the gears within her mind turning.>\n\nThis has been the best trip ever!  I hope it never ends." }
WordHunterWoW_QuestEN[10964] = { title = "Waking the Sleeper", description = "Take the ward with you and travel to Moonglade, to the Stormrage Barrow Dens. Within the southernmost of the Stormrage Barrow Dens, watched over by the dreamwardens, you will find Clintar Dreamwalker.\n\nAdminister the potion and watch over him while he wakes. He'll be extremely vulnerable as his spirit reunites with his body and he certainly won't recognize you. Declare yourself to him as soon as he comes around, <name>. He will need your help to gather the relics for the ceremony.Upon completion of this quest you will gain:", objectives = "Use the Ward of Waking to help Clintar Dreamwalker emerge from the Emerald Dream. When he is conscious, speak to him." }
WordHunterWoW_QuestEN[10965] = { title = "No Mere Dream", description = "<Clintar listens as you relay Morthis' instructions, nodding, but clearly fearful.>\n\nI cannot extricate myself fully from the Emerald Dream to help you, but a fragment of my spirit will guide you in your search for the relics. Guard it well, <race>, for it is a fragile thing.\n\nThe Emerald Dream itself has become an alien, dangerous place. Its grasp on me is strong, and I will not be whole until the Emerald Dream returns to normalcy. What you see around you is but an echo of the reality inside the dream!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Protect Clintar Dreamwalker's Spirit while it gathers the relics of Aviana, then speak to Dreamwarden Lurosa." }
WordHunterWoW_QuestEN[10966] = { title = "Back to the Orphanage", description = "Darn it all!  I guess it's time to go back to the orphanage at Shattrath City.\n\nI've had such a great time.  You're the best person in all of the worlds, {name}!  You're my big brother now!\n\n<Dornaa's eyes begin to well up with tears.>\n\nI'm going to miss you so much!  When I grow up, I'm going to be just like you!!!", objectives = "Return your ward to the Shattrath City orphanage by handing in the Draenei Orphan Whistle to Orphan Matron Mercy in the Lower City.", completion = "It is good for the soul to know that there are heroes such as yourself that are willing to give of their time so selflessly.\n\nI can tell already that your time together with Dornaa has made a huge impression.  It's good for the children to have a chance to get out and see the world.\n\nHere, she told me that she wanted you to take care of one of her favorite pets, just like you took care of her.  Something to remember her by.\n\nDon't be a stranger." }
WordHunterWoW_QuestEN[10967] = { title = "Back to the Orphanage", description = "Darn it all!  I guess it's time to go back to the orphanage at Shattrath City.\n\nI've had such a great time.  You're the best person in all of the worlds, {name}!  You're my big brother now!\n\n<Salandria's eyes begin to well up with tears.>\n\nI'm going to miss you so much!!!", objectives = "Return your ward to the Shattrath City orphanage by handing in the Blood Elf Orphan Whistle to Orphan Matron Mercy in the Lower City.", completion = "It is good for the soul to know that there are heroes such as yourself that are willing to give of their time so selflessly.\n\nI can tell already that your time together with Salandria has made a huge impression.  It's good for the children to have a chance to get out and see the world.\n\nHere, she told me that she wanted you to take care of one of her favorite pets, just like you took care of her.  Something to remember her by.\n\nDon't be a stranger." }
WordHunterWoW_QuestEN[10968] = { title = "Call on the Farseer", description = "I am sensing something very special about this child indeed.\n\nYou should take her to visit Farseer Nobundo, here in the Exodar.  I believe that he has been expecting the two of you.\n\nLook for Nobundo upon the highest terrace in the Crystal Hall.", objectives = "Take your orphan, Dornaa, to visit Farseer Nobundo at the Crystal Hall inside of the Exodar, which is on Azuremyst Isle. Make sure to call for her if she is not present when you arrive.\n\nRemember that you can use your map inside the city.", progress = "Remarkable.", completion = "I had hoped, but despaired she was only a figment of my imagination.  The child is amazing!\n\nIt's unheard of in this day and age that one of the draenei should exhibit such ability with the elements without any training.  She must have inherited this power from an ancient ancestor.\n\nI will send a missive to the orphan matron in Shattrath City requesting that the child be allowed to come stay with us.\n\nPlease, keep her safe until then." }
WordHunterWoW_QuestEN[10969] = { title = "Seek Out Ameer", description = "It would seem that an outside force has taken an interest in the business practices of the Consortium. Five Consortium dealers have gone missing in the past two days. We have reason to believe the Ethereum are involved. If you are interested in assisting, seek out Commander Ameer at the Protectorate Watch Post.\n\nYou will find the Protectorate Watch Post directly east of here on the next island. \n", objectives = "Seek out Commander Ameer at the Protectorate Watch Post.", completion = "Aye, it is true, but the Consortium are not the only group claiming losses." }
WordHunterWoW_QuestEN[10970] = { title = "A Mission of Mercy", description = "We salvaged this prison orb on our last scouting mission into Ethereum territory. We'd have never found it had it not been for the distress signal that it was faintly emitting.\n\nWe think one of our own might be locked up in there but we have no way of opening the orb up without harming whatever is inside.\n\nWhat we know about the Ethereum is that any of their members could - at any given time - be carrying a key to unlock an orb. Retrieve one and return so that we may uncover the mysteries of this orb.", objectives = "Recover the Salvaged Ethereum Prison Key for Commander Ameer at the Protectorate Watch Post in Netherstorm.", progress = "Any luck?", completion = "Stand back, <name>. This could very well be an Ethereum trap." }
WordHunterWoW_QuestEN[10971] = { title = "Ethereum Secrets", description = "<Ameer holds up a tag.>\n\nI found this prisoner I.D. tag with the remains of the fallen vanguard. I can only assume that all of their prisoners are tagged in the same manner.\n\nI'm going to start cataloguing the tags in hopes of making sense of their penal system. If in your adventures you find more Ethereum prison keys, you can use them to open the Ethereum prisons at the Ethereum Staging Grounds - directly south of here. Bring me back any and all I.D. tags that you find.", objectives = "Commander Ameer at the Protectorate Watch Post in Netherstorm wants you to bring him an Ethereum Prisoner I.D. Tag.", progress = "Have you recovered any I.D tags?", completion = "It seems to be more than just an identifier. There is some sort of code written on these tags. I'm on the verge of breaking it wide open. Perhaps if I had a few more pieces." }
WordHunterWoW_QuestEN[10972] = { title = "Ethereum Prisoner I.D. Catalogue", description = "I am in need of more I.D tags, <name>. What I've discovered thus far is that this is not just a way to catalogue prisoners but it also documents locations!\n\nOnce this code is broken we'll be able to pinpoint exactly where all of our allies are held and free them with minimal hostile action received.", objectives = "I am in need of more I.D. tags, <name>. What I've discovered thus far is that this is not just a way to catalogue prisoners but it also documents locations!\n\nOnce this code is broken we'll be able to pinpoint exactly where all of our allies are held and free them with minimal hostile action received.", progress = "I am in need of more I.D. tags, <name>. What I've discovered thus far is that this is not just a way to catalogue prisoners but it also documents locations!\n\nOnce this code is broken we'll be able to pinpoint exactly where all of our allies are held and free them with minimal hostile action received.", completion = "We are close to the truth, <name>." }
WordHunterWoW_QuestEN[10973] = { title = "A Thousand Worlds", description = "I have cracked the code! Each tag is broken up into several segments. The front side of the tag is always the same and states: \"A Thousand Worlds...\" I am unsure as to the meaning of this phrase but it sounds insidious.\n\nOn the back side of the tag are the vital statistics. The first set of runes indicates location and the second indicates prisoner type. Furthermore, it would seem that the keys can be combined to form a special key that accesses another prison type. Now I just need more keys...", objectives = "Commander Ameer at the Protectorate Watch Post in Netherstorm wants you to bring him 5 Ethereum Prison Keys.", progress = "I know it's asking a lot but think of the lives that could be saved!", completion = "<Ameer deftly combines the keys and begins to read the markings on the newly formed key tablet.>\n\n\"A thousand worlds shattered, a thousand worlds more to overcome... Such is the will of the Nexus-King.\"\n\n<Ameer turns the tablet over and begins to read from the back-side.>\n\nStasis chambers of Bash'ir?" }
WordHunterWoW_QuestEN[10974] = { title = "Stasis Chambers of Bash'ir", description = "The Ethereum have a settlement on the northernmost shelf of Blade's Edge Mountains known as Bash'ir's Landing. According to the key tablet, much larger versions of the prisons are kept at Bash'ir's. It should also be noted that the Ethereum refer to those prisons as stasis chambers.\n\nThe key tablet grants access to a very specific stasis chamber at the landing known as Stasis Chamber Alpha. Take the key and investigate.\n\nMy image will be awaiting your return at Bash'ir's Landing. Speak to me there.", objectives = "Use the Ethereum Key Tablet - Alpha to open Stasis Chamber Alpha at Bash'ir's Landing in Blade's Edge Mountains.\n\nReturn Evidence from Alpha to the Image of Commander Ameer at Bash'ir's Landing.", progress = "You made it! Any luck?", completion = "<The image of Commander Ameer rummages through the evidence.>\n\nIt is worse than I thought... These chambers hold ferocious beasts and creatures from many, many different worlds. They hope to one day command the beasts to do their bidding. We must destroy them all!" }
WordHunterWoW_QuestEN[10975] = { title = "Purging the Chambers of Bash'ir", description = "", objectives = "We're at an impasse here, <name>. The data you've collected has given us enough information to save our allies being held at the smaller prisons of Netherstorm but we must press forward and eradicate the larger Ethereum threats here at Bash'ir's Landing.\n\nJoin the battle against the Ethereum! Bring Ethereum prison keys to me and I shall forge Ethereum stasis chamber keys for you to use on the stasis chambers of Bash'ir.", progress = "We're at an impasse here, <name>. The data you've collected has given us enough information to save our allies being held at the smaller prisons of Netherstorm but we must press forward and eradicate the larger Ethereum threats here at Bash'ir's Landing.\n\nJoin the battle against the Ethereum! Bring Ethereum prison keys to me and I shall forge Ethereum stasis chamber keys for you to use on the stasis chambers of Bash'ir.", completion = "There is always more work that must be done, <name>. Now seek out a stasis chamber and destroy whatever evil lurks within!" }
WordHunterWoW_QuestEN[10976] = { title = "The Mark of the Nexus-King", description = "What I must now know is what the Ethereum have held inside the Mana-Tombs of Auchindoun.\n\nIn your battles against the beasts of the stasis chambers of Bash'ir you may run across an item known as the Mark of the Nexus-King. Should you find such an item, return it to me immediately! It is the final piece in crafting a key that will allow access to the stasis chamber inside the Mana-Tombs.", objectives = "The Image of Commander Ameer at Bash'ir's Landing in the Blade's Edge Mountains wants you to bring him a Mark of the Nexus-King.", progress = "This will be your most daunting task, <name>.", completion = "At last!\n\n<Commander Ameer reads from the Mark of the Nexus-King.>\n\nTwo final prisons? I shudder to think what horrors lie in wait..." }
WordHunterWoW_QuestEN[10977] = { title = "Stasis Chambers of the Mana-Tombs", description = "The Mark of the Nexus-King that you recovered has allowed me to forge a new key for the stasis chambers found inside the Mana-Tombs.\n\nAccording to the glyphs on the mark, two exist: one near the front and one near Nexus-Prince Shaffar. This key that I am about to give you will open the stasis chamber near the front.\n\nI want you to go to the Mana-Tombs of Auchindoun and open the Mana-Tombs Stasis Chamber.", objectives = "The Image of Commander Ameer at Bash'ir's Landing in the Blade's Edge Mountains wants you to use the Mana-Tombs Stasis Chamber Key on the Stasis Chamber inside the Mana-Tombs of Auchindoun.\n\nThis quest may only be completed on Heroic difficulty.", progress = "I would understand if you chose not to continue, <name>.", completion = "Word has gotten back of your heroics, <name>. Haramad and I both agree that what you've done deserves a great reward.\n\nThough... Nevermind, you've done enough. I cannot in good conscience ask anything more from you." }
WordHunterWoW_QuestEN[10978] = { title = "Return to Morthis Whisperwing", description = "Now that the relics have been recovered, you must leave this place with all haste. Clintar risked his safety and that of the dreamwardens to help you, <name>, but now he must fully devote his attention to fighting the force that has invaded the Emerald Dream.\n\nTake the relics back to Morthis Whisperwing, along with word of what you've seen here. He may be able to help us identify just what Clintar is struggling against.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Bring the Relics of Aviana to Morthis Whisperwing at Cenarion Refuge in Zangarmarsh." }
WordHunterWoW_QuestEN[10979] = { title = "To the Evergrove", description = "Are you certain you saw a raven in the barrow den?\n\nThis is a troubling development. There's little we can do to help Clintar and the dreamwardens directly, but if we can learn more about what's threatening the Emerald Dream, we may be able to stop it.\n\nWe've been learning about the resurgence in an ancient arakkoa cult in Blade's Edge -- one that venerates a raven god. Go to the Evergrove and find Arthorn Windsong. There may be a connection between what's happening there and in the Emerald Dream!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak with Arthorn Windsong at the Evergrove in Blade's Edge Mountains.Are you certain you saw a raven in the barrow den?\n\nThis is a troubling development. There's little we can do to help Clintar and the dreamwardens directly, but if we can learn more about what's threatening the Emerald Dream, we may be able to stop it.\n\nWe've been learning about the resurgence in an ancient arakkoa cult in Blade's Edge -- one that venerates a raven god. Go to the Evergrove and find Arthorn Windsong. There may be a connection between what's happening there and in the Emerald Dream!You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[10980] = { title = "The Book of the Raven", description = "From what you've told me, Morthis's suspicions seem plausible, but we need confirmation.\n\nIn his research, Timeon has uncovered clues that a \"book of the raven\" served as an ancient scripture to the cult.\n\nThe arakkoa spirits will not reveal themselves to your eyes. Take this stone with you to the high peaks in the western part of Blade's Edge, to the south of Raven's Wood, obtain an aether ray eye, and combine them to augment your sight. Search for the ghost Timeon identified as Sai'kkal the Elder.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Use an Aether Ray Eye with your Seer's Stone to reveal the raven cult ghosts. Search the Vortex Pinnacle for the spirit of Sai'kkal the Elder and question him about the book of the raven, then return to Arthorn Windsong." }
WordHunterWoW_QuestEN[10981] = { title = "Nexus-Prince Shaffar's Personal Chamber", description = "", objectives = "Only the most steadfast and battle-hardened of adventurers will take me up on this offer, <name>. Should you wish to face the horrors of the second stasis chamber in the Mana-Tombs, I am able to synthesize a key. Bring me a mark of the Nexus-King and I will make it so.", progress = "Only the most steadfast and battle-hardened of adventurers will take me up on this offer, <name>. Should you wish to face the horrors of the second stasis chamber in the Mana-Tombs, I am able to synthesize a key. Bring me a mark of the Nexus-King and I will make it so.", completion = "As promised, here is the key to Shaffar's personal stasis chamber." }
WordHunterWoW_QuestEN[10982] = { title = "The Eye of Haramad", description = "", objectives = "You have done much for the Protectorate and the Consortium, <name>. It is only fitting, then, that the first of our new keys goes to you. With this key you will be able to open Shaffar's personal stasis chamber at any time without having expended the key itself.\n\n\n\nIt is permanent and will be with you forever." }
WordHunterWoW_QuestEN[10983] = { title = "Mog'dorg the Wizened", description = "Mog'dorg wise!  Him send Grok to city, look for help.  Bloodmaul clan need help.\n\nMog'dorg say, send powerful little ones to him at Blade's Edge Mountains.  Him stand on tower at Circle of Blood.  Mog'dorg wise!", objectives = "Visit Mog'dorg the Wizened atop one of the towers just outside the Circle of Blood in the Blade's Edge Mountains.", completion = "Grok said that I am wise?  I don't know about that.\n\nPerhaps it is because I am the only one in my clan that is truly trying to save us from annihilation by the Bladespire clan, and Gruul and his sons, who are backing them.\n\nI hope that you have come to deliver us from certain doom, <class>." }
WordHunterWoW_QuestEN[10984] = { title = "Speak with the Ogre", description = "<V'eru's voice fills your mind with crystalline tone and clarity.>\n\nThere is an ogre down in the Lower City, pleading for the assistance of passersby.  They have all turned a deaf ear upon his plight.\n\nDo you think you might aid him?\n\nHis name is Grok, and he is sitting near the merchants to the southeast.\n\nThank you, {name}.", objectives = "Speak with the Ogre, Grok, in the Lower City section of Shattrath City.", completion = "You help Grok?  Grok need help!  Bloodmaul clan need help!" }
WordHunterWoW_QuestEN[10985] = { title = "A Distraction for Akama", description = "<Xi'ri pulses with lights as the Aldor and Scryer forces around him respond to his orders.  Xi'ri's army is ready to push Illidan's forces back and create a distraction for Akama.  The naaru awaits your request to begin the attack.>", objectives = "Ensure that Akama and Maiev enter the Black Temple in Shadowmoon Valley after Xi'ri's forces create a distraction.", completion = "<Xi'ri pulses with energy as you feel an object materialize in your hands.  It is the medallion you gave to A'dal on Akama's behalf, its power augmented by the naaru's magic.  The Sha'tar have entrusted you with the Medallion of Karabor, and with it access to the Black Temple.>" }
WordHunterWoW_QuestEN[10986] = { title = "Eyes in the Sky", description = "Locating the pieces of the Book of the Raven, if they survive at all, is going to be difficult. Our best hope is to use a keener pair of eyes than your own.\n\nDown in western Nagrand, on the eastern lip of the Twilight Ridge, Watcher Elaira studies the various bird species that make their home there. Visit her and see if she can help you harness avian sight to gather the pieces of the Book of the Raven.Upon completion of this quest you will gain:", objectives = "Speak with Watcher Elaira at the Twilight Ridge in Nagrand.Locating the pieces of the Book of the Raven, if they survive at all, is going to be difficult. Our best hope is to use a keener pair of eyes than your own.\n\nDown in western Nagrand, on the eastern lip of the Twilight Ridge, Watcher Elaira studies the various bird species that make their home there. Visit her and see if she can help you harness avian sight to gather the pieces of the Book of the Raven.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[10987] = { title = "To Catch A Sparrowhawk", description = "The wild sparrowhawks of Nagrand have the keenest sight of all the predatory birds here. But, because of their size, they've been pushed out of most areas by the larger windrocs.\n\nMost of the sparrowhawks nest here, on the Twilight Ridge. If you can catch one, I'll train it to spot the pieces of your buried tablet.\n\nIt's going to be difficult, though. The sparrowhawks are very skittish and will flee at your approach. I'd suggest cornering one or prowling to get close enough to cast your net.Upon completion of this quest you will gain:", objectives = "Use the Sparrowhawk Net to capture a Wild Sparrowhawk and bring it to Watcher Elaira on the Twilight Ridge." }
WordHunterWoW_QuestEN[10988] = { title = "The Raven Stones", description = "I've trained your sparrowhawk to respond to a specific whistle. When it hears the sound, the bird will fly to you and guide you to the location of the nearest tablet fragment. Arthorn sent word that the fragments you're looking for are buried in the Skettis area of southeastern Terokkar Forest, so the bird will wait for you there.\n\nWhen you've gathered all the stones, return the whistle to Arthorn and she will see to the animal's care and release.\n\nConvey my greetings to Arthorn when you see her.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Gather 8 Raven Stones from Skettis and bring them to Arthorn Windsong at Evergrove in Blade's Edge Mountains." }
WordHunterWoW_QuestEN[10989] = { title = "Mog'dorg the Wizened", description = "Mog'dorg the Wizened waits for you at top of da tower.  He tells me to look for a {race} {class} just like you.  You go speak with him about smart things.\n\nGo now, but don't tell no one.  It's a secret!", objectives = "Speak with Mog'dorg the Wizened atop the tower where Chort is standing, just outside the Circle of Blood in the Blade's Edge Mountains.", completion = "Finally, Chort has sent me someone who looks like they might be able to help.  I am trying to save the Bloodmaul from annihilation by the Bladespire clan, and Gruul's sons, who are backing them.\n\nI trust that you will be the one to aid our secret society and deliver us into freedom." }
WordHunterWoW_QuestEN[10990] = { title = "The Eagle's Essence", description = "The Book of the Raven tells us the raven's followers captured and bound the spirits of his rivals within stone shrines. A guardian was set to watch over each, lest the raven's enemies attempt to free them.\n\nThe first of the shrines is the eagle's, found in the hills to the south of Lake Jorune and west of Stonebreaker Hold in Terokkar Forest.\n\nThe tablet says that the eagle fought valiantly, but was overcome by a swarm of enemies. The armor and endurance of your bear form is well-suited to this fight.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Defeat the Guardian of the Eagle and obtain the Essence of the Eagle. Use Arthorn's Sparrowhawk Whistle to call Arthorn's Sparrowhawk to relay news of your success.\n\nIf you lose Arthorn's Sparrowhawk Whistle, return to Arthorn Windsong at the Evergrove for a replacement." }
WordHunterWoW_QuestEN[10991] = { title = "The Falcon's Essence", description = "<The bird speaks with Arthorn's voice.>\n\nThe second spirit bound by the raven's followers was the falcon.\n\nIt was subdued and imprisoned close to Skettis as a reminder to the raven-priests when they held power.\n\nOn the shores of Lake Ere'Noru, to the northwest of Skettis, you'll find the falcon's shrine.\n\nTo overcome the falcon's guardian, you'll need to use the falcon's strengths to your advantage. Use the speed and grace of your cat form to defeat the guardian before it reaches full strength!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Defeat the Guardian of the Falcon, obtain the Essence of the Falcon. Use Arthorn's Sparrowhawk Whistle to call Arthorn's Sparrowhawk to relay news of your success.\n\nIf you lose Arthorn's Sparrowhawk Whistle, return to Arthorn Windsong at the Evergrove for a replacement." }
WordHunterWoW_QuestEN[10992] = { title = "The Hawk's Essence", description = "<Arthorn's voice addresses you.>\n\nThe last, and strongest, of the spirits spoken of in the Book of the Raven is that of the hawk. It was imprisoned far from Skettis, in a shrine on a remote island southeast of Auchindoun.\n\nI believe this description best matches the island we know as Sorrow Wing Point.\n\nThe tablet describes the hawk's guardian as nearly invulnerable to the bird's claws. Forsake physical attacks and call down the fury of the stars to defeat this foe. Do not repeat the hawk's mistake.You will receive:", objectives = "Defeat the Guardian of the Hawk and bring the Essence of the Hawk to Arthorn Windsong at the Evergrove." }
WordHunterWoW_QuestEN[10993] = { title = "Return to Cenarion Refuge", description = "Bring the essences to Morthis Whisperwing, along with word of our findings about the raven god.\n\nMorthis will know best how to use the essences and information in drawing Anzu out into the open. Make your way to him quickly, for there's no telling how long Clintar and the dreamwardens can withstand the raven's assault!\n\n<Arthorn grabs your arm before you turn to leave>.\n\nPlease, <name>, tell Morthis how much of a help I've been to you. I fear he will not see my hand in this work!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Bring Arthorn's Package to Morthis Whisperwing at Cenarion Refuge." }
WordHunterWoW_QuestEN[10994] = { title = "Chasing the Moonstone", description = "If the essences are combined within a rare gemstone such as a Southfury moonstone, you'll be able to release them when you're prepared to challenge Anzu.\n\nThe only problem is that Southfury moonstones are only found on the Azshara side of the river, on the cliffs near the river's source.\n\nTragedy befell the last night elf party that sought the stone. Their boat is still anchored in the river near where they sighted the moonstone. Keep your eyes open and approach the site by land from the Azshara side.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Bring a Southfury Moonstone to Morthis Whisperwing at the Cenarion Refuge." }
WordHunterWoW_QuestEN[10995] = { title = "Grulloc Has Two Skulls", description = "To the east, at the terminus of Dragons' End, is the Cursed Hollow.  Therein, Grulloc, son of Gruul, plots his dimwitted schemes.\n\nI heard that one of his possessions was stolen from him through trickery.  Was that you?  Unfortunate that he was not slain in the process.\n\nIf we are to regain our freedom, I would have you take his most prized possession, a dragon skull from when he rejoiced in his father's slaying of the black dragonflight.  The only way you'll get the skull is to vanquish him.", objectives = "Collect Grulloc's Dragon Skull.", progress = "Is Grulloc no more?", completion = "Indeed, it must have been a difficult struggle, <class>.  I feel greatly relieved now that he will not be breathing down our necks here.\n\nI will send this skull down to Chort for safekeeping.  I'm beginning to think that with your help, we might just pull this off." }
WordHunterWoW_QuestEN[10996] = { title = "Maggoc's Treasure Chest", description = "On the Razor Ridge, above and to the southeast, Maggoc patrols.  His father assigned him as the warden of the eastern mountain range, and he revels in terrorizing any creature that gets in his way.\n\nAs a son of Gruul, he must be done away with if my clan is to survive.  That's where you come in.\n\nMaggoc carries a treasure chest with him at all times.  Prove to me that he has been slain by bringing me his precious chest.  Feel free to keep whatever you find within it.", objectives = "Collect Maggoc's Treasure Chest.", progress = "Do you have the chest?", completion = "You say it was empty?  Unfortunate, but you can see the mindless brutality that we're up against.\n\nWith the fall of Maggoc, we are one step closer to realizing my dream of a home for the ogres where we can determine our own destiny." }
WordHunterWoW_QuestEN[10997] = { title = "Even Gronn Have Standards", description = "Are you familiar with Shattrath City, {class}?  Above it to the northwest is a place called the Barrier Hills, which you can only get to upon a flying mount.\n\nOne of Gruul's sons, Slaag, exiled himself and took control of the Gordunni ogres that reside there.  Even at such a distance, we cannot afford to leave him in peace, lest he return when the rest of his brothers have been slain.\n\n{name}, you must travel there, and bring back his standard as proof that he has been dealt with.", objectives = "Collect Slaag's Standard.", progress = "Do you return with Slaag's standard in hand?", completion = "What a relief that Slaag is gone.  No longer will we be threatened by the looming specter of his return!\n\nIf you do not mind, I will take the standard as a symbol of hope for all of the ogres of the mountains.\n\nThank you, <name>." }
WordHunterWoW_QuestEN[10998] = { title = "Grim(oire) Business", description = "There is one more gronn to be slain: Skulloc Soulgrinder. He keeps himself hidden away, but there is a way to coax him forth.\n\nHe was trained by an ogre warlock known as Vim'gol the Vile, whose grimoire you must retrieve!\n\nVim'gol must be summoned by standing within a fire ring at his circle. Find Vim'gol's Circle in the mountains, to the northeast, near the Broken Wilds.", objectives = "Collect Vim'gol's Vile Grimoire.", progress = "Have you summoned forth Vim'gol the Vile and taken the grimoire from his dead clutches?", completion = "I hesitate to even touch such a tainted thing of evil.  Yet read it we must if we are to glean what knowledge it contains and bring forth Skulloc from his hiding place." }
WordHunterWoW_QuestEN[10999] = { title = "One Shot, One Kill", description = "Bring me 8 trogg stone teeth.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Bring me 8 trogg stone teeth." }
WordHunterWoW_QuestEN[11000] = { title = "Into the Soulgrinder", description = "The grimoire is the key to Skulloc's downfall.\n\nRead aloud from the book at Soulgrinder's Barrow to initiate the ritual.  An object known as the Soulgrinder will appear, as well as Skulloc's ghostly victims, who will try to destroy it.  You must keep them from doing so long enough to force Skulloc fully into the world.\n\nFind the barrow by heading north through the Daggermaw Canyon on the other side of the Circle of Blood.  It is on the right side before Gruul's Lair.\n\nBring back Skulloc's soul.", objectives = "Collect Skulloc's Soul.", progress = "Have you taken Skulloc's soul yet?", completion = "It is over then.  You have freed us from the shackles of our enslavement to the Sons of Gruul.  You have given the Bloodmaul Clan a reprieve from certain extinction.\n\nWords cannot describe the extent of the debt that ALL of the ogres of the Blade's Edge Mountains, Bloodmaul and Bladespire alike, owe you, <name>.\n\nLook down, even now the ogres gather to pay you tribute.  Let Gruul and his puppet, the old king, Maulgar, cower within their lair.  Go to the ogres below as our new king!" }
WordHunterWoW_QuestEN[11001] = { title = "Vanquish the Raven God", description = "We must waste no time in dealing with the raven god. You must take the essence-infused moonstone to a place of great power in order to lure the god from the relative safety of the Emerald Dream.\n\nDescend into the Sethekk Halls and set the moonstone in the clutches of the raven's claw. You'll find it in the chamber before the talon king's hall.\n\nAnzu must be made believe that his followers have gathered to welcome him back into the world. Once he has manifested, show him no mercy!You will learn:", objectives = "Slay the Raven God and return to Morthis Whisperwing at Cenarion Refuge.\n\nThis quest must be completed in Heroic dungeon difficulty." }
WordHunterWoW_QuestEN[11002] = { title = "The Fall of Magtheridon", description = "The source of Illidan Stormrage's fel orc army has been vanquished. The manufactory halts production of its grim product - at least for now. All that remains are a few trinkets and this severed head - a fitting trophy for a hero of the Alliance.\n\nReturn Magtheridon's head to Danath Trollbane at Honor Hold.\n", objectives = "Return Magtheridon's Head to Force Commander Danath Trollbane at Honor Hold in Hellfire Peninsula.", progress = "For the first time - in as long as I can remember - there is silence.", completion = "This defeat is not only a blow to Illidan, <name>. The Legion too reels... A pit lord commander has been defeated. The siege of Hellfire Citadel now holds no purpose for the Burning Legion. All of their efforts will undoubtedly be turned upon the Black Temple.\n\nRedemption comes for Illidan... and soon." }
WordHunterWoW_QuestEN[11003] = { title = "The Fall of Magtheridon", description = "The source of Illidan Stormrage's fel orc army has been vanquished. The manufactory halts production of its grim product - at least for now. All that remains are a few trinkets and this severed head - a fitting trophy for a hero of the Horde.\n\nReturn Magtheridon's head to Nazgrel at Thrallmar.\n", objectives = "Return Magtheridon's Head to Nazgrel at Thrallmar in Hellfire Peninsula.", progress = "For the first time - in as long as I can remember - there is silence.", completion = "This defeat is not only a blow to Illidan, <name>. The Legion too reels... A pit lord commander has been defeated. The siege of Hellfire Citadel now holds no purpose for the Burning Legion. All of their efforts will undoubtedly be turned upon the Black Temple.\n\nRedemption comes for Illidan... and soon." }
WordHunterWoW_QuestEN[11004] = { title = "World of Shadows", description = "Sky Commander Adaris was seriously injured during a Skettis incursion.  He's been in and out of consciousness since.\n\nI fear he has succumbed to a feverish delirium.  During brief lucid moments he demands that I prepare an elixir made from shadow dust carried by the arakkoa.  He seems to believe it will allow him to see into a \"world of shadows\" where the arakkoa's true leaders dwell.\n\nI do not believe this nonsense for a second, but I fear he won't rest until I obtain such an elixir.  Will you help?", objectives = "Severin wants you to venture into Skettis and retrieve 6 Shadow Dusts from the arakkoa that dwell there.", progress = "Have you obtained the dust, <name>?", completion = "I thank you, <name>.  I will administer a small amount to the commander... to humor him.  You can keep the rest, perhaps you'll find a use for it." }
WordHunterWoW_QuestEN[11005] = { title = "Secrets of the Talonpriests", description = "Thank you for paying heed to my fevered rants.  All along we had been trying to identify and destroy the Skettis chain of command; we had learned of three clerics known as the talonpriests, but we'd never seen them with our own two eyes.  Now we know why.\n\nTalk to Severin to obtain more of the elixir he discovered.  Use the elixir to find and kill the three talonpriests: Ishaal, Skizzik and Zellek.  They're rumored to dwell in Veil Ala'rak, near the eastern shore of Blackwind Lake.", objectives = "Obtain an Elixir of Shadows from Severin and use it to find and slay Talonpriest Ishaal, Talonpriest Skizzik and Talonpriest Zellek in Skettis. Return to Commander Adaris after completing this task.", completion = "You've done well, <name>.  You've dealt a tremendous blow to the enemy by slaying the talonpriests." }
WordHunterWoW_QuestEN[11006] = { title = "More Shadow Dust", description = "", objectives = "It looks like the commander was not delirious after all.  Bring me more dust and I'll prepare another elixir for you.", progress = "It looks like the commander was not delirious after all.  Bring me more dust and I'll prepare another elixir for you.", completion = "Keep bringing the dust to me.  I'll prepare as many elixirs as you need.\n\nCommander's orders." }
WordHunterWoW_QuestEN[11007] = { title = "Kael'thas and the Verdant Sphere", description = "The air around you hums - a gentle hum. The naaru are aware of your victory. Perhaps they are the reason you were compelled to pick up this sphere from the still-twitching remains of Kael'thas Sunstrider. What secrets could it hold?\n\nPerhaps A'dal in Shattrath City could make sense of the item.", objectives = "Take the Verdant Sphere to A'dal in Shattrath City.", progress = "You heard my call? Yes...", completion = "<A'dal's thoughts intermingle with your own.>\n\nThe sphere... Strange. Did you know that he lived? Yes. It is here - in the sphere itself. Maimed for certain. He calls to a higher power now. No, not Illidan.\n\nHigher.\n\nKil'jaeden the Deceiver comes...\n\nNot here...\n\n<A'dal points your mind elsewhere.>\n\nAzeroth. Unknown.\n\nRest. Your brothers and sisters will retake Tempest Keep now.\n\n<A'dal hums a song of battle.>" }
WordHunterWoW_QuestEN[11008] = { title = "Fires Over Skettis", description = "You think you have what it takes to be part of the Skyguard?  We'll have to see how you handle yerself in the air.\n\nThe arakkoa are breeding a gargantuan variety of their attack pets and are using it against our scouts.  I want you to take these blasting charges and use them to destroy hatcheries above the arakkoa's dwellings.  Avoid the monstrous kaliri guarding the hatcheries.  They'll knock you off your mount before you know what hit you.", objectives = "Seek out Monstrous Kaliri Eggs on the tops of Skettis dwellings and use the Skyguard Blasting Charges on them. Return to Sky Sergeant Doryn.", progress = "Did you finish your assignment yet?", completion = "Excellent job, <name>!  That'll show those bird men the meaning of air superiority!" }
WordHunterWoW_QuestEN[11009] = { title = "Ogre Heaven", description = "Now that you have delivered us from bondage, we can begin the process of reunifying the clans.  This will take some time; old grudges are difficult to overcome.\n\nBut more pressing, you must go to Ogri'la in the heavens above to the west.  You must defend it, and us, from those forces above that the gronn used to protect us from: ethereals, demons, and worst of all, the black dragonflight.\n\nWhen you find ogre heaven, seek out the wisdom of Chu'a'lor on how best to proceed.", objectives = "Mog'dorg the Wizened has asked you to speak with Chu'a'lor at Ogri'la in the Blade's Edge Mountains.", completion = "Mog'dorg sent a message ahead, saying that I should expect you.  I am glad that you came.\n\nWith the Sons of Gruul destroyed, it is only a matter of time - a short amount at that - before the various inhabitants of this mountain terrace, and the one to the north, decide to prey upon our ogre brothers down below.\n\nI trust that you will help us to prevent that, <name>." }
WordHunterWoW_QuestEN[11010] = { title = "Bombing Run", description = "You have a flying mount... so what!  You think you have what it takes to use it properly?\n\nForge Camp: Wrath and Forge Camp: Terror, to the north and south, are a major pain in my backside, as well as being a threat to peaceful Ogri'la.  With all of those fel cannons shooting down the Skyguard left and right, we can't get through there to take care of business.\n\nYou want to prove yourself?  Take these bombs and knock out their ammo stacks.  Just don't let them shoot you down, too!", objectives = "Use the Skyguard Bombs to destroy 15 Fel Cannonball Stacks.", progress = "You take out their stacks of fel cannonballs yet?", completion = "Well, well, well, I guess you had it in you after all.  Good work.  Maybe Old Man Keller was wrong about you after all.\n\n<Sky Sergeant Vanderlip smirks.>" }
WordHunterWoW_QuestEN[11011] = { title = "Eternal Vigilance", description = "Your defeat of Anzu, the raven god, is truly a remarkable accomplishment. He may not abandon his quest to return to Outland, I fear.\n\nAs long as he has followers here, he will attempt to rise again. Keep the essence-infused moonstone with you in case we have not heard the last of Anzu.You will receive:", objectives = "Speak with Morthis Whisperwing to receive an Essence-Infused Moonstone.Your defeat of Anzu, the raven god, is truly a remarkable accomplishment. He may not abandon his quest to return to Outland, I fear.\n\nAs long as he has followers here, he will attempt to rise again. Keep the essence-infused moonstone with you in case we have not heard the last of Anzu.You will receive:" }
WordHunterWoW_QuestEN[11012] = { title = "Blood Oath of the Netherwing", description = "", objectives = "Our lands are lost. Our children stolen in the night, forced into slavery - or worse...\n\n<Mordenai's voice tenses.>\n\nThe time is now, my ally. The time to retake what was once ours has come! You have proven yourself a capable combatant and compassionate soul.\n\nWill you swear to assist the Netherwing Dragonflight in retaking our lands and rebuilding our homes? Will you swear to watch over the flight and allow the bloodline to be born anew? Swear this and let us battle for our home and our loved ones!" }
WordHunterWoW_QuestEN[11013] = { title = "In Service of the Illidari", description = "Netherwing Ledge... What was once a bastion of sanctuary for the Netherwing is now home to the Dragonmaw. While the orcs may have control of our territory, our magic there is still strong. Strong enough to cloak your true identity and allow you to infiltrate the ranks of Dragonmaw.\n\nI have prepared this letter for you to present to their leader, Overlord Mor'ghor. Fly headlong into the maw of our enemy and seek out Dragonmaw Base Camp to start your new life as a fel orc of Illidan Stormrage.", objectives = "Travel to Netherwing Ledge and deliver the Illidari Service Papers to Overlord Mor'ghor at Dragonmaw Base Camp.", progress = "<Mor'ghor grunts.>\n\nYou're late...", completion = "<Mor'ghor reads the letter and laughs.>\n\nA death knight? You couldn't shine the boots of a death knight, maggot.\n\n<Mor'ghor looks you over.>\n\nBut yes... You might be able to work your way up to peon. At the worst, I'll toss you into the pit and leave you to die..." }
WordHunterWoW_QuestEN[11014] = { title = "Enter the Taskmaster", description = "<Mor'ghor crumples up the service letter and tosses it aside.>\n\nAlright grunt, first things first. If you're gonna join my beloved Dragonmaw army, you'll need to work. Everyone works up here on the ledge. Get a job and don't screw it up and I'll see if there might be something more interesting for you to do later.\n\nGo talk to Taskmaster Varkule Dragonbreath. He's standin' in the middle of town. He'll assess your skills and assign work as he sees fit.\n\nNow get out of my face!", objectives = "Speak with Taskmaster Varkule Dragonbreath at Dragonmaw Base Camp.", completion = "Varkule gonna set you up right, grunt. You get your choice of one job best suited to your skills and Netherwing crystal collection. You'll be required to fill your work orders once per day.\n\nYeah, it's a bunch of crap jobs but even the ascendants started out as peons." }
WordHunterWoW_QuestEN[11015] = { title = "Netherwing Crystals", description = "No good at nothin'? That's fine. Even lunkheads like you can be used around here. Just find creatures on the ledge and kill 'em. Sometimes they'll have nether crystals on their carcasses. Gather those and bring 'em back to me and I'll consider your work order for the day complete.\n", objectives = "Taskmaster Varkule Dragonbreath at Dragonmaw Base Camp in Shadowmoon Valley wants you to bring him 30 Netherwing Crystals.", progress = "Nether crystals are used for lots of things. Mainly makin' weapons and armor...", completion = "You're done for today, kid. Come back tomorrow if you're still alive." }
WordHunterWoW_QuestEN[11016] = { title = "Nethermine Flayer Hide", description = "A skinner, eh? Well you'll find plenty to skin here! You gotta search for flayers around crystal formations. Take 'em down and take their hides. Sometimes they'll have a hide worth keepin'. Bring those to me.", objectives = "Taskmaster Varkule Dragonbreath at Dragonmaw Base Camp in Shadowmoon Valley wants you to bring him 35 Nethermine Flayer Hides.", progress = "We use the flayer hides for armor lining and structural tarps.", completion = "You're done for today, kid. Come back tomorrow if you're still alive." }
WordHunterWoW_QuestEN[11017] = { title = "Netherdust Pollen", description = "A flower picker?! Hilarious... Unfortunately, our mages and shaman need your services. The netherdust bushes that grow on this ledge have special pollen that is apparently very useful in their magical dealings. Bring me that stuff and I'll consider your work order complete.", objectives = "Taskmaster Varkule Dragonbreath at Dragonmaw Base Camp in Shadowmoon Valley wants you to bring him 40 Netherdust Pollen.", progress = "Like I said, netherdust pollen is used by our spell casters.", completion = "You're done for today, kid. Come back tomorrow if you're still alive." }
WordHunterWoW_QuestEN[11018] = { title = "Nethercite Ore", description = "A miner!\n\n<Varkule salutes.>\n\nAn orc after my own heart! That's how Varkule got his start - minin'! There ain't nothin' better than getting down and dirty in the mines, is there?\n\nNow get out there and find those nethercite deposits. Strip 'em for all their worth and bring me back the ore.", objectives = "Taskmaster Varkule Dragonbreath at Dragonmaw Base Camp in Shadowmoon Valley wants you to bring him 40 Nethercite Ore.", progress = "Gug over there is gonna use the ore to reinforce our weapons and armor.", completion = "You're done for today, kid. Come back tomorrow if you're still alive." }
WordHunterWoW_QuestEN[11019] = { title = "Your Friend On The Inside", description = "", objectives = "Didn't think we'd leave you to face the fel orc army by yourself, did you?\n\n<Yarzill's eyes flicker a translucent blue.>\n\nAye, we are here with you, <name>. For every service you perform for the fel orcs in your quest to reclaim Netherwing lands, we'll be at your side to make sure that they suffer a sufficient setback.\n\nYou'll need to keep a low profile so as not to draw any unwanted attention to yourself during your sabotage missions." }
WordHunterWoW_QuestEN[11020] = { title = "A Slow Death", description = "The Dragonmaw have peons stationed at nearly every crystal formation up here. While the outright slaying of them would draw far too much unwanted attention to you, there is a way that we can thin their numbers and remain below the suspicious eyes of Mor'ghor.\n\nVenture into the wilds of Shadowmoon Valley and slay the tainted wildlife. Take from them their corrupt fel glands. Use those fel glands with this mutton that I'll give you near the peons. They'll take one bite and fall deathly ill!", objectives = "Yarzill the Merc at Dragonmaw Base Camp in Shadowmoon Valley wants you to use Yarzill's Mutton in conjunction with Fel Glands to poison 12 Dragonmaw Peon Camps.", progress = "It is dirty work, <name>.", completion = "<Yarzill speaks in a low whisper.>\n\nExcellent work, <name>. Lay low for now. Come back to me tomorrow and we can do it again." }
WordHunterWoW_QuestEN[11021] = { title = "Ishaal's Almanac", description = "This mysterious tome was on Talonpriest Ishaal's body.  It contains arcane symbols and charts of celestial bodies beyond your comprehension.\n\nAll writing is in a language you don't understand; likely an ancient version of the arakkoa written tongue.  Perhaps you should bring this to Sky Commander Adaris.", objectives = "Bring Ishaal's Almanac to Sky Commander Adaris north of Skettis.", progress = "You've something to show me?", completion = "What have you brought to me?  I can't make out the writing on this tome, <name>... my loss of blood... must've blurred my vision." }
WordHunterWoW_QuestEN[11022] = { title = "Speak with Mog'dorg", description = "King {name}!  You speak with Mog'dorg the Wizened before you leave and go to Ogri'la!", objectives = "Speak with Mog'dorg the Wizened. He stands atop the tower on the east side of the Circle of Blood in the Blade's Edge Mountains.", completion = "My good man, I am glad that you have decided to speak to me again before leaving." }
WordHunterWoW_QuestEN[11023] = { title = "Bomb Them Again!", description = "We're still having problems with those flak cannons, {name}.\n\nDon't get me wrong -- I think that you did an outstanding job the last time out -- but, that doesn't change the fact that those damned demons seem to be replenishing their ammo supplies faster than we can knock them out.  And that means we're having a hell of a time getting our people through there, not to mention the risk those demons pose to Ogri'la.\n\nWhat do you say?  Want to take another shot at it?", objectives = "Use the Skyguard Bombs to destroy 15 Fel Cannonball Stacks.", progress = "How goes the bombing run?", completion = "Outstanding work, <name>!  I'd have you back up in the air and bombing them again, but policy around here is to make sure that our pilots get plenty of R&R.  Sorry, I don't make the rules, but I sure as hell enforce them!\n\nSee you again tomorrow, Ace!" }
WordHunterWoW_QuestEN[11024] = { title = "An Ally in Lower City", description = "There is an arakkoa in Lower City by the name of Rilak...  He can be trusted.  Take the book... to him.\n\n<Adaris drifts into unconsciousness as he returns the book to you.>", objectives = "Bring Ishaal's Almanac to Rilak the Redeemed in the Lower City section of Shattrath City.", progress = "You have the smell of Skettis on you!  Explain yourself!", completion = "This cannot be... this belonged to a talonpriest once.  How did you ever come across it?" }
WordHunterWoW_QuestEN[11025] = { title = "The Crystals", description = "When prepared correctly, the crystals of the mountains exhibit strange powers, such as the clarity of mind that we have found here in Ogri'la.\n\nAll of the creatures atop the mountains covet the crystal shards and use them to further their own goals.  An economy has even sprung up around them.\n\nTo assist us, you must first learn about the Apexis shards.  Bring me some.  In addition to the creatures here having them, they can sometimes be found where the flayers dig at the larger crystals.", objectives = "Chu'a'lor has tasked you with gathering 5 Apexis Shards. Bring them to him at Ogri'la atop the Blade's Edge Mountains.", progress = "As you come to understand the shards and crystals, you will be better able to assist us in protecting ourselves and our ogre brethren below.\n\nThe shards themselves get their name from an ancient and now-extinct arakkoan civilization, which used to live atop the mountains here.\n\nDo you have the shards with you?", completion = "<Chu'a'lor's left head begins to speak.>\n\nThese will do fine.\n\nRemember, <name>, the value of the shard is not in what it can purchase for you.  It is not even in what it can potentially do for you when properly forged, though there is some debate over that.\n\n\n\nThe true value is in the journey to attain the shard." }
WordHunterWoW_QuestEN[11026] = { title = "Banish the Demons", description = "You've arrived at the perfect time, friend!  We are in need of assistance.  In return, you will receive something very rare, which will help us both in the end.\n\nWe're not a violent ogre any longer, but the demons nearby threaten to overrun us and the Skyguard.  The problem with demons is that, once killed, they come right back in new bodies!\n\nBut, if you use this crystal to summon a banishing portal, when they die near it, their essences will be drawn in and banished back from whence they came!", objectives = "Use the Banishing Crystal to banish 15 demons at Forge Camp: Wrath or Forge Camp: Terror.", progress = "We trust that you've used the banishing crystal to send a whole slew of those Burning Legion things packing?!", completion = "That'll teach them!" }
WordHunterWoW_QuestEN[11027] = { title = "Yous Have Da Darkrune?", description = "", objectives = "" }
WordHunterWoW_QuestEN[11028] = { title = "Countdown to Doom", description = "This almanac presages the return of Terokk, the most powerful and terrible Skettis king in arakkoa history.\n\nI always believed this to be the mere legend, {name}.  The return of the talonpriests and your recovery of this tome indicate otherwise.\n\nWith each day, Terokk comes closer to returning to full strength.  Your only chance is to bring him to our world prematurely.  Return to Skettis and speak to Adaris about this.  Let us hope he has the wisdom to do the right thing.", objectives = "Return to Sky Commander Adaris at Blackwind Landing in Terokkar Forest with the news about Terokk's return.", completion = "The arakkoa seek to bring Terokk back beyond the veil of time and Rilak... wants to find a way to accelerate the process?  Is he out of his mind?\n\n<Adaris lies back down as his strength fades.>\n\nYou've done your duty, <name>.  It is time you let my men take over from here.  This has become a purely military matter." }
WordHunterWoW_QuestEN[11029] = { title = "A Shabby Disguise", description = "Open the package, {name}.  It is a disguise.  It doesn't look very convincing, does it?\n\nI craft them for ethereal smugglers in search of rare books.  There is an arakkoa scribe who dwells in the central island in Skettis, Terokk's Rest; his name is Sahaak.  He is old and nearly blind.\n\nUse the disguise to speak with him and obtain the book known as the Adversarial Bloodlines.  Be careful, {name}.  The disguise won't fool the other arakkoa.", objectives = "Use the Shabby Arakkoa Disguise to obtain the Adversarial Bloodlines from Sahaak and return to Hazzik.", progress = "The book, <name>.  Have you obtained it?", completion = "Excellent!  This book catalogs the descendants of Terokk's ancient enemies.  It is prophesied that their demise will be followed by Terokk's return." }
WordHunterWoW_QuestEN[11030] = { title = "Our Boy Wants To Be A Skyguard Ranger", description = "{class}, we've got a problem -- we have lots of sons.  And ever since the Skyguard moved in nearby, all our sons ever talk about is joining their ranks.\n\nAs a proud father, we want them to have every advantage for when they apply.  So, would you go to the fel crystalforge at either forge camp to the north or south, and procure a magic flask for our sons?  You can't miss their green smoke.\n\nWe think that they take ten apexis shards to make.  We'd give you the shards, but we don't have any at the moment.", objectives = "Collect an Unstable Flask of the Beast.", progress = "You have that magic flask, yet?  It will mean the world to little Torkus Jr.", completion = "You're a lifesaver, <name>.  Our boys are going to be so excited to hear the news!\n\nOK, so one down and one to go.  We did tell you about the other magical flask that they're going to need, didn't we?" }
WordHunterWoW_QuestEN[11031] = { title = "Archmage No More", description = "", objectives = "You've decided against your previous choice?  I suppose I can help you reverse it.  In the end Dalaran cares more about your loyalty than how you choose to show it.\n\nIt won't be cheap.  And of course, I will need your old ring back.", progress = "You've decided against your previous choice?  I suppose I can help you reverse it.  In the end Dalaran cares more about your loyalty than how you choose to show it.\n\nIt won't be cheap.  And of course, I will need your old ring back.", completion = "Make this next decision carefully.  We do our best to accommodate our allies, but even Dalaran's resources have their limits." }
WordHunterWoW_QuestEN[11032] = { title = "Protector No More", description = "", objectives = "You've decided against your previous choice?  I suppose I can help you reverse it.  In the end Dalaran cares more about your loyalty than how you choose to show it.\n\nIt won't be cheap.  And of course, I will need your old ring back.", progress = "You've decided against your previous choice?  I suppose I can help you reverse it.  In the end Dalaran cares more about your loyalty than how you choose to show it.\n\nIt won't be cheap.  And of course, I will need your old ring back.", completion = "Make this next decision carefully.  We do our best to accommodate our allies, but even Dalaran's resources have their limits." }
WordHunterWoW_QuestEN[11033] = { title = "Assassin No More", description = "", objectives = "You've decided against your previous choice?  I suppose I can help you reverse it.  In the end Dalaran cares more about your loyalty than how you choose to show it.\n\nIt won't be cheap.  And of course, I will need your old ring back.", progress = "You've decided against your previous choice?  I suppose I can help you reverse it.  In the end Dalaran cares more about your loyalty than how you choose to show it.\n\nIt won't be cheap.  And of course, I will need your old ring back.", completion = "Make this next decision carefully.  We do our best to accommodate our allies, but even Dalaran's resources have their limits." }
WordHunterWoW_QuestEN[11034] = { title = "Restorer No More", description = "", objectives = "You've decided against your previous choice?  I suppose I can help you reverse it.  In the end Dalaran cares more about your loyalty than how you choose to show it.\n\nIt won't be cheap.  And of course, I will need your old ring back.", progress = "You've decided against your previous choice?  I suppose I can help you reverse it.  In the end Dalaran cares more about your loyalty than how you choose to show it.\n\nIt won't be cheap.  And of course, I will need your old ring back.", completion = "Make this next decision carefully.  We do our best to accommodate our allies, but even Dalaran's resources have their limits." }
WordHunterWoW_QuestEN[11035] = { title = "The Not-So-Friendly Skies...", description = "On the northeast edge of this island exists a dock used for the packaging and transport of Netherwing crystals and relics. Dragonmaw Transporters transport the goods from the dock to Dragonmaw Fortress while Dragonmaw Ascendants guard the ground from any would-be attackers.\n\nThis leaves one opening for you to make a strike at the Dragonmaw: The Dragonmaw Skyway.\n\nFly to the shattered islands of the Dragonmaw Skyway and ambush the transporters that use the route. Recover our stolen relics!", objectives = "Yarzill the Merc at Dragonmaw Base Camp in Shadowmoon Valley wants you to recover 10 Netherwing Relics.", progress = "Dead orcs tell no tales, <name>. Make sure those Dragonmaw transporters do not escape.", completion = "<Yarzill whispers.>\n\nYou are doing the Netherwing a great service, <name>. Slowly, we will topple the Dragonmaw. From the inside a disease now grows - a disease with no cure...\n\nReturn to me tomorrow if you are interested in more work at the Dragonmaw Skyway." }
WordHunterWoW_QuestEN[11036] = { title = "Out of This World Produce!", description = "I'll be the first to admit I'm not quite sure what this order is for, but Rocket-Chief Fuselage's instructions were very specific -- only the very best fruit, preserved to survive a long voyage and sealed against the elements.\n\nThere were other specifications, zero-gravity this and low pressure that. I don't pretend to understand it, but the price is right, so he'll get his superfood. Bring this crate to him up at Area 52. After crossing into Netherstorm, keep following the road until you see the town.", objectives = "Bring the Preserved Fruit to Rocket-Chief Fuselage at Area 52 in the Netherstorm.", progress = "Is that the delivery from Old Orok?", completion = "<The chief inspects the crate's contents.>\n\nEverything looks good here. That's one more thing to cross off the list. Now all we need to do is get the rocket off the ground!" }
WordHunterWoW_QuestEN[11037] = { title = "A Strange Vision", description = "I've had a most unusual vision, {name}, and I don't know quite what to make of it. I've seen an arrow, an immense arrow, riding into the sky on a trail of fire. Such a feat is trivial for a skilled mage, but somehow I know the arrow I saw is not the product of magic.\n\nIt will be unlike anything the people of Azeroth have ever achieved. You must seek out the people working on this, {name}. Lend them your help, for without it, their efforts may yet fail.", objectives = "Speak with Rocket-Chief Fuselage at Area 52.", completion = "<The chief listens as you describe the seer's vision.>\n\nWell, I don't know about any of that, but we could certainly use your help around here. Behold the rocket behind me! That's the X-52...\n\nIsn't it the most beautiful thing you've ever seen?" }
WordHunterWoW_QuestEN[11038] = { title = "Assist Exarch Orelis", description = "Not long ago, High Priestess Ishanah sent a small group of anchorites to Netherstorm, under the command of Exarch Orelis. They were to investigate the activities of Kael'thas and his minions, but we haven't received any reports of their findings yet.\n\nI worry that our presence in the area might not be strong enough to carry out the mission. I'm certain that the exarch could benefit from your knowledge and experience. Are you willing to travel to Area 52 and assist him?", objectives = "Speak with Exarch Orelis at Area 52.", completion = "So you're here to help us determine exactly what Kael'thas is planning? Your help is most welcome. Netherstorm is crawling with blood elf agents whose activities threaten to tear the land asunder." }
WordHunterWoW_QuestEN[11039] = { title = "Report to Spymaster Thalodien", description = "Some time ago, Voren'thal dispatched a small team to Netherstorm to investigate the activities of Kael'thas. Our leader has the utmost confidence in Spymaster Thalodien and his compatriots, and has decided to honor his request for reinforcements.\n\nThalodien's report was brief, but clear that he's encountered something of great importance. Report to him at Area 52 and assist him in any way possible, {name}.", objectives = "Report to Spymaster Thalodien at Area 52.", completion = "<A brief look of disappointment crosses the spymaster's face.>\n\nI was hoping for at least a squad, but if Voren'thal saw fit to send only you, then I will adjust my plans accordingly." }
WordHunterWoW_QuestEN[11040] = { title = "Parts for the Rocket-Chief", description = "You can count on one hand the number of times I've collaborated with a goblin. We're far more likely to be in competition with them, but when I received Rocket-Chief Fuselage's request, I just couldn't refuse him.\n\nThis crate is full of parts I'm not using here, but that the rocket-chief might be able to put to use on his project. Would you be kind enough to deliver them if you're on your way to Area 52?\n\nWho knows, maybe some fine gnomish parts could keep his creation from exploding!", objectives = "Bring Bossi's Spare Parts to Rocket-Chief Fuselage at Area 52 in the Netherstorm.", progress = "That crate has the look of a master gnomish engineer about it. Did Bossi send you?", completion = "I don't even know what some of these parts do! I'm certain I'll find a use for some of them, but I never suspected I'd have to learn to think like a gnome!" }
WordHunterWoW_QuestEN[11041] = { title = "A Job Unfinished...", description = "In the name of our great master... For the glory of Illidan!\n\nBy order of Overlord Mor'ghor, the great plateau of Netherwing Ledge is to be secured. With all Netherwing drakes captured or forced off of the land, rock flayers are running rampant and threatening crystal harvesting operations.\n\nDestroy them all, their den mother and her consort, Arvoar.\n\nMor'ghor commands it!\n\n<It would appear that this orc failed to take the plateau. It is time to prove your worth to Mor'ghor!>", objectives = "Slay 10 Overmine Flayers and Barash the Den Mother. Return to Overlord Mor'ghor at the Dragonmaw Base Camp should you succeed.", progress = "Who dares approach Mor'ghor? This had better be important.", completion = "So from the remains of one of my own overseers you recovered the command and took matters into your own hands? You have managed to impress Mor'ghor. Well done..." }
WordHunterWoW_QuestEN[11042] = { title = "A Mystifying Vision", description = "A strange vision haunts me, {name}. I see a continuous cloud of smoke ascending toward the sky, left in the wake of a giant fire moving ever faster away. It is not a natural phenomenon, nor a creation of evil; that much I know.\n\nI have no knowledge of what it looks like, save that it is the product of the labor of many. Yet, without more hands, it may never come to be.\n\nTravel to Netherstorm, {class}. Locate those responsible for this creation and offer them your aid.", objectives = "Speak with Rocket-Chief Fuselage at Area 52.", completion = "<The chief listens as you describe the seer's vision.>\n\nWell, I don't know about any of that, but we could certainly use your help around here. Look at the behemoth behind me. That's the X-52...\n\nIsn't it the most beautiful thing you've ever seen?" }
WordHunterWoW_QuestEN[11043] = { title = "Building a Better Gryphon", description = "I've heard that the Wildhammer dwarves maintain a gryphon roost at their fortress down in southern Shadowmoon Valley. If you're going down there, would you speak to them on my behalf? I have some ideas on how to improve their gryphons!\n\nWhy stop at armoring them when you could attach an altimeter, a rear view mirror, and rocket? Imagine how fast you could go with one of those babies strapped to your gryphon's back! I'll call it the TurboGryphon 8000!", objectives = "Speak with Brunn Flamebeard at Wildhammer Stronghold in Shadowmoon Valley.", completion = "<Brunn's face reddens until its color is indistinguishable from his beard.>\n\nHe wants to do WHAT to my gryphons?\n\nIf that little pipsqueak puts anything other than a saddle on them, I'll personally travel up to Blade's Edge and stuff that rocket o' his down his throat!" }
WordHunterWoW_QuestEN[11044] = { title = "Visions of Destruction", description = "A vision of cataclysm often disturbs my rest -- a rain of green fire falling to the earth, felling the valiant defenders of a mighty fortress. It has haunted me for weeks now, although I have only recently come to understand its meaning.\n\nTo the far east, in Shadowmoon Valley, the Wildhammer dwarves endure constant attacks from the Burning Legion and numerous other foes. They fight bravely, but without relief, their enemies will triumph. Go to their side, {name}. Help them in their fight.", objectives = "Speak with Wing Commander Nuainn at Wildhammer Stronghold.", completion = "A vision, you say? I don't care if he saw it in a vision, read it in a letter, or heard it from the mouth of a pit lord. He was dead on! What matters is that you're here, friend, and we need all the help we can get." }
WordHunterWoW_QuestEN[11045] = { title = "Zorus the Judicator", description = "The history of Shadowmoon Valley is a long and troubled one. Few delve into it for fear of breathing new life into the unspeakable atrocities that took place there.\n\nNot all are so timid, though. Zorus the Judicator searches for the truth about the ghosts of Shadowmoon's past. It is a staggering undertaking, one with which he would welcome help, I'm sure.\n\nIf you should venture into the valley, look for Zorus at Wildhammer Stronghold, in the central portion of the valley's southern region.", objectives = "Speak with Zorus the Judicator at Wildhammer Stronghold.", completion = "Fantei speaks the truth and I would welcome your help." }
WordHunterWoW_QuestEN[11046] = { title = "Chief Apothecary Hildagard", description = "The history of Shadowmoon Valley is a long and troubled one. Few study it for fear of breathing new life into the unspeakable atrocities that took place there.\n\nNot all are so timid, though. Chief Apothecary Hildagard's research delves into the ghosts of Shadowmoon's past. It is a staggering undertaking, one with which she would welcome help, I'm sure.\n\nIf your travels bring you there, seek Hildagard at Shadowmoon Village, in the northwestern reaches of the valley.", objectives = "Speak with Chief Apothecary Hildagard at Shadowmoon Village.", completion = "Fantei has a good memory. It's been months since I was last in Shattrath to buy reagents. He's right, though. I could use the help." }
WordHunterWoW_QuestEN[11047] = { title = "The Apprentice's Request", description = "As an apprentice wind rider master, one of my tasks is to care for the beasts when they're not flying. The problem is that we have so few here, there's very little downtime for any of them.\n\nI'm afraid we'll work them all to death if we don't receive any replacements. There's a large stable down in Shadowmoon Village, in western Shadowmoon Valley. Dama Wildmane oversees the wind rider care and training there.\n\nWould you speak with her on our behalf and let her know about our situation?", objectives = "Speak with Dama Wildmane at Shadowmoon Village in Shadowmoon Valley.", completion = "<Dama listens to Agadai's request.>\n\nI can't guarantee that there will be any wind riders available, but I'll see what I can do. As it is, we're having trouble keeping up with the demands of other buyers and outposts." }
WordHunterWoW_QuestEN[11048] = { title = "Kroghan's Report", description = "My original orders were to remain in Garadar for a short time, then continue on and report to Blood Guard Gulmok at Shadowmoon Village. What I've seen in my time here is that Garadar could benefit from a long term Horde liaison.\n\nI know that Blood Guard Gulmok needs all the troops he can get, but I know he'll understand that my mission here isn't yet complete. Travel to Shadowmoon Village, in northwestern Shadowmoon Valley, and inform Blood Guard Gulmok of my delayed arrival.", objectives = "Speak with Blood Guard Gulmok at Shadowmoon Village.", completion = "<Gulmok grumbles upon hearing of Kroghan's decision.>\n\nI understand his point of view, but we need warm bodies in the trenches here too! The Legion's bombarding us with infernals day and night. If Kroghan's going to be delayed, you can take his place on the field!" }
WordHunterWoW_QuestEN[11049] = { title = "The Great Netherwing Egg Hunt", description = "Should you discover any Netherwing eggs while exploring, bring them to me.\n\nBe warned, a Netherwing egg is a rare discovery. Do not become frustrated if you cannot locate one. These Dragonmaw have been very thorough in collecting most of them and shipping them off to parts unknown.\n\nEggs might be found on creatures of the island, near crystal formations, in the mines, or even inside a nethercite node or netherdust bush.\n\nKeep a low profile. We don't need Mor'ghor catching wind of your actions.", objectives = "Yarzill the Merc at Dragonmaw Base Camp in Shadowmoon Valley wants you to recover a Netherwing Egg.", progress = "How goes the egg hunt?", completion = "Neltharaku will be most pleased, <name>. Well done." }
WordHunterWoW_QuestEN[11050] = { title = "Accepting All Eggs", description = "", objectives = "We don't need those eggs to get into the wrong hands, <name>. Bring me any additional eggs that you may find.\n\nJust remember to keep a low profile and avoid raising suspicion!", progress = "We don't need those eggs to get into the wrong hands, <name>. Bring me any additional eggs that you may find.\n\nJust remember to keep a low profile and avoid raising suspicion!", completion = "You are a true hero, <name>." }
WordHunterWoW_QuestEN[11051] = { title = "Banish More Demons", description = "If we know the demons, and we do because we've studied them extensively, they're fast at work repairing any damage that has been done to their precious transporter.\n\nSo, if you want a chance at another darkrune, take our banishing crystal back out there and eliminate more demons.  Besides, you want to help us to lessen the threat that the demons pose, yes?\n\nWe said \"chance\" because the process we use yields mixed results.  You might get a darkrune, or you might get something else entirely.", objectives = "Use the Banishing Crystal to banish 15 demons at Forge Camp: Wrath or Forge Camp: Terror.", progress = "A seasoned pro such as yourself shouldn't be having any difficulty banishing demons.  You're not having any difficulties, right, <race>?", completion = "We wish the process of creating a darkrune was foolproof, <name>.  Alas, it is not.  Please, take this bag and look in it to see what we've wrought today.  We couldn't bear to look ourselves.\n\nRemember, if you get a darkrune, take it to Gahk to exchange for a crystalforged darkrune.  Then you'll be able to once more bring down Shartuul's transporter.\n\nOh, and <name>, don't forget to come by again tomorrow and pickup the banishing crystal.  There are always more demons to be banished." }
WordHunterWoW_QuestEN[11052] = { title = "Akama's Promise", description = "<Akama inserts the crystal into the medallion in his hand.>\n\nI am not as strong as I once was, {name}.  Being so close to evil itself all these years - I do not know if I can trust myself with an artifact as powerful as this.\n\nTake this as my promise to you that when the time comes and you face Illidan, I will be on your side.  Take it to the one being we know we can trust with its power.  Take the medallion to A'dal in Shattrath City.", objectives = "Bring the Medallion of Karabor to A'dal in Shattrath City.", progress = "<A'dal notices your approach and a warm light embraces you.  A'dal seems to know you have something for him.>", completion = "<As you give the medallion to A'dal, it disappears into his being in a flash of light.>\n\n<You are briefly shown a glimpse of a moment... perhaps in the future.  You see Akama and Maiev coming out of the Warden's Cage, fighting their way to the Dark Temple.  A third figure shrouded in shadows is aiding them.  Upon closer inspection you notice that the figure is you.>" }
WordHunterWoW_QuestEN[11053] = { title = "Rise, Overseer!", description = "Rare it is that a peon survives for as long as you have. Rarer still is when a peon rises from the dregs to attain a new rank.\n\n<Varkule claps.>\n\nThe Overlord has called for you, grunt. A new rank awaits, no doubt.", objectives = "Speak with Overlord Mor'ghor at Dragonmaw Base Camp in Shadowmoon Valley.", completion = "I have been following your activities closely, <name>. You have proven to be an invaluable asset to Dragonmaw. With that said, I am going to promote you to Overseer. With that rank comes new responsibilities that you must fulfill.\n\nRise, Overseer <name>! Rise and seek out those that need your assistance at the base camp." }
WordHunterWoW_QuestEN[11054] = { title = "Overseeing and You: Making the Right Choices", description = "So you're the new overseer, eh? Well there's one thing any good overseer needs and that's the proper disciplinary weapon. Before you can go out there and knock some sense into these peons you need to have your \"piece.\" Each overseer has to gather the materials required to make their own \"piece\" and you'll be no different.\n\nI'll need knothide leather and the hardened hide of Tyrantus. You'll find Tyrantus in Eco-Dome Farfield, located in the northern reaches of Netherstorm.", objectives = "Chief Overseer Mudlump at the Dragonmaw Base Camp in Shadowmoon Valley wants you to bring him 10 pieces of Knothide Leather and 1 Hardened Hide of Tyrantus.", progress = "There's peons to be disciplined, <name>! Hurry it up!", completion = "ARRR! You might make it as an overseer after all. That oversized lizard has been the bane of many an orc!\n\n<Chief Overseer Mudlump begins to fashion the weapon.>" }
WordHunterWoW_QuestEN[11055] = { title = "The Booterang: A Cure For The Common Worthless Peon", description = "This is your booterang. There are many like it but this one is yours.\n\nAs an overseer you will use this booterang to sow terror into the hearts of defiant peons. Proper use of the booterang will instill obedience and ensure subservience.\n\nVenture forth to the crystal fields and discipline any peons that you see slacking off. Show them the might of the booterang!\n", objectives = "Chief Overseer Mudlump at the Dragonmaw Base Camp in Shadowmoon Valley wants you to discipline 20 lazy Dragonmaw Peons. You will also need to return your Booterang.", progress = "It's all in the wrist, <name>.", completion = "A hard day's work! It pays off, though, doesn't it? Warms your heart seeing those worthless runts slavering over those crystals... Anyhow, that's all for today. Come back tomorrow for another round of booterang discipline." }
WordHunterWoW_QuestEN[11056] = { title = "Hazzik's Bargain", description = "Do not draw attention to our conversation.  Adaris would not approve.\n\nI belong to the lowest caste of arakkoa, {name}.  During Terokk's rule I would've been sacrificed to the dark powers worshipped by his talonpriests.  If what you say is true and the talonpriests are seeking Terokk's return, then you must prevent them from succeeding - regardless of what your leader says!\n\nI've something to offer you that you'll find useful.  There is a package at my old dwelling in Upper Veil Shil'ak.  Bring it to me!", objectives = "Obtain Hazzik's Package at his dwelling in eastern Skettis and return to him with it.", progress = "You've returned, <name>.  I was beginning to think you'd given up on me.", completion = "Excellent, <name>.  You will see that I'm true to my word." }
WordHunterWoW_QuestEN[11057] = { title = "The Trouble Below", description = "We commend your zeal in wanting to help out here in Ogri'la, {class}.  However, we have a favor to ask of you before we can accept your assistance.\n\nDown below our brethren are enslaved to the Sons of Gruul.  Please, speak with Mog'dorg the Wizened, who is leading an ogre resistance against their gronn masters.\n\nSeek him out atop the tower on the eastern side of the Circle of Blood arena.", objectives = "Speak with Mog'dorg the Wizened atop one of the towers just outside the Circle of Blood in the Blade's Edge Mountains.", completion = "You were sent from on high?  Truly my mission is blessed!  I am trying to save the Bloodmaul from annihilation by the Bladespire clan, and Gruul's sons, who are backing them.\n\nI trust that you will be the one to aid our secret society and deliver us into freedom." }
WordHunterWoW_QuestEN[11058] = { title = "An Apexis Relic", description = "Long ago a now-extinct sect of the arakkoa known as the Apexis lived here.  Remnants of their civilization are still present.  We call them apexis relics.\n\nWhat we know about them is that, when properly used, they grant a boon.  Each relic presents a colored sequence which, when the crystals are pressed in the correct order, leads through a series of levels, each harder than the last.\n\nAn apexis shard is needed to power the relic.  Return when you have attained the insight of the apexis vibration.", objectives = "Gain Apexis Vibrations from an Apexis Relic.", progress = "Have you learned how to use the apexis relic yet?  Both we and the Sha'tari Skyguard just to the north are interested in what you learn about them.", completion = "<Chu'a'lor nods his heads at you in satisfaction at your accomplishment.>\n\nYou have a quick mind, <name>.  It took us much longer to successfully make use of the relic.\n\nNow that you know how, you can do so as much as you care to.  Just remember that they require an apexis shard to power them." }
WordHunterWoW_QuestEN[11059] = { title = "Guardian of the Monument", description = "You've figured out how to use the single-person relics, but as you may have seen, there are bigger ones, which they surround.\n\nThese larger apexis monuments function in much the same way, but they take 35 apexis shards to activate.\n\nOf greater concern to us are the guardians that are summoned through their use.  These crystal constructs turned on their arakkoan masters long ago, and now endanger Ogri'la.\n\nWe would ask that you destroy one and bring us proof.", objectives = "Collect an Apexis Guardian's Head.", progress = "We abhor violence, but at least the construct that we have sent you against isn't a living being.\n\nSpeaking of which, do you have the head?", completion = "<Chu'a'lor beams at you with obvious respect.>\n\nNot only are we impressed with the mental alacrity of you and your friends, but we are indebted to you, as is all of Ogri'la and the Skyguard, for helping to protect our way of life here.\n\nAnd remember, <name>, at any time you can gather others and return to any of those larger apexis monuments to make use of them; as long as you have enough apexis shards to power it that is." }
WordHunterWoW_QuestEN[11060] = { title = "A Crystalforged Darkrune", description = "", objectives = "Da demons are making da Forge Camp: Wrath bigger.  Soon, dey be too big and crush us.  You crush dem first!\n\nShartuul's transporter is da key, but it protected by a magic shield and a demon called a degrader.  Us powerful warlock, and make special darkrune dat give you control of da degrader.  <race> give Gahkdarkrune, us give <race> crystalforged darkrune back.\n\nTake control of da degrader and possess as many of da demons dat come through da gate as you can ta stop dem!", progress = "Da demons are making da Forge Camp: Wrath bigger.  Soon, dey be too big and crush us.  You crush dem first!\n\nShartuul's transporter is da key, but it protected by a magic shield and a demon called a degrader.  Us powerful warlock, and make special darkrune dat give you control of da degrader.  <race> give Gahkdarkrune, us give <race> crystalforged darkrune back.\n\nTake control of da degrader and possess as many of da demons dat come through da gate as you can ta stop dem!", completion = "Little <race>, remember, when you control da degrader, you use its hammer ta smash da warp-gate's shield and let loose da demon within.\n\nDen you crush dat demon and control it.  Den another demon come and you control it, until da eredar overseer come.\n\nDen you crush him too!!!" }
WordHunterWoW_QuestEN[11061] = { title = "A Father's Duty", description = "As to that other magical flask, it can only be obtained from one spot: Bash'ir Landing.  It's an ethereal base, and they aren't too friendly with outsiders, so it might be a little dangerous to obtain.\n\nWhere's Bash'ir Landing, you ask?  Well, if you get on your flying steed and head north by northeast, well past Forge Camp: Wrath, you'll eventually spot it.  The Bash'ir crystalforge itself is at the northeast corner of the landing.\n\nThank you for doing this, {name}.  It'll mean the world to our sons!", objectives = "Collect an Unstable Flask of the Sorcerer for him.", progress = "That sorcerer's flask is sure to make my boys more intelligent than they already are, and that should help immensely with what they'll need to do once they're in the Sha'tari Skyguard.", completion = "We can't thank you enough, <name>!\n\nNow with these two flasks, unstable though they may be, we'll be able to send one of our boys north to the Skyguard Outpost.\n\nHere, just wait a moment and we'll call for one of them." }
WordHunterWoW_QuestEN[11062] = { title = "The Skyguard Outpost", description = "{name}, we were wondering if you might be willing to visit our friends just to the north at the Skyguard Outpost?\n\nSky Commander Keller and his Skyguard are here running missions for our mutual protection, and he's asked us to send along anyone that we feel would excel at helping out.\n\nThat would be you!\n\nHead up there as soon as you can, and please, give him our regards.", objectives = "Speak with Sky Commander Keller at the Skyguard Outpost in the Blade's Edge Mountains.", completion = "Welcome ta the Skyguard Outpost!  I built it with me own hands ya know.\n\nYeah, the whole thing!\n\n<The sky commander looks serious.>\n\nSo, ye must be lookin' ta spoil for a fight if ye're here talkin' ta me.  It was kind of old Chu'a'lor ta send ye along.  We can always use fresh meat for the grinder around here.\n\nIf ye don't mind, I'd like ya ta start by having a talk with my sergeant across the way: Vanderlip.  Don't mind her tongue, though it be sharper than the greatsword she be carrying." }
WordHunterWoW_QuestEN[11063] = { title = "Earning Your Wings...", description = "", objectives = "So you wanna join the Skybreakers, eh? You've certainly proven yourself an able Dragonmaw but that means nothing in the skies of Outland. The question has to be answered: CAN YOU FLY?\n\nAnd I don't just mean being able to mount up on a nether drake and delivering a shipment of crystals to the fort like those transporter scrubs. I'm talking about being the best... The top orc...\n\nOver to the west there are six riders. Defeat them all and I will grant you Skybreaker wings." }
WordHunterWoW_QuestEN[11064] = { title = "Dragonmaw Race: The Ballad of Oldie McOld", description = "Don't let the gray hair fool you, grunt. I'm still ten times the rider that you are! And don't go thinking that this old dog doesn't have any tricks up his sleeve.\n\nNow all you gotta do is follow me and try not to get knocked down off your mount. If you can do that, Oldie will admit defeat.\n\nWe'll lift off as soon as you're ready.\n", objectives = "Follow Murg \"Oldie\" Muckjaw while attempting to stay on your flying mount. Should you defeat Murg \"Oldie\" Muckjaw, report your victory to Ja'y Nosliw at the Dragonmaw Base Camp in Shadowmoon Valley.", completion = "Pumpkins? Oh how the mighty have fallen... I am certain the other riders will prove to be much more challenging." }
WordHunterWoW_QuestEN[11065] = { title = "Wrangle Some Aether Rays!", description = "Wanna help the Skyguard and Ogri'la?\n\nJust hear me out before you walk away, hot stuff.  We're in need of remounts!  The bombing runs and missions to Bash'ir Landing have taken a toll on our mounts.\n\nThe aether rays that fly around Vortex Summit, and the Crystal Spine to the northeast, look like they'd do just fine.  You don't even have to bring them back here, though that would be nice.  Just break and rope them, and we'll track them down later.\n\nThink you can wrangle me up some?", objectives = "Use the Wrangling Rope to capture 5 Aether Rays.", progress = "You wrangle me some aether rays yet?  You look like you might have some skill with rope, so it shouldn't take you too long.", completion = "Woo hoo!  Nice job, <name>!  Those rays are going to make excellent mounts!\n\nStick around kid... the Sha'tari Skyguard can always use a man of your obvious talents!" }
WordHunterWoW_QuestEN[11066] = { title = "Wrangle More Aether Rays!", description = "So, I hope that you're up to helping us wrangle up even more aether rays!  From what I can see, you're a natural with the rope!  And it's for a good cause, because not only do we get fresh mounts, but it helps us to protect Ogri'la, which the ogres appreciate.\n\nRemember, the aether rays fly around Vortex Summit, and the Crystal Spine to the northeast.\n\nThink you can wrangle me up some more?", objectives = "Use the Wrangling Rope to capture 5 Aether Rays.", progress = "You're doing great work for us, <name>.  I want you to know that we really appreciate everything that you're doing to keep us stocked up in fresh mounts!", completion = "You continue to amaze me!  Tell you what... why don't you come back tomorrow and we'll let the rope cool off for now?\n\n<Khatie laughs.>\n\nThank you so much, <name>!" }
WordHunterWoW_QuestEN[11067] = { title = "Dragonmaw Race: Trope the Filth-Belcher", description = "Dragonmaw treat you right, {name}. Even a worn out cursed being like me is given a chance. Now if you want to prove your worth to the Skybreakers, you will have to defeat me.\n\nI'm going to shake you off my tail like a bad case of fleas...\n\nWe'll lift off when you are ready.", objectives = "Follow Trope the Filth-Belcher while attempting to stay on your flying mount. Should you defeat Trope the Filth-Belcher, report your victory to Ja'y Nosliw at the Dragonmaw Base Camp in Shadowmoon Valley.", completion = "Interesting... Your next match will undoubtedly prove much more difficult. Corlok is no slouch." }
WordHunterWoW_QuestEN[11068] = { title = "Dragonmaw Race: Corlok the Vet", description = "You are challenging ME? Don't make me laugh!\n\nYou're serious? Very well then! All you need to do is not die. You can manage to not die, right?? Even if I'm hurling skulls at you and flying circles around your pathetic riding skills?\n\nJust let me know when you're ready and we'll lift off.", objectives = "Follow Corlok the Vet while attempting to stay on your flying mount. Should you defeat Corlok the Vet, report your victory to Ja'y Nosliw at the Dragonmaw Base Camp in Shadowmoon Valley.", completion = "The next two riders were the two top pilots that the dwarves and orcs of Azeroth had to offer. You stand no chance!" }
WordHunterWoW_QuestEN[11069] = { title = "Dragonmaw Race: Wing Commander Ichman", description = "Three years I spent in that hell hole. Three years a prisoner of war to the damnable Frostwolf Clan. Made to sit in their tower and listen to them endlessly whine about the bridge to Dun Baldar. About how it's \"unfair\" that blah, blah, blah, blah... War isn't fair! To hell with 'em all!\n\nThe minute I was freed I left that place forever and came here to start a new life. Now Mulv and I are vying for the top orc spot. If you want it, you're gonna have to go through me, scrub.\n\nWe go when you're ready.\n", objectives = "Follow Wing Commander Ichman while attempting to stay on your flying mount. Should you defeat Wing Commander Ichman, report your victory to Ja'y Nosliw at the Dragonmaw Base Camp in Shadowmoon Valley.", completion = "I don't believe it! Mulverick is your next challenge. There's no way you'll survive that match." }
WordHunterWoW_QuestEN[11070] = { title = "Dragonmaw Race: Wing Commander Mulverick", description = "Three years of blood, sweat and tears. Mostly tears... The amount of crying that a hardened soldier does when it comes down to all-out war is amazing!\n\n\"They're jumping into our tower with their horses!\" \"Why is their base so well defended?\" \"They're taking our relief hut, I'm going A.W.O.L.!\"\n\nWimps...\n\nI took the first train out of \"cry-town\" the minute the Dark Portal opened. Now I'm a top gun for the Dragonmaw. If you want to be top orc, you'll have to defeat me.\n\nWe go when you are ready.\n", objectives = "Follow Wing Commander Mulverick while attempting to stay on your flying mount. Should you defeat Wing Commander Mulverick, report your victory to Ja'y Nosliw at the Dragonmaw Base Camp in Shadowmoon Valley.", completion = "Well it looks like it's just you and the captain now, grunt. Good luck! You're gonna need it!" }
WordHunterWoW_QuestEN[11071] = { title = "Dragonmaw Race: Captain Skyshatter", description = "You dare challenge Skyshatter? The world around you will fall into darkness as the heavens are torn asunder by my meteors.\n\nYou stand no chance, soldier. Yet it is your desire to die...\n\nI will entertain this morbid obsession if only to prove a point to any that might foolishly dream of making the same mistake.\n\nWe ride when you are ready!", objectives = "Follow Captain Skyshatter while attempting to stay on your flying mount. Should you defeat Captain Skyshatter, report your victory to Ja'y Nosliw at the Dragonmaw Base Camp in Shadowmoon Valley.", completion = "I never dreamed any would be skilled enough to defeat Skyshatter. You do know what this means, right? You are now the top orc! You must defend your title." }
WordHunterWoW_QuestEN[11072] = { title = "Adversarial Blood", description = "The descendants held prisoner by the Skettis talonpriests are listed in this book: Gezzarak the Huntress, Karrog the crystal giant, the heretic known as Darkscreecher Akkarai and Vakkiz the Windrager.  They will all need to be slain before Terokk returns to this world.\n\nYou will need the scrolls carried by the time-lost arakkoa to call them forth at the summoning circles in Skettis.  Bring me a token from each one.  These are powerful beings you will be facing; you would do well to bring friends.", objectives = "Find the Skull Piles in the middle of the summoning circles of Skettis. Summon and defeat each of the descendants by using 10 Time-Lost Scrolls at the Skull Pile. Return to Hazzik at Blackwind Landing with a token from each.", progress = "Have you completed your task, <name>?", completion = "Excellent!  Take this.  I've prepared this bundle with the items you obtained.  They will allow you to summon Terokk.\n\nBeware, <name>.  He is the most powerful arakkoa to ever exist.  Do not underestimate him!" }
WordHunterWoW_QuestEN[11073] = { title = "Terokk's Downfall", description = "I... I've turned a blind eye to your dealings with the arakkoa prisoner, {name}.  It looks like your instincts to cooperate with him were right.\n\nYou must understand... I would've faced a mutiny in my current state if I endorsed your efforts to bring Terokk to this world.\n\nTake the items that Hazzik prepared for you and go ahead with your plan.  I will command my men to back you up when the time comes.  I recommend that you bring a force of your own as well.  I fear you'll only get one chance at this.", objectives = "Take the Time-Lost Offering prepared by Hazzik to the Skull Pile at the center of Skettis and summon and defeat Terokk. Return to Sky Commander Adaris when you've completed this task.", completion = "You've made us all very proud, <name>.  I'll send word of your deeds back to Shattrath.  The Skyguard will be forever in your debt." }
WordHunterWoW_QuestEN[11074] = { title = "Tokens of the Descendants", description = "The descendants held prisoner by the Skettis talonpriests are listed in this book.  Gezzarak the Huntress, Garokk the Crystal Giant, the heretic known as Darkscreecher Akkarai and Vekkaz the Windrager.  They will all need to be slain before Terokk returns to this world.\n\nYou will need the scrolls carried by the time-lost arakkoa and burn them at the summoning circles all over Skettis.  Bring me a token from each one.  These are powerful beings you will be facing; you would do well to bring friends.", objectives = "Collect Time-Lost Scrolls from the time-lost arakkoa in Skettis and bring them to a Skull Pile inside a summoning circle in Skettis. Summon and defeat the descendants of Terokk's adversaries and return to Hakkiz with Akkarai's Talon, Garokk's Spine, Vekkaz's Scale and Gezzarak's Claw.", progress = "I require a token from each of the descendants of Terokk's greatest adversaries.  Only then will we be ready to summon Terokk.", completion = "Excellent!  Take this.  I've prepared this bundle with the items you obtained.  They will allow you to summon Terokk.\n\nBeware, <name>.  He is the most powerful arakkoa to ever exist.  Do not underestimate him!" }
WordHunterWoW_QuestEN[11075] = { title = "The Netherwing Mines", description = "Your help is required at the Netherwing Mines, overseer {name}.\n\nTwo days ago our mining operations came to a grinding halt when we made a grim discovery. A miner was working in the depths of the mine and struck his pick upon an unusual crystal formation. Unfortunately, this crystal formation was attached to a very angry nether dragon. The beast woke from its slumber and annihilated all of our workers.\n\nReport to the Mistress of the Mines. They await you at the mouth of the mines, southwest of here.", objectives = "Seek out the Mistress of the Mines on Netherwing Ledge.", completion = "The miners are working hard but none dare step foot further into the mines. They choose death rather than being forced to mine deeper! It is going to be your job to carry out the duties and tasks that they failed to complete." }
WordHunterWoW_QuestEN[11076] = { title = "Picking Up The Pieces...", description = "Much of our hard work lies scattered about in these mines. Carts full of cargo are littered across every inch of this mine! We just can't get to any of it with the current infestation.\n\nThat's where you come in, {name}. Your daily duty here at this mine is to collect the cargo left behind by the miners and deep mine workers.\n\nGather the nethermine cargo and return it to me or my sister.", objectives = "The Mistress of the Mines at the Netherwing Mines in Shadowmoon Valley wants you to recover 15 Nethermine Cargo crates.", progress = "Have you gathered the cargo?", completion = "Well done, <name>. Return tomorrow for another mission into the depths of the mine." }
WordHunterWoW_QuestEN[11077] = { title = "Dragons are the Least of Our Problems", description = "That dragon waking up riled up a host of other nasty creatures in these mines. Two types are proving to be a thorn in the side of the Dragonmaw: Nethermine flayers and Nethermine ravagers. You must help us by killing them off. All I ask is your involvement once per day.\n\nGet in there and kill as many as you can!", objectives = "The Dragonmaw Foreman at the Netherwing Mines in Shadowmoon Valley wants you to kill 15 Nethermine Flayers and 5 Nethermine Ravagers.", progress = "How's that flayer infestation problem coming along?", completion = "That'll be enough for today, overseer. Come back tomorrow for another round of clean up." }
WordHunterWoW_QuestEN[11078] = { title = "To Rule The Skies", description = "As ye've flown around, ye must have noticed the dragons above.  I trust ye haven't fallen victim ta their rage.  Help us put an end ta it, {name}!\n\nRivendark and Obsidia lord over this terrace, while Insidion and Furywing rule the skies over yon terrace ta the northeast.  Each has a perch on their respective domains.  I be wondering if ye and yer friends will go ta one, lad, break open an egg with 35 apexis shards and attract the dragon down.\n\nBring me some teeth as proof.", objectives = "Collect Dragon Teeth.", progress = "How fares yer mission, <name>?  I needn't tell ye how important this be ta our continued ability ta fly around up here.", completion = "Yes!  Those teeth look like they be sharp enough ta cut through just about anything!\n\nAnd let me encourage ye and yer friends ta keep up the good work!  Those dragons be fierce predators that make the skies wholly unsafe.\n\nYe might have noticed, too, the dragon scales.  I hear they be good fer making powerful cloaks if ye get one o' each o' their scales.  And if yer not happy with the cloak ya get, I'll be willing ta trade ye an apexis crystal fer it." }
WordHunterWoW_QuestEN[11079] = { title = "A Fel Whip For Gahk", description = "Gahk think being smart is dumb sometimes.  Gahk not want to think.  Me want little {race} to smash big demons!\n\nDey have some chiefs, and da chiefs all have whips to hurt da little demons.  You bring Gahk a whip!\n\nYou challenge demon chief in forge camps at burning, green, fel crystal prism.  Use 35 apexis shards to get dem to come.  Dey called Galvanoth, Braxxus, Zarcsin and da Mo'arg Incinerator.", objectives = "Collect a Fel Whip.", progress = "Yous have da whip?", completion = "Gahk like whip.  Maybe Gahk take whip and beat demons with it!\n\nMe say to <race> that <race> summon demon chiefs anytime <race> have friends and many shards." }
WordHunterWoW_QuestEN[11080] = { title = "The Relic's Emanation", description = "Now that you have felt the enlightening vibrations of the apexis relics, it is time for you to further your understanding of their workings.  We are very eager to benefit from your observations!\n\nAs you progress in your ability to attune to the relics, you will gain a higher level of knowledge.  This recognition will come in the form of an emanation from the relic.\n\nReturn to us when you have attained such an emanation.", objectives = "Gain Apexis Emanations from an Apexis Relic.", progress = "Do you have the emanation from the apexis relic about you?", completion = "You continue to amaze us with your acumen as concerns the relics, <name>.  May we suggest that you practice with the relics at least once a day to maintain such a sharp edge to your mental acuity?" }
WordHunterWoW_QuestEN[11081] = { title = "The Great Murkblood Revolt", description = "This document outlines a revolt planned by the Murkblood broken. It seems that the dragon was to be used as a diversion to draw attention away from their escape. Looking at all of the corpses littering the mine, it would be safe to assume that their plans failed.\n\nReturn the escape plans to the Mistress of the Mines.", objectives = "Take the Murkblood Escape Plans to the Mistress of the Mines.", progress = "What's this?", completion = "Excellent work, overseer. Mor'ghor will hear of your outstanding service to the Dragonmaw.\n\nNow back to these Murkblood dogs. They plan an escape, eh? Dare they defy the one true lord of Outland? Their masters will pay for this!" }
WordHunterWoW_QuestEN[11082] = { title = "Seeker of Truth", description = "These miners are far too stupid to concoct any type of escape plan. We must find and punish the source. Venture into the depths of the mine and seek out the Murkblood overseers. If they have not been overcome by the denizens of the mine, they will undoubtedly be hiding.\n\nOnce you locate one, interrogate him until he reveals the true mastermind behind the escape. Return to me with the identity of this traitor and the hand of the overseer.", objectives = "Find a Murkblood Overseer and interrogate him. Return to the Mistress of the Mines with the Murkblood information and the Hand of the Overseer.", progress = "Well? What's taking so long?", completion = "Nothing to say? Perhaps as he lies bleeding to death on the floor of this cursed mine he will remember... Remember what it means to cross the forces of Illidan!" }
WordHunterWoW_QuestEN[11083] = { title = "Crazed and Confused", description = "Don't worry about this dragon, {name}. We've got plans for it...\n\nDeeper in this mine is a band of crazed Murkblood. After the dragon broke out, they were cut off from the exit. Somehow, after a mere 2 days of isolation, they've lost all sense of decency.\n\nThey've resorted to cannibalism and the promotion of mayhem. We don't need that kind of madness in this place. Find 'em and kill 'em. All of 'em.", objectives = "Ronag the Slave Driver in the Netherwing Mines of Shadowmoon Valley wants you to slay the Crazed Murkblood Foreman and 5 Crazed Murkblood Miners.", progress = "Is the problem \"solved\"?", completion = "Yeah, I don't understand it... You would think that they wouldn't even be that hungry after 2 days. Murkblood...\n\n<Ronag shakes his head.>\n\nDamn they're stupid..." }
WordHunterWoW_QuestEN[11084] = { title = "Stand Tall, Captain!", description = "Well, well, well... still alive I see. That's good, because Mor'ghor has requested your presence in his tower at once. Get a move on!", objectives = "Speak with Overlord Mor'ghor at Dragonmaw Base Camp in Shadowmoon Valley.", completion = "<Mor'ghor nods.>\n\nThat's right, I said captain. You've earned another promotion, <name>.\n\nYou certainly don't work like any fel orc I've ever seen. Keep this up and you might make overlord some day.\n\nNow get out there and take command. I would suggest you try and earn your Skybreaker wings." }
WordHunterWoW_QuestEN[11085] = { title = "Escape from Skettis", description = "Hail, {name}.  I thank you for coming to my aid.\n\nThe arakkoa's monstrous birds knocked me from my nether ray while on a scouting mission.\n\nLet's get out of here, while we can.", objectives = "Escort the Skyguard Prisoner to safety and report to Sky Sergeant Doryn.", completion = "Thank you for rescuing one of our scouts, <name>.  We lose good people every day and there aren't enough new recruits to replace them." }
WordHunterWoW_QuestEN[11086] = { title = "Disrupting the Twilight Portal", description = "One of your responsibilities as a captain of Dragonmaw is to snuff out Burning Legion activity in Outland. It is your duty to silence those that defy Lord Illidan!\n\nThe demons foolishly attempt to stabilize the portal found on the Twilight Ridge of western Nagrand. They must pay for their treachery, and you will be the orc that collects on their debt.\n\nTravel to the Twilight Ridge and lay waste to its inhabitants. You will be responsible for making at least one attack per day on their fortifications.", objectives = "Overlord Mor'ghor at Dragonmaw Base Camp in Shadowmoon Valley wants you to kill 20 Deathshadow Agents.", progress = "It was our lord, after all, that banished the demons from Outland and closed their portals. All should bow down to the magnificence of Illidan.", completion = "Excellent work, captain! Lord Illidan will hear of your heroism!" }
WordHunterWoW_QuestEN[11087] = { title = "HYJAL FLAG", description = "Seven vials were drawn from the Well of Eternity by Illidan.  He poured three into the lake on top of Mount Hyjal and a second Well of Eternity was created.  For years the rest were believed lost.\n\nWith the opening of the Dark Portal, we've come to know that he gave one each to his lieutenants Kael'thas and Vashj.  Retrieve what remains of them; we will need them as foci to open a gateway to any events tied to Mount Hyjal, recent or ancient.  The outcome of the Battle of Mount Hyjal must be preserved.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Soridormi at Caverns of Time wants you to retrieve Vashj's Vial Remnant from Lady Vashj at Coilfang Reservoir and Kael's Vial Remnant from Kael'thas Sunstrider at Tempest Keep." }
WordHunterWoW_QuestEN[11088] = { title = "<DEPRECATED>Unravelling Your Training", description = "Bring me a lot of Spellfire cloth, and then you can forget everything.You will learn:", objectives = "Bring Jonathan LeCraft 10 pieces of Spellfire cloth." }
WordHunterWoW_QuestEN[11089] = { title = "The Soul Cannon of Reth'hedron", description = "Reth'hedron now lords over the Twilight Ridge of Nagrand. An eredar of such power being loosed upon this world does not bode well for the Illidari. Alas, we do not have the resources required to slay Reth'hedron. Not with the war the Sha'tar have brought to the Black Temple. No... I have a better plan.\n\nYou will subdue Reth'hedron, banishing him back through the Twilight Portal. For this a soul cannon must be fashioned.\n\nReturn to me with the materials on this list.", objectives = "Illidari Lord Balthas at the Dragonmaw Base Camp in Shadowmoon Valley wants you to bring him 2 Felsteel Bars, 1 Adamantite Frame, 1 Khorium Power Core and 1 Flawless Arcane Essence.", progress = "Have you gathered the components required to fashion the soul cannon?", completion = "<Balthas deftly combines the components you brought him.>\n\nYou are now ready for the second phase of the plan, captain." }
WordHunterWoW_QuestEN[11090] = { title = "Subdue the Subduer", description = "<Balthas holds up an alien looking device.>\n\nThis is a soul cannon. Its effects are devastating when attuned. This one is attuned to my blood. The same blood flowing through the veins of Reth'hedron - my brother. Aye, his misplaced allegiance will be the end of him.\n\nTake the cannon and fly to the Twilight Ridge in western Nagrand. Locate Reth'hedron and fire! You must stay on your mount and within range for the effects to take hold. Stand your ground against him and he will have no choice but to flee!", objectives = "Illidari Lord Balthas at Dragonmaw Base Camp in Shadowmoon Valley has tasked you with using the Soul Cannon on Reth'hedron the Subduer in Nagrand.\n\nYou must also return the Soul Cannon.", progress = "Is it done?", completion = "He will be back, but for now the Legion's war against Lord Illidan is weakened. He shall know of your deeds, captain." }
WordHunterWoW_QuestEN[11091] = { title = "A Special Thank You", description = "You honor us with your efforts on our behalf.  And now there is someone that we would like for you to meet.\n\nJho'nass is our most trusted quartermaster.  He maintains a stock of goods that we provide for sale to only the most dedicated of friends to Ogri'la.\n\nYou are one such friend, {name}.\n\nWhen you find the time, go and speak with him.  As we understand it, he has prepared a little something for you as a token of our appreciation.", objectives = "Speak with Jho'nass at Ogri'la in the Blade's Edge Mountains.", completion = "Hey, man, that's great.  We hear you've been doing good things.  That's cool.  We've got a feeling that you're going to make things right for us here in Ogri'la, and keep us safe, and everything nice and mellow.\n\nHere, take this.  It's nothing much, just a care package that we whipped up as a thanks for your effort.\n\nFeel free to look around at our goods.  We have a lot of really choice stuff that you're gonna want to get." }
WordHunterWoW_QuestEN[11092] = { title = "Hail, Commander!", description = "Captain {name}!\n\n<Taskmaster Varkule salutes you.>\n\nOverlord Mor'ghor has asked to see you in his chambers at once!", objectives = "Speak with Overlord Mor'ghor at Dragonmaw Base Camp in Shadowmoon Valley.", completion = "Lord Illidan himself has asked that I promote you to the rank of commander! This is unprecedented. You will be the first Dragonmaw to reach such a rank outside of the Black Temple." }
WordHunterWoW_QuestEN[11093] = { title = "Hungry Nether Rays", description = "Nether rays are surprisingly loyal and obedient once properly trained.  Unfortunately the war on Skettis is taking a toll on them.\n\nWe have dozens of sorties a day - the poor fellows rarely get a break.  And with recent shortages on feed, if those blasted birdmen don't kill them on a mission then starvation will.\n\nIf you can lend a hand, take one of our rays to the woods in the south.  They don't mind warp chaser meat as long as it's a fresh kill.", objectives = "Use the Nether Ray Cage in the woods south of Blackwind Landing and slay Blackwind Warp Chasers near the Hungry Nether Ray. Return to Skyguard Handler Deesak when you've completed your task.", progress = "You're back!  Did your ray behave well?", completion = "Thanks for taking care of the ray, <name>.  Goodness knows these guys fly much better when they're well-fed.  We don't want our boys getting shot down because their ray was too weak to fly." }
WordHunterWoW_QuestEN[11094] = { title = "Kill Them All!", description = "Commander {name}, stand at attention! You are to take a battalion of Skybreakers and sack the Scryers' outpost located at the foot of the Netherwing Fields. With the Sanctum of the Stars destroyed, our lines of communication to our posts at Eclipse Point and Illidari Point will once more be open.\n\nGo now! Use this flare gun to signal the Skybreakers for the attack!", objectives = "Deliver news of your mission along with the Dragonmaw Flare Gun to Arcanist Thelis at the Sanctum of the Stars in Shadowmoon Valley.", progress = "Settle down, child.", completion = "It is good that you came to us. Perhaps we can use this attack to our advantage and turn the tables on the Dragonmaw." }
WordHunterWoW_QuestEN[11095] = { title = "Commander Hobb", description = "The Dragonmaw only dare attack us when our guard is down. They would face certain defeat if they were to attack us while we were prepared.\n\nI want you to let them come, {name}.\n\n<Thelis nods.>\n\nYes... a trap. Take this flare that their overlord gave you and deliver it to Commander Hobb. He is standing guard right outside this building.", objectives = "Give the Dragonmaw Flare to Commander Hobb at the Sanctum of the Stars in Shadowmoon Valley.", progress = "<Hobb nods.>", completion = "<Hobb grins.>\n\nThe deadliest trap ever laid..." }
WordHunterWoW_QuestEN[11096] = { title = "Threat from Above", description = "So you want to join the Skyguard?  Well, I know you can fly... but can you fight?\n\nThe Skyguard is sworn to protect Shattrath from the dangers that loom above us, both near and far.  The Gordunni ogres who dwell in the Barrier Hills to the north are an immediate threat to us.\n\nReaching the ogres has been problematic for Shattrath's ground units.  That's where we come in.  See what you can do to help contain them.", objectives = "Slay any 20 Gordunni Ogres in the Barrier Hills and return to Yuula in Shattrath City.", progress = "Have you completed your task, <name>?", completion = "Good job, ace.  I've a feeling you're going to fit in well with us." }
WordHunterWoW_QuestEN[11097] = { title = "The Deadliest Trap Ever Laid", description = "Take these Scryer medals. Mor'ghor will need proof of \"victory\" once this is over. He will recognize them as coming from the corpses of fallen Scryer soldiers.\n\nNow all that remains is to use the signal flare to alert the Dragonmaw raiders. We will crush them when you are ready. Just give me the word.", objectives = "Assist Commander Hobb and the Scryers in defending the Sanctum of the Stars. Once all of the Dragonmaw forces have been defeated, return to Overlord Mor'ghor at Dragonmaw Base Camp with the Scryer Medals.", progress = "Did you crush them under your boot, commander?", completion = "<Mor'ghor laughs.>\n\nHAH! I knew you wouldn't let me down, commander! I want you to lead a raid on the Sanctum of the Stars at least once per day. They will have no choice but to leave Shadowmoon!" }
WordHunterWoW_QuestEN[11098] = { title = "To Skettis!", description = "The Barrier Hills are only one of the fronts where we've been deployed.  A less immediate but far more dangerous threat looms from beyond the Skethyl Mountains, from within the arakkoa city of Skettis.\n\nA few months ago our scouts detected a huge increase in arakkoa activity there.  Several attacks against Shattrath followed.  We've stationed forces outside of their city since.\n\nTake these explosives to Sergeant Doryn at Blackwind Landing, just outside Skettis.  Tell him you're a new recruit.", objectives = "Take the Explosives Package to Sky Sergeant Doryn at Blackwind Landing outside Skettis.", progress = "You've something for me, lad?", completion = "Thanks for the supplies; we'll put them to good use!  A new recruit?  Well, let's see what you're made of." }
WordHunterWoW_QuestEN[11099] = { title = "Kill Them All!", description = "Commander {name}, stand at attention! You are to take a battalion of Skybreakers and sack the Aldor outpost located northwest of our beloved Black Temple. With the Altar of Sha'tar destroyed, our lines of communication to our posts at Coilskar will once more be open.\n\nGo now! Use this flare gun to signal the Skybreakers for the attack!", objectives = "Deliver news of your mission and the Dragonmaw Flare Gun to Anchorite Ceyla at the Altar of Sha'tar.", progress = "Settle down, child.", completion = "It is good that you came to us. Perhaps we can use this attack to our advantage and turn the tables on the Dragonmaw." }
WordHunterWoW_QuestEN[11100] = { title = "Commander Arcus", description = "The Dragonmaw only dare attack us when our guard is down. They would face certain defeat if they were to attack us while we were prepared.\n\nI want you to let them come, {name}.\n\n<Ceyla nods.>\n\nYes... a trap. Take this flare that their overlord gave you and deliver it to Commander Arcus. He is standing guard right outside this building.\n", objectives = "Give the Dragonmaw Flare to Commander Arcus at the Altar of Sha'tar in Shadowmoon Valley.", progress = "<Arcus nods.>", completion = "<Arcus grins.>\n\nThe deadliest trap ever laid..." }
WordHunterWoW_QuestEN[11101] = { title = "The Deadliest Trap Ever Laid", description = "Take these Aldor medals. Mor'ghor will need proof of \"victory\" once this is over. He will recognize them as coming from the corpses of fallen Aldor soldiers.\n\nNow all that remains is to use the signal flare to alert the Dragonmaw raiders. We will crush them when you are ready. Just give me the word.", objectives = "Assist Commander Arcus and the Aldor in defending the Altar of Sha'tar. Once all of the Dragonmaw forces have been defeated, return to Overlord Mor'ghor at Dragonmaw Base Camp with the Aldor Medals.", progress = "Did you crush them under your boot, commander?", completion = "<Mor'ghor laughs.>\n\nHAH! I knew you wouldn't let me down, commander! I want you to lead a raid on the Altar of Sha'tar at least once per day. They will have no choice but to leave Shadowmoon!" }
WordHunterWoW_QuestEN[11102] = { title = "Bombing Run", description = "You can fly around as a crow... so what!  Ever annihilate something on the ground while you were flying?  Want to?\n\nForge Camp: Wrath and Forge Camp: Terror, to the north and south, are a major pain in my backside, as well as being a threat to peaceful Ogri'la.  With all of those fel cannons shooting down the Skyguard left and right, we can't get through there to take care of business.\n\nWant to prove yourself?  Take these bombs and knock out their ammo stacks.  Just don't let them shoot you down, too!", objectives = "Use the Skyguard Bombs to destroy 15 Fel Cannonball Stacks.", progress = "You take out their stacks of fel cannonballs yet?", completion = "Well, well, well, I guess you had it in you after all.  Good work.  Maybe Old Man Keller was wrong about you after all.\n\n<Sky Sergeant Vanderlip smirks.>" }
WordHunterWoW_QuestEN[11103] = { title = "Sage No More", description = "", objectives = "The power within your ring is malleable, though reversing your choice is not easy.  Are you sure you want to replace its current form?", progress = "The power within your ring is malleable, though reversing your choice is not easy.  Are you sure you want to replace its current form?", completion = "The sands of time flow forwards easily.  They can be made to flow backward, but with great difficulty." }
WordHunterWoW_QuestEN[11104] = { title = "Restorer No More", description = "", objectives = "The power within your ring is malleable, though reversing your choice is not easy. Are you sure you want to replace its current form?", progress = "The power within your ring is malleable, though reversing your choice is not easy. Are you sure you want to replace its current form?", completion = "The sands of time flow forwards easily. They can be made to flow backward, but with great difficulty." }
