WordHunterWoW_QuestEN[11106] = { title = "Defender No More", description = "", objectives = "The power within your ring is malleable, though reversing your choice is not easy. Are you sure you want to replace its current form?", progress = "The power within your ring is malleable, though reversing your choice is not easy. Are you sure you want to replace its current form?", completion = "The sands of time flow forwards easily. They can be made to flow backward, but with great difficulty." }
WordHunterWoW_QuestEN[11107] = { title = "Bow to the Highlord", description = "I am unworthy to even carry a message directed at you, sir. Please forgive me for this indulgence. Overlord Mor'ghor has requested your presence in his chambers at once!", objectives = "Speak to Overlord Mor'ghor at Dragonmaw Base Camp in Shadowmoon Valley.", completion = "You are the first highlord of the Dragonmaw, <name>. The master himself has chosen to come here to promote you." }
WordHunterWoW_QuestEN[11108] = { title = "Lord Illidan Stormrage", description = "Come, highlord {name}. Illidan himself awaits us!", objectives = "Meet Illidan Stormrage. Seek out Barthamus in the Lower City of Shattrath should you survive.", completion = "I was the first, you know. The abandoned child of a monster...\n\n<Barthamus shakes his head.>\n\nWe owe you everything, <name>. You have single-handedly shattered the Dragonmaw empire and gathered enough information to keep my brethren occupied for ten lifetimes.\n\nIt is not much but there is something that we can offer... My kin have each offered to join you on your mission in Outland. Simply ask and they will bond with you." }
WordHunterWoW_QuestEN[11109] = { title = "Jorus the Cobalt Netherwing Drake", description = "", objectives = "It is an honor to meet you, <name>. We have all been keeping a close eye on your adventures and are grateful for all that you have done for the Netherwing Dragonflight.\n\nIf you choose me as your compatriot, I will fly you to the ends of this world and back. Whatever it is that you ask of me, I will do my best to comply.\n\nBe warned that you may only select one of us for your journeys in Outland. Once the selection has been made, you cannot change your mind." }
WordHunterWoW_QuestEN[11110] = { title = "Malfas the Purple Netherwing Drake", description = "", objectives = "It is an honor to meet you, <name>. We have all been keeping a close eye on your adventures and are grateful for all that you have done for the Netherwing Dragonflight.\n\nIf you choose me as your compatriot, I will fly you to the ends of this world and back. Whatever it is that you ask of me, I will do my best to comply.\n\nBe warned that you may only select one of us for your journeys in Outland. Once the selection has been made, you cannot change your mind." }
