WordHunterWoW_QuestEN[11115] = { title = "The Mark of Vashj (FLAG ONLY)", description = "", objectives = "" }
WordHunterWoW_QuestEN[11116] = { title = "Trial of the Naaru: (QUEST FLAG)", description = "Four trials you must pass before you are deemed worthy of the Tempest key.\n\nOnly one obstacle remains, mortal. Gather an army and travel to the lair of Magtheridon, deep inside Hellfire Citadel. Battle your way to the heart of the chamber and destroy the foul corrupter!\n\nDo this and you will be granted the Tempest key.You will receive:", objectives = "A'dal in Shattrath City wants you to slay Magtheridon." }
WordHunterWoW_QuestEN[11117] = { title = "Catch the Wild Wolpertinger!", description = "Here now. Ye hear that? There be sounds in them hills. Those're the wolpertingers! Wily beasts, they are, attracted by the smells o' Brewfest. I've a mind to catch me some, but I knocked me shin and can't outrun the buggers. Ye can help me, though!\n\nTake this net and cast it over the little blighters. Bring me a good five of 'em and I'll make it worth yer while!\n\nOne more thing - ye gotta use Synthebrew Goggles to spot 'em! Let me know if ya need a pair.", objectives = "Goldark Snipehunter has asked you to capture 5 Stunned Wolpertingers using the Wolpertinger Net. He mentioned that you must be wearing Synthebrew Goggles to see them.", progress = "Did ya see the little buggers?", completion = "Well, lookee there! Ye've got yerself a right bushel o' wolpertingers, ye do!\n\n<He takes a deep drink from his tankard.>\n\nI'll tell ye what I'm gonna do. Since ye're such a spot-on hunter, I'll let ye keep one'a these fer yer very own!" }
WordHunterWoW_QuestEN[11118] = { title = "Pink Elekks On Parade", description = "Getting drunk is a time-honored tradition at Brewfest -- it's damn near required! Thing is, I'm getting reports across Azeroth saying the celebration's plagued by hallucinations!  We can't have that!\n\nThese elekks can't be harmed by normal weapons -- they pass right through 'em -- so take this fabulous piece of gnomish machinery, visit one of the other beer gardens, and zap 'em to oblivion.\n\nRemember, you have to be wearing Synthebrew Goggles to see 'em! Talk to me if you need a pair.", objectives = "Visit the beer gardens outside Stormwind, Darnassus, or the Exodar, zap three elekks at any location, and return to Goldark Snipehunter. You must be wearing Synthebrew Goggles to see the pink elekks.", progress = "Are those pesky pink elekks gone yet?", completion = "Good work! Pink elekks... what a preposterous notion!" }
WordHunterWoW_QuestEN[11119] = { title = "Assault on Bash'ir Landing!", description = "Heya, boyo!  Up fer some fun are ye?\n\nEvery couple o' hours, me aether-techs launch an assault on Bash'ir Landing, far ta the northeast in the Blade's Edge Mountains.  They say that they're there 'studying' the Bash'ir crystalforge, but it's an assault; there be no two ways about it.  We use the crystalforge to resupply, and there's always extra to be sold.\n\nGo on down ta the landin' pad and speak with the aether-tech apprentice.  He'll tell ye when the next mission is ta launch.", objectives = "Speak with the Aether-tech Apprentice at Skyguard Outpost in the Blade's Edge Mountains.", completion = "Despite how Keller cares to characterize it, I prefer to think of our missions as research-oriented.\n\nBut yes, we do resupply the Skyguard while we're there.  That is if we can stay long enough to do so.\n\nYou look like you'd be willing to keep the ethereals off of our backs.  If you can manage to for long enough, we'll sell you surplus items that we create at the crystalforge, so bring your apexis shards and crystals!\n\nWe leave in 0 |4minute:minutes;." }
WordHunterWoW_QuestEN[11120] = { title = "Pink Elekks On Parade", description = "Brewfest is a time-honored celebration of food and drink. But sometimes drink gets the better of you! Excessive brew drinking can lead to many side effects... and we're getting many reports on hallucinations!\n\nFolks have been talking about seeing pink elekks, and I need you to take care of them. Take this goblin-engineered ray gun to one of the beer gardens and zap the elekks away. To keep yourself safe, I recommend wearing Synthebrew Goggles to see your targets while still keeping your wits about you.", objectives = "Visit the beer gardens outside of Silvermoon, Thunder Bluff, or the Undercity, zap 3 Pink Elekks at any location, and return to Snipehunter Goro. You must be wearing Synthebrew Goggles to see them.", progress = "Ya clear up that little problem we talked about?", completion = "Ya did good, kid. Here, take this as payment for the job ya did." }
WordHunterWoW_QuestEN[11121] = { title = "DAILY TEST QUEST (RAID)", description = "<NYI>Seek <QUESTGIVER> in <LOCATION>.  S/he wishes for you to aid them in a difficult task.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak with <QUESTGIVER> in the <AREA>.<NYI>Seek <QUESTGIVER> in <LOCATION>. S/he wishes for you to aid them in a difficult task.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[11122] = { title = "There and Back Again", description = "So you want to help out at Brewfest? I've got the perfect task for ya. I'll put you on one of my racing rams and you head down to Kharanos. I've got some kegs I need to pick up. \n\nFlynn Firebrew is waiting on a hill near a stack of kegs. He'll toss you a keg when you get near, then you run the keg back here and toss the keg to Pol Amberstill. You can only carry one at a time. \n\nReady?", objectives = "Get a keg from Flynn Firebrew in Kharanos and return it to Pol Amberstill. If you lose your ram, ask Neill Ramstein for another.", progress = "I need those kegs!  So, what are yeh waitin' for!?!", completion = "Thanks a lot for your help!  As long as Brewfest is going and the Dark Iron dwarves are attacking, I'll need some help shipping kegs.  So if you want to work for more tokens, talk to me every day.\n\nBut enough about that, I need to pay you for the job you just did.  Here are your tokens, have fun at Brewfest!" }
WordHunterWoW_QuestEN[11123] = { title = "nspecting the Ruins", description = "Poor James never recovered from the destruction of the Shady Rest and the murder of his family. The boys and I are doing what we can to find the monsters who did this.\n\nI've sent our best investigator, Inspector Tarem, out to the ruins, but this is too big a job for any one man. If you'd lend Tarem a hand, we'd appreciate it. Light knows, we'd all like to be out there helping.\n\nThe main road will lead you to the inn, but take care. Your journey will take you beyond the protection of my soldiers.", objectives = "Speak to Inspector Tarem at the Shady Rest Inn.", completion = "It's good to see that Captain Vimes is finally assigning others to this investigation.\n\nI've used a reflective powder to dust the area. It will reveal suspicious objects and markings, helping you to focus your efforts. Look over anything the dust illuminates." }
WordHunterWoW_QuestEN[11124] = { title = "nspecting the Ruins", description = "If you follow the road south from the village, and then west toward the Barrens, you'll come across the ruins of the Shady Rest Inn.\n\nTheramore has sent an investigator to discover how the inn met its fate. I had a man placed in that inn as a spy and I don't trust in the competence of these humans to uncover what happened.\n\nWhatever you find, don't give a scrap of it to that investigator. We'll handle this ourselves.", objectives = "Investigate the Shady Rest Inn in at the border of the Barrens in Dustwallow Marsh.", completion = "<The inspector regards you with what can only be distrust.>\n\nI've been told that you're to... aid in this investigation. Very well, then.\n\nI've been using this powder to search the ruins for clues that might help identify the attackers. It will illuminate anything that might have been involved in the attack. Don't hesitate to examine anything that looks suspicious." }
WordHunterWoW_QuestEN[11126] = { title = "Traitors Among Us", description = "It's good to meet you, <class>. I've come to Theramore to help eliminate the problem of the deserters. Not only have some of the men abandoned their posts, but some have filtered back into the town.\n\nThese deserter agents are spreading lies and propaganda, hoping to convince others to join their ranks.\n\nThey're at virtually every guard post throughout the town and the docks. Find them, expose them, and discredit them. At this point, anything more risks inspiring more sympathy for them.", objectives = "Confront 5 Deserter Agitators and return to Calia Hastings near the docks in Theramore.", completion = "Well done, <name>. I think we managed to catch them off guard. Their agents probably thought themselves safe within the city walls.\n\nGiven time, the agitators will return and spread their lies again. We'll use the time you've bought to shut out the deserters further." }
WordHunterWoW_QuestEN[11128] = { title = "Propaganda War", description = "The deserter agents were doing far more than just chatting up the guards. We've found a number of leaflets the deserters somehow managed to smuggle in on a ship in the docks.\n\nThe ship used to transport the leaflets is still in Theramore, at the farthest dock. If you can sneak aboard and capture the rest of their propaganda documents, their agents will lose their most powerful tool. Be careful! The ship is manned by seasoned privateers and the cargo is probably being kept in the captain's quarters.", objectives = "Bring the Deserter Propaganda to Calia Hastings near the docks in Theramore.", progress = "Did you manage to find and capture the remaining propaganda leaflets?", completion = "<The SI:7 agent nods in approval.>\n\nExcellent. All that remains is to discredit the deserters so that they'll never gain a foothold in Theramore again, and I have just the plan to do it." }
WordHunterWoW_QuestEN[11129] = { title = "Kyle's Gone Missing!", description = "Help, {name}! My prized puppy, Kyle, has run away! I just know he's running around Bloodhoof Village, lost and hungry.\n\nWill you find him and feed him? Once he eats he will settle down and come home.\n\nTo feed him you will need to find food. His favorite meal is tender strider meat. Just venture east and you should find plenty of striders. Hunt one down and take its succulent meat to Kyle. When you see Kyle in town, put the meat down and he is sure to come to you.", objectives = "Ahab Wheathoof at Bloodhoof Village in Mulgore wants you to feed his prized puppy, Kyle the Frenzied.\n\nFeed Kyle Tender Strider Meat and return to Ahab Wheathoof.", progress = "Did you find Kyle?", completion = "Fantastic work, <name>! Kyle came home as soon as he ate and went straight to bed. Thank you for your help." }
WordHunterWoW_QuestEN[11130] = { title = "Oooh, Shinies!", description = "Come closer, <man/sweetheart>! Let ol' Griftah look at yer shiny things....\n\nHmm. Yeh, yeh, not bad, but ya can do better. Much, much better.\n\n<Griftah leans in and whispers.>\n\nThere be priceless shinies everywhere, <name>, ya just gotta know where to look! It be yer lucky day; I know a fella who can help ya find more shinies than ya can ever carry.\n\nVisit my ol' friend, Budd, near Zul'Aman and show him this here. Ya be tellin' him ol' Griftah sent ya and he'll let ya in on his new project.", objectives = "Griftah wants you to take Griftah's Note to Budd in the Ghostlands, just outside of Zul'Aman.", progress = "<Budd eyes the note suspiciously.>\n\nWhat have you there, <class>?", completion = "<Budd reads the note.>\n\nAhh! A friend of Griftah? Welcome!\n\nYou have impeccable timing, friend. As fate would have it, I recently lost my latest partners. Tragic, truly, but great rewards often have a high price. Best not to dwell on the negative!\n\nYou've doubtlessly heard of my countless exploits and discoveries. Well, all of that was nothing compared to this! Truth is, we're close to making history here at Zul'Aman and, by fate's decree, you're in on the ground floor!" }
WordHunterWoW_QuestEN[11131] = { title = "Stop the Fires!", description = "You must help us!  The Headless Horseman is attacking the village.  Fires are everywhere!  The children aren't safe!\n\nPlease, {name}, join the fire brigade.  Grab a bucket and toss it on the fires, or pass it to a friend who's closer to the blaze.  Put out all the fires and we may yet be saved!", objectives = "The Costumed Orphan Matron wants you to help put out all the village fires. When they are out, speak again to the Costumed Orphan Matron.", progress = "<name>, you promised to save the children!", completion = "Oh, thank you!  May the Light bless your good works, kind sir.  The shadow of the Dark Horseman yet looms, but at least, for now, the village is safe from his flames." }
WordHunterWoW_QuestEN[11132] = { title = "Promises, Promises...", description = "My inscrutable theories confirm rumors of vast treasure in Zul'Aman. There'll be mounts and mansions for everyone! First things first, though. You must earn your share, after all....\n\nOur initial efforts here haven't gone as well as I hoped. In fact, my map, and the recruits I lent it to, have gone missing. They were after a troll-beast named Nalorakk.\n\nForget the crew, I need that map! Succeed, and you'll go down in history as the one who helped Budd Nedreck unlock the secrets of Zul'Aman!", objectives = "Budd Nedreck in Hatchet Hills wants you to retrieve his map from High Priest Nalorakk's terrace in Zul'Aman.", progress = "Ahh yes, <name>, isn't it?\n\nHave you recovered my map yet?", completion = "<Budd looks a bit shocked.>\n\nOh? You've found it?\n\nAhem, I mean, of course you have! Well done, <class>.\n\nLet me see if I can find you a little something nice... ahh yes, this should do." }
WordHunterWoW_QuestEN[11133] = { title = "Discrediting the Deserters", description = "I've altered the leaflets you captured from the deserters' mercenary friends at the docks. Now, anyone who reads them will get an entirely different view of the deserters and their aims.\n\nIf we distribute these to enough of the guards, the deserters will be too embarrassed to ever reestablish their presence within our walls.\n\n<Calia hands you a stack of the altered leaflets.>\n\nWhy don't you get started while I plan our next move?", objectives = "Calia Hastings wants you to distribute the Altered Leaflets to 6 Theramore Guards, then report back to her near the docks in Theramore.", progress = "I thought I heard laughter coming from the barracks. Did you distribute those leaflets I gave you?", completion = "<Calia chuckles as you describe the guards' reactions to the propaganda.>\n\nJust as I'd hoped! I think it's safe to say any deserter agents who try to infiltrate Theramore will be laughed right out of town!" }
WordHunterWoW_QuestEN[11134] = { title = "The End of the Deserters", description = "Now that we've eliminated the deserters from Theramore, it's time to complete this operation. My local contacts have reported that the deserters base their operations in a ship moored on a small island to the southeast of the docks.\n\nArresting their leader, Gavis Greyshield, should cause the others to lose their will to fight. Find him within the ship and convince him to surrender. I wouldn't be surprised if he puts up a bit of a fight for show, but then surrenders when he understands he can't win.", objectives = "Capture Gavis Greyshield, then report to Calia Hastings near the docks in Theramore.", completion = "Gavis' request isn't as outlandish as it might sound. With the proper handling, Lady Jaina can return the deserters to the fold, but that is her decision, of course.\n\nIt's been a pleasure working with you, <name>. Without your help, I doubt the operation would've gone so smoothly. When I make my report in Stormwind, it will name you as the <class> who ended the deserter threat." }
WordHunterWoW_QuestEN[11135] = { title = "The Headless Horseman", description = "The Headless Horseman is driven away, but he will return as long as Hallow's End looms.  {name}, end our misery, and the insane lament of the Horseman.  Face him when he is joined with his head, and destroy it!\n\nHe rests in the Forlorn Cloister of the Scarlet Monastery, in Tirisfal Glades.  Find his pumpkin shrine and say this:\n\n  Horseman, rise\n  Your time is nigh\n  You felt death once\n  Now, know demise!\n\nGo, {name}.  And may the Light go with you.", objectives = "Find the Headless Horseman's pumpkin Shrine.The Headless Horseman is driven away, but he will return as long as Hallow's End looms. <name>, end our misery, and the insane lament of the Horseman. Face him when he is joined with his head, and destroy it!\n\nHe rests in the Forlorn Cloister of the Scarlet Monastery, in Tirisfal Glades. Find his pumpkin shrine and say this:\n\n  Horseman, rise\n  Your time is nigh\n  You felt death once\n  Now, know demise!\n\nGo, <name>. And may the Light go with you.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[11136] = { title = "A Disturbing Development", description = "Reports from our scout patrols have recently taken a disturbing turn. They tell of men wearing red Defias bandanas walking the Dreadmurk Shore north of Theramore's walls.\n\nWreckage in the area suggests they may be survivors of a shipwreck, but our information is limited. Captain Wymor at Sentry Point, a guard tower to the north of the city, is looking for help in following up on the reports.", objectives = "Report to Captain Wymor at Sentry Point.Reports from our scout patrols have recently taken a disturbing turn. They tell of men wearing red Defias bandanas walking the Dreadmurk Shore north of Theramore's walls.\n\nWreckage in the area suggests they may be survivors of a shipwreck, but our information is limited. Captain Wymor at Sentry Point, a guard tower to the north of the city, is looking for help in following up on the reports.", completion = "<The captain makes no effort to hide that he's assessing your abilities.>\n\nSo you've heard about the recent shipwreck off the coast? Good, I could use some help confirming my suspicions about the survivors. Welcome aboard, <name>." }
WordHunterWoW_QuestEN[11137] = { title = "efias in Dustwallow?", description = "My scouts have reported a shipwreck just off the beach to the northeast. Shipwrecks aren't all that unusual out here, but the reports also indicated the survivors were all wearing red bandanas!\n\nThe Defias are craftsmen and guildsmen, not sailors. What are they doing at the site of a shipwreck on a continent they've no interest in?\n\nTheir leader is rumored to reside on a large island just off the coast to the northeast of the tower. Kill him and retrieve any documents you find in his possession.", objectives = "Obtain the Defias Orders from Garn Mathers and bring them to Captain Wymor at Sentry Point.", progress = "Were you able to track down their leader?", completion = "<Captain Wymor accepts the orders from you and reads over them.>\n\nWhat in the world could 'precious cargo' refer to? The Defias have done some small time smuggling back in lands of Stormwind, but this seems out of their league. The language of these orders suggests a wealthy or noble patron." }
WordHunterWoW_QuestEN[11138] = { title = "enn McGill", description = "From the wording of the orders you recovered, it looks like the first priority of the Defias will be to locate and secure whatever cargo they possessed.\n\nSI:7 has had a salvage diver named Renn McGill working out of Theramore for some time. When he heard about the shipwreck, Renn went north to dive near the islands the Defias now occupy.\n\nIf we're to beat the Defias to this cargo, we'll need his help. Look for him in the waters northeast of a small island just north of the island you visited earlier.", objectives = "Bring the Defias Orders to Renn McGill in the waters off the Dreadmurk Shore.", progress = "Well met, <class>. What brings you out here?", completion = "<Renn looks over the orders.>\n\nSo there was valuable cargo on board! We have to locate it before the Defias recover it. These guys are no divers, but we're going to need some of their gear if you're to help me find the cargo." }
WordHunterWoW_QuestEN[11139] = { title = "econdhand Diving Gear", description = "There's plenty of wreckage strewn across the bottom of the water from here to Alcaz, and the Defias have already got divers out there looking around. With the help of some of their gear, we can get you suited up and ready to join the hunt, but you'll have to do some creative \"borrowing\" first.\n\nSearch this island for a crate of diving gear and something to repair it with. When you've got them, bring them to me and I'll have your gear ready in no time!", objectives = "Bring the Tool Kit and Damaged Diving Gear to Renn McGill in the Dustwallow Marsh.", progress = "Let's see what you managed to \"borrow\" from the Defias.", completion = "Wow, this is in worse shape than I'd thought, and these tools...\n\nWell, I said I'd get this back into working condition for you, so I'd better get to work." }
WordHunterWoW_QuestEN[11140] = { title = "ecover the Cargo!", description = "Well, I was able to make enough repairs to this gear to let you dive for awhile, anyway. I wouldn't count on it holding out for a long time, though.\n\nThe wreckage of the ship is strewn along the bottom from the east coast of this island out toward Alcaz Island. While that helm holds out, locate pieces of the wreckage on the bottom between this island and Alcaz. Use this salvage kit to search the wreckage for pieces of the cargo. Be careful not to venture too close to Alcaz Island. Those hydra are fierce.", objectives = "Bring 6 Salvaged Strongboxes to Renn McGill in Dustwallow Marsh.", progress = "Did your search of the wreckage reveal anything about the Defias cargo?", completion = "<Renn rifles through the contents of the strongboxes you recovered.>\n\nGood work. Now, let's see if our 'precious cargo' is in here...." }
WordHunterWoW_QuestEN[11141] = { title = "aina Must Know", description = "You must bring news of our findings to Lady Jaina without delay! If the Defias were transporting a prisoner, there's no telling who it might be or if the person is still alive!\n\nOne thing is for certain, <name>. The Defias wouldn't go to all this trouble for some petty grudge. Their prisoner must have been someone of importance. Lady Jaina would know better than anyone else what these findings mean. You'll find her at the top of the mage tower at Theramore's center.", objectives = "Speak with Lady Jaina Proudmoore in Theramore.", completion = "You and Renn have done excellent work in bringing this information to light and reporting it immediately. Now, we must confirm your findings. The implications are too great if we are wrong." }
WordHunterWoW_QuestEN[11142] = { title = "urvey Alcaz Island", description = "It looks like Renn's hunch about Alcaz Island was right. We need to survey that island, but it would take a whole brigade of troops to fight our way in there.\n\nTheramore's defenses can't weather such a hit, so I've arranged with Cassa Crimsonwing, the apprentice to Theramore's gryphon master, to allow you to use one of her beasts to survey Alcaz from the air.\n\nAlcaz Island holds the key to the mystery of the Defias' involvement in this kidnapping.", objectives = "Speak to Cassa Crimsonwing and use one of her gryphons to survey Alcaz Island. When your survey is complete, speak with Lady Jaina Proudmoore in Theramore.", completion = "<Lady Jaina listens intently as you report the results of your aerial survey.>\n\nA rune circle, dragonkin? The Defias have allied themselves with HER? The traitor?\n\n<Lady Jaina composes herself and prepares to explain.>" }
WordHunterWoW_QuestEN[11143] = { title = "Grim Connection", description = "I've spoken with Inspector Tarem regarding the evidence you gathered from the ruins of the Shady Rest Inn. He seems certain that the hoofprints and the shield you found there point to the Grimtotem clan of tauren.\n\nWith reports of Grimtotem activity on the rise in the marsh, this has to be more than a mere coincidence. I'm sending you to speak with Captain Darill, who is something of an expert on the Grimtotems. Follow the road north out of town to North Point tower. It's the second outpost on the road.", objectives = "Report to Captain Darill at North Point.I've spoken with Inspector Tarem regarding the evidence you gathered from the ruins of the Shady Rest Inn. He seems certain that the hoofprints and the shield you found there point to the Grimtotem clan of tauren.\n\nWith reports of Grimtotem activity on the rise in the marsh, this has to be more than a mere coincidence. I'm sending you to speak with Captain Darill, who is something of an expert on the Grimtotems. Follow the road north out of town to North Point tower. It's the second outpost on the road.", completion = "Captain Vimes thinks the Grimtotems are behind the destruction of the Shady Rest Inn? They wouldn't have been first on my list of suspects, but if Captain Vimes sent you here to follow up on a lead, he must have his reasons. Regardless, the Grimtotems have been a thorn in our side for some time and we're always glad to have the extra help." }
WordHunterWoW_QuestEN[11144] = { title = "onfirming the Suspicion", description = "The Grimtotems may be the most warlike of all the tauren clans, but they're by no means unorganized. If they're the ones who put the torch to the Shady Rest Inn, they'll have had orders from one of their clan elders.\n\nThere's a large Grimtotem settlement called Blackhoof Village to the northwest. They've been using it as a base to attack the tower, but I'll bet that you'll find the orders you're looking for there. Check the village's elders for traces of the orders you seek.", objectives = "Bring the Grimtotem Battle Plan to Captain Darill at North Point Tower.", progress = "Were you able to find any trace of the orders?", completion = "<Captain Darill glances at the battle plan.>\n\nI'd say it doesn't get any clearer than this. They've taken it upon themselves to fight back against human settlements in the area and I have little doubt Theramore is next on their list." }
WordHunterWoW_QuestEN[11145] = { title = "risoners of the Grimtotems", description = "We're doing all we can to keep the Grimtotem raiders at bay, but they keep launching assaults on the tower. Even worse, they've managed to discover and capture the patrols the captain sends out to gather information and safeguard the road.\n\nI suspect the captives are being held in Blackhoof Village, to the northwest. Knowing the Grimtotems, the defenders of the village probably carry the keys to the prisoners' cages with them. I don't care what you have to do, <class>, just bring back my men alive.", objectives = "Sergeant Lukas at North Point Tower wants you to free 5 Theramore Prisoners.", completion = "The freed captives have already begun returning from Blackhoof Village. The information the captain is receiving from the prisoners will give us an advantage in our next battle against the Grimtotems.\n\nYou have my thanks and that of the men." }
WordHunterWoW_QuestEN[11146] = { title = "aptor Captor", description = "The patch of swamp to the northeast is home to a particularly nasty breed of raptors. We've lost more than one unwary soldier to them, but I think we can turn them against our Grimtotem neighbors.\n\nTake this rope and use it to capture bloodfen raptors or bloodfen screechers that you've subdued. I wouldn't try to capture one of the beasts until you've weakened them quite a bit in combat. It's going to be quite a struggle.", objectives = "Sergeant Lukas at North Point Tower wants you to capture 6 raptors. You can capture either Bloodfen Raptors or Bloodfen Screechers.", progress = "Did you capture those raptors?", completion = "You look a little scratched up, but nothing major. You're certainly in a lot better shape than the Grimtotems will be when our new raptor friends get done with them." }
WordHunterWoW_QuestEN[11147] = { title = "nleash the Raptors", description = "Now that we've got our raptors, our next move is to \"encourage\" them to attack the Grimtotems at Blackhoof Village to the northwest.\n\nI've got a leftover haunch of... well, it doesn't really matter what it is. It'll be your bait. Set it down on the ground in Blackhoof Village near the windmill in the center of the settlement. The raptors should take care of the rest, if their training took.", objectives = "Sergeant Lukas at North Point Tower wants you to place the Raptor Bait near the windmill in Blackhoof Village.", completion = "<The sergeant doesn't bother to hide his grin.>\n\nGood. That ought to forestall a raid or two." }
WordHunterWoW_QuestEN[11148] = { title = "rms of the Grimtotems", description = "If the equipment you found at the ruins of the inn belonged to a Grimtotem attack party, there's likely to be more just like it within their camp to the northwest.\n\nWe haven't been able to gather much information about Blackhoof Village, but judging from the size of the raiding parties, there's a substantial force based there.\n\nDo whatever you have to to capture some of their equipment so that we can compare it with your findings from the inn.", objectives = "Captain Darill at North Point Tower wants you to bring him 7 Blackhoof Armaments.", progress = "Did you get those weapons from Blackhoof Village?", completion = "<Captain Darill inspects the armaments you've brought from Blackhoof Village.>\n\nThere's no doubt about it. These match the description exactly, but there's just one problem -- these have never been used in battle. Blackhoof Village must not be the only Grimtotem post in the marsh." }
WordHunterWoW_QuestEN[11149] = { title = "abetha's Assistance", description = "I can't spare any men to help search for a second Grimtotem outpost, but I think I know of someone who might be able to help you.\n\nDeep in the Quagmire, to the south, there is a small farmstead owned by Tabetha. She may seem little more than an old hermit, but the truth is that she's a mage and scryer of some renown. Follow the road south to her farm and seek her help in finding the culprits responsible for the massacre at the Shady Rest Inn.", objectives = "Speak with Tabetha at her farm.I can't spare any men to help search for a second Grimtotem outpost, but I think I know of someone who might be able to help you.\n\nDeep in the Quagmire, to the south, there is a small farmstead owned by Tabetha. She may seem little more than an old hermit, but the truth is that she's a mage and scryer of some renown. Follow the road south to her farm and seek her help in finding the culprits responsible for the massacre at the Shady Rest Inn.", completion = "So you want me to scry for Grimtotems, eh? And what will you say when I tell you there's no need?" }
WordHunterWoW_QuestEN[11150] = { title = "aze Direhorn Post!", description = "There's no scrying necessary to see the trouble my new \"neighbors\" are creating. And if this is the band that burnt down the Shady Rest Inn, as you claim, there's no reason to tolerate their presence any longer.\n\nTake this torch and raze their camp to the ground! You'll find Direhorn just to the north of my farm, near the road. You can't miss it, really, as the Grimtotems have done a splendid job of announcing their presence with those totems they favor.", objectives = "Burn the North Tent, East Tent, and the Northeast Tent at Direhorn Post, then return to Tabetha at her farm.", progress = "Have you put that torch to good use?", completion = "I hope the Grimtotems got the message. Any attempt to return will be met with far worse than a mere torch. My apprentices and I will see to that." }
WordHunterWoW_QuestEN[11151] = { title = "ustice for the Hyals", description = "Although these Grimtotems were simply a nuisance to me, Captain Vimes will want to know of your deeds. Bring him the news that you have tracked down and dealt with those responsible for the burning of the Shady Rest Inn.\n\nIt's too late to save Jim Hyal's family, but perhaps the Grimtotems will think twice before attacking anyone connected to Theramore.", objectives = "Speak to Captain Garran Vimes at Foothold Citadel in Theramore.Although these Grimtotems were simply a nuisance to me, Captain Vimes will want to know of your deeds. Bring him the news that you have tracked down and dealt with those responsible for the burning of the Shady Rest Inn.\n\nIt's too late to save Jim Hyal's family, but perhaps the Grimtotems will think twice before attacking anyone connected to Theramore.", completion = "<The captain listens to your report intently.>\n\nWe have avenged James and his family, but not even that can restore what was destroyed." }
WordHunterWoW_QuestEN[11152] = { title = "eace at Last", description = "I wish we had a way of letting James Hyal's wife and son know that we have brought their murderers to justice.\n\n<Captain Vimes produces a small wreath decorated with flowers.>\n\nThere are some who say that their spirits will know, even if we cannot reach them. It's not much, but I'd like you to lay this wreath at the Hyal family monument. It's one of the larger stones in the graveyard just north of Theramore's gates.", objectives = "Captain Garran Vimes at Foothold Citadel wants you to lay the Wreath at the Hyal Family Monument.", completion = "<Captain Vimes smiles slightly as you relate the events you witnessed at the Hyal family grave.>\n\nIt's good to know that they understand. You didn't tell them about James, did you?\n\nI'll deliver his wife's message to him, but I doubt he'll understand." }
WordHunterWoW_QuestEN[11153] = { title = "Break the Blockade", description = "All of our ships are sunk! We need your help to break the pirate blockade below in the Shattered Straits!\n\nTake these cluster bombs and hitch a ride on the zeppelin that Harrowmeiser has 'loaned' to us.  He'll fly you over the decks of those pirate scoundrels, and you make sure to give it to them good!\n\nIf you can't bomb them to smithereens, I'm afraid we'll never be able to break the blockade.", objectives = "Take Petrov's Cluster Bombs and drop them on enough pirates to kill or destroy 25 Blockade Pirates and 10 Blockade Cannons. Once you've accomplished that, return to Bombardier Petrov at Westguard Keep.", progress = "We're talking again are we?  That must mean that you've done it!  You've shown those rotten Northsea pirates a thing or two!\n\nRight?", completion = "That's what I wanted to hear!  You've got the stuff, <name>, that's for sure!\n\nYou think maybe you could come back again tomorrow when we've made more cluster bombs?  I'd have you back out there right now, but my assistant, Feknut, isn't back from collecting more bat guano for them.\n\nI wonder what's taking him so long?" }
WordHunterWoW_QuestEN[11154] = { title = "Scare the Guano Out of Them!", description = "You, yes you... I need your help!\n\nPetrov sent me up here to get bat guano for the cluster bombs he's making back at the keep. He sent me to my doom!\n\nThe darkclaw bats hang out in the Rivenwood to the north, but I'm not taking a step off of this platform unless it's to go home!\n\nBut you... you could get it for me! Yes? Pretty please?!!!\n\nHere, take these firecrackers. My thinking is that if you drop 'em underneath the bats, the guano will be scared right out of them!", objectives = "Collect 10 Darkclaw Guano and deliver them to Engineer Feknut at Steel Gate.", progress = "Please tell me that you have the darkclaw guano?!", completion = "Ugh, what's that smell? Ack, it's you! Well, I guess I did send you on a smelly job!\n\nThank you, <class>. Don't worry, I'll get this stuff back to Petrov as soon as we get out of here.\n\n\n\nYou hear that guys? Lets get the hell out of here!!!" }
WordHunterWoW_QuestEN[11155] = { title = "Shoveltusk Soup Again?", description = "With all of the strange disappearances of our livestock, we better resupply in a hurry, or the beasties around these parts will be the least of our worries!\n\nSeeing as I'm in charge of feeding this lot, I'm going to need you to head east and get me some meat. More to the point, I'm looking to cook us up some tender shoveltusk meat.\n\nJust beware the stags... they're mean!", objectives = "Chef Kettleblack has asked you to obtain 6 Shoveltusk Meat and deliver them to her at Westguard Keep.", progress = "There's nothing as sumptuous as the tender meat carved from the flanks of a shoveltusk!", completion = "This will make a fine meal for the men.\n\n<The chef leans in closer to whisper in your ear.>\n\nHere, boy, take some for yourself. You look like you could use some more meat on your bones!" }
WordHunterWoW_QuestEN[11156] = { title = "irehorn Raiders", description = "The Grimtotems up at Direhorn Post, just to the north, are getting bolder by the day. At night, you can often hear them chanting about their deeds in battle against people who've tried to settle here.\n\nThey're determined to drive us from Tabetha's farm even though she's trained generations of apprentices here. We've defended the farm as best we can, but Apprentice Garion was wounded in the last attack.\n\nGo to Direhorn Post and kill any Grimtotem you can find! The attacks must stop.", objectives = "Kill 12 Direhorn Grimtotems and return to Apprentice Morlann at Tabetha's Farm.", completion = "<Apprentice Morlann nods.>\n\nGood. Can't say I'll miss the company, if you can call it that. You'd think at least in the middle of the swamp you'd get some privacy, you know?" }
WordHunterWoW_QuestEN[11157] = { title = "The Clutches of Evil", description = "{name}, I don't trust anyone but you to take care of this.  I need the proto-drake eggs and proto-whelps in the burning forest to the southeast destroyed!\n\nSince we arrived here, the Ember Clutch has been ablaze; there must be some sort of perverse magic at work. And lately it seems to be growing. My men tell me that if we don't do something quickly, we'll be surrounded on all sides by the fire within a few weeks' time!\n\nGet down there and eliminate the threat by destroying those eggs and the proto-whelps.", objectives = "Destroy 15 Proto-Drake Eggs and 15 Proto-Whelps, and then return to Captain Adams at Westguard Keep.", completion = "Good work! With any luck at all, the destruction of their egg clutches and whelps should drive off those fiery beasts and prevent that magical blaze from spreading.\n\nWait... what's that sound? It sounds like the beating of wings." }
WordHunterWoW_QuestEN[11158] = { title = "loodfen Feathers", description = "Are you startled by Brogg's presence here, little <race>? Don't worry. Goblins at Mudsprocket are Brogg's friends and you can be, too.\n\nBrogg left Brackenwall Village when new overlord not take revenge against black dragonkin for destroying old home and killing many of Brogg's old friends. Brogg come here to lay friends spirits to rest and avenge them, but Brogg need help preparing. For ritual, Brogg need feathers with strong magic, like ones worn by raptors at Bloodfen Burrow to the west of town.", objectives = "Bring 5 Bloodfen Feathers to Brogg at Mudsprocket.", progress = "<Brogg looks at you hopefully.>\n\nYou bring Brogg feathers?", completion = "<Brogg accepts the feathers.>\n\nBrogg pleased with these feathers. Very strong magic. Brogg not know what raptors do to give feathers power, but raptor feathers always best for ritual." }
WordHunterWoW_QuestEN[11159] = { title = "pirits of Stonemaul Hold", description = "Brogg has completed the totem that will put the spirits of his friends to rest. When the dragonkin came, they killed all Stonemaul who did not flee. Brogg fled with Overlord Mok'Morokk, hoping to lead a counterattack with other Stonemaul survivors.\n\nThe counterattack never came and the spirits of the Stonemaul dead still haunt Brogg and the others. Take this totem north to Stonemaul Ruins and use it near ogre skeletons to draw the spirit to you. Defeat the spirit to give it rest with its bones.", objectives = "Brogg, at Mudsprocket, wants you to put 10 Stonemaul Spirits to rest.", progress = "Brogg must know, have you brought peace to the violent spirits of the Stonemaul?", completion = "Brogg thanks you for your help, although he knows Overlord Mok'Morokk never will. At least surviving Stonemaul can finally focus on problems with the living and leave dead where they belong. Only one thing remains for Brogg to do." }
WordHunterWoW_QuestEN[11160] = { title = "anner of the Stonemaul", description = "When the dragons came and took over Brogg's old home, Stonemaul ogres fled and left everything behind, including clan's banner.\n\nBrogg knows banner was kept deep in Stonemaul ogre mound, but these days it's called Den of Flame. Brogg must have clan banner to get his revenge on dragons who killed his friends.\n\nBrogg's clan's old mound, Den of Flame, is northwest of Mudsprocket and crawling with dragonkin. Banner will be deep inside the cave. Be careful, <name>.", objectives = "Retrieve the Stonemaul Banner and bring it to Brogg at Mudsprocket.", progress = "You bring Stonemaul banner?", completion = "You have Brogg's thanks, <name>. Brogg has big plans for clan banner." }
WordHunterWoW_QuestEN[11161] = { title = "he Essence of Enmity", description = "To make the totem Brogg will need for his ritual, he must use the essences of the creatures who killed his friends. The hate and anger of Brogg's enemies will fuel the magic of his vengeance.\n\nTrack down Firemane ash tails, scouts, or scalebanes and use Brogg's totem on their corpses. Only when the dragonkin die will they give up their essences.\n\nThe creatures you seek swarm over the Den of Flame to the northwest and the Stonemaul Ruins to the north.", objectives = "Bring 10 Black Dragonkin Essences to Brogg at Mudsprocket.", progress = "Do you have the essences? Brogg must have them to avenge his friends!", completion = "You have Brogg's thanks, <name>. Once Brogg adds their magic to the totem, it will be able to redeem the spirits of Brogg's fallen friends." }
WordHunterWoW_QuestEN[11162] = { title = "hallenge to the Black Flight", description = "Brogg relishes the thought of taking his revenge on the black dragonkin of the marsh. <name>, you have been very helpful in preparing for this moment. Will you help?\n\nTake Brogg's clan banner and travel east until you see a cave like a dragon's mouth. At the entrance to that cave, plant Stonemaul banner and issue Brogg's challenge to Onyxia.\n\nBrogg and the Stonemaul will have their lands back!", objectives = "Plant the Stonemaul Banner near the entrance to Onyxia's Lair, wait for Onyxia's response, then return to Brogg at Mudsprocket.", progress = "Brogg will have his revenge!", completion = "<Brogg listens as you recount your experience at the entrance to Onyxia's lair.>\n\nBrogg suspected Onyxia would be too much of a coward to confront you. Just like black dragonflight to attack when victory is guaranteed.\n\nBrogg is grateful for your help, <name>, and he will never forget what you have done for him. Brogg will never give up his quest to bring Stonemaul back where they belong." }
WordHunterWoW_QuestEN[11163] = { title = "Undercover Sister", description = "<Donna looks around and then whispers to you.>\n\n<name>, what I'm about to tell you must remain confidential, understood?\n\nI've been sent by the Shattrath Peacekeepers to infiltrate Budd's gang here. Truth be told, since you first arrived you've been a key person of interest in my investigation. \n\nBut your deeds have since cleared you of any suspicion. In fact, for your slaying of the crazed warlord, Zul'Jin, I'm compelled to reward you for your efforts.", objectives = "Report to Donna Brascoe to collect a reward for your heroism in Zul'Aman. Donna is currently stationed in the Ghostlands, just outside Zul'Aman.<Donna looks around and then whispers to you.>\n\n<name>, what I'm about to tell you must remain confidential, understood?\n\nI've been sent by the Shattrath Peacekeepers to infiltrate Budd's gang here. Truth be told, since you first arrived you've been a key person of interest in my investigation. \n\nBut your deeds have since cleared you of any suspicion. In fact, for your slaying of the crazed warlord, Zul'Jin, I'm compelled to reward you for your efforts.", completion = "<Donna looks around and then whispers to you.>\n\n<name>, what I'm about to tell you must remain confidential, understood?\n\nI've been sent by the Shattrath Peacekeepers to infiltrate Budd's gang here. Truth be told, since you first arrived you've been a key person of interest in my investigation. \n\nBut your deeds have since cleared you of any suspicion. In fact, for your slaying of the crazed warlord, Zul'Jin, I'm compelled to reward you for your efforts." }
WordHunterWoW_QuestEN[11164] = { title = "Tuskin' Raiders", description = "'Ey mon! You be new around 'ere, eh? Lemme ask a favor of ya.\n\nBudd's been refinin' his forest troll disguise. Says that he be close now - just be needin' one last touch. Tusks.\n\nMy skinnin' talents be wasted 'ere. Somethin' about yankin' troll tusks be makin me queasy. \n\nBring me back 10 troll tusks, eh mon?", objectives = "Prigmon needs you to collect 10 Forest Troll Tusks from the trolls in Zul'Aman. Bring them to him at Budd's camp in the Ghostlands.", progress = "Hurry, mon!\n\nBudd be sendin' me into Zul'Aman alone to test his mask if I don't be givin' him those tusks soon!", completion = "Ahh yeah, these be just what I be needin'!\n\nHere be the payment I promised ya, <class>." }
WordHunterWoW_QuestEN[11165] = { title = "A Troll Among Trolls", description = "Lissen mon, there be sumthin' else needs doin fer ol' Prigmon.\n\nZungam, my good-fer-nuthin' cousin, be stuck inside Zul'Aman. He still be alive too - I seen his signal flare just last night!\n\nI should be lettin' him rot fer gettin' me tied up in this mess, but he be owin' me big money.\n\nDo what ya can to help him out, then leave the collectin' to me!", objectives = "Prigmon has tasked you with locating and assisting his cousin Zungam, somewhere within Zul'Aman.", completion = "I be free!\n\nDey took most everyting when dey nabbed me, but here - take the last of my coin fer your troubles.\n\nAnd the least I can be doin' is stickin' around to offer my services...." }
WordHunterWoW_QuestEN[11166] = { title = "X Marks... Your Doom!", description = "How did those fools fail? I told them to be careful - even gave them disguises to help them blend in. Ahh, well. The bright side of their failure is that this opportunity falls to you.\n\nSucceed, and you'll be well on your way to joining my crew and sharing in the immeasurable fame that will soon be mine. Not that I need any more, mind you.\n\nThere are yet a few portions of my map that require further exploration before our excavation can be initiated....", objectives = "Enter Zul'Aman and visit Halazzi's Chamber, Jan'alai's Platform, and Akil'zon's Platform. Report the details of those areas to Budd, at his camp in the Ghostlands.", completion = "<Budd struggles to maintain his composure.>\n\nErr - So, <name> - it's, uhhh,  about time you returned. Yes - in fact you're holding up the entire operation.\n\nNow then, let's get to filling in this map...." }
WordHunterWoW_QuestEN[11167] = { title = "The New Plague", description = "Not long after Arthas condemned us to this wretched existence, we in the Royal Apothecary Society endeavored to create a plague of our own.  A plague that would devour all flesh: living, dead or undead.\n\nWe've succeeded in creating this plague and we're here to hand deliver it to the Scourge's doorstep.\n\nThe Alliance intercepted the ship carrying the latest strain engineered in our Undercity laboratories.  Head to the wreckage southeast of here and salvage whatever containers you can.", objectives = "Apothecary Lysander at Vengeance Landing wants you to recover 10 Intact Plague Containers from the wrecked ship to the southeast.", progress = "Have you obtained the containers, <name>?", completion = "It's good that you're back in one piece.  The danger of becoming infected from handling these containers is not non-existent.  I suppose I should've warned you about that earlier." }
WordHunterWoW_QuestEN[11168] = { title = "Spiking the Mix", description = "I've a feeling the long trip across the sea is affecting the effectiveness of our plague.  What is needed is a potent toxin to boost the potency of the strain.\n\nThe crabs near this beach are a distant relative of the much smaller brown-shelled tidecrawler.  The smaller tropical variety produces a paralytic toxin strong enough to knock out an ogre.\n\nAs we all know bigger is better!  The much larger glands on the local variety should prove more potent.  Bring me a few!", objectives = "Bring 3 Giant Toxin Glands from Giant Tidecrawlers to Apothecary Lysander at Vengeance Landing in Howling Fjord.", progress = "Have you obtained the toxin glands I seek, <name>?", completion = "You continue to prove your competence, <name>.  Hopefully this toxin will be enough to boost our plague to the levels that we need to.\n\nAt the very least it should help weaken the recipient and make them more susceptible to infection." }
WordHunterWoW_QuestEN[11169] = { title = "he Grimtotem Weapon", description = "During the last Grimtotem attack, I was wounded, but not before I managed to capture a curious totem our enemies were using against us.\n\nIt seemed to be emitting raw bolts of energy during the battle, but in all my experiments, I haven't managed to figure out how it works. I'll loan the totem to you if you agree to help me test it.\n\nThe watery areas surrounding the farm are home to pesky mottled drywallow crocolisks and drywallow daggermaws. Try fighting the crocolisks near the totem.", objectives = "Apprentice Garion at Tabetha's Farm wants you to test the Captured Totem on 10 Mottled Drywallow Crocolisks or Drywallow Daggermaws.", progress = "Have you had any luck testing the totem?", completion = "<The apprentice listens as you describe your experiment.>\n\nA haze and some lightning? That's it? There's got to be more to the totem than just that! The Grimtotems aren't likely to bring something like this to the battlefield unless it has some kind of utility." }
WordHunterWoW_QuestEN[11170] = { title = "Test at Sea", description = "We've just received word of reinforcements coming to the aid of the Alliance forces.  Their timing couldn't be better!\n\nWe're in sore need of test subjects and these North Fleet reservists will do nicely!\n\nTake these plague vials with you and speak to Camille, the Bat Handler.  Tell her you need to commandeer a riding bat for a special assignment for us.\n\nOnce you're at sea, drop the vials on the reinforcement fleet.  I can't wait to see the results!", objectives = "Speak to Bat Handler Camille and take a riding bat to intercept the Alliance reinforcements. Once above their fleet, use the Plague Vials to infect 16 North Fleet reservists.", progress = "You're back!", completion = "Hmmphh.... the reports from the field are.... not encouraging!" }
WordHunterWoW_QuestEN[11171] = { title = "Hex Lord? Hah!", description = "Excellent! Everything's nearly ready for my grand entrance into Zul'Aman.\n\nYou've done a fine job, <name>. I've spoken with my crew and they're warming up to you nicely. I'd say you're very close to becoming a permanent member of the team. Only one thing remains for you to do - dispatch that 'Hex Lord' fellow.\n\nNothing to it, really. You stand up to this wretch and he'll likely just turn and run. Weaker, older trolls just add intimidating titles to their name to make up for their deficiencies, you see?", objectives = "Budd Nedreck in Hatchet Hills wants you to kill Hex Lord Malacrass in Zul'Aman.", completion = "Finally! Now that the light work is done, I can at last make yet another mark on history. But first, there's one small matter to attend to - You....\n\nI'm afraid, <name>, that the time has come for me to let you go. I feel that your potential has been reached here, if not far exceeded.\n\nDon't feel bad, though. After all, it takes an exceptional type of individual to participate in such extraordinary events and not lose their wits. And look here, I have a little something for you to remember me by." }
WordHunterWoW_QuestEN[11172] = { title = "he Zeppelin Crash", description = "Not long ago, a goblin zeppelin crashed to the east. A representative of the Steamwheedle Cartel passed through here a few days ago.\n\nShe was looking for information about the zeppelin's cargo and it's pilot, Beezil, but none of us really got a good look at the crash. I doubt she'll be able to clean up after the wreck by herself, much less recover whatever cargo the vessel might have carried.\n\nIf you have time, you may want to check up on her out at Beezil's Wreck, due east of here, near the mountains.", objectives = "Speak with Moxie Steelgrille at Beezil's Wreck.", completion = "So those hermit mages sent you? How can I be sure that I can trust you?\n\nI suppose I can use the help. There's not much here a mage would be interested in, anyway." }
WordHunterWoW_QuestEN[11173] = { title = "he Reagent Thief", description = "If there's one thing you can count on Apprentice Morlann to do, it's whine about reagents.\n\nNormally, I just ignore him, and it never works. This time, I'm going to try something different.\n\nMaybe if I replace the missing reagents before he notices, he'll leave me alone. The most common reagent we both use is marsh venom, which comes from the darkfang creepers and noxious shredders in the marsh north of the farm. If you bring me the venom, I'll replace it before Morlann notices it's gone.", objectives = "Bring 6 vials of Marsh Venom to Apprentice Garion at Tabetha's Farm.", progress = "Did you get that venom? Morlann's going to discover that it's gone any moment now...", completion = "<Apprentice Garion inspects the venom.>\n\nThis is absolutely perfect! He'll never know the difference." }
WordHunterWoW_QuestEN[11174] = { title = "orrosion Prevention", description = "Just look at this area! It's swarming with oozes. If I don't find some way to keep them under control, they'll corrode the wreckage and the zeppelin's cargo!\n\nI can't go back empty-handed, <class>! Help me dissolve these oozes before they've digested everything!\n\nThis device, when powered, will concentrate energy on the slimes, causing them to explode. The zeppelin's fragmented power core should power the device. The one near the main crash works all the time, but the others flicker on and off.", objectives = "Moxie Steelgrille wants you to dissolve 10 oozes and report back to her at Beezil's Wreck.", progress = "Did you make any progress against those oozes?", completion = "Well, it does look a little cleaner out there...\n\nI suppose it's time to get down to the business of salvaging this wreckage." }
WordHunterWoW_QuestEN[11175] = { title = "My Daughter", description = "Tell me, is it true? Did the explorers that went into Whisper Gulch go mad?\n\nMy daughter is the overseer of the Explorers' League that went north to some place called Steel Gate. With the horrible events that have befallen us, I fear for her safety.\n\nPlease, {class}, I am too old to make the journey. Her name is Irena. Will you go make certain that she is alright?", objectives = "Old Man Stonemantle has asked you to find his daughter, Overseer Irena Stonemantle, at Steel Gate.", completion = "Grrr. I knew it! He's sooooo over-protective! This is just embarassing.\n\nNot that I'm not happy to see you... I am! We all are. We can use your help!" }
WordHunterWoW_QuestEN[11176] = { title = "See to the Operations", description = "Our work out here is really just beginning. But now that we've brought these flying machines in from Westguard Keep, it should really pick up.\n\nThe problem is that we're lacking enough qualified pilots. And with things getting worse in the Rivenwood to the north, I'd like to get things wrapped up here quickly and then head back home.\n\nIf you can lend a hand, go have a chat with one of my chief archaeologists. You'll find them next to the flying machines on the north and south sides of the site.", objectives = "Explorer Irena Stonemantle has asked you to speak with a Steel Gate Chief Archaeologist at Steel Gate.", completion = "Irena sent you over, did she? Good, we've got work for you then!" }
WordHunterWoW_QuestEN[11177] = { title = "he Hermit of Swamplight Manor", description = "There's a fellow the locals know as \"Swamp Eye\" Jarl, who lives alone out in the swamp. Sometime ago he \"took over\" Swamplight Manor after the previous owners disappeared under mysterious circumstances.\n\nI like to send someone to check up on him every once in a while. He kind of reminds me of my grandfather, you know? Some say he's not quite right in the head.\n\nIf you're headed northwest on the road out of Theramore, you'll find Swamplight Manor in the Witch Hill area, before the road turns west.", objectives = "Speak to \"Swamp Eye\" Jarl at Swamplight Manor.There's a fellow the locals know as \"Swamp Eye\" Jarl, who lives alone out in the swamp. Sometime ago he \"took over\" Swamplight Manor after the previous owners disappeared under mysterious circumstances.\n\nI like to send someone to check up on him every once in a while. He kind of reminds me of my grandfather, you know? Some say he's not quite right in the head.\n\nIf you're headed northwest on the road out of Theramore, you'll find Swamplight Manor in the Witch Hill area, before the road turns west.", completion = "Get off my lawn... unless, that is, you want to help old \"Swamp Eye\" with a little bit of cooking. Whad'ya say?" }
WordHunterWoW_QuestEN[11178] = { title = "Blood of the Warlord", description = "As you examine the pulsating vial, your thoughts turn to the petulant little man outside Zul'Aman.\n\nYou can't wait to see Budd's expression when he sees this!", objectives = "Bring the Blood of Zul'jin to Budd at his camp in the Ghostlands, outside Zul'Aman.", progress = "<Budd tries to mask his displeasure at your presence.>\n\nYou again....\n\nI don't know how else to say it - I'm simply too busy with my preparations to hold your hand any longer.\n\nTrust me, <name>, it's all for the best. Perhaps, by some miracle, you might eventually build a name for yourself.\n\nIf so, you'll be able to say that you got your start from the incomparable Budd Nedreck!", completion = "Th-the Blood of Zul'jin himself you say?\n\n<Gathering himself, Budd continues>\n\nWell, I appreciate the gesture, <class>, but I could've taken him down with ease. There's no way he was as fearsome as the legends say. These things have a way of being utterly overstated, as you'll learn in time. More likely, the pitiful old cretin was overcome with arthritis!\n\nAnyway, I suppose it was the least you could do as payment for the kindness I've shown you here.\n\nNow off with you - I must dispose of this vial!" }
WordHunterWoW_QuestEN[11180] = { title = "What's Haunting Witch Hill?", description = "I traveled out here to pay Jarl a visit at his new home and it's been a nonstop horror show ever since! There's something seriously wrong here and I can't be the only one who sees it...\n\nHave you seen the ghosts and corpses shambling about Witch Hill? I've a feeling that if anyone knows what happened here, it is them. Seek out these risen husks and risen spirits in the surrounding area, grant them rest through combat, and see what you can learn from them before this evil consumes Jarl!", objectives = "Mordant Grimsby at Swamplight Manor wants you to gather information from 10 Risen Husks or Risen Spirits.", completion = "<Mordant produces a small sheet of paper and a pen, beginning to scribble down notes on your findings.>\n\nFrom your findings, the spirits in this place must amount to everyone who ever lived on this land, not just the previous occupants.\n\nSomething has been corrupting and killing them. Those who follow don't learn the truth until it's too late. We have to put an end to this, <name>!" }
WordHunterWoW_QuestEN[11181] = { title = "The Witch's Bane", description = "In my years as an herbalist, I've often observed that nature will provide subtle cures to the most vexing of problems. I've read that hedge mages and witch doctors often use the smoke of an herb known as witchbane to draw evil from its hiding places.\n\nIf true, this would mean witchbane should be growing near the shallow waters of Witch Hill. You should be able to identify it by its broad leaves and reddish central stalk. Bring me any of the herb you can find, <name>. It may be our only hope.", objectives = "Bring 9 sprigs of Witchbane to Mordant Grimsby at Swamplight Manor.", progress = "Were you able to gather any of the herb? We must work quickly, before whatever evil is behind this infestation consolidates its hold on this area.", completion = "<Mordant accepts the bunch of herbs from you.>\n\nThese match the description exactly! I prepared the torch while you were out. All that remains is to fasten the herbs to the end here." }
WordHunterWoW_QuestEN[11182] = { title = "Root Causes", description = "All things in nature seek a balance. It is only through the interference of those not in tune with that harmony that the balance is shifted.\n\nYou waste your efforts when you kill the whelps and drakes. The real culprits behind the expansion of these magically burning woods are the newly awakened vrykul and their master, Skeld Drakeson.\n\nIf it's blood on your hands that you seek, start with them. You will find their lair on the south side of the Ember Clutch.", objectives = "Slay 5 Dragonflayer Handlers and Skeld Drakeson. If you manage to do so, return to an Ember Clutch Ancient in the Ember Clutch.", progress = "How fare your efforts against the meddlesome handlers, little one?", completion = "Unfortunate that one predator must be used to put down another, but that is the natural order of things.\n\nPerhaps now the proto-drakes and their whelps can go back to living peacefully. Somehow I doubt it with the reawakening of the vrykul." }
WordHunterWoW_QuestEN[11183] = { title = "Cleansing Witch Hill", description = "The torch is ready. Plant it at the end of the dock and be prepared to face whatever comes forth.\n\nI have no idea what the torch's smoke may reveal... if anything emerges at all. I must say, I have my doubts about this kind of folk magic, but we haven't time for anything else. For your sake and Jarl's, I wish you luck.", objectives = "Mordant Grimsby at Swamplight Manor wants you to plant the torch at the end of the dock and defeat anything that appears.", progress = "Is it over?", completion = "It worked?\n\n<Mordant clears his throat.>\n\nI mean... it worked! Jarl and I are in your debt, <name>. Now the only remaining problem is my friend's taste in furniture, and I'm afraid that won't be solved as easily." }
WordHunterWoW_QuestEN[11184] = { title = "ANTED: Goreclaw the Ravenous", description = "Travelers and Steamwheedle personnel working in the field are advised to avoid the Bloodfen Burrow to the west of town.\n\nThe area is overrun with raptors lead by the cruel and cunning Goreclaw the Ravenous, who has already killed at least two Steamwheedle engineers.\n\nDrazzit Dripvalve has authorized a generous reward to be paid to the individual who rids Mudsprocket of this menace.", objectives = "Kill Goreclaw the Ravenous and report to Drazzit Dripvalve at Mudsprocket.", completion = "Thank goodness someone's finally taken me up on that offer. I was just thinking that I might need to triple the reward to get that stupid raptor killed, and our budget couldn't afford that!" }
WordHunterWoW_QuestEN[11185] = { title = "he Apothecary's Letter", description = "Recovered from the body of a Forsaken apothecary, this letter contains alarming evidence of a close alliance between the Grimtotems and the new masters of Lordaeron.\n\n\"As a demonstration of good faith and a symbol of our newfound trust, we have dispatched Apothecary Cylla to aid you in battling our mutual enemy in the land of Kalimdor. None will stand before our combined might and determination.\"\n\nThis letter should be brought to the attention of the SI:7 agent at Tabetha's Farm, Andello Porter.", objectives = "Bring the Sealed Letter to Andello Porter at Tabetha's Farm.", progress = "What is that you're carrying, <class>?", completion = "<Andello reads the letter, shocked at its contents.>\n\nWe've long had misgivings about the cooperation between the Horde and the Forsaken, and this only confirms those suspicions. With the backing for Forsaken magic and arms, the Grimtotems would become an even more fearsome enemy. The balance of power in Kalimdor could shift considerably." }
WordHunterWoW_QuestEN[11186] = { title = "igns of Treachery?", description = "Recovered from the body of a Forsaken apothecary, this letter hints at an underground correspondence between Undercity and the Grimtotem leadership.\n\n\"As a demonstration of good faith and a symbol of our newfound trust, we have dispatched Apothecary Cylla to aid you in battling our mutual enemy in the land of Kalimdor. None will stand before our combined might and determination.\"\n\nPerhaps Nazeer Bloodpike in Brackenwall Village will know how to handle this information.", objectives = "Bring the Sealed Letter to Nazeer Bloodpike in Brackenwall Village.", progress = "What is that you're carrying, <class>?", completion = "If this is what it appears to be, the Forsaken have some explaining to do!\n\nThe antics of the Grimtotems have long tried the Warchief's patience. We have traditionally treated it as a matter to be settled among the tauren people, but this letter may change it.\n\nIt will take time to investigate these suspicions, but do not speak to anyone of what you have seen this day." }
WordHunterWoW_QuestEN[11187] = { title = "Mage-Lieutenant Malister", description = "THIS IS OUTRAGEOUS! Those proto-drakes are attacking the keep!\n\nBeasts such as that should have been scared off when you took care of their clutches and whelps.\n\nYou did take care of them, right?\n\n{name}, this calls for more direct action. Speak with my advisor, Mage-Lieutenant Malister. He'll provide you with the means to get at those infernal creatures.", objectives = "Captain Adams has asked you to speak with his advisor, Mage-Lieutenant Malister, at Westguard Keep.", completion = "<Malister beckons you closer and speaks in whispered tones.>\n\nI was worried that something like this might happen. I tried to dissuade the captain from this course of action, but he is a dwarf of action with a definite outlook on how things should proceed.\n\nLet us speak of the options left to us." }
WordHunterWoW_QuestEN[11188] = { title = "Two Wrongs...", description = "Now that we've riled up these Ember Clutch proto-drakes, they may be inclined to continue their attacks upon the keep. This will not do.\n\nI hate to compound one wrong with another, but in this case it would appear that we will have to destroy the creatures. A regrettable course of action, but one that we need to undertake regardless.\n\nTake my wand. I've been experimenting with increasing its range, but it doesn't pack much of a punch. However, what it will do is get a proto-drake's attention.", objectives = "Mage-Lieutenant Malister at Westguard Keep has tasked you with the destruction of 3 Proto-Drakes.", progress = "It is unfortunate that the captain had to have you go rile up the proto-drakes. Though they seem to lack the intelligence of the dragons that we know, they still seem to be noble creatures. Not to mention the situation it places us in.\n\nDare I ask if you have dealt with the situation?", completion = "<The mage-lieutenant sighs.>\n\nUnfortunate business to be certain. Well, what's done is done. With any luck the new whelps that grow to be drakes at Ember Clutch will not retain a memory of our shameful actions therein.\n\nAnd with a bit more luck, the boundaries of that magical forest will not continue to spread.\n\nHere, <name>, please take this pittance from the treasury for all of your troubles. It's the least that we can do." }
WordHunterWoW_QuestEN[11189] = { title = "One Last Time", description = "Hello there. Am I dead? I think I am, because I'm hovering over my body!\n\nOh, what an unfortunate turn of events. I was about to propose to Irena when the Scourge descended on us.\n\nI know that she's still alive... I can feel her in my heart.\n\n<class>, do you think you might safely get me to her? The Scourge can still see my ghost, and no doubt can do horrible things to me.\n\nI'd like to look upon her beautiful face one last time. You can tell her that I love her for me.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Escort the Ghost of Explorer Jaren safely to Explorer Irena Stonemantle at Steel Gate in the Howling Fjord." }
WordHunterWoW_QuestEN[11190] = { title = "One Size Does Not Fit All", description = "Lad, who's the genius that made our cannons a non-standard size? Now we have ta make special cannonballs ta shoot out o' the infernal contraptions!\n\nI would look kindly on ye if ye would go out and find the balls we've already shot. No doubt with the way these louts shoot they be all o'er the place ta the south and east.\n\n<The cannoneer spaces his hands apart to give you an idea of how big the cannonballs are.>\n\nThat would be faster than us making 'em from scratch fer a certainty.", objectives = "Cannoneer Ely has tasked you with rounding up 10 Westguard Cannonballs and returning them to him at Westguard Keep.", progress = "We're runnin' dangerously low on rounds 'round here, <class>. Our enemies need poundin', especially Skorn!\n\nYa got more balls fer us?", completion = "Oh, bless ya, <name>, bless ya!\n\nJust set 'em down right where yer standin'. I'll have one o' the boys come load 'em up soon enough and we can stop worryin' 'bout runnin' out o' balls ta shoot at Skorn." }
WordHunterWoW_QuestEN[11191] = { title = "his Old Lighthouse", description = "The old lighthouse out to the east hasn't worked for some time, but Babs Fizzletorque has gotten it into her head to get it working again.\n\nI don't know how she plans to do it by herself, but she claims that it'll make the movement of ships and goods into the docks smoother, so I can't really object. Drawing duty on the docks is really nothing to complain about when you could be on the front lines, you know?", objectives = "Speak to Babs Fizzletorque at the lighthouse on the island east of Theramore.The old lighthouse out to the east hasn't worked for some time, but Babs Fizzletorque has gotten it into her head to get it working again.\n\nI don't know how she plans to do it by herself, but she claims that it'll make the movement of ships and goods into the docks smoother, so I can't really object. Drawing duty on the docks is really nothing to complain about when you could be on the front lines, you know?", completion = "Good. I can use all the help you can offer. My first priority is to get that lamp re-lit." }
WordHunterWoW_QuestEN[11192] = { title = "hresher Oil", description = "The old log in the lighthouse indicates that the lamp was fueled with oil from the threshers that live along the coast here.\n\n<Babs wrinkles her nose at the mention of such outdated technology.>\n\nI suppose it's a practical, if inelegant solution. The log says that the oil taken from the youngest murk threshers works the best, and those live right underneath the docks of Theramore.\n\nIf you're up for it, would you help resupply the lighthouse with fuel?", objectives = "Bring 4 containers of Thresher Oil to Babs Fizzletorque at the lighthouse near Theramore.", progress = "Were you able to get any of that thresher oil?", completion = "Well, I have my doubts, but this is the only solution available right now. Once we have it up and running, I'm sure there will be time to look at other ways to fuel the lamp." }
WordHunterWoW_QuestEN[11193] = { title = "astardly Denizens of the Deep", description = "You know, it's amazing what you can find in that old lighthouse. After I lit the lamp, I noticed this book in one of the old trunks up there.\n\n<Babs holds up the book and reads the title dramatically.>\n\n\"Dastardly Denizens of the Deep!\"\n\nWhy, I think I might swoon if I ever saw one of these! I'm sure it's good for a laugh or two, but I simply don't have time for reading right now.\n\nYou know who might enjoy it, though... that fishmonger on the docks, \"Dirty\" Michael Crowe. He collects old books.", objectives = "Bring Dastardly Denizens of the Deep to \"Dirty\" Michael Crowe on the Theramore docks.", progress = "What'll it be today? The snook is quite good.", completion = "Well, now, that was thoughtful o' Babs to send that over. I don't know if you've leafed through it or not, but there's a lot of truth to the tales in that book. Sailors didn't just make it all up, you know." }
WordHunterWoW_QuestEN[11194] = { title = "s it Real?", description = "Oh, I'm sure you and Babs had a good laugh over the outlandish descriptions and sketches in the book, but have you stopped to consider there might be some truth to the legends?\n\nIf you listen closely enough, I bet you can still hear sailors talk about Tethyr, the sea creature the book says lives right here! Of course, if you wanted to know for sure, you could always ask old Nat Pagle.\n\nHe's got a small fishing camp on a little island in Tidefury Cove, which is southwest across Dustwallow Bay.", objectives = "Talk to Nat Pagle at Nat's Landing in Dustwallow Marsh.", completion = "So you want to know about sea monsters? Hmm... well, I'll make you a deal, but it's going to involve a lot of alcohol and some embarrassment on your part." }
WordHunterWoW_QuestEN[11195] = { title = "Playin' With Dolls", description = "I'm touched, <name>, an' dat be da truth. I'm not rememberin' the last time a <race> helped Zungam outta trouble.\n\nI snatched this from one of them savages when he was busy chainin' me up. It don't look like much, but if anyone can determine its worth, it be my good friend, Griftah!\n\nIf ya be makin' it outta here alive, it might be worth takin' this to him out in Shattrath City.", objectives = "Take the Tattered Voodoo Doll to Griftah in Shattrath City.", progress = "Hey, <name>! I hear ya been workin' yer way into Budd's crew. Ya won't live to regret that move, friend, I can promise ya that.\n\nWhatcha got there, mon?", completion = "Hey now, where ya be gettin' this?\n\nNo, no, don't tell me - this be comin' from the Hex-Lord himself! It all be clear now. Strong mojo! The bearer of this relic, no matter how many disgraces he be sufferin', be always honored by his peers. Incredible!\n\n<As Griftah holds the doll in the air, a small, rusty charm falls from around its neck. The troll begins to discard it, but then turns toward you with a gleam in his eye.>\n\nI gots no coins right now, mon, but ya be welcome to this here..." }
WordHunterWoW_QuestEN[11196] = { title = "Warlord of the Amani", description = "Da Amani been rebuildin' their forces and dey raised up a new warlord to lead dem, {name}. He be called Daakara da Invincible, but we be seein' whether he lives up to the name or not.\n\nYa must first defeat all his lieutenants to clear da way before ya can face this Daakara. Defeat him and put an end to da ambitions of da Zandalari and da Amani!\n\n\n", objectives = "Defeat the new Amani warlord, Daakara.", progress = "Dis new warlord must fall before da Zandalari foothold here becomes permanent.", completion = "Victory be ours, <name>. Da Zandalari be fleein' and without da warlord's leadership, da Amani will soon be reduced to fighting among demselves." }
WordHunterWoW_QuestEN[11197] = { title = "ZZOLD Upper Deck Promo - Ghost Wolf Mount OLD", description = "", objectives = "" }
WordHunterWoW_QuestEN[11198] = { title = "ake Down Tethyr!", description = "Sea monster or no, we're not going to risk the safety of our shipping. I've ordered our best marksmen to prepare for a confrontation with this Tethyr. The artillerymen have augmented the dock's defenses with three mortars.\n\nI'm going to order the lighthouse's lamp illuminated. If Tethyr does attack, it will be your job to operate the mortars and take down the beast before it can kill all of the marksmen. I wouldn't stand in one place too long, though. Using the mortars is likely to draw its attention.", objectives = "Major Mills at the Theramore docks wants you to defeat Tethyr.", completion = "Well done, <name>! I'll admit, when I caught my first glimpse of that beast, I had doubts about our ability to defend the docks, but you held together the defenders brilliantly!" }
WordHunterWoW_QuestEN[11199] = { title = "Report to Scout Knowles", description = "{name}, now that those damnable proto-creatures have been dealt with, I've another task for you.\n\nOne of my scouts has reported back some suspicious activity by the Forsaken to the south. It looks like they're up to no good at the vrykul village known as Halgrind.\n\nI want you to personally take over the investigation down there. Speak with Scout Knowles to find out what he's uncovered and proceed from there.\n\nHis last reported position is at the Ember Spear Tower, just to the west of Halgrind.", objectives = "Captain Adams has asked you to report to Scout Knowles at the Ember Spear Tower.", completion = "Oh good, help, and just in time!" }
WordHunterWoW_QuestEN[11200] = { title = "ore than Coincidence", description = "We've gleaned as much as we can from the ruins of the inn. I'm concerned about where the investigation will lead us from here, but we must know the truth.\n\nBetween the hoofprints and the shield with Mosarn's mark, I'm lead to believe that the Grimtotems may have been involved. They've recently established a settlement in the swamp, Blackhoof Village to the northeast. Travel to Blackhoof Village and search for more arms of Mosarn's manufacture.", objectives = "Krog at Brackenwall Village wants you to bring him 7 Blackhoof Armaments.", progress = "What did your search of Blackhoof Village reveal?", completion = "<Krog inspects the weapons and armor you've brought from Blackhoof Village.>\n\nThis is unmistakably the work of Mosarn. Questioning him further may draw too much attention, but we have a bit more freedom in dealing with the Grimtotems." }
WordHunterWoW_QuestEN[11201] = { title = "he Grimtotem Plot", description = "With the activities of the Grimtotems in Thousand Needles brought to light, many tauren now regard them with suspicion.  We've seen high-ranking Grimtotems engage in murder and kidnapping to advance their interests and I fear we may become their next target.\n\nBlackhoof Village, to the northeast, near Bluefen, is a large new Grimtotem settlement. Their leaders, the elders, will all have orders from Thunder Bluff. See if you can capture the orders and piece them together to learn the Grimtotems' plans.", objectives = "Bring the Grimtotem Battle Plan to Krog at Brackenwall Village.", progress = "Were you able to find any trace of the orders?", completion = "<Krog reads over the battle plan.>\n\nThere's no doubt in my mind that the Grimtotems are moving against the humans. What I don't understand is what their intentions are toward us. The actions of the Grimtotems have caused tension within the Horde in the past, but the Warchief has always diffused it." }
WordHunterWoW_QuestEN[11202] = { title = "Mission: Eternal Flame", description = "The Forsaken are up to no good and from what I can tell, those plague tanks of sludge are a big part of it.\n\nIf I may suggest, sir, we should probably destroy them before they can get any more use out of the things. I took the liberty of preparing a bundle of torches from the Ember Clutch. These things have been burning for days!\n\nHere, I'm sure you can put them to better use than I in destroying those tanks.", objectives = "Scout Knowles at the Ember Spear Tower has recommended that you use the Ever-burning Torches to destroy the four Plague Tanks surrounding Halgrind.", completion = "Nice!\n\nBut what's this about the stuff you found inside those tanks? Are you saying that the Forsaken are spraying a plague upon the vrykul down there?" }
WordHunterWoW_QuestEN[11203] = { title = "eek Out Tabetha", description = "The arms you captured in Blackhoof Village have not seen any combat beyond mere training exercises, which means the Grimtotems who destroyed the Shady Rest are still at large.\n\nTo the south, in the heart of the Quagmire, lives the witch Tabetha. Though she is a human, she has dealt honorably with us and trained some of our mages.\n\nAsk her for assistance in tracking down the band of Grimtotem responsible for burning the inn. The Alliance must not be allowed to think we were complicit in the attack.", objectives = "Speak with Tabetha at her farm in the Quagmire.", completion = "<Tabetha smiles slightly.>\n\nKrog wishes me to scry for the Grimtotems, eh? Well, I have no need of magic in this case.\n\nIt seems we have a mutual enemy. The Grimtotems have built an outpost nearby and are a constant thorn in the side of me and my students." }
WordHunterWoW_QuestEN[11204] = { title = "eturn to Krog", description = "I hope I've been helpful to you and I'm sorry I can't offer more information. My apprentices and I produce such a large volume of arms and armor that it's almost impossible to recall details about any individual piece.\n\nNot only do we outfit the braves defending tauren lands, but the Grimtotems have a particular fondness for my work. A seasoned warrior knows good work when he sees it.", objectives = "Speak with Krog at Brackenwall Village.", completion = "He actually said that the Grimtotems are his biggest customers? Mosarn gave us more help than he knows. With this much pointing toward the Grimtotems, I think we just found our first suspects." }
WordHunterWoW_QuestEN[11205] = { title = "aze Direhorn Post!", description = "There's no scrying necessary to see the trouble my new \"neighbors\" are creating. And if this is the band that burnt down the Shady Rest Inn, as you claim, there's no reason to tolerate their presence any longer.\n\nTake this torch and raze their camp to the ground! You'll find Direhorn just to the north of my farm, near the road. You can't miss it, really, as the Grimtotems have done a splendid job of announcing their presence with those totems they favor.", objectives = "Burn the North Tent, East Tent, and the Northeast Tent at Direhorn Post, then return to Tabetha at her farm.", progress = "Have you put that torch to good use?", completion = "The Grimtotems should have no trouble understanding our latest message.\n\nAs for you, your contact at Brackenwall Village will want to know of your success. I know the destruction of the Shady Rest Inn could be a source of tensions between the Horde and Alliance. If I encounter any investigators from Theramore, I will gladly tell them the Grimtotems acted on their own." }
WordHunterWoW_QuestEN[11206] = { title = "ustice Dispensed", description = "I doubt the Grimtotems will give up their campaign to drive humans from the marsh, though I get the impression you probably don't mind that. At least we have dealt with the perpetrators of the crimes at the Shady Rest Inn.\n\nGo tell your leader that his vengeance has been sated.", objectives = "Return to Krog at Brackenwall Village.", completion = "<Krog listens to your report.>\n\nI'm impressed, <name>. I would've thought that the Grimtotem criminals would've been more difficult to locate. \n\nTabetha's warnings have not fallen on deaf ears, but it is not my place to chastise the Grimtotems. I will, of course, mention it in my report to the Warchief. Do not speak of it to anyone until Thrall has dealt with the Grimtotems. You have done well in solving the mystery of the Shady Rest and sparing us from the suspicion of Theramore." }
WordHunterWoW_QuestEN[11207] = { title = "ecure the Cargo!", description = "This zeppelin was carrying six months' worth of supplies to us at Mudsprocket! Sure, they've been able to barter for some of what they need, but they won't hold out forever.\n\nI've been sent out here to recover what I can of the cargo, but the wreckage is scattered all over the marsh in this area. I'm sure a lot of the cargo didn't survive the crash, but are you willing to help me recover what we can?", objectives = "Moxie Steelgrille at Beezil's Wreck wants you to recover 8 pieces of Zeppelin Cargo.", progress = "<Moxie looks frantic with worry.>\n\nDid the cargo survive? Did you find any of it?", completion = "Wow! You certainly found a lot more than I expected would be out there. I'm not sure how much Drazzit thought we were going to find out here, but he's going to have to be happy with this for now." }
WordHunterWoW_QuestEN[11208] = { title = "Delivery for Drazzit", description = "Drazzit will expect to hear something from me soon, but I don't think the site is secure enough for me to leave. If you have time, would you be willing to take some of the salvaged cargo down to him at Mudsprocket?\n\nIf you haven't been there yet, it's a small settlement to the southwest of here, beyond the Stonemaul Ruins. You can take the road there from Tabetha's Farm, too. When you get to Mudsprocket, the guy you're looking for is Drazzit Dripvalve.", objectives = "Take the Zeppelin Cargo to Drazzit Dripvalve at Mudsprocket.", progress = "Yes?", completion = "<Drazzit accepts the cargo from you.>\n\nI'm so hungry, I could eat a dragon! Thank goodness Moxie finally got some of that cargo down here. We've been reduced to playing dice against the ogre for whatever he's managed to kill on his hunting trips!" }
WordHunterWoW_QuestEN[11209] = { title = "at's Bargain", description = "So you found a copy of Dastardly Denizens of the Deep, did you? Well, I can tell you from experience, it's all true. I've even seen a few of 'em with my own eyes.\n\nBut you want to know about Tethyr.  I said I'd make you a deal, so here's what I want you to do. I'm working on a new line of baits, but I haven't tested this one yet.\n\nJust take this paste -- yeah, it smells a little foul -- smear it on yourself, and swim over to that wrecked ship to the southwest. If you survive, let me know how it works!", objectives = "Nat Pagle at Nat's Landing wants you to test his new fish bait.", progress = "Remember, the deal is \"don't come back until something bites you.\"", completion = "Not bad at all, but you know, I think I'd get a bath in as soon as possible, if I was you.\n\nNow, about your sea monster...\n\nHelp yourself to a brew or two in the meantime." }
WordHunterWoW_QuestEN[11210] = { title = "h, It's Real", description = "Yes, Tethyr is certainly real, and he lives in the waters off Theramore.\n\nHas a thing for bright lights. He's the reason they shut down the lighthouse in the first place, you know...\n\nAnd if you light it up again, he'll come right back. But no one in their right mind would do that.\n\nSo that must be your plan! It's been good sharing a drink with you, but don't blame ol' Nat if Tethyr REALLY turns you into fish bait. If you're going to do this, make sure you consult Major Mills at the Theramore docks.", objectives = "Speak with Major Mills at the docks in Theramore.", completion = "<You recount your experiences with Nat Pagle, carefully omitting the portion about the 'bait test.'>\n\nWell, it sounds like we've got our work cut out for us. I'll make the preparations." }
WordHunterWoW_QuestEN[11211] = { title = "Help for Mudsprocket", description = "When that goblin... what's her name... Boxie, Foxy... Moxie, that's it! Anyway, when she came through here on her way to the zeppelin wreck, she said the town of Mudsprocket was having some problems.\n\nThat crashed zeppelin was bringing them fresh supplies. If you follow the road south from here, past the Stonemaul Ruins, you'll eventually come to Mudsprocket.\n\nWhy don't you check in with Drazzit Dripvalve down there and see if there's anything you can do to help?", objectives = "Speak with Drazzit Dripvalve at Mudsprocket.", completion = "It's good of Tabetha to send you down here. I'd prevail upon her for some food until the wreckage from the zeppelin is taken care of, but I know she's got none to spare at the moment. If you're feeling adventurous, I've posted a bounty for the death of a particularly nasty raptor." }
WordHunterWoW_QuestEN[11212] = { title = "Tabetha's Farm", description = "Deep in the heart of the swamp lives an old woman named Tabetha. We've never really known much about her, save that she's a good deal older than she appears. She's helped us from time to time and helped keep the peace here between the Horde and our forces.\n\nShe used to keep in regular contact, but we haven't received one lately.\n\nCould you check in with her when you have time? Just follow the road beyond North Point Tower, where it turns south and into the Quagmire. You can see her farm from the road.", objectives = "Speak with Tabetha at her farm in the Quagmire.", completion = "It's good of Theramore to send someone. Your guard friend's suspicions were correct. We've got some new neighbors, and they aren't the kind you'd bring a casserole." }
WordHunterWoW_QuestEN[11213] = { title = "Check Up on Tabetha", description = "A human woman named Tabetha lives on a small farm near the middle of the marsh. Ordinarily, I wouldn't associate with a human, but her help has proven useful at times.\n\nUnfortunately, she's been out of touch for quite some time now and I'm looking for someone to travel down to her farm to see if everything's all right.\n\nIf you follow the road south out of the village, then into the swamp's interior, you'll find her farm near the middle of the Quagmire.", objectives = "Speak to Tabetha at her farm in the Quagmire.", completion = "It's fortunate Nazeer thought to send someone. We've got some new neighbors and they've been nothing but pests since they set up camp." }
WordHunterWoW_QuestEN[11214] = { title = "ission to Mudsprocket", description = "The Steamwheedle Cartel has recently established a new outpost in the southern part of Dustwallow Marsh. It's called Mudsprocket, if I recall, and it's located on the main road south out of Tabetha's Farm and the Stonemaul Ruins.\n\nThis is an excellent opportunity for us to establish new trade contacts and Lady Jaina wants me to send a representative down there to establish contact. Would you be willing to go?", objectives = "Speak with Drazzit Dripvalve at Mudsprocket.", completion = "So Theramore is interested in doing business? Well, that's not an offer I'd turn down. Supplies are pretty scarce here right now, so we need all the business contacts we can get!" }
WordHunterWoW_QuestEN[11215] = { title = "Help Mudsprocket", description = "The Steamwheedle Cartel's new outpost in the southern part of the marsh isn't faring so well. The zeppelin carrying supplies to Mudsprocket crashed, leaving them without vital tools, food, and medical supplies.\n\nFollow the road down south and into the marsh's interior. You'll pass by Tabetha's Farm and the Stonemaul Ruins before the road brings you to Mudsprocket. Offer any help you can provide to the town's leadership.", objectives = "Speak with Drazzit Dripvalve at Mudsprocket.", completion = "I won't turn down any help! We're in the process of setting up here and trying to make the most of what we've got, until those supplies from the zeppelin arrive." }
WordHunterWoW_QuestEN[11216] = { title = "Archmage Alturus", description = "I was sent here by my mentor to look for assistance, but unfortunately I'm not allowed outside of Lower City and the individuals that frequent this establishment tend to be less than helpful.\n\nYou do seem different, more like the adventurous type.  If you're interested in aiding our cause, speak to Archmage Alturus outside of Medivh's old dwelling, Karazhan.\n\nIn the meantime, I'm going to see about gaining access to the rest of the city.  One of our old associates is rumored to be here.", objectives = "Speak to Archmage Alturus outside of Karazhan in Deadwind Pass.", completion = "I thank you for taking the time to come to our aid.  We've important work ahead of us." }
WordHunterWoW_QuestEN[11217] = { title = "atch a Dragon by the Tail", description = "With the zeppelin crash delaying supplies, we've run out of medicines and bandages.\n\nWe're making use of what we can, but between all the insects, the injuries, and the enemies we're encountering here, I can barely keep up! I've found one herb that seems to help heal wounds and dull pain, but it, too, is in short supply.\n\nIt's called wyrmtail, and it's abundant in the Dragonmurk and Wyrmbog areas east of town. The plants themselves are made of coiled stalks, and seem to pulsate when you look at them.", objectives = "Gizzix Grimegurgle at Mudsprocket wants you to bring him 8 Wyrmtail stalks.", progress = "Did you find any of the wyrmtail?", completion = "Thank you! This will help keep our guys going out in the field until Moxie returns with the rest of the supplies from the zeppelin crash." }
WordHunterWoW_QuestEN[11218] = { title = "Danger! Explosives!", description = "{name}, the captain's tasked me with a mission. I'd like you to help.\n\nA bunch of my fellow Explorers' League people went nuts digging up stuff in the Whisper Gulch just to the north. They're attacking anyone trying to get in!\n\nThe captain is only concerned with the ore for the keep. Lucky for us, I have just the thing to do the trick.\n\nGet in there, blow up the ore, and bring it back along with any gems you find. Running this place isn't cheap you know!\n\nI gotta warn you though, that ore is strange!", objectives = "Use Steelring's Foolproof Dynamite to collect 6 Whisper Gulch Ore Fragments and 18 Whisper Gulch Gems. Then return them to Sapper Steelring at Westguard Keep.", progress = "Construction on this place seems to be a never-ending task. I just hope that you're able to get us what we need to continue.", completion = "The ore gave you a strange feeling? Maybe we won't use that stuff after all.\n\n<Steelring looks at the stuff and takes a step back, changing the subject.>\n\nThose gems look really nice! I wonder what I can get for them? Of course, there are always repairs, and new stuff to be made.\n\nYou know, I've really found working with you to be profitable. Take this... it's the least that I can do!" }
WordHunterWoW_QuestEN[11219] = { title = "Stop the Fires!", description = "The Horde's children need you, {name}.  The Headless Horseman, once a human paladin and now an insane fiend, has set fire to our village!  You must put out those fires!\n\nGrab a bucket and throw it onto the blaze, or toss it to an ally who is closer to the flames.  Extinguish all the fires and thwart the Headless Horseman!", objectives = "The Masked Orphan Matron wants you to help put out all the village fires. When they are out, speak again to the Masked Orphan Matron in town.", progress = "The Horde's children need you! Do not abandon them!", completion = "The fires are out! You and your fire brigade were victorious! Hah!\n\nThe Headless Horseman's attack has failed, but until he and his head are destroyed together, He will return.\n\nUntil then, however, let's take comfort in the safety you brought our children. I am honored to have watched your brave work today." }
WordHunterWoW_QuestEN[11220] = { title = "The Headless Horseman", description = "Until the head of the Headless Horseman is destroyed, his rampage will not end.\n\nThe Horseman rests within the Forlorn Cloister of the Scarlet Monastery, in Tirisfal Glades.  Go to his pumpkin shrine and speak these words:\n\n  Horseman, rise\n  Your time is nigh\n  You felt death once\n  Now, know demise!\n\nThis will rouse the fiend.  Destroy the head of the Horseman and he will plague us no longer.", objectives = "Find the Headless Horseman's Pumpkin Shrine.Until the head of the Headless Horseman is destroyed, his rampage will not end.\n\nThe Horseman rests within the Forlorn Cloister of the Scarlet Monastery, in Tirisfal Glades. Go to his pumpkin shrine and speak these words:\n\n  Horseman, rise\n  Your time is nigh\n  You felt death once\n  Now, know demise!\n\nThis will rouse the fiend. Destroy the head of the Horseman and he will plague us no longer.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[11221] = { title = "Reports from the Field", description = "Our mission in Northrend is to destroy Arthas.  The Alliance are but an obstacle that we'll crush wherever we find them.\n\nWe've managed to destroy their easternmost fleet; but the survivors have barricaded themselves on the Derelict Strand, south of here.\n\nOur forces should've overwhelmed their make-shift defenses long ago, but we underestimated their will to live.  Seek my officers in the field, Dark Ranger Lyana and Deathstalker Razael and get them to report on the situation.", objectives = "Speak to Dark Ranger Lyana and Deathstalker Razael in the battlefield at the Bleeding Vale south of Vengeance Landing. Return to High Executor Anselm when you've completed this task.", progress = "Are you back with your report, <name>?", completion = "Cannons are holding us back?  I'll show them cannons." }
WordHunterWoW_QuestEN[11222] = { title = "roof of Treachery", description = "Although Onyxia has been exposed and removed from the court, the Defias who carried out her plan must be punished. Carry word to King Varian Wrynn in Stormwind castle that the Defias are the ones who carried out his kidnapping. I have little doubt that the king will mete out swift and terrible justice to those involved.\n\nI can use my magic to expedite your trip to Stormwind. Just speak to me when you're prepared to go, <name>.Upon completion of this quest you will gain:", objectives = "Speak to King Varian Wrynn in Stormwind Keep.Although Onyxia has been exposed and removed from the court, the Defias who carried out her plan must be punished. Carry word to King Varian Wrynn in Stormwind castle that the Defias are the ones who carried out his kidnapping. I have little doubt that the king will mete out swift and terrible justice to those involved.\n\nI can use my magic to expedite your trip to Stormwind. Just speak to me when you're prepared to go, <name>.Upon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[11223] = { title = "eturn to Jaina", description = "I must make plans to destroy the remnants of the Defias. Please convey my thanks to Lady Jaina, back in Theramore. She has ever been a loyal friend and steadfast ally.\n\nGo to the Mage Quarter at the western end of the city and speak with Archmage Malin at the foot of the tower there. He will speed your return to Theramore.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak to Lady Jaina Proudmoore in Theramore.I must make plans to destroy the remnants of the Defias. Please convey my thanks to Lady Jaina, back in Theramore. She has ever been a loyal friend and steadfast ally.\n\nGo to the Mage Quarter at the western end of the city and speak with Archmage Malin at the foot of the tower there. He will speed your return to Theramore.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[11224] = { title = "Send Them Packing", description = "I've heard rumors of bad happenings in the Whisper Gulch to the north. Most of the Explorers' League went down into that place, and some say they went mad with what they discovered.\n\nThat doesn't change the fact that they took most of our mules and equipment with them, though. I won't lose those mules!\n\nIf you find yourself in there, and happen across any of my mules, just get up close on them and threaten them with a raised hand. They'll spook and come home for sure.", objectives = "Explorer Abigail has asked you to /raise your hand at 10 Abandoned Pack Mules and then return to her at Westguard Keep.", progress = "This is quite a blow to our efforts. I don't even want to know what they discovered down there.\n\nIt's enough to keep me awake at night just trying to imagine what it could be.", completion = "I'm indebted to you, <class>. At least with most of the mules and equipment recovered, we can hope to rebuild our numbers soon.\n\nPlease, take this." }
WordHunterWoW_QuestEN[11225] = { title = "The Hermit of Witch Hill", description = "The marsh seems to have a strange effect on humans. Some grow mad simply by living here.\n\nAnyone who has ever settled at Swamplight Manor has gone mad in a spectacular way. The latest owner, one \"Swamp Eye\" Jarl, is already showing signs.\n\nI don't completely understand what's happening there, you'd have my thanks for looking into it.\n\nThe manor is at the eastern edge of the swamp. Trek east across Bluefen and past North Point Tower. The manor is in a haunted patch of land called Witch Hill.", objectives = "Speak with \"Swamp Eye\" Jarl at Swamplight Manor.", completion = "Have you come here to spy on me? No?\n\nPerhaps you have an appreciation for fine cuisine, then? Good, you can help!" }
WordHunterWoW_QuestEN[11226] = { title = "Upper Deck Promo - Spectral Tiger Mount", description = "", objectives = "" }
WordHunterWoW_QuestEN[11227] = { title = "Let Them Eat Crow", description = "The high executor wants me to use my dogs to sniff out enemy scouts, but I can tell you right now these plaguehounds aren't going anywhere until they're properly fed.\n\nIf our military doesn't understand that these beasts are picky enough to not eat the rubbish they've given me, then they can't expect them to be of any use in the field.\n\nYou seem to have some time on your hands, why don't you take one of these dogs out hunting for crows out west?  Their meat isn't very tasty to us, but my boys love it!", objectives = "Pontius, the kennel keeper at Vengeance Landing, wants you to use the Plaguehound Cage to summon a Hungry Plaguehound and feed it Crow Meat from Fjord Crows west of Vengeance Landing.", completion = "Did you hunt down some crows, boy?  Good boy, good boy!\n\nAh, these hounds remind me of my days raising purebreds in Tirisfal... those were good times!" }
WordHunterWoW_QuestEN[11228] = { title = "Hell Has Frozen Over...", description = "Fordragon's got another thing coming if he thinks the group of green-gilled scrubs he sent to defend this port can hold out much longer.\n\n<Macalroy raises an eyebrow as he examines your equipment.>\n\nYou, however, might fare a bit better.\n\nThe importance of holding this port cannot be stated enough; and with those monsters flying overhead, the situation around here has gone from bad to worse.\n\nReport to Vice Admiral Keller just northwest of here and let him know that you're all out of bubble gum.", objectives = "Speak with Vice Admiral Keller at Valgarde Port.", completion = "The dwarf speaks the truth. We can't afford to lose this port. It's one of two safe harbors that the Alliance has on this chunk of frozen hell - the other being a few hundred miles west of here on the coast of the Borean Tundra." }
WordHunterWoW_QuestEN[11229] = { title = "The Windrunner Fleet", description = "We have the Windrunner, the Queen's Reprisal and the Oblivion stationed just east of the Derelict Strand.  Send orders to the fleet's commander, Captain Harker, that they're to destroy the Alliance's cannons.\n\nSpeak to our bat handler, Camille, and ask for passage to the fleet's location.  Be quick, {name}, every minute we spend fighting the Alliance is a minute we could've spent fighting Arthas.", objectives = "Speak to Bat Handler Camille at Vengeance Landing and obtain passage to the Windrunner. Report to Captain Harker aboard the ship.", completion = "I hope you're ready to fight, <name>.  The Queen's fleet needs you!" }
WordHunterWoW_QuestEN[11230] = { title = "Ambushed!", description = "This should have been a walk in the park.  Their forces are hungry, injured and ill equipped.  Yet somehow, we walked right into their trap.\n\nWe approached these reefs from the south to gain cover and were immediately boarded by the Alliance dogs.\n\nI'm sorry to say, if you want our cannons to fire at anything, you're going to have to help us take our ships back.", objectives = "Captain Harker aboard the Windrunner wants you to kill 15 North Fleet Marines.", progress = "What are you waiting for?  Kill the Alliance scum already!", completion = "Nice work paring those mongrels down to size.  My men will be able to clean up the rest." }
WordHunterWoW_QuestEN[11231] = { title = "Of Keys and Cages", description = "The captain may not care, but from the little we know, the vrykul are conducting heinous rites in some sort of 'awakening' ritual up north in Gjalerbron.\n\nThey're using living sacrifices to fuel their unholy rituals!\n\n{class}, you must put a stop to this! It matters not who or what is in those cages, they must be freed. I'd bet that the vrykul hold the keys.\n\nThe Light knows the last thing we need is more of those strange vrykul walking about, or worse yet, them wakening something even more evil!", objectives = "Father Levariol has asked you to collect enough Gjalerbron Cage Keys to free 10 Gjalerbron Prisoners. Return to him at Westguard Keep when you manage to do so.", completion = "Bless you child! With your help, the Light shines even in the darkest of places.\n\nPlease, take this as just compensation for your good deeds. I shall see to the salvation of those you freed; at least, those truly within the Light, and the Alliance, who returned here to the keep." }
WordHunterWoW_QuestEN[11232] = { title = "Guide Our Sights", description = "We should be able to kill our way back to our guns.  Unfortunately, visibility is less than desirable so you will have to mark our targets from the ground.\n\nTake these smoke flares with you and use them to mark the locations of the cannons along the northern wall in the Derelict Strand, west of here, where the Alliance are holding out.\n\nLet Lyana know as soon as the way is clear for the ground troops.  We can take care of ourselves over here.", objectives = "Use the Smoke Flares at the location of the Alliance Cannons on the northern wall of the Derelict Strand. Report to Dark Ranger Lyana at the Bleeding Vale after you've completed this task.", progress = "The cannons, <name>.  Is someone going to take care of them?", completion = "Excellent.  I will signal our ground troops to make their move." }
WordHunterWoW_QuestEN[11233] = { title = "Landing the Killing Blow", description = "You've proven yourself in the field of battle, {name}.  You might very well have changed the tides in our favor.\n\nI've an important assignment for you now.  I'm not sure how much longer the weakness we've exposed is going to last, so we must use the element of surprise to our advantage.\n\nI want you to use the confusion created by our attack and go behind enemy lines to assassinate their leaders.  In order of rank, they are: Captain Olster, Lieutenant Celeyne and Sergeant Lorric.  Good luck, {class}.", objectives = "Dark Ranger Lyana south of the Vengeance Landing wants you to kill Captain Olster, Lieutenant Celeyne, and Sergeant Lorric at the Derelict Strand.", completion = "This marks undisputable victory for our forces.  Anselm will be most glad to hear about this." }
WordHunterWoW_QuestEN[11234] = { title = "Report to Anselm", description = "Let's send word back to old Anselm then.  Victory has come later than expected, but better late than never.  Tell him it will take our forces a few hours at most to finish off the stragglers here.\n\nGlory to the Banshee Queen!", objectives = "Report back to High Executor Anselm at Vengeance Landing in Howling Fjord.", completion = "It was about time.  The Alliance has been a thorn in our side for a long time now.\n\nThere's no time to celebrate, however.  Look to the west, it appears we have visitors." }
WordHunterWoW_QuestEN[11235] = { title = "Dealing With Gjalerbron", description = "And now we have a different problem. My scouts that have lived to return have informed me that the vrykul are up to no good at their main fortress to the north.\n\nThey call the place Gjalerbron, though you'd pronounce the 'Gj' as if it were an 'Sh'. Odd creatures.\n\nBut that's not important; what is, is that you get up there and put an end to the lives of as many of those creatures as you can while trying to figure out what they're up to.\n\nI know that I can count on you, {name}.", objectives = "Captain Adams has asked you to kill 15 Gjalerbron Warriors, 8 Gjalerbron Rune-casters, and 8 Gjalerbron Sleep-watchers. Afterward, return to him at Westguard Keep.", completion = "Good work, <name>, and good riddance.\n\nBut, what you say about that place troubles me still, and I think our culling is not quite at an end!" }
WordHunterWoW_QuestEN[11236] = { title = "Necro Overlord Mezhen", description = "The Scourge are at Gjalerbron and they have necromancers with them! They must be working to bring the vrykul into Arthas' fold.\n\nI want the leader of these necrolords eliminated!\n\nDo whatever it takes, {name}, but see to it that Necro Overlord Mezhen, and whatever he's attempting to accomplish, is neutralized.\n\nI will not see the vrykul successfully allied with the Scourge!\n\nLook for Mezhen on the platform in the rear right section of Gjalerbron.", objectives = "Kill Necro Overlord Mezhen. Then, return to Captain Adams at Westguard Keep.", completion = "<The captain breathes a sigh of relief.>\n\nWell, that should take some of the pressure off of us.\n\n<name>, time and again you have proven yourself invaluable to Westguard Keep and the Alliance at large. Pick something from the treasury, boy! It's the least we can do!" }
WordHunterWoW_QuestEN[11237] = { title = "Gjalerbron Attack Plans", description = "These plans detail an imminent attack upon Westguard Keep. It would appear that the frost wyrm, Glacion, who circles overhead is to be used for the offensive.\n\nSurely Mage-Lieutenant Malister would be of some assistance in this matter. Deliver the plans to him at the keep to the south.", objectives = "Deliver the Gjalerbron Attack Plans to Mage-Lieutenant Malister at Westguard Keep.", progress = "What?! Plans for an attack upon the keep?\n\nA FROST WYRM?!!!", completion = "<name>, we can't let this come to pass!" }
WordHunterWoW_QuestEN[11238] = { title = "The Frost Wyrm and its Master", description = "You were right to bring this to me, {name}. You must venture to Gjalerbron and slay that wyrm and its master, Wyrmcaller Vile!\n\nEven now, as we speak here, the frost wyrm may be on its way.\n\nHowever, if I'm reading these plans correctly, blowing the wyrmcaller's horn on his platform, outside in the rear left area of Gjalerbron, will call Glacion back. When the creature lands, destroy it!\n\nAnd {name}, please bring me the horn. We wouldn't want it falling back into the wrong hands.", objectives = "Slay Wyrmcaller Vile and use the Wyrmcaller's Horn to call down and slay Glacion. Then, return with the horn to Mage-Lieutenant Malister at Westguard Keep.", progress = "Is the attack averted? Are the frost wyrm and its master destroyed?\n\nDid you retrieve the horn?", completion = "Wow, that horn is cold!\n\nOnce again you've saved Westguard Keep from certain doom. What a curious man you are, <name>. If only there were more of you.\n\nWell, this certainly calls for a reward. Which do you prefer?" }
WordHunterWoW_QuestEN[11239] = { title = "In Service to the Light", description = "Your service has been exemplary, {name}, but there is something that is troubling me: the Scourge.\n\nThe Light cannot abide their presence, and neither shall we. I hope that it is not asking you too much, but I would have you return north to Gjalerbron and crush the unholy Scourge in that vile lair! Be sure to check for them in the Waking Halls beneath Gjalerbron as well.\n\nPurification is the key to salvation, my child. Make us proud!", objectives = "Slay 10 Deathless Watchers, 4 Fearsome Horrors, and 2 Putrid Wights. Afterward, inform Father Levariol at Westguard Keep of your success.", completion = "<The priest quietly mouths a benediction for you.>\n\nBless you, <name>, you have answered my prayers. Stand proudly in the Light, chin held high with the knowledge that your actions were most holy!\n\nI'm certain that the church's coffers can yield up something of use to you." }
WordHunterWoW_QuestEN[11240] = { title = "Leader of the Deranged", description = "So, I hate to say it, pal, but while you were out, the captain took a keener interest in that place.\n\nLooks like he wants my old Explorers' League boss in there dead. My guess would be that we're gearing up for an offensive to clear out the rest of them, and the captain wants their head lopped off, as it were.\n\nDo me a favor? Head back into Whisper Gulch and put an end to Squeeg Idolhunter. From what I remember, my guess would be that he's in the cave in the northwest corner.", objectives = "Slay Squeeg Idolhunter and then report back to Sapper Steelring at Westguard Keep.", completion = "<The sapper grumbles as if he wishes that you hadn't succeeded.>\n\nThe captain will be pleased to hear of your success.\n\nYou know, since you've been such a good sport in dealing with this Whisper Gulch business, why don't you take your pick of one of these?" }
WordHunterWoW_QuestEN[11241] = { title = "Trail of Fire", description = "Thanks for bailing me out of this mess, {name}.  I was not looking forward to what these Alliance scumbags had in store for me.\n\nLet's get out of here and see if we can get back at them somehow.  Is that a campfire over there?", objectives = "Escort Apothecary Hanes out of the Derelict Strand. Report to Apothecary Lysander at Vengeance Landing in Howling Fjord when you've completed this task.", completion = "Apothecary Hanes is alive?  You burned the Alliance supplies to the ground?  He must've gotten a real kick out of that.\n\nAt any rate, the Royal Apothecary Society is in your debt, <name>.  We thank you from the bottom of our black, black hearts." }
WordHunterWoW_QuestEN[11242] = { title = "Free at Last!", description = "Rage was my prison, {name}, and you have freed me.  Though I thought I did right, my soul now weeps for the terror and the death I have caused the good people of Azeroth.\n\nThank you for leading me back to the Light.  May I never again lose my way.\n\nTake this torn prayer book to an orphan matron, so the children may know that I will haunt them no more.", objectives = "Take the Tome of Thomas Thomson to the Costumed Orphan Matron in Goldshire, Kharanos or Azure Watch.", progress = "You have something for me, good <name>?", completion = "What is this?  The tome of Thomas Thomson?  But that is the name of the Horseman before he was cursed!  Does this mean that he is finally free?  Does this mean he will no longer torment the good people of Azeroth?\n\nWhat a joyous day!  <name>, your feat will live long with us.  The children, and their children, will sing your name!" }
WordHunterWoW_QuestEN[11243] = { title = "If Valgarde Falls...", description = "If Valgarde falls, our primary supply line into Northrend will cease to exist. From there it'll only be a matter of time before we're all servants of the Lich King. Now I don't know about you, but I've got a wife and three kids back in Elwynn and I'll be damned if I'll go down without a fight.\n\nThe situation here is critical and we can use all the manpower you're able to muster. Get to the front gate and help the guards defend the city against the invading monsters!", objectives = "Vice Admiral Keller at Valgarde Port in the Howling Fjord wants you to slay 12 Dragonflayer Invaders or Dragonflayer Worgs.", progress = "The fate of the world may very well rest with us.", completion = "You gave our defenders the extra support they needed, <name>. Morale is higher than ever now, thanks to you. I think they'll be able to handle the remaining onslaught on their own. I've got bigger plans for you..." }
WordHunterWoW_QuestEN[11244] = { title = "Rescuing the Rescuers", description = "We'd been here for a month when those malformed giants appeared out of thin air. We were ill-prepared for any sort of attack and paid dearly for our complacency. An entire archaeology team was lost and several townsfolk were abducted and taken to the ruins. We've been on the defensive ever since.\n\nTo make matters worse, the scouts we sent to rescue our people have been harpooned by the vrykul and left for dead in the forest directly north of Valgarde. Dislodge those harpoons and free our scouts!\n", objectives = "Vice Admiral Keller at Valgarde Port in the Howling Fjord wants you to rescue 8 Valgarde Scouts that have been impaled and left for dead.", completion = "What the vrykul did to our scouts was a gruesome display of savagery. It was a scare tactic, meant to weaken our resolve... to send us running in fear for our lives.\n\nIt failed.\n\nWe are going to show those monsters what it means to wage war against the Alliance!" }
WordHunterWoW_QuestEN[11245] = { title = "Towers of Certain Doom", description = "Sir, as we move through Skorn, we have to bring down those towers!\n\nIf you have a look at them, you'll notice that their tops are lined with casters. Getting too close to them would mean certain doom for us!\n\nHowever, we do have it within our means to call in cannon volleys from Westguard Keep. To do so, we need to get close enough so that you can lob a smoke flare atop of them.\n\nJust don't get too close!", objectives = "The Westguard Sergeant has informed you that using the Sergeant's Flare to target all four of the towers at Skorn for cannon volleys would be advisable.", completion = "Excellent targeting, sir! I'll have to remember to buy a round for the cannoneers back at the keep." }
WordHunterWoW_QuestEN[11246] = { title = "Gruesome, But Necessary", description = "We've had reports that these vrykul can rise from the dead; not unlike the Scourge, but a different kind of undeath.\n\nLet's not take any chances.\n\nHere, take my machete. As we move through this place, you'll need to carve up the remains of the vrykul that we take down. I'd do it, but I have a sensitive stomach.\n\n<The sergeant smirks.>\n\nI spent all morning sharpening it, so it should do the job.", objectives = "The Westguard Sergeant has asked you to use The Sergeant's Machete to dismember 20 Vrykul of the Winterskorn tribe at Skorn.", completion = "Well, sir, I have to say that you went about that particular business with a bit of zeal.\n\n<The sergeant looks at you warily.>\n\nAnyway, if you don't mind, I'll be taking my machete back now. It looks dull and we wouldn't want you to accidentally slip and carve me up, too." }
WordHunterWoW_QuestEN[11247] = { title = "Burn Skorn, Burn!", description = "Captain Adams gave me strict instructions to make sure that a good deal of infrastructure damage was inflicted on this site.\n\nHowever, since you're in charge out here, that's at your discretion, sir.\n\nMay I suggest that we burn down the two longhouses and the barracks that are in the lower area of Skorn? All we have to do is get inside each and throw this torch.", objectives = "The Westguard Sergeant has orders that you should use the Sergeant's Torch to set fire to the Northeast and Northwest Longhouses and the Barracks at Skorn.", completion = "Very good, sir. That couldn't have been done without your help.\n\nI'm sure that the captain will be pleased with my report on the matter once we're done here." }
WordHunterWoW_QuestEN[11248] = { title = "Operation: Skornful Wrath", description = "{name}, I must now ask you to undertake an operation so hazardous, so deadly, that only you can see it through.\n\nThe vrykul fortress, Skorn, sits on our eastern border. My scouts inform me that those 'giants' are poised to strike us, and with my forces scattered all over the fjord, I don't have the men to take the place by force.\n\nInstead, you're going to use your cunning. I've sent a sergeant ahead with the details. Show this command insignia at Skorn and he'll reveal himself and follow your orders.", objectives = "Captain Adams has asked you to use the Westguard Command Insignia at Skorn, and then to speak with the Westguard Sergeant.\n\nProvided item:", completion = "A pleasure to meet you, sir! I look forward to working with you.\n\nSpeaking of which, we have a great deal to do." }
WordHunterWoW_QuestEN[11249] = { title = "Stop the Ascension!", description = "This huge scroll is made from dragon skin. Unfurling its more-than-ten-foot length, you can see that the images painted upon its scaly surface depict a mysterious vrykul ritual.\n\nA vrykul thane, surrounded by angelic-looking beings, ascends into the heavens. A mysterious, darkened figure looms large in the picture's background.\n\nA tingling in your gut tells you that the thane of Skorn is about to do this. You must stop it! A large pyre sits at the top of Skorn in front of the thane's lodge.", objectives = "Present the Vrykul Scroll of Ascension near the Thane's Pyre to call him out and slay him. Afterward, due to the nature of the ritual, you're sure that Father Levariol at Westguard Keep will be interested in seeing the scroll.", progress = "Yes? How may I help you, my child?", completion = "Yes, my son, that is ominous-looking, and you obviously had the right of it.\n\nThank you for bringing this scroll to me. I am very keen to study its implications. If I were to hazard a guess, I would say that these vrykul have a way to transcend death; at least those that are worthy.\n\nBy defeating the Winterskorn thane, you proved him unworthy. The Light only knows what he would have become, and what terror he might have rained down upon us, had you not slain him." }
WordHunterWoW_QuestEN[11250] = { title = "All Hail the Conqueror of Skorn!", description = "We -- well, you -- have done everything that we were sent here to accomplish sir. I must say that it's been a pleasure taking orders from such a fine, young {race}.\n\nThe captain is sure to want to hear of your success, but if you decide to stay out here for whatever reason, I am at your disposal.", objectives = "Return the Westguard Command Insignia to Captain Adams at Westguard Keep.", progress = "I gather that since you're here, Skorn is no more?", completion = "That's unbelievably good news! I knew that you could pull it off, <name>!\n\nAt least someone around here can produce results!\n\nWell, this calls for a reward. Go ahead, take your pick; the treasury is open to you." }
WordHunterWoW_QuestEN[11251] = { title = "Fresh Legs", description = "It's come at great cost, but we've completed our inspection of the site.\n\nThe news isn't good. Nearly everyone has been slain or captured. Only a few veteran guards remain unaccounted for.\n\nThe scouts have done all we can here. You must pick up where we've left off.\n\nSounds of a skirmish are coming from up the hill to the northeast. Have a look, {class}. We can only hope there are some who have survived, and that they may have some intel we can use against this enemy.", objectives = "Scout Valory wants you to investigate the sounds of battle coming from the northeast of Wyrmskull Village.", completion = "Late though ye may be, it's good to see a friendly face.\n\nNow stop standin' around with yer thumb up yer nose. there's work to be done!" }
WordHunterWoW_QuestEN[11252] = { title = "Into Utgarde!", description = "Listen up, youngster. I've put down me share of these creatures - and your share too fer that matter. Here be what ya need to know....\n\nThe vrykul are fearless in a fight. Seems they actually yearn fer a death in battle. With their numbers and that ferocity, we're doomed - plain and simple.\n\nThere's one they esteem though, goes by the name of Ingvar. I dunno why they be seekin' his praise, but bring him down and you'll deal a mighty blow to their spirit.\n\nThen, perhaps, we'll have a chance....", objectives = "Defender Mordun has tasked you with the execution of Ingvar the Plunderer who resides deep in Utgarde.\n\nYou are then to bring his head to Vice Admiral Keller.", progress = "Good to see you're well, <name>.\n\nWe've had about as many casualties as we can handle.", completion = "Outstanding!\n\nThis could be the turn of luck we've all been hoping for.\n\nWell done, <name>!" }
WordHunterWoW_QuestEN[11253] = { title = "Sniff Out the Enemy", description = "Now that this rascal's belly's full, maybe he will be more willing to cooperate.  Here's his leash, just come get him from his cage whenever you're ready to take him.\n\nI don't know what Anselm expects you to find, but look for clues wherever it is that the dog takes you.", objectives = "Use the Plaguehound Leash near the plaguehound cages at Vengeance Landing and look for clues at the location you're led to by the Plaguehound Tracker.\n\nProvided item:", completion = "This scaly scroll is covered in stark painted images.  You've a feeling this is the sort of thing the kennel keeper had in mind when he asked you to look for clues." }
WordHunterWoW_QuestEN[11254] = { title = "The Dragonskin Map", description = "Upon closer inspection, the scroll appears to be a heavily-illustrated map of the fjord.  The location of various villages are depicted in what seem to be tribal symbols.\n\nThe location of Vengeance Landing is marked with a disproportionately large skull.\n\nThis map will almost certainly be of military value to High Executor Anselm.", objectives = "Bring the Dragonskin Map to High Executor Anselm in Vengeance Landing.", progress = "You've something to show me, <class>?", completion = "<The high executor looks at the map intently, occasionally looking up at landmarks around the Fjord.>\n\nHere's the eastern coastline over here.  The Dragonflayer and Winterskorn villages are here and here... and this must be us over here, marked for death." }
WordHunterWoW_QuestEN[11255] = { title = "Prisoners of Wyrmskull", description = "This battle is far from over, {name}. If our people are still alive inside that village, someone has to go and get 'em.\n\n<Vice Admiral Keller nods at you.>\n\nHead north and enter Wyrmskull Village. Once there, look for our people. If they are imprisoned you'll need to find a way to break them out.\n\nMaybe they'll have some more information about what it is that we're actually fighting.", objectives = "Vice Admiral Keller at Valgarde Port in the Howling Fjord wants you to rescue 3 Captured Valgarde Prisoners.", completion = "Those soldiers you rescued had a good bit of information for us. These monsters call themselves 'vrykul.' The tribe that's taken up residence in Wyrmskull Village is led by a mystic named Yanis who himself is an underling of another vrykul known as Ingvar the Plunderer." }
WordHunterWoW_QuestEN[11256] = { title = "Skorn Must Fall!", description = "{name}, the vrykul fortress, Skorn, sits to the south. Its strange giants have recently awakened and have begun to spread, attacking us wherever they can.\n\nMy scouts inform me that they are poised to strike at us here, but I do not have the strength to repel such a force. Instead, we will prepare to leave north to less dangerous lands.\n\nI ask that you use your cunning to buy us time. I've sent a brave ahead with the details. Show this emblem at Skorn and he'll reveal himself and do all he can to aid you.", objectives = "Chieftain Ashtotem has asked you to use the Winterhoof Emblem at Skorn, and then to speak with the Winterhoof Brave.\n\nProvided item:", completion = "It will be interesting to learn about your people, <class>, while fighting alongside you.\n\nShall we proceed?" }
WordHunterWoW_QuestEN[11257] = { title = "Gruesome, But Necessary", description = "Our elders say that these vrykul may be able to rise from the dead; not unlike the walking dead you call the Scourge, but a different kind of undeath.\n\nWe should not take any chances.\n\nHere, take my machete. As we move through this place, carve up the remains of the vrykul that we slay.\n\nI spent the morning sharpening it, so it should cleave even through their thick bones.", objectives = "The Winterhoof Brave has asked you to use The Brave's Machete to dismember 20 Vrykul of the Winterskorn tribe at Skorn.", completion = "Have you done that before? Your skill with my machete seemed practiced.\n\n<The brave looks at you warily.>\n\nI'll take it back from you now, <class>." }
WordHunterWoW_QuestEN[11258] = { title = "Burn Skorn, Burn!", description = "Chieftain Ashtotem ordered me to destroy many buildings here.\n\nHowever, you are in charge, so it falls to your hands, {name}.\n\nI suggest that we burn down the two longhouses and the barracks that are in the lower area of Skorn. All we have to do is get inside each and set them ablaze with this torch.", objectives = "The Winterhoof Brave suggests that you use the Brave's Torch to set fire to the Northeast and Northwest Longhouses and the Barracks at Skorn.", completion = "<The brave nods at you in clear approval of your handling of the torch>\n\nLet these vrykul feel the heat of the land. Let them know the fear they would instill in others!" }
WordHunterWoW_QuestEN[11259] = { title = "Towers of Certain Doom", description = "As we move through Skorn, we must destroy the towers.\n\nIf you have a look at them, you'll notice that their tops are lined with casters. Getting too close to them would mean certain doom.\n\nHowever, we can call in wind rider air strikes from Camp Winterhoof. To do so, we need to get close enough so that you can lob a smoke flare atop of them.\n\nJust don't get too close.", objectives = "The Winterhoof Brave has informed you that using the Brave's Flare to target all four of the towers at Skorn for air strikes would be advisable.", progress = "Getting too close to those towers is certain death as long as those casters are up there.", completion = "You have a strong arm, <name>.\n\nIt looks as if those wind riders finally made themselves useful instead of just standing around and drinking all day." }
WordHunterWoW_QuestEN[11260] = { title = "Stop the Ascension!", description = "This huge scroll is made from dragon skin. Unfurling its more-than-ten-foot length, you can see that the images painted upon its scaly surface depict a mysterious vrykul ritual.\n\nA vrykul thane, surrounded by angelic-looking beings, ascends into the heavens. A mysterious, darkened figure looms large in the picture's background.\n\nA tingling in your gut tells you that the thane of Skorn is about to do this. You must stop it! A large pyre sits at the top of Skorn in front of the thane's lodge.", objectives = "Present the Vrykul Scroll of Ascension near the Thane's Pyre to call him out and slay him. Afterward, due to the nature of the ritual, you're sure that Greatmother Ankha at Camp Winterhoof will be interested in seeing the scroll.", progress = "Yes? How may I help you, child?", completion = "Yes, that is ominous-looking, and you obviously had the right of it.\n\nThank you for bringing this scroll to me. I will study its implications. If I were to hazard a guess, I would say that these vrykul have a way to transcend death; at least those that are worthy.\n\nBy defeating the Winterskorn thane, you proved him unworthy. Who knows what he would have become, and what terror he might have rained down upon us, had you not slain him?" }
WordHunterWoW_QuestEN[11261] = { title = "The Conqueror of Skorn!", description = "You have done everything that we were sent here to do, {class}. I must admit that you fight well. Your people are not as strange as I first thought.\n\nChieftain Ashtotem is certain to want to hear of your success, but if you decide to stay out here for whatever reason, I will continue to fight at your side.", objectives = "Return the Winterhoof Token to Chieftain Ashtotem at Camp Winterhoof.", progress = "What news do you bring of Skorn, <name>?", completion = "That is good news indeed! You have given us some breathing room to further our preparations for leaving.\n\nPlease, take one of these as a sign of our appreciation." }
WordHunterWoW_QuestEN[11262] = { title = "Ingvar Must Die!", description = "Of our entire recon party, only I remain.\n\nThese vrykul are relentless fighters. Given their numbers and their savage tactics, our only hope is to bring down their leader and pray it brings chaos to their ranks.\n\nIngvar is his name. Bring me his head!", objectives = "Dark Ranger Marrah has asked you to kill Ingvar the Plunderer inside Utgarde Keep.", progress = "Gird up, <race>.\n\nThere's much work to be done. This is just the tip of the iceberg, so to speak.", completion = "Excellent work, <name>. With their leader removed, our efforts against these vrykul should be more successful.\n\nService such as this cannot go unrewarded!" }
WordHunterWoW_QuestEN[11263] = { title = "Dealing With Gjalerbron", description = "My longrunners that have lived to return have informed me that the vrykul have awakened at their main fortress to the west.\n\nIt is a forbidden place known as Gjalerbron. The longrunners tell me that the vrykul are performing strange rituals.\n\nWe cannot allow this to continue.\n\nAre you willing to continue to assist us? Will you kill the vrykul at Gjalerbron before they finish whatever they are doing and attack us here?", objectives = "Chieftain Ashtotem has asked you to kill 15 Gjalerbron Warriors, 8 Gjalerbron Rune-casters, and 8 Gjalerbron Sleep-watchers. Afterward, return to him at Camp Winterhoof.", completion = "You have my thanks, <name>. I know that you do not have any duty to me or my people.\n\nWhat you say about that place troubles me still, and I sense that our culling is not quite at an end." }
WordHunterWoW_QuestEN[11264] = { title = "Necro Overlord Mezhen", description = "The dead ones are at Gjalerbron and they have necromancers with them?\n\nWe must eliminate the leader of these necrolords.\n\nDo whatever it takes, {name}, but see to it that Necro Overlord Mezhen, and whatever he's attempting to accomplish, is neutralized.\n\nWe cannot afford to see the vrykul successful in whatever they are doing with these undead creatures!\n\nLook for Mezhen on the platform in the rear right section of Gjalerbron.", objectives = "Kill Necro Overlord Mezhen. Then, return to Chieftain Ashtotem at Camp Winterhoof.", completion = "<Chieftain Ashtotem breathes a sigh of relief.>\n\nThat should take some of the pressure off.\n\n<name>, time and again you have proven your value to the taunka of Camp Winterhoof. Please, choose something from our bounty. I insist." }
WordHunterWoW_QuestEN[11265] = { title = "Of Keys and Cages", description = "From the little we know, the vrykul are conducting unnatural rites in an 'awakening' ritual to the west in Gjalerbron.\n\nThey're using living sacrifices to fuel their rituals.\n\n{name}, you must stop this. It matters not who or what is in those cages, they must be freed. I would guess that the vrykul hold the keys.\n\nThe last thing we need is more of those strange vrykul threatening us, or worse, them wakening something even more evil....", objectives = "Greatmother Ankha has asked you to collect enough Gjalerbron Cage Keys to free 10 Gjalerbron Prisoners. Return to her at Camp Winterhoof when you manage to do so.", completion = "A great stone is lifted from my shoulders to hear of your success. And I smile to know that some you freed were taunka.\n\nPlease, take this as a gift for what you have done. I shall see to the health of those you freed." }
WordHunterWoW_QuestEN[11266] = { title = "Gjalerbron Attack Plans", description = "These plans detail an imminent attack upon Camp Winterhoof. It would appear that the frost wyrm, Glacion, who circles overhead, is to be used for the offensive.\n\nSurely Celea Frozenmane would be of some assistance in this matter. Deliver the plans to her at the camp to the east.", objectives = "Deliver the Gjalerbron Attack Plans to Celea Frozenmane at Camp Winterhoof.", progress = "What?! Plans for an attack upon our camp?\n\nFROM A GREAT WYRM IN THE SKY?!!!", completion = "<name>, we cannot let this come to pass!" }
WordHunterWoW_QuestEN[11267] = { title = "The Frost Wyrm and its Master", description = "Your instincts were right to bring this to me, but my wind riders cannot fight a dragon. You must venture west to Gjalerbron and slay the frost wyrm and its master, Wyrmcaller Vile!\n\nEven now it may be on its way!\n\nIf I'm reading these plans correctly, blowing the wyrmcaller's horn on his platform, outside in the rear left area of Gjalerbron, will call Glacion back. When the creature lands, destroy it!\n\nAnd {name}, bring me the horn. We wouldn't want it falling back into the wrong hands!", objectives = "Slay Wyrmcaller Vile and use the Wyrmcaller's Horn to call down and slay Glacion. Then, return with the horn to Celea Frozenmane at Camp Winterhoof.", progress = "Is the attack averted? Is the great death wyrm and its master destroyed?\n\nDid you retrieve the horn?", completion = "This horn is as cold as the land... perhaps even colder!\n\nYou have saved Camp Winterhoof from certain doom, not that we'll be staying here much longer. What a curious man you are, <name>. Perhaps you <race>-types from over the ocean are not so bad after all.\n\nThis calls for a reward. Which do you prefer?" }
WordHunterWoW_QuestEN[11268] = { title = "The Walking Dead", description = "Your assistance to us has been tremendous, {name}, but there is something that is troubling me: these so-called Scourge.\n\nThe spirits of the land and air, the waters and the fire below the world, would not abide their presence, but seem to do nothing about them. We will see to it that they are dealt with!\n\nPerhaps it is asking too much, but I would have you return west to Gjalerbron and destroy the unnatural Scourge in that vile lair. Be sure to check in the Waking Halls below Gjalerbron as well!", objectives = "Slay 10 Deathless Watchers, 4 Fearsome Horrors, and 2 Putrid Wights. Afterward, inform Greatmother Ankha at Camp Winterhoof of your success.", completion = "<The greatmother nods her approval of your actions.>\n\nThank you, <name>, you have done what is right and you have bought us a little more time to finish our preparations for leaving. We will soon make the journey north.\n\nI am too old; when we go, I will not be able to carry everything with me. Would you like to take one of these?" }
WordHunterWoW_QuestEN[11269] = { title = "Down to the Wire", description = "The vanguard of the Alliance force will be arriving within days. The soldiers will be expecting their winter gear to be prepared, but I've still got more cloaks to make.\n\nI've been using spotted hippogryph down for the cloaks' linings, but my stock won't last!\n\nYou've got to help me, {name}. Captain Adams will have my hide if those cloaks aren't ready in time! Bring me all the down you can find out there. It's dropped to the ground by molting hippogryphs flying over the wilderness around the fort.", objectives = "Gil Grisert wants you to bring him 10 clumps of Spotted Hippogryph Down.", progress = "Have you brought any of that down? I could really use it...", completion = "Thank goodness! This should be enough to finish the order in time. Of course, I won't sleep until the troops arrive, but that's far better than risking Captain Adams' wrath.\n\nI've heard the stories they tell about him!" }
WordHunterWoW_QuestEN[11270] = { title = "War is Hell", description = "We're slowly finishing off the remnants of Stormwind's North Fleet stationed on this coast.  The bodies to the west are a testament to how brutal this confrontation has been.\n\nThis does not happen to bother my refined aesthetics, but it does present a danger to our lives.\n\nIn the lands of the Lich King, the dead are a weapon that can rise against us at any point in time.  Take this torch - you're going to make sure that doesn't happen.", objectives = "High Executor Anselm at Vengeance Landing wants you to take the Burning Torch and use it to burn 10 of the corpses littered to the west of town.", completion = "I'm glad you've proven you can follow orders.  If I had a copper piece for every arrogant fool in shiny armor to come here and think they're above the chain of command... well, I'd have a few gold.\n\nNow that you've demonstrated a measure of discipline, I have other tasks more suitable for someone of your caliber." }
WordHunterWoW_QuestEN[11271] = { title = "Hasty Preparations", description = "The down of the spotted hippogryph is prized by my people and used for everything from fletching to ceremonial clothing. We're making preparations to leave the post, so this is the last chance I'll get to gather it this season.\n\nWith your help, I'll have enough to make sure everyone has the equipment they need for the long trek into the hills. Conditions worsen very quickly up there and a storm can blow in without warning.\n\nThe down can be found all over the ground in the area surrounding the post.", objectives = "Ahota Whitefrost at Camp Winterhoof wants you to bring him 10 clumps of Spotted Hippogryph Down.", progress = "Have you gathered any of the down?", completion = "With your contribution, we'll be well prepared for the journey. I haven't much to offer you for your help, but I will give you a choice of some of my spare combat gear." }
WordHunterWoW_QuestEN[11272] = { title = "A Score to Settle", description = "This elf prince thinks he can come to my town, insult my queen, kill my men and get away with it? He thinks we're going to stand by while the hordes of Utgarde build up to launch an attack?\n\nNot in a million years.\n\nYou're going to walk right into Utgarde and kill him. I want Arthas to know that we've arrived and we're playing for keeps.\n\nReport to Dark Ranger Marrah inside Utgarde Keep when the deed is done and she'll tie up any... loose ends.", objectives = "High Executor Anselm wants you to slay Prince Keleseth inside Utgarde Keep.", completion = "Revenge feels good.  To think that this is but a taste of what's to come.\n\nArthas will get what he deserves soon enough.  Then and only then will I die a happy man." }
WordHunterWoW_QuestEN[11273] = { title = "The Human League", description = "We were on the brink of an archaeological breakthrough when those monsters attacked! Sadly, I was the only one to make it back to Valgarde. Now I don't know if my crew is dead or alive, but the artifacts we uncovered on that dig must be found!\n\nIf you're heading into Wyrmskull Village, will you keep an eye out for my team? If there's any hope of recovering that information, we must pursue it!\n\nSearch for Pulroy first. He was the last one I saw before I made my escape.", objectives = "Search Wyrmskull Village for Pulroy.", completion = "You've found Pulroy. A bit too late it seems.\n\nWhile looking over the corpse you see a journal clenched tightly in Pulroy's death grip. Upon examining the journal you read what appears to be the scribbling of a dying dwarf." }
WordHunterWoW_QuestEN[11274] = { title = "Zedd's Probably Dead", description = "To whomever finds this journal:\n\nThese bloodthirsty monsters have taken up residence in the ruins of Wyrmskull. What they want or why they're here is a mystery. In any case, the artifacts are not safe with those beast-men around.\n\nZedd and I made a new discovery while hiding out: a cipher to decode the tablets! Unfortunately Zedd and I were separated late last night. He had the cipher. Tablets were with Glorenfeld and Daegarn. Location unknown...\n\nFind Zedd.\n\n-Pulroy", objectives = "Search Wyrmskull Village for Zedd.", completion = "You've found Zedd. You're no doctor but the prognosis for Zedd is most assuredly negative.\n\nIt looks as if they were preparing to feed him to the worgs. Gruesome..." }
WordHunterWoW_QuestEN[11275] = { title = "Making the Horn", description = "My people have been hunting the giant yeti of these hills for generations and I will be participating for the first time this year. It will probably be the last before we leave the post forever.\n\nTo prepare for the hunt, I must fashion a loud horn from the horns of the dire rams that roam the snowy areas near our camp. The elders tell me the sound mimics the mating call of the female yeti, but I have my doubts.\n\nBring me the best dire ram horns you can find, {name}, and I'll select one from among them.", objectives = "Nokoma Snowseer at Camp Winterhoof wants you to bring her 6 Undamaged Ram Horns.", progress = "Have you brought any suitable horns?", completion = "These are all fine horns, <name>. Let me examine them and select the one I will use in the hunt.\n\nI'll give the rest to the craftsmen for use in their carvings." }
WordHunterWoW_QuestEN[11276] = { title = "And Then There Were Two...", description = "There's no sign of the cipher on Zedd. After carefully searching the area you discover some writing in the dirt:\n\n\"Glor and Dae inside catacombs. Have cipher and tablets.\"\n\nPerhaps you should head into the catacombs located just north of here and search for Glorenfeld and Daegarn. The bridge crossing the worg pit will lead you right to the tunnel leading down into the catacombs.", objectives = "Search the Utgarde Catacombs for Glorenfeld.", completion = "About bloody time! Pulroy and Zedd are dead.\n\nAnd Daegarn...\n\n<Glorenfeld shakes his head.>\n\nTaken by the Dragonflayer chieftain into the depths of these catacombs. I overheard that oversized mongrel mention something 'bout a sacrifice to the \"Dread King.\"\n\nThe cipher is hidden away in Daegarn's grimy beard.\n\nWhat? Dwarves hide things in their beards all the time!" }
WordHunterWoW_QuestEN[11277] = { title = "The Depths of Depravity", description = "They're keepin' Daegarn locked up in a cage at the large fightin' ring nearby. From what I've gathered, the Dragonflayers bring out their prisoners to battle against their most powerful gladiators. They dump the losers in the basement where Scourge necromancers turn 'em into ghoulies! It's horrifying!\n\nBut first things first! The tablets are strewn about all across this dungeon. Let's get those recovered before you go off tryin' to be a hero.", objectives = "Glorenfeld at the Utgarde Catacombs wants you to collect 10 Wyrmskull Tablets.", progress = "Check every nook and cranny!", completion = "You've done well, mate. Now that we've secured the tablets we can try and save Daegarn's life and recover the cipher that will help us decode the meaning behind these ancient relics!\n\nI'll hold on to these tablets, you rescue Daegarn." }
WordHunterWoW_QuestEN[11278] = { title = "Return to Valgarde", description = "'Tis a shame we lost two of our best dwarves while uncovering these relics. They sacrificed their lives to keep this information safe.\n\n<Glorenfeld wraps the cipher and tablets in a tattered cloth.>\n\nTake these back to Valgarde. McSorf will know what to do with the find.\n\nAs for me? I'll be alright on my own. I've gotten this far in one piece!", objectives = "Take Glorenfeld's Package to Beltrand McSorf at Valgarde Port.", progress = "You're back!", completion = "Sorting these tablets out is going to take some time. All I can gather from a precursory study is that whatever used to be here was an ancestor of the humans. Those vrykul things probably killed 'em all off. Anyhow, we'll know more once I get these relics set up." }
WordHunterWoW_QuestEN[11279] = { title = "Green Eggs and Whelps", description = "This new plague that we're working on is wonderful and I think we should expand its testing.\n\nHow about testing it on proto-whelps?!\n\nJust think of the possibilities. The ability to infect not only humanoids, but extend our reach to any creature!\n\nHere, I've hoarded an extra plague canister for the right time and place, and you look like the right person.\n\nSpray the eggs at Ember Clutch to the northwest, then get specimens from the plagued proto-whelps that hatch.", objectives = "Plaguebringer Tillinghast has asked you to collect 10 Plagued Proto-Whelp Specimens and deliver them to him at New Agamand.", progress = "Without those samples, how am I to tell if this latest strain of the plague can be expanded for use on all sorts of creatures?", completion = "What?! No, this can't be right.\n\nCURSES!\n\nThis batch of the plague doesn't seem to have had any real effect on the proto-whelps at all other than to make them glow green!\n\nMy dream of using the plague upon anything we come into contact with seems to have gone up in smoke!" }
WordHunterWoW_QuestEN[11280] = { title = "Draconis Gastritis", description = "Wait, that gives me an idea! What if it didn't kill the whelps because it was sprayed on the outside of their eggs?\n\n{name}, we have to get the plague inside of them!\n\nI know! I've got some plagued meat here. Take it to the Ember Clutch and get them to eat it!\n\nBut no, we're thinking too small. Let's get one of the proto-drakes flying overhead to come down and eat it.\n\nYes!\n\nStay close to the meat and observe what happens. Yes, it might attack you, but such is the price of progress.", objectives = "Plaguebringer Tillinghast at New Agamand wants you to use Tillinghast's Plagued Meat to attract down a Proto-Drake and observe its reaction to eating the stuff.", completion = "NOOOOOOOOOOOOOOOO!!!\n\n<The plaguebringer begins to cry.>\n\nAll of my hopes... all of my dreams, ruined!\n\nLeave me, <name>. Leave me to my despair. I'm nothing.\n\nHere, you might as well take all of my worldly possessions. When the rest of the apothecaries hear of my failure, I'll be done for and won't need them anyway." }
WordHunterWoW_QuestEN[11281] = { title = "Mimicking Nature's Call", description = "The horn has been roughed out, but before I make the traditional carvings, I want to be certain that it will work. Ahota tells me that he tests his horns at the foot of the frozen waterfall to the northeast of the post. Ahota tells me that our hunters have used the acoustics of frozen water in this way for generations. I can't wait to learn more!\n\nWill you help me test out the horn? If I've done everything right, you may even attract a yeti, so be prepared! Bring the horn back once you've tested it. ", objectives = "Test the Carved Horn and then return to Nokoma Snowseer at Camp Winterhoof with the results.", completion = "<Nokoma listens to your report from the test.>\n\nI'm relieved that the horn worked so well... maybe too well if what you're saying was true. You're sure the beast spoke? I don't know if I can go on with the hunt if that's true. I'll have to speak with Chief Ashtotem about it.\n\nThis horn may end up being merely decorative, but that won't diminish its worth. Thank you for all your help, <name>." }
WordHunterWoW_QuestEN[11282] = { title = "A Lesson in Fear", description = "When you've been in lots of fight like Gorth, you learn that to beat enemy good you have to make them really scared to die!\n\nBut these vrykuls not afraid.  You kill one and another comes... screaming louder and with a bigger weapon than the one before.\n\nOnly thing that makes vrykuls afraid is when we kill the biggest and baddest vrykul of all.\n\nGo fight the Winterskorn across the blockade until hero vrykuls show up!  Then you kill them dead and put queen's flag on corpses.  They must learn to fear!", objectives = "Gorth wants you to kill Ulf the Bloodletter, Oric the Baleful and Gunnar Thorvardsson and drive the Forsaken Banner through their corpses. Slay Vrykul across the Forsaken blockade until they appear.", completion = "You do some good killings over there.  I see vrykul men fall and get stabbed with Sylvanas flag.  Our side doing good!" }
WordHunterWoW_QuestEN[11283] = { title = "Baleheim Bodycount", description = "Them vrykuls just keeps coming and coming out from town west of here.  No end in sight!\n\nGorth has an idea.  You go INSIDE town and kill them Winterskorn there.  THEN they stop coming here!", objectives = "Sergeant Gorth wants you to kill 16 Winterskorn Vrykul inside Baleheim.", completion = "You must have lots of practice with doing killings.  You almost as good as Gorth!" }
WordHunterWoW_QuestEN[11284] = { title = "The Yeti Next Door", description = "Maybe if the sentries won't help me, you will? I'm the foreman of the mine just across the bridge. My men are mining ore for the weapons our expeditionary force will need to carve a path into the Grizzly Hills.\n\nA giant yeti has invaded the mine, blocking the tunnel we need to expand! We've tried yelling at him and smoking him out, but nothing's worked.\n\nMaybe you could rouse it from its sleep with a meal of meat from the frosthorn rams in the snowy areas around town? Please? We're desperate!", objectives = "Foreman Colbey at Fort Wildervar wants you to defeat Shatterhorn.", completion = "You've done it? By the Light, you're a walking miracle! I was beginning to think I'd personally have to explain to Captain Adams why his men's weapons weren't ready in time!" }
WordHunterWoW_QuestEN[11285] = { title = "Baleheim Must Burn!", description = "Killing the Winterskorns maybe not enough.  Maybe we burn their houses too!  Uh... and their bridges.  We should burn whole town to be safe!\n\nYou take this torch.  Go to Baleheim, to the west, and burn EVERYTHING!  That teach them good.", objectives = "Sergeant Gorth wants you to go to Baleheim and use Gorth's Torch to burn 1 Winterskorn Dwelling, 1 Winterskorn Watchtower, 1 Winterskorn Bridge and 1 Winterskorn Barracks.", completion = "I guess you burned everything.  I see couple of spots not burning... but is close enough for Gorth." }
WordHunterWoW_QuestEN[11286] = { title = "The Artifacts of Steel Gate", description = "I came out here for a different reason; an old friend of mine has been calling to me in my dreams. But now that I see these small things with their machines making a big hole in the ground, it makes my blood boil.\n\nFrom what I can see, these dwarves, as they are known, are digging up artifacts; artifacts that could be important to our past.\n\nI want you to go down there and get these things for me. Don't let any of those dwarves stand in your way.", objectives = "Sage Mistwalker has asked you to collect 10 Steel Gate Artifacts. When you have all of them, return to him at Steel Gate.", progress = "How many artifacts have you managed to gather from this Steel Gate?", completion = "<The sage grunts his approval at your actions on his behalf.>\n\nPerhaps I will be able to find the time soon to study these artifacts and come to an understanding of their significance.\n\nBut now there are more pressing matters to attend to." }
WordHunterWoW_QuestEN[11287] = { title = "Find Sage Mistwalker", description = "{class}, I grow worried that my son, Sage Mistwalker, has been gone for such a long time. The land is cruel and deadly.\n\nHe spoke of a recurring vision that he had of a wolf, and went west with a small group of longrunners to seek its source. I believe the name of the place he mentioned was Steel Gate.\n\nWill you find him? I want to make sure that no ill has befallen him.", objectives = "Greatmother Ankha has asked you to check on the condition of Sage Mistwalker. She believes him to be at or near Steel Gate.", completion = "My mother should not concern herself with my safety. But, I thank you for coming, stranger.\n\nSince you are here, perhaps you will help me with a few things?" }
WordHunterWoW_QuestEN[11288] = { title = "The Shining Light", description = "<Ares gasps for air as he tries to speak.>\n\nI am an envoy of the Argent Crusade, charged with a sacred duty.\n\nOur forces were decimated in the Plaguelands. By the light of dawn, the artifact was cleansed and made pure once more. So many perished in the wake of its redemption.\n\nThere is still a chance... still time.\n\nThe artifact was hurled into the den of the fallen, far below us. Guarded by the unmerciful dead.\n\n<Ares' body glows with blinding light.>\n\nLight. Will. Protect. You.\n", objectives = "Ares the Oathbound in the Utgarde Catacombs wants you to recover the Sacred Artifact.\n\nThis is a timed quest.", progress = "<Ares is unconscious.>", completion = "You feel compelled to place the sacred blade next to the body of Ares.\n\nUpon doing this you are once again blinded by light." }
WordHunterWoW_QuestEN[11289] = { title = "Guided by Honor", description = "<Ares smiles.>\n\nGlory to the Light. You have done it!\n\n<Ares coughs.>\n\nTake the artifact and return it to Valgarde. Lord Irulon Trueblade awaits its return.\n\nFight with honor, friend. Always. Honor.\n\n<Ares dies.>", objectives = "Return the Sacred Artifact to Lord Irulon Trueblade at Valgarde.", progress = "By the Light!", completion = "Many men and women died to recover this blade. Alas, I fear valiant Ares will not be the last.\n\nBut you do the Light's work, hero. This sacred blade will be wielded by Lord Tirion Fordring himself. Even now the Argent Crusade works toward Icecrown. Lord Fordring has vowed that he will tear down the walls of the cursed place himself! And with the blade, he just might stand a chance against the Lich King.\n\nLord Fordring remains our greatest hope." }
WordHunterWoW_QuestEN[11290] = { title = "Dragonflayer Battle Plans", description = "While we were able to gather very little information as to the whereabouts of Ingvar, we do know that Yanis resides in a cave next to the worg pit inside Wyrmskull Village.\n\nIntelligence gathered from the rescued soldiers indicates that Yanis guards Dragonflayer battle plans.\n\nI need you to go back to Wyrmskull and recover those plans. Kill any vrykul that get in your way - including Yanis!", objectives = "Vice Admiral Keller at Valgarde Port in the Howling Fjord has asked that you bring him the Dragonflayer Battle Plans.", progress = "Have you recovered the Dragonflayer battle plans?", completion = "<Vice Admiral Keller glances over the plans.>\n\nOutstanding! By the looks of things, there are many more vrykul villages in the fjord. A different tribe of vrykul is preparing an assault on Westguard Keep. Hell, for all I know it may already be too late. We haven't heard from Westguard in days. Either way, we must alert Westguard!" }
WordHunterWoW_QuestEN[11291] = { title = "To Westguard Keep!", description = "<Vice Admiral Keller rolls up the battle plans.>\n\nWe've got all the information we need to keep Valgarde protected. You must take these battle plans to Westguard Keep, located on the western fjord cliff wall. Speak with the flight master assistant, Emilune Winterwind. She will put you on the back of a gryphon headed towards Westguard.\n\nOnce there, find Captain Adams. He's the one in charge. Adams will know what to do with these plans.", objectives = "Take the Dragonflayer Battle Plans to Captain Adams at Westguard Keep in the Howling Fjord.", progress = "Valgarde has not fallen? That's a surprise.\n\nMust be due to your help. It sure wasn't because of Keller.", completion = "<Captain Adams takes the plans from you.>\n\nI'm glad you decided to come over. My advisors and I will need some time to study these plans. In the meantime, we can use all the help we can get!" }
WordHunterWoW_QuestEN[11292] = { title = "Preying Upon the Weak", description = "Glad to meet you. I've come here from the Grizzly Hills to do business with your cohorts. My people maintain a large outpost there, and you'd do well to visit it when you head north.\n\nI've set up traps in the woodlands and snowy areas around here. With the meat and the furs from the creatures they capture, I'll have plenty to barter with the townspeople.\n\nI can offer you a share of my profits if you're willing to help gather prey from the traps. Beware though, you won't be the only predator out there.", objectives = "Trapper Jethan at Fort Wildervar wants you to bring him 8 pieces of Trapped Prey.", progress = "I hope you haven't returned empty-handed. I thought we had a deal.", completion = "<Trapper Jethan inspects the creatures you've brought him.>\n\nNicely done. Some of these will fetch a better price than others, but I should have plenty to trade with the locals." }
WordHunterWoW_QuestEN[11293] = { title = "Bark for the Barleybrews!", description = "We need to get the word out about the Barleybrews at Brewfest.  You need to shout at the flags outside the bank, in the Military Ward, in the Hall of Explorers and in the Mystic Ward.  I'll make things easy though, I'll lend you a racing ram for 4 minutes.  Use the reins to let him go, but try not to tire him out.", objectives = "Spread the word about Brewfest at the flags outside the bank, in the Military Ward, in the Hall of Explorers and in the Mystic Ward.", progress = "Have you finished spreading the word about Brewfest?  But more importantly, did you let people know about the Barleybrews?", completion = "Well done!  That kinda shouting is sure to bring business our way.\n\nAnd we promised you a reward, here it is.  The Barleybrews keep their word.\n\nOh, and come back any other day if you want to help spread the good name of Barleybrew." }
WordHunterWoW_QuestEN[11294] = { title = "Bark for the Thunderbrews!", description = "It's time to let people know that the Thunderbrew have heard their cries for good brew.  You need to shout at the flags outside the bank, in the Military Ward, in the Hall of Explorers and in the Mystic Ward.\n\nWe'll make it easy though.  We'll lend you a ram for 4 minutes.\n\nBe careful with going too fast though since you won't find any apple crates in Ironforge...  We can't take the chance of helping out the Barleybrew messengers.", objectives = "Spread the word about Brewfest at the flags outside the bank, in the Military Ward, in the Hall of Explorers and in the Mystic Ward.", progress = "Did you let everyone know that the Thunderbrews are here at Brewfest?", completion = "Good job!  That'll show those arrogant Barleybrews.\n\nWell we promised you a reward and here it is.  We Thunderbrew reward you with prizes, the Barleybrew reward you with foul odors and false promises.\n\nYou chose wisely.\n\nIf you want to keep making the right choice, stop by another day and help us spread the word." }
WordHunterWoW_QuestEN[11295] = { title = "The Offensive Begins", description = "No one seems to know very much about the vrykul.  Our records show no signs of activity in their lands for centuries.  Yet here they are, just as we move against Arthas.\n\nThe map you retrieved makes it clear that we'll have to defeat them if our forces are to get any further into Northrend.\n\nOne of my best sergeants, an abomination known as Gorth, oversees the blockade beyond the lift.  Assist him in launching a pre-emptive strike on Baleheim.  If a vrykul attack occurs, it will be launched from there.", objectives = "Speak to Sergeant Gorth at the blockade near the elevator west of Vengeance Landing in Howling Fjord.", completion = "You come to help?  Good... good...\n\nGorth was getting tired of killing vrykuls all day.  Help is welcome!" }
WordHunterWoW_QuestEN[11296] = { title = "Rivenwood Captives", description = "Something, most likely the walking dead known as the Scourge, has agitated the creatures hereabouts.\n\nWhile escorting the sage here, we lost most of our hunting force to the riven widows -- huge and deadly spiders, which inhabit the Rivenwood to the north.\n\nI must stay here to protect the small force we have left, but you... you could see if my longrunners are still alive, trapped within the riven widow's cocoons.\n\nWould you do this, stranger?", objectives = "Longrunner Skycloud has asked you to free his 7 Winterhoof Longrunners. Once you have managed to do so, return to him at Steel Gate.", completion = "That was a very brave act, <class>. I did not know that your people were capable of such selflessness.\n\nNext time I will heed the warnings of my elders and steer clear of the Rivenwood. I advise you to do the same." }
WordHunterWoW_QuestEN[11297] = { title = "Keeping Watch on the Interlopers", description = "Even the earth cannot hold back the tide of death washing over it. Corpses walk the land, spreading their putrefaction with alarming speed.\n\nA small expedition has made its way up the western cliffs and rests near Whisper Gulch. Take a look for yourself, {name}. See if you can learn their purpose and dissuade them from bringing their poisons into our lands. Travel southwest from the post, toward the cliffs overlooking the western beach. Their camp will be west of the excavation at Steel Gate.", objectives = "Speak to Apothecary Malthus at the Apothecary Camp.", completion = "Ah, yes, the reclusive bison-men of the north. I've seen them skulking about, believing themselves unseen. I suppose they fancy this land theirs? Well, that's but one of many things that will change shortly.\n\nI wasn't expecting any company, but while you're here on that fool's errand, you might as well make yourself useful." }
WordHunterWoW_QuestEN[11298] = { title = "What's in That Brew?", description = "To the southeast is an area called Whisper Gulch. It's overrun with members of the Explorers' League who've gone mad! They attacked our caravan as it passed through the area, and they've harried our foraging parties as well.\n\nI must know what's causing this madness! I suspect that whatever they're drinking from the kegs scattered around the gulch contributes to their insanity. I want you to steal the kegs from those dwarves while they're busy mining away.", objectives = "Apothecary Malthus at the Apothecary Camp wants you to bring him 5 Dwarven Kegs.", progress = "Did you get those kegs or not?", completion = "<The apothecary pours out a tankard of the beverage for himself.>\n\nWell, here I go!" }
WordHunterWoW_QuestEN[11299] = { title = "The Ring of Judgment", description = "You might have already seen the room where Daegarn is being held while you were gatherin' the tablets. It's through this corridor and then down a set of steps. Daegarn will be in the room at the bottom of the steps - locked up tight!\n\nGet down there and find him. At the very least you might be able to get the cipher from him.", objectives = "Find Daegarn in the Ring of Judgment located inside the Utgarde Catacombs.", completion = "Yep. You found me. Woopedy-do!\n\nAnd no, I don't have the cipher. My beard was the first thing those beasts checked! Oluf's the one that's got it now. He's the chieftain of the gladiators." }
WordHunterWoW_QuestEN[11300] = { title = "Stunning Defeat at the Ring", description = "Oluf will come out if you defeat the other gladiators. That's 'bout the only way we're getting' that cipher back. Put on your whompin' boots and get busy in the Ring of Judgment. If you do manage to get the cipher back, return it to Glorenfeld o'er near the entrance to these catacombs.\n\nMe? Don't worry about me! We're on the brink of discovering the missing link to human-kind!", objectives = "Defeat the gladiators at the Ring of Judgment and face Oluf the Violent. Defeat Oluf and recover the Ancient Cipher.\n\nReturn the Ancient Cipher to Glorenfeld at the entrance to the Utgarde Catacombs.", progress = "Daegarn? The cipher?", completion = "Fascinating tale! Something is actually judgin' these things? To what end?! For what purpose?\n\nWell, never mind that nonsense. Someone else can figure out that stuff. We got the cipher and the tablets back - and only two fatalities in the whole ordeal." }
WordHunterWoW_QuestEN[11301] = { title = "Brains! Brains! Brains!", description = "Has Malthus drawn you in with his blather about beer kegs and crazy dwarves?\n\nI'm not questioning that the dwarves are crazy, but I don't think stealing their beer is going to do any good.\n\nWhat we need is brains. Lots of brains. We'll get down to the bottom of this mystery in no time, and perhaps even find a new component for the plague.\n\nTake this saw, go southeast into the Whisper Gulch, and kill yourself some dwarves. Use the saw to help you harvest the brains and bring them back here.", objectives = "Apothecary Grick at the Apothecary Camp wants you to bring him 12 Deranged Explorer Brains.", progress = "Did you get those brains? If not, I want my saw back. You'd better not walk off with that saw.", completion = "These brains are beautiful! Gorgeous, even! They're exactly what I need.\n\nThank you for your help, <name>. Now I'll show Malthus the truth his beer goggles couldn't reveal." }
WordHunterWoW_QuestEN[11302] = { title = "The Enigmatic Frost Nymphs", description = "When we first scouted locations for the fort, we encountered hostile creatures at two of the glades here in the north. When we passed the snow-covered one directly south of the town, the dryads there watched us with interest, but did not attack.\n\nWe were tired and worn down by the weather. They could've easily killed several of our men, but they didn't.\n\nPerhaps, in reaching out to them, we might discover unexpected allies. Are you willing to travel to the Frozen Glade and make contact with them?", objectives = "Speak with Lurielle at the Frozen Glade.", completion = "<Lurielle listens as you introduce yourself.>\n\nIt is good to finally meet you, <name>. We have long hoped that you and the other newcomers might send representatives. We don't often venture beyond the borders of our glades, especially amid the changes the land is going through." }
WordHunterWoW_QuestEN[11303] = { title = "The Ambush", description = "The vrykuls in Baleheim is completely defeated, no doubt about it.  But still their leader stays in town and won't give up.\n\nGorth sends Lydell and his assassins to make good ambush to the northwest.  You talk to Lydell and figure out how to get Vrykul chieftain to come out.  Then you kill him.  You kill him real good.", objectives = "Speak to Lydell at Lydell's Ambush.", completion = "We all showed up to the party, but the guest of honor stayed at home." }
WordHunterWoW_QuestEN[11304] = { title = "New Agamand", description = "I'm afraid our equipment isn't exactly the best here at Vengeance Landing.  After all it's a military controlled outpost.\n\nI will need you to take a sample of this strain to Chief Plaguebringer Harris in New Agamand, follow the road beyond Baleheim south and then west.  They have better equipment there - he will know what to do.\n\nYou must hurry, {name}.  Our enemies are stronger and more numerous than us.  We need to develop a viable weapon against them!", objectives = "Bring Lysander's Strain to Chief Plaguebringer Harris in New Agamand in western Howling Fjord.", progress = "Yes, <name>?", completion = "This strain is far from worthless, my friend!  Those fools at Vengeance Landing have had all the answers right under their own noses!" }
WordHunterWoW_QuestEN[11305] = { title = "A Tailor-Made Formula", description = "We've been spraying down the vrykul village of Halgrind for weeks now and the vrykul just won't drop dead.\n\nLet's face it, {name}, by now our Plague has been exposed to humans, dwarves, dogs, livestock... you name it.  As our strains adapt to their hosts, more impurities get thrown in the mix.  What we need is a strain made custom for the vrykul's biology.\n\nHalgrind's chieftain fled the town after we took it over; you'll find him west of here.  As a patriarch of the Dragonflayer clan, his blood is ideal.", objectives = "Obtain the Dragonflayer Patriarch's Blood from Thorvald at Thorvald's Camp and bring it to Chief Plaguebringer Harris in New Agamand.", progress = "Have you obtained the sample I require, <name>?", completion = "This will do.  It's time for some real apothecary work now, <name>!" }
WordHunterWoW_QuestEN[11306] = { title = "Apply Heat and Stir", description = "You've done well so far, {name}.  I'd like to teach you some of my more advanced techniques, so that you gain a better understanding of the plague.\n\nTake this empty flask and fill it with blood from the cauldron to my left.  Mix it with the plague samples to my right until you obtain a well balanced mix.", objectives = "Fill the Empty Apothecary's Flask at the Cauldron of Vrykul Blood, then mix the Flask of Vrykul Blood with Harris's Plague Samples nearby until you've obtained a Balanced Concoction.\n\nReturn to Chief Plaguebringer Harris when you've completed this task.", progress = "How is your experiment going, <name>?  Let me know if you have any questions behind the science involved!", completion = "Excellent!  You are an apt pupil, <name>.\n\nNow comes the fun part.  Deployment!" }
WordHunterWoW_QuestEN[11307] = { title = "Field Test", description = "Now that we have a strain of the plague that has adapted to vrykul carriers, we really ought to test it on our specimens in Halgrind.  If all goes according to plan, they will disintegrate immediately as the plague devours their innards!\n\nYou will find Halgrind north of here.  Our plaguebringers are deploying the previous strain there - shouldn't be hard to spot.", objectives = "Venture into Halgrind and use the Plague Spray on 10 Plagued Dragonflayer Vrykul. Return to Chief Plaguebringer Harris to report the results.", completion = "The plague didn't disintegrate our subjects?  Are you certain, <name>??!\n\nThere must be an external factor we're not accounting for... perhaps the low temperatures of this climate?  Perhaps... a mutation in the strain!" }
WordHunterWoW_QuestEN[11308] = { title = "Time for Cleanup", description = "Being the practical man that I am, I'm going to declare our research here a success.  After all, what army can't be stopped by turning its rank and file against each other?\n\nI will send word of our achievements to Vengeance Landing soon enough.  But first I need you to take care of cleaning up our experimentation site.\n\nSee \"Hacksaw\" Jenny about making you a custom abomination.  One packing some explosive power if you catch my drift.", objectives = "Speak to \"Hacksaw\" Jenny in New Agamand.", completion = "What do you want?  Can't you see I'm in the middle of something?" }
WordHunterWoW_QuestEN[11309] = { title = "Parts for the Job", description = "So Harris wants a demolition job, eh?  Yeah, I can help out.\n\nYou're gonna have to get me some parts, though.  I can't afford to use up my choice components on something that's gonna get blown up.\n\nFirst of all, I'm going to need shoveltusk ligaments... way better than the human kind.\n\nI will also need a pound of flesh.  A fellow known as Anton sells cheap meat.  He travels up and down the road to the west.", objectives = "\"Hacksaw\" Jenny in New Agamand wants you to obtain 6 Shoveltusk Ligaments and 1 Fresh Pound of Flesh.", progress = "You get my components yet?", completion = "Excellent!  Yes, yes, these will do just fine!" }
WordHunterWoW_QuestEN[11310] = { title = "Warning: Some Assembly Required", description = "Well, here you are!  Our friend's going to be somewhat... unstable.  So I suggest not putting him together until reaching Halgrind.\n\nOnce you're there, use the abomination to round up as many vrykul as you can before self-destructing.\n\nCome back with whatever's left once you're done.  I can always use more body parts!", objectives = "Use the Abomination Assembly Kit in Halgrind and round up plagued Vrykul with your Mindless Abomination. Slay at least 20 and return to \"Hacksaw\" Jenny in New Agamand when you're done.", progress = "Are you done with the cleanup in Halgrind?", completion = "Great job, <name>.  Say, you wouldn't be looking for something more... permanent, would ya?  I could sure use some help around these parts!" }
WordHunterWoW_QuestEN[11311] = { title = "Suppressing the Elements", description = "If you are to survive here, as we have, you must learn to face the environment's challenges head on. The elements will claim your life if you're not vigilant, as the proliferation of elementals in these northern hills shows.\n\nWe must cull the elementals one last time before we can leave this place. Are you willing to aid us while we continue to make preparations?\n\nYou must kill any iceshard elementals or howling cyclones you encounter in the snowy hills surrounding the outpost.", objectives = "Wind Tamer Kagan at Camp Winterhoof wants you to kill 8 mountain elementals. You may kill either Howling Cyclones or Iceshard Elementals.", completion = "The influence of the elemental spirits has receded, but it will return. We've bought ourselves the time we need to complete our tasks here and take our leave." }
WordHunterWoW_QuestEN[11312] = { title = "The Frozen Glade", description = "For generations, my people have told tales of frost nymphs cavorting in glades hidden away in the wilderness. I used to search for them as a child, against the advice of my parents, until I nearly froze to death.\n\nThese days, it isn't necessary to comb the forests for them. They've decided to reveal themselves for reasons I can only guess, but I don't think the change can be ignored. Venture southeast to the Frozen Glade and seek out the nymphs, but beware; you will pass the Twisted Glade on your way.", objectives = "Speak with Lurielle at the Frozen Glade.", completion = "<Lurielle listens as you introduce yourself.>\n\nIt is good to meet you, <class>. My sisters have often watched the taunka search the forests for us, but we are forbidden by our queen from interacting with outsiders. You only see us now because the land has become unsettled and many of my sisters are in danger." }
WordHunterWoW_QuestEN[11313] = { title = "Spirits of the Ice", description = "The ice elementals surrounding our glade were once our companions, but a volatile and destructive force has swept through the land, turning them against us!\n\nThis is but one of the horrors my sisters and I have endured. We have revealed ourselves to you in the hope that you will help us stave off the decay that has crept into our glades and poisoned our sisters!\n\nWe've been gathering the cores of the ice elementals and keeping them safe so that one day, we might be able to restore them. Will you help?", objectives = "Lurielle at the Frozen Glade wants you to bring her 15 Icy Cores.", progress = "Have you recovered any of the cores?", completion = "<Lurielle accepts the cores from you quietly.>\n\nThank you, <name>.\n\n\n\nI promise, my friends, I will do all I can to restore you." }
WordHunterWoW_QuestEN[11314] = { title = "The Fallen Sisters", description = "To the southwest was a glade that used to look much like this one. Mysterious forces and alien magics are reshaping the land. The glade has thawed, the sisters living there driven mad by the sudden change.\n\nWe thought to reach out to them, but they attacked us. I fear many may be beyond saving, but I cannot give up hope.\n\nTake my pendant, travel southwest to the Vibrant Glade, and use it to try to free my sisters.", objectives = "Lurielle at the Frozen Glade wants you to use her pendant on 7 Chill Nymphs.", completion = "So there is hope for my sisters?\n\n<Lurielle looks away from you, then down at the ground.>\n\nI feel guilty for not thinking of the pendant sooner. We might have saved even more of the sisters." }
WordHunterWoW_QuestEN[11315] = { title = "Wild Vines", description = "The sisters who lived in the Vibrant Glade, to the southwest, used to tend to gorgeous beds of scarlet ivy, but the same force that has driven them mad has transformed their beloved ivy.\n\nThe vines now grasp at the feet of the unwary, or lash at any who approach the glade. Before we can reclaim the glade, the vines must be tamed and uprooted.\n\nClear as much of the ivy as you are able. It has already begun to grow out of control.", objectives = "Lurielle at the Frozen Glade wants you to kill 8 Scarlet Ivy.", completion = "Thank you for your help, <name>. The Vibrant Glade was once a beautiful place, and when we return to it, we shall make it so again." }
WordHunterWoW_QuestEN[11316] = { title = "Spawn of the Twisted Glade", description = "The glade to the west has been transformed into a hideous place called the Twisted Glade. Horrible beasts dwell among the trees, stones, and pool of the glade.\n\nI cannot guess where the creatures came from or what horrible forces animate them, but they must be dealt with!\n\nI fear that if they are allowed to dominate the glade, they will poison it beyond redemption. Clear the glade of these creatures who murdered our sisters.", objectives = "Lurielle at the Frozen Glade wants you to kill 10 Thornvine Creepers.", completion = "You have done well, <name>. If we'd had allies like you when the land first began to change, perhaps we might have been able to preserve some of what we've lost." }
WordHunterWoW_QuestEN[11317] = { title = "The Cleansing", description = "We braved the Rivenwood because of my troubled dreams concerning my worg life-friend, Ulfang. He has called out for help, and you must go to him.\n\nBut, you do not have the means to speak with him, or walk amongst the other worgs. I know a way.\n\nFirst, you must cleanse your inner turmoil.\n\nThere is a shrine that sits at the top of Frostblade Peak, northeast of Camp Winterhoof. A single path leads up to it from the western base of the mountain.\n\nMeditate there and then return to me.", objectives = "Sage Mistwalker at Steel Gate has advised you to cleanse yourself of Your Inner Turmoil through meditation at the Frostblade Shrine.", completion = "Already I can sense the change within you.\n\nAre you ready for what comes next?" }
WordHunterWoW_QuestEN[11318] = { title = "Now This is Ram Racing... Almost.", description = "So you want to check out the racing rams? Well I hope you're ready for speed. BUT before I let you loose in the world, you'll need to show me that you can handle these fine creatures.\n\nSo here's the deal: I'll lend you some racing reins and the use of a ram. You need to prove to me that you can handle using these rams.\n\nKeep the ram at a trot, canter and gallop for 8 seconds each. If you need instructions how to handle the ram, talk to my apprentice, Pol Amberstill.", objectives = "You have 4 minutes to ride the ram and maintain 3 different levels of speed for 8 seconds.", progress = "Were you able to handle the speed?", completion = "Nice work there!  It takes time to get the hang of controlling your ram.  But once you do, you'll wish every ram was a racing ram.\n\nWhat's that? \"Where's my reward?\"  Ha Ha Ha... you got to ride the fastest ram around!  You want more?  Well how about this...\n\nYou've been rewarded with the chance to help other people around Brewfest.  There's plenty of work, and rewards, for an eager, young, ram racer." }
WordHunterWoW_QuestEN[11319] = { title = "Seeds of the Blacksouled Keepers", description = "The glade to the northwest, now the Twisted Glade, used to be home to a number of keepers of the glade. Together with the sisters, they saw to the glade's upkeep.\n\nWhen the glade changed, the sisters died, but somehow the keepers managed to survive. Now, they seed the land with poisonous spores that wither healthy greenery.\n\nI'll give you one of the cores from the ice elementals. Once you've destroyed a spore, use the ice crystal to freeze it and keep it from regenerating.", objectives = "Lurielle at the Frozen Glade wants you to freeze 8 Spores.", completion = "The ice core worked well for you? I'll have to remember that. I'm certain the keepers will not stop just because we've destroyed their work once." }
WordHunterWoW_QuestEN[11321] = { title = "Did Someone Say \"Souvenir?\"", description = "Brewfest isn't just about racing rams, it's also about drinking!  When you have a moment, take this voucher to Belbi Quikswitch.  She's near the back of the Brewfest camp.  If you can't see her, don't worry, she'll be sure to see you.\n\nIn any case, take this voucher to her to get your free Brewfest stein.  She'll also be more than happy to handle any and all other Brewfest transactions.", objectives = "Redeem the Brewfest Stein Voucher with Belbi Quikswitch in the Brewfest camp." }
WordHunterWoW_QuestEN[11322] = { title = "The Cleansing", description = "Of late I've had nightmares concerning a worg named Ulfang. He has called out for help, and you must go to him.\n\nHowever, you do not have the means to speak with him, or walk amongst the other worgs. I know a way.\n\nBut first, you must cleanse your inner turmoil through meditation.\n\nThere is a shrine that sits at the top of Frostblade Peak, far to the northeast. A single path leads up to it from the western base of the mountain.\n\nMeditate there to cleanse yourself and then return to me.", objectives = "Watcher Moonleaf at Steel Gate has advised you to cleanse yourself of Your Inner Turmoil through meditation at the Frostblade Shrine.", completion = "Already I can sense the change within you.\n\nAre you ready for what comes next?" }
WordHunterWoW_QuestEN[11323] = { title = "In Worg's Clothing", description = "From my dreams, I know that Ulfang is in a cave on the snowy northwestern edge of the Rivenwood.\n\nHe is in great danger.\n\nI have devised a magical disguise that will make you appear as a worg while you are within the Rivenwood. The disguise is weak, relying upon the strange magics of that haunted wood. While it will only convince the worgs, it will allow you to get close to Ulfang.\n\nPlease, {class}, find and help him.", objectives = "Sage Mistwalker has asked you to seek out and help Ulfang in the Rivenwood.\n\nIf you somehow lose the Worg Disguise, return to Sage Mistwalker for a replacement.\n\nProvided item:", completion = "You look and smell different... you are not one of my pack. Tell me your story; I have nothing but time while I am trapped in here." }
WordHunterWoW_QuestEN[11324] = { title = "Alpha Worg", description = "When you've eaten Talonshrike's eyes, you should be able see Garwal and rip out his throat!\n\n{race}-thing, seek out and slay Garwal in the western Rivenwood. After you have killed him, go and tell Mistwalker that I am once more the alpha worg!", objectives = "Ulfang has asked you to slay Garwal. Then, return the Worg Disguise to Sage Mistwalker at Steel Gate.", progress = "<name>, you have returned. What news of Ulfang?", completion = "Garwal was not a worg at all! I know of these creatures... they are called worgen.\n\nBut, Ulfang indicated that it came south from the Grizzly Hills? Odd. There aren't any worgen there.\n\nI thank you for helping to restore Ulfang to his proper place amongst his pack. Now we both will be able to sleep peacefully.\n\nPlease, you must accept this as a sign of gratitude." }
WordHunterWoW_QuestEN[11325] = { title = "In Worg's Clothing", description = "From my dreams, I know that Ulfang is in a cave on the snowy northwestern edge of the Rivenwood.\n\nHe is in great danger!\n\nI have devised a magical disguise that will make you appear as a worg while you are within the Rivenwood. The disguise is weak, relying upon the strange magics of that haunted wood. While it will only convince the worgs, it will allow you to get close to Ulfang.\n\nPlease, {class}, find and help him.", objectives = "Watcher Moonleaf has asked you to seek out and help Ulfang in the Rivenwood.\n\nIf you somehow lose the Worg Disguise, return to Watcher Moonleaf for a replacement.\n\nProvided item:", completion = "You look and smell different... you are not one of my pack. Tell me your story; I have nothing but time while I am trapped in here." }
WordHunterWoW_QuestEN[11326] = { title = "Alpha Worg", description = "When you've eaten Talonshrike's eyes, you should be able see Garwal and rip out his throat!\n\n{race}-thing, seek out and slay Garwal in the western Rivenwood. After you have killed him, go and tell Moonleaf that I am once more the alpha worg!", objectives = "Ulfang has asked you to slay Garwal. Then, return the Worg Disguise to Watcher Moonleaf at Steel Gate.", progress = "<name>, you have returned. What news of Ulfang?", completion = "Garwal was not a worg at all! The thing you describe him turning into sounds a lot like a worgen!\n\nBut, Ulfang said that it came south from the Grizzly Hills? Odd. There aren't any worgen there.\n\nI thank you for helping to restore Ulfang to his proper place amongst his pack. Now we both will be able to sleep peacefully.\n\nPlease, you must accept this as a sign of gratitude." }
WordHunterWoW_QuestEN[11327] = { title = "Mission: Package Retrieval", description = "Well darn, we need some of that plague-stuff.\n\nI know!\n\nWhile you were destroying the vats, I happened to spy one of the apothecaries from New Agamand being pulled into Halgrind by the vrykul down in there. Poor fella'.\n\n{name}, I'd bet anything that apothecary has the goods on him. Think you could go into Halgrind and retrieve his package?", objectives = "Scout Knowles has asked you to retrieve the Apothecary's Package from inside Halgrind. Once you have it, return to the scout at the Ember Spear Tower.", progress = "That place looks like a nightmare. Vrykul or not, no one deserves to be the victim of the Royal Apothecary Society.\n\nGlad I'm standing safely over here. You find that package yet?", completion = "Holy... what the hell?! Look at this stuff!\n\nWe need to get this back to the keep a.s.a.p.!" }
WordHunterWoW_QuestEN[11328] = { title = "Mission: Forsaken Intel", description = "Right, so I think you should get this stuff over to Peppy Wrongnozzle back at the keep. She's something of an amateur alchemist, but she's the only one we've got.\n\nOne thing about Peppy; she does love her drink. So, you'll likely find her at the tavern 'soaking up the atmosphere'.\n\nI'm sure she'll know what to do.", objectives = "Scout Knowles has asked you to deliver the Apothecary's Package to Peppy Wrongnozzle at Westguard Keep.", progress = "Yeah, whadya want ...hic?", completion = "Oh... hey, that'sh different!\n\nOkay, let me shee that shtuff. I jusht love tinkering with alchemy!\n\nInteresting, interesting... here, I think I know jusht what to do. A little mixing of that with the jusht the right amount of thish.\n\nYou know, I think a little dash of this rotgut will help, too ...hic!" }
WordHunterWoW_QuestEN[11329] = { title = "I'll Try Anything!", description = "I never want to see another barrel of salted fish as long as I live! Filling barrels day in and day out, and there are still more to be filled!\n\nI wish I hadn't used up all that bait I bought from Nat Pagle. Worked like magic, it did. Now I'm lucky if I can catch a fish an hour!\n\nI hear the northern barbfish make pretty good bait, but who's crazy enough to dive into a freezing cold lake and hack up the water plants in search of them? Not me... but maybe, just maybe, I can persuade you to...", objectives = "Christopher Sloan at Fort Wildervar wants you to bring him 5 Northern Barbfish.", progress = "You look like you're still in one piece. Get any of that bait?", completion = "Well, these certainly are ugly enough, but I suppose I don't care if it actually works. I'll be relieved once the expedition has passed through and I can go back to simply fishing for my dinner." }
WordHunterWoW_QuestEN[11330] = { title = "Absholutely... Thish Will Work!", description = "Voila, inshtant plague vacshine!\n\nBut I sure as heck am not going to try thish on myself. And I know you don't want to be my tesht shubject!\n\nOh, I've got... I've got an idea!\n\nWe've got a vrykul prishoner being held down in the cells under the keep. Why don't you take thish mix I whipped up down there, and get that giant to drink it ...hic?!", objectives = "Peppy Wrongnozzle at Westguard Keep has suggested that you take her Peppy's Special Mix and administer it to the Dragonflayer Vrykul Prisoner to witness its results.", completion = "Huh? Well that sucks! Darn, I made thingsh worsh. In fact, I think I perfected their plague for them ...hic!\n\n<Peppy grimaces and takes a huge gulp of whatever noxious brew she's been drinking.>\n\nWell, I wash hoping that it wouldn't come down to thish, but it looks like there'sh no alternative ...hic." }
WordHunterWoW_QuestEN[11331] = { title = "You Tell Him ...Hic!", description = "Here'sh the deal. I'm not going to the captain with thish news. I'm an amateur alchemist, thish ishn't my job, and I'm on break!\n\nBeshides, he'sh a big grumpkin... and you know him better than I do!\n\nSho, jusht go up into the keep and tell him. I'm sure he'll be reashonable about the whole thing ...hic.\n\n<Peppy turns back to her drinking.>", objectives = "Peppy Wrongnozzle has suckered you into giving the bad news about the Forsaken plague to Captain Adams. Visit him at Westguard Keep.", completion = "Yes, <name>, what is it now?\n\nWHAT?!! A Forsaken super plague that melts you in no time?\n\nYou oozed my vrykul prisoner?\n\n\n\nAlright, I know what we need to do. Or rather, what YOU need to do!" }
WordHunterWoW_QuestEN[11332] = { title = "Mission: Plague This!", description = "The Royal Apothecary Society thinks they're going to perfect a new plague to melt us down where we stand?!\n\nNot on my watch!\n\nGet out to the courtyard and speak with Greer Orehammer. He's got a gryphon and some bombs ready for you. I want you to bomb the plague tanks at New Agamand to smithereens!", objectives = "Captain Adams has ordered you to get 5 bomb hits on the Plague Tanks at New Agamand. Do not return to him at Westguard Keep until you have accomplished that.", progress = "Those plague tanks destroyed, yet? That new plague looms over our heads like certain death, <class>!", completion = "Nicely done, <name>, nicely done!\n\n\n\nThat'll show those good-for-nothing Forsaken to think about messing with us!\n\nI'd say you've earned yourself something from the treasury!" }
WordHunterWoW_QuestEN[11333] = { title = "Into the World of Spirits", description = "While the Explorers' League may discern bits and pieces of the past through their archaeological findings and the Vice Admiral might extract some knowledge of the present through brute force, the truth lies with the spirits.\n\nWith the proper reagents I am able to see into the spirit world. It is there that the past, present and future of Northrend resides.\n\nIf you wish to learn more, I will require my reagent pouch. It was lost in a ship that is now at the bottom of Daggercap Bay, just east of here.", objectives = "Thoralius the Wise at Valgarde wants you to find his Reagent Pouch.", progress = "Have you found my reagent pouch?", completion = "A bit worse for the wear but still functional.\n\n<Thoralius reaches into the pouch and removes some odd looking roots.>\n\nNow to place them in the fire and inhale!\n\n<Thoralius throws the roots into the smoldering incense burner.>\n\n<Thoralius inhales deeply. His body begins to quiver.>\n\nWha... What... It cannot be... I cannot..." }
WordHunterWoW_QuestEN[11334] = { title = "He Shoots, He Scores!", description = "[PH] Shoot a marked target.", objectives = "[PH] Rinling wants you to shoot a marked target and then return the Target Rifle to him." }
WordHunterWoW_QuestEN[11335] = { title = "Call to Arms: Arathi Basin", description = "The reality of fighting on multiple fronts, <lad/lass>, is that we cannot spread our forces too thin or we risk losing it all!\n\nCritical troop deployments are necessary on a day by day basis.  Today it is the battle of Arathi Basin that demands immediate reinforcements.\n\nReturn to me with news of victory, <name>.  We cannot allow the Horde scum to secure the resources that are rightfully ours!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Win an Arathi Basin battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath." }
WordHunterWoW_QuestEN[11336] = { title = "Call to Arms: Alterac Valley", description = "The reality of fighting on multiple fronts, <lad/lass>, is that we cannot spread our forces too thin or we risk losing it all!\n\nCritical troop deployments are necessary on a day by day basis.  Today it is the battle for Alterac Valley that's in most need of brave combatants.\n\nGo now, <name>, and aid the Stormpike Expedition.  We cannot allow the Frostwolf Clan to get away with the violence they've inflicted on our brethren!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Win an Alterac Valley battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath." }
WordHunterWoW_QuestEN[11337] = { title = "Call to Arms: Eye of the Storm", description = "The fight against the Horde knows no boundaries, <name>.  Even in Outland, territorial disputes and old hatreds are enough to tip the scales in favor of war.\n\nGo into the Eye of the Storm and make sure the Alliance prevails in Outland just like it has in Azeroth.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Win an Eye of the Storm battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath." }
WordHunterWoW_QuestEN[11338] = { title = "Call to Arms: Warsong Gulch", description = "The Silverwing Sentinels fight to protect the forest in Warsong Gulch.  We aid them, not because we're tree-lovers, but because the forest forms a natural protective barrier for Alliance territory.\n\nTheir need is greater today than it's ever been.  We need to deploy reinforcements right away unless we want to see Ashenvale annexed to the Barrens!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Win a Warsong Gulch battleground match and return to an Alliance Brigadier General at any Alliance capital city, Wintergrasp, Dalaran, or Shattrath." }
WordHunterWoW_QuestEN[11339] = { title = "Call to Arms: Arathi Basin", description = "Arathi Basin is on the verge of being lost to Alliance forces.  We must send reinforcements at this very moment or all our efforts will have been in vain.\n\nDo not delay, <class>, go to Arathi Basin and crush the enemy.  Victory to the Horde!", objectives = "Win an Arathi Basin battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath.", completion = "You've brought great honor to the Horde, <name>.  Your victory today will ensure a thousand victories tomorrow!" }
WordHunterWoW_QuestEN[11340] = { title = "Call to Arms: Alterac Valley", description = "We've recently come extremely close to driving the Stormpike invaders from Alterac Valley.  As a result we're redirecting all our reinforcements to aid the Frostwolf Clan.\n\nA decisive victory there would free up the resources we need to crush the Alliance scum on all the other battlefronts.\n\nGo, <name>.  Earn great honor by heeding the call of the brave Frostwolf warriors.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Win an Alterac Valley battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath." }
WordHunterWoW_QuestEN[11341] = { title = "Call to Arms: Eye of the Storm", description = "We will fight and crush the enemy wherever we find them.  Azeroth, Outland, the place makes no difference.\n\nWe cannot allow the Alliance to establish superiority in the Eye of the Storm.  Take the battle to them today... tomorrow it might be too late!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Win an Eye of the Storm battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran,  or Shattrath." }
WordHunterWoW_QuestEN[11342] = { title = "Call to Arms: Warsong Gulch", description = "The Alliance is an insidious enemy, <name>.  They claim to defend the Ashenvale forests to justify their acts of aggression against our territories in the Barrens.\n\nToday we have an opportunity to drive the enemy from our lands once and for all.  Go to Warsong Gulch and take back what is rightfully ours!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Win a Warsong Gulch battleground match and return to a Horde Warbringer at any Horde capital city, Wintergrasp, Dalaran, or Shattrath." }
WordHunterWoW_QuestEN[11343] = { title = "The Echo of Ymiron", description = "The spirit world has fallen under the sway of the Lich King. Fearsome creatures made of pure nightmare now stand watch over the realm of the elements. I sense that these val'kyr are guarding a terrible secret.\n\nI am too old and weak to survive another journey. You must go in my place, {name}.\n\nTake this incense burner to Wyrmskull Village and use it to enter the spirit world. Find the large dwelling in the northeast! Avoid the val'kyr at all costs lest they make you a permanent fixture in their world.", objectives = "Thoralius the Wise wants you to search Wyrmskull Village while you are in the spirit world and find information about the Secrets of Wyrmskull.", completion = "I do not understand. The creatures that you saw looked like the vrykul that are attacking Valgarde?" }
WordHunterWoW_QuestEN[11344] = { title = "Anguish of Nifflevar", description = "All that we know of the vrykul indicates that they only recently appeared in Northrend. Why, then, are we seeing vrykul in visions that date back 15,000 years? Surely if the vrykul had previously existed in Northrend we would have known.\n\nYou must press on to Nifflevar. To get there you must go northeast, through Wyrmskull Village, and take the path leading up through the dam. Nifflevar is on the bluffs of the fjord.\n\nUse the incense burner once you arrive at Nifflevar and search the area for clues.", objectives = "Thoralius the Wise wants you to search Nifflevar while you are in the spirit world and find information about the Secrets of Nifflevar.", completion = "Human children born of vrykul? And Ymiron ordered the deaths of all human born offspring?\n\n<Thoralius goes silent for a moment.>\n\nAs much as I wish to deny what is so plainly presented to me, I cannot. There is no extinct \"missing link\" to humans as the Explorers' League proposed. The vrykul are the missing link. They are the progenitors of humanity." }
WordHunterWoW_QuestEN[11345] = { title = "Prizes for Pellets", description = "[PH] Shoot a marked target.", objectives = "[PH] Rinling wants you to shoot a marked target and then return the Target Rifle to him." }
WordHunterWoW_QuestEN[11346] = { title = "The Book of Runes", description = "The vast rocky area to the southeast, Giants' Run, has been overrun by Iron Dwarves. Scouts have reported seeing the dwarves coaxing stone giants from the ground, then carving runes on them.\n\nI can't fathom their motives, but I suspect they're somehow trying to turn the giants into weapons. The iron rune stonecallers and binders carry large tomes with them, which must contain the runes they're carving on the giants.\n\nCapture the pieces of this book, assemble them, and bring it back to me, {name}.", objectives = "Prospector Belvar at Fort Wildervar wants you to bring him The Book of Runes.", progress = "Have you recovered the book?", completion = "<Prospector Belvar browses the book of runes.>\n\nHmm... there's so much here. I'm going to need some time to study it, and if we hope to understand these runes, we'll need to try to make our own." }
WordHunterWoW_QuestEN[11348] = { title = "The Rune of Command", description = "Can you feel the power emanating from the runes I've carved on this tablet? They're smaller versions of the runes that the Iron Dwarves are using. We'll use it to shut down their operation.\n\nTake it to Giants' Run and use it on a stone giant that the dwarves have not altered.\n\nThe giant should obey you, but I've tailored the runes to restore it to its natural state after a time. The giant may prove a valuable ally in the battle against Binder Murdis, the leader of the Iron Dwarf forces at Giants' Run.", objectives = "Prospector Belvar at Fort Wildervar wants you to test the Rune of Command and defeat Binder Murdis.", completion = "You've done well in defeating Binder Murdis, but the Iron Dwarves won't give up easily.\n\nWe've made a lot of progress in understanding how they manipulate runes. Perhaps next time we encounter them, our knowledge will give us an advantage." }
WordHunterWoW_QuestEN[11349] = { title = "Mastering the Runes", description = "I've got a set of picks, hammers, and chisels with me, but they won't work for carving these runes. The tools used by the Iron Dwarves are imbued with magic during their forging.\n\nWhen they're used to carve runes, the symbols form much more than mere words. These runes have the power to bind, compel, and twist.\n\nI believe I know how it works, but without a set of those tools, I can't be certain. Look for kits resembling mine near the Iron Dwarf pavilions at Giants' Run and bring them to me.", objectives = "Bring a set of Iron Rune Carving Tools to Prospector Belvar at Fort Wildervar.", progress = "Have you returned with those tools?", completion = "<Belvar handles the tools carefully.>\n\nI'm going to try these out. If we're to understand the Iron Dwarves' motives and defeat them, I need to know exactly what the runes are doing." }
WordHunterWoW_QuestEN[11350] = { title = "The Book of Runes", description = "Chieftain Ashtotem dispatched me on a scouting mission to Giants' Run, a broad, rocky plateau to the southeast, past the Frozen Glade.\n\nThe area has been taken over by Iron Dwarves who seem to be altering the giants as they emerge from the earth.\n\nThe iron rune stonecallers and binders carry large tomes with them, which must contain the runes they're carving on the giants.\n\nCapture the pieces of this book, assemble them, and bring it back to me. It's the only way we'll understand their plans.", objectives = "Longrunner Pembe at Camp Winterhoof wants you to bring him The Book of Runes.", progress = "Have you recovered the book?", completion = "<The longrunner browses the book of runes.>\n\nI'm no loremaster, but I have some familiarity with the language of the Iron Dwarves. I think the runes they're carving on the giants are derived from their spoken language, but there are some differences." }
WordHunterWoW_QuestEN[11351] = { title = "Mastering the Runes", description = "I think I've figured out what the Iron Dwarves are doing. The tools they use are imbued with magic during their forging.\n\nWhen they're used to carve runes, the symbols form much more than mere words. These runes have the power to bind, compel, and twist.\n\nIf I had a set of those tools, I could mimic the runes in the book. I captured one of these boxes from one of the pavilions at Giants' Run, but it was empty. Look for similar boxes and recover a set of tools from them.", objectives = "Bring a set of Iron Rune Carving Tools to Longrunner Pembe at Camp Winterhoof.", progress = "Have you returned with those tools?", completion = "<Pembe examines the tools.>\n\nThese are more delicate than I'd thought. Allow me a moment to try them out." }
WordHunterWoW_QuestEN[11352] = { title = "The Rune of Command", description = "Can you feel the power emanating from the runes I've carved on this tablet? They're smaller versions of the runes that the Iron Dwarves are using. We'll use it to shut down their operation.\n\nTake it to Giants' Run and use it on a stone giant that the dwarves have not altered.\n\nThe giant should obey you, but I've tailored the runes to restore it to its natural state after a time. The giant may prove a valuable ally in the battle against Binder Murdis, the leader of the Iron Dwarf forces at Giants' Run.", objectives = "Longrunner Pembe at Camp Winterhoof wants you to test the Rune of Command and defeat Binder Murdis.", completion = "You've done well in defeating Binder Murdis, but the Iron Dwarves won't give up easily.\n\nAs my people move north, I'm certain we will encounter the Iron Dwarves again. Next time, we will be prepared to thwart them before they can dig in." }
WordHunterWoW_QuestEN[11353] = { title = "FLAG: Got the work shirt", description = "", objectives = "" }
WordHunterWoW_QuestEN[11354] = { title = "WANTED: Nazan's Riding Crop", description = "Today I have a buyer who is interested in a piece that's held by the mount of Illidan's herald. I, of course, speak of Vazruden the Herald and his dragon mount, Nazan.\n\nIf you want the finder's fee that I offer in return, find them flying above the Ramparts at Hellfire Citadel and return with the dragon's riding crop.\n\nMy sources tell me that the item in question is personally held by the dragon. It is said that Nazan refuses to allow Vazruden to strike him with it.", objectives = "Wind Trader Zhareem has asked you to obtain Nazan's Riding Crop. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "The riding crop please.", completion = "Another soon-to-be satisfied customer. It looks like it's in fine condition. You are to be rewarded.\n\nCome back tomorrow and I will have another request for you to fulfill." }
WordHunterWoW_QuestEN[11355] = { title = "March of the Giants", description = "To the east, at Giants' Run, rune-inscribed stone giants have started to migrate north toward Frostblade Peak. What their ultimate destination is, I do not know.\n\nThe glowing runes inscribed in the stone flesh of the giants guide them on their journey.\n\nUse this pick to deactivate the runes on the giants' corpses and return with your findings.", objectives = "Researcher Aderan at Fort Wildervar wants you to use the Runeseeking Pick on the corpses of 4 Runed Stone Giants.", completion = "<Researcher Aderan listens to your findings.>\n\nThe runes for \"north\" and \"west\" appeared multiple times? There's a highly reinforced command to move in that direction, but the runes are more than propulsion. Something is attracting them, but what?" }
WordHunterWoW_QuestEN[11356] = { title = "Costumed Orphan Matron", description = "During Hallow's End, human orphanages have organized trips for their orphans to visit Alliance countryside villages.  Those poor children would love to see a real {class} like yourself!\n\nWhy don't you visit them?  You'll find orphans at Goldshire in Elwynn Forest, Kharanos in Dun Morogh and Azure Watch in Azuremyst.  Speak to the children's ward, a costumed orphan matron, and she'll introduce you to the children.", objectives = "Speak with a Costumed Orphan Matron in either Goldshire, Kharanos or Azure Watch.", completion = "You're here to visit the children!  Wonderful!  They have known such heartache in their short lives.  It is good that they see real heroes like you.  It really lifts their spirits!" }
WordHunterWoW_QuestEN[11357] = { title = "Masked Orphan Matron", description = "For Hallow's End, several orphans were taken on a trip to different Horde villages. The orphan matrons thought it would be good for them to see real heroes adventuring in the field.\n\nWhy don't you visit them? A brave {class} like yourself could strengthen their spirits with tales of your valor! Go to Razor Hill in Durotar, Brill in Tirisfal Glades, or Falconwing Square in Eversong Woods. Speak with the masked orphan matron and she'll introduce you to the children.", objectives = "Speak with a Masked Orphan Matron in Razor Hill, Brill, or Falconwing Square.", completion = "The children love to watch heroes at their work.  It is my hope that, one day, each of these orphans will grow into a strong member of the Horde, and ultimately die in glorious battle!\n\nAh, thoughts of such a fine fate brings mist to my eyes..." }
WordHunterWoW_QuestEN[11358] = { title = "The Lodestone", description = "If we can locate what's luring the giants northwest, we might be able to stop them before they reach their destination.\n\nAlthough I was able to decipher many of the runes on the samples you brought me, the ones I don't know concern me the most. When I visited Giants' Run, I noticed a large broken tablet jutting from the ground where the northeastern part of the area met the snow at the foot of Frostblade Peak. Take this sample, compare the runes with the tablet, and see what you can learn.", objectives = "Researcher Aderan at Fort Wildervar wants you to compare the Rune Sample with the Broken Tablet.", completion = "<Aderan listens as you describe your findings.>\n\nOf course! This Megalith must be the key to the Iron Dwarves' plans. We must destroy it before their plan comes to fruition!" }
WordHunterWoW_QuestEN[11359] = { title = "Demolishing Megalith", description = "Binder Murdis created Megalith to be the most powerful of the runed giants and to lead them in their mission. Defeating Megalith will leave them lost and without direction. After the expeditionary force arrives, our soldiers will be able to isolate and defeat the remaining giants and oust their Iron Dwarf masters from their camps.\n\nSearch the foothills of Frostblade Peak, north of Giants' Run for Megalith and defeat him!", objectives = "Defeat Megalith and return to Researcher Aderan at Fort Wildervar.", completion = "You've done well in felling Megalith, but I wonder about his final words.\n\nYou're sure he said the Stoneforge?\n\nI know of no place with that name, but it sounds like a word with origins in the titans. What plans do the Iron Dwarves have for such a thing? This bears watching, <name>, for we must find it before the Iron Dwarves' plan comes to fruition." }
WordHunterWoW_QuestEN[11360] = { title = "Fire Brigade Practice", description = "With the Headless Horseman at large, the heroes of Goldshire are always ready to form a fire brigade.  Do you want to help?\n\nNorth of here, guards set up a small area to practice fighting fires.  Go there and throw buckets onto the blazes.  You can fill a bucket from the water barrel here, or the one near the fires.\n\nGood bye, {name}.  When you're done with fire brigade practice, please visit us again!", objectives = "Throw Water Buckets onto 5 fires, and then speak with the Costumed Orphan Matron.", progress = "Hello, <name>.  Have you been perfecting your fire fighting techniques?  Don't forget about the practice area to the north!", completion = "You're wet and smudged with soot!  You must have been extinguishing fires!\n\nWell done!  As an honorary member of the Fire Brigade, I beg you to return here if ever the village needs you!" }
WordHunterWoW_QuestEN[11361] = { title = "Fire Training", description = "The grunts set up a fire training area outside the village. These days, Razor Hill's buildings often catch fire -- you should lend a hand and train as a fire fighter!\n\nHead west out of Razor Hill, then turn right as you pass the village's wall. Find the training area, then grab buckets and toss them on the practice fires.", objectives = "Toss Water Buckets on 5 fires, then speak with the Masked Orphan Matron in Razor Hill.", completion = "Well done, <name>!  Children, take a good look at this <class>. Grow strong and brave like him and one day you too will fight for the Horde." }
WordHunterWoW_QuestEN[11362] = { title = "WANTED: Keli'dan's Feathered Stave", description = "There is no accounting for taste. Take my most recent buyer for instance.\n\nThere is a blood orc within Hellfire Citadel known as Keli'dan the Breaker. He bears a most mundane stave; certainly nothing to take a second glance at. And yet, this is what my customer wishes.\n\nWho am I to say no?\n\nIf you desire my compensation, you will find him and his stave within the Blood Furnace.", objectives = "Wind Trader Zhareem has asked you to obtain Keli'dan's Feathered Stave. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "We are speaking again... you must have the stave.", completion = "Perhaps I will have new feathers tied onto it before shipping it on to the buyer. I'm certain with so many arakkoa hereabouts it will not prove difficult. A small matter, and nothing to detract from your reward in any case.\n\nCome back tomorrow and I will have another request for you to fulfill." }
WordHunterWoW_QuestEN[11363] = { title = "WANTED: Bladefist's Seal", description = "Today I have a very wealthy collector in need of something very unique indeed.\n\nWarchief Kargath Bladefist carries upon his person his seal of command, which he uses to sign all official documents. I want you to retrieve it for me.\n\nYou will find him deep within the Shattered Halls. No doubt you will have to wade through a veritable army to get to him. I have no doubt that you will succeed.", objectives = "Wind Trader Zhareem has asked you to obtain Bladefist's Seal. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "I have heard it whispered that the warchief has weapons in place of his hands. Is this true?", completion = "Truly a daring acquisition that the bards should put pen to parchment for. Here, you have more than earned this.\n\nCome back tomorrow and I will have another request for you to fulfill." }
WordHunterWoW_QuestEN[11364] = { title = "WANTED: Shattered Hand Centurions", description = "Do you question your master? Neither does Mah'duun.\n\nThe blood of the centurions of the Shattered Hand clan is what I seek. You will find them within the Shattered Halls of Hellfire Citadel.\n\nIf you want the bounty, you will not return until you have slain them all.", objectives = "Nether-Stalker Mah'duun has tasked you with the deaths of 4 Shattered Hand Centurions. Return to him in Shattrath's Lower City once they all lie dead in order to collect the bounty.", completion = "Very well, you have earned your bounty.\n\nReturn again tomorrow and the winds will have whispered once more to Mah'duun." }
WordHunterWoW_QuestEN[11365] = { title = "March of the Giants", description = "To the east, at Giants' Run, rune-inscribed stone giants have started to migrate north toward Frostblade Peak. I know nothing of their goals, nor of their destination.\n\nThe glowing runes inscribed in the stone flesh of the giants guide them on their journey. Fell some of these giants.\n\nTake this pick with you and use it on the corpses of the runed stone giants. It will deactivate the runes. Once you've tested enough giants, return to me with your findings.", objectives = "Sage Edan and Camp Winterhoof wants you to use the Runeseeking Pick on the corpses of 4 Runed Stone Giants.", completion = "<The sage listens to your findings.>\n\nThe runes for \"north\" and \"west\" appeared over and over? I'm not an expert in these runes, but the repetition of them suggests a strong command.\n\nThese carvings are more than passive directions, though. They seem to pull the giants toward something, but what?" }
WordHunterWoW_QuestEN[11366] = { title = "The Lodestone", description = "We must find what's luring the giants northwest, so we can stop them before they reach their destination.\n\nWhile the rune samples gave us some clues, the unknown runes worry me.\n\nWhen I visited Giants' Run, I noticed a large broken tablet jutting from the ground where the northeastern part of the area met the snow at the foot of Frostblade Peak. Take this sample, compare the runes with the tablet, and see what you can learn about the identity of this lodestone.", objectives = "Sage Edan at Camp Winterhoof wants you to compare the Rune Sample with the Broken Tablet.", completion = "<Edan listens as you describe your findings.>\n\nMegalith? A literal transcription from the tablet! This Megalith must be the centerpiece of the iron ones' mysterious plans." }
WordHunterWoW_QuestEN[11367] = { title = "Demolishing Megalith", description = "Binder Murdis created Megalith to be a kind of keystone for the runed giants and to lead them in their mission. Defeating Megalith will leave them lost and without direction. I will ask Chieftain Ashtotem to divert some of our men as we move north and dedicate them to eliminating the last of the runed giants. Without their giants, the Iron Dwarves cannot stand against us.\n\nSearch the foothills of Frostblade Peak, north of Giants' Run for Megalith and defeat him!", objectives = "Defeat Megalith and return to Sage Edan at Camp Winterhoof.", completion = "You've done well in felling Megalith, but I wonder about his final words.\n\nYou're sure he said the Stoneforge?\n\nIt is not a name our people know, but it sounds like it might be a creation of the \"titans\" the ousiders speak of. The Iron Dwarves have ever been a cunning and dangerous foe, <name>. We must watch these giants and find this Stoneforge before they can carry out their plans." }
WordHunterWoW_QuestEN[11368] = { title = "WANTED: The Heart of Quagmirran", description = "I have an unusual request. A certain wealthy individual that I am in contact with off-world is interested in a macabre piece.\n\nSpecifically, she wants the heart of Quagmirran.\n\nI hear that the beast has three, but one will suffice for our purposes. As I understand it, you can find Quagmirran resting within a deep pool of water at the Slave Pens.", objectives = "Wind Trader Zhareem has asked you to obtain The Heart of Quagmirran. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "I trust that you know of a way to preserve the heart in transit?", completion = "Now that I think of it, it's a pity I didn't ask you to return with the other two hearts as well. Perhaps next time. In any case, you've earned your commission.\n\nCome back tomorrow and I will have another request for you to fulfill." }
WordHunterWoW_QuestEN[11369] = { title = "WANTED: A Black Stalker Egg", description = "There is only ever one great mother of the marsh walkers in Zangarmarsh. She is always known as the Black Stalker, and she hatches from one of the eggs left behind when her mother dies.\n\nI have a buyer who is interested in one of those eggs. He mentioned something about adding her as a zoo attraction.\n\nIf you are interested in the reward I am offering, travel to the Underbog and slay the Black Stalker for her egg.", objectives = "Wind Trader Zhareem wants you to obtain a Black Stalker Egg. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "We're speaking again because you have the egg? Outstanding, let me see it!", completion = "Is it not amazing to feel the life pulsing within the egg? I must hurry to deliver it to the purchaser. We wouldn't want it hatching here now would we?\n\nYour payment is ready.\n\nCome back tomorrow and I will have another request for you to fulfill." }
WordHunterWoW_QuestEN[11370] = { title = "WANTED: The Warlord's Treatise", description = "While it is known that Warlord Kalithresh of the naga is a great warrior in his own right, there are fewer who know that he has codified all of his knowledge.\n\nOne of my customers is aware of it though, and is keenly interested in obtaining his treatise.\n\nI ask that you travel to the Steamvault in Coilfang Reservoir and obtain this book for me.", objectives = "Wind Trader Zhareem has asked you to acquire The Warlord's Treatise. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "My customer grows restless. I believe he wishes to plumb the depths of the warlord's tactical thinking to help with one of his ongoing conflicts.", completion = "Indeed, I fear my customer will not have time to peruse the entirety of this book. Nevertheless, that is not our concern.  Here is your reward.\n\nCome back tomorrow and I will have another request for you to fulfill." }
WordHunterWoW_QuestEN[11371] = { title = "WANTED: Coilfang Myrmidons", description = "Mah'duun hears and obeys, and I now ask you to be my instrument.\n\nIt has been related to me that the myrmidons of the coilfang tribe must be destroyed. Seek them out within the humid confines of the Steamvault underneath Coilfang Reservoir.\n\nI will accept nothing less than their utter annihilation.", objectives = "Nether-Stalker Mah'duun has asked you to slay 14 Coilfang Myrmidons. Return to him in Shattrath's Lower City once they all lie dead in order to collect the bounty.", completion = "I trust that it was a fight worthy of your time? Certainly this bounty will be.\n\nReturn again tomorrow and the winds will have whispered once more to Mah'duun." }
WordHunterWoW_QuestEN[11372] = { title = "WANTED: The Headfeathers of Ikiss", description = "I've recently been approached by a tauren whose husband is about to be elevated to chieftain. She wishes to make a special addition to his headdress.\n\nSpecifically, she wants to obtain the headfeathers from the dastardly Talon King Ikiss.\n\nIf you are interested in collecting my reward, travel to Auchindoun's Sethekk Halls and find him.", objectives = "Wind Trader Zhareem has asked you to acquire The Headfeathers of Ikiss. Deliver them to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "The time of the chieftain's ceremony grows near.", completion = "I am sure that these feathers will make a fine addition to the chieftain's headdress. You have earned your compensation, <class>.\n\nCome back tomorrow and I will have another request for you to fulfill." }
WordHunterWoW_QuestEN[11373] = { title = "WANTED: Shaffar's Wondrous Pendant", description = "Today I have a personal request of you, yet the reward will certainly match the danger.\n\nMy family has a 'history', shall we say, with Nexus-Prince Shaffar and his followers. If the amulet he wears were to fall into my hands then surely that would mean that he had been dealt with.\n\nIf the bounty I am offering is of interest to you then journey to his lair within Auchindoun's Mana-Tombs.", objectives = "Wind Trader Zhareem wants you to obtain Shaffar's Wondrous Amulet. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "Not many know that the source of Shaffar's magic rests solely within his amulet. Without it he is powerless.\n\nThen again, if you have it that must mean that he is dead.", completion = "<You sense a deep level of satisfaction from the wind trader.>\n\nGood, I am glad to hear of his demise. And perhaps I will be able to unlock the secrets of his amulet for myself. If not, then I will sell it for a handsome price.\n\nI trust that this reward is sufficient.\n\nCome back tomorrow and I will have another request for you to fulfill." }
WordHunterWoW_QuestEN[11374] = { title = "WANTED: The Exarch's Soul Gem", description = "Within Auchindoun's Auchenai Crypts many unsavory experiments are undertaken in the pursuit of a greater understanding of the necromantic arts. Many are the spirits that are tortured or destroyed therein.\n\nI have a customer who is interested in the liberation of one of those spirits. I have been informed that this spirit is contained within a soul gem held by none other than Exarch Maladaar himself.\n\nSeek him out within the crypts with all due haste and return to me with the gem.", objectives = "Wind Trader Zhareem has asked you to recover The Exarch's Soul Gem. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "Can you imagine being trapped within a gem for all eternity?", completion = "You're quite the hero, <name>. I am certain that my customer will find a way to free the spirit of their loved one from within the gem. For a job well done, your payment awaits.\n\nCome back tomorrow and I will have another request for you to fulfill." }
WordHunterWoW_QuestEN[11375] = { title = "WANTED: Murmur's Whisper", description = "When I'm done speaking, you may not want to take this commission.\n\nI have an eccentric client who specializes in the study of dead realities. It is rumored that the being known as Murmur destroyed the last world from which he was summoned. The professor is interested in examining his 'whisper' as he called it to understand how it is that Murmur accomplished such a feat.\n\nWill you journey to the Shadow Labyrinth within Auchindoun and retrieve it for me?", objectives = "Wind Trader Zhareem has asked you to obtain Murmur's Whisper. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "I'm not even certain what form a whisper is supposed to take in the physical world, but the professor assures me that you'll know it when you see it.\n\nPerhaps it is something akin to the being's voice box?", completion = "I was worried that you might not return. I trust that you didn't go deaf from fighting Murmur?\n\nHere is your reward. The professor will be pleased no doubt, though I worry what he ultimately wishes to do with this thing.\n\nCome back tomorrow and I will have another request for you to fulfill." }
WordHunterWoW_QuestEN[11376] = { title = "WANTED: Malicious Instructors", description = "Mah'duun has heard it said that none are as cruel as the six-armed demonesses inside the Shadow Labyrinth.\n\nGo to Auchindoun, seek them out, kill them all.\n\nIf you cannot accomplish so simple a task, we do not have anything further to say to one another.", objectives = "Nether-Stalker Mah'duun wants you to kill 3 Malicious Instructors. Return to him in Shattrath's Lower City once they all lie dead in order to collect the bounty.", completion = "I am satisfied. He who speaks through the nether shall be as well. Mah'duun has your bounty prepared.\n\nReturn again tomorrow and the winds will have whispered once more to Mah'deen." }
WordHunterWoW_QuestEN[11377] = { title = "Revenge is Tasty", description = "I'm providing the catering for some unusual party guests tonight.  One of these fellows was flying around in Skettis and got knocked to the ground by a monstrous kaliri--his leg was broken badly.\n\nThey've requested something special for his get well party: Kaliri Stew.\n\nI can loan you my cooking pot so you can whip up a batch of stew for me.  The recipe itself is simple, but you'll need to get a giant kaliri wing and some cooked warp burgers.", objectives = "The Rokk in Lower City has asked you to cook up some Kaliri Stew using his cooking pot. Return to him when it's done.", progress = "Do I smell something tasty?", completion = "Oh, I do smell something tasty!  I hope you gave that bird quite a good beating.\n\nPlease, help yourself to some of my extra stock.  I'm sure someone of your talent could put it to good use." }
WordHunterWoW_QuestEN[11378] = { title = "WANTED: The Epoch Hunter's Head", description = "The tastes of my customers range from the mundane to the exotic. And sometimes they want to do very mundane things with the exotic objects they seek.\n\nSuch is the case with my latest request. My client, who shall remain nameless, wishes to obtain the head of the Epoch Hunter to mount on his wall.\n\n{class}, will you find a way to travel back in time to Old Hillsbrad and procure said head for my trophy-hunting patron?", objectives = "Wind Trader Zhareem has asked you to obtain the Epoch Hunter's Head. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "The head of the Epoch Hunter... how does one come to the decision that they want it mounted on their wall?\n\nAnd even then, to not hunt the beast yourself, what does one say to their friends when asked how the fight went?\n\nHe'll lie, I suppose.", completion = "I see you are returned to the present time intact.\n\n<The wind trader looks around.>\n\nIt doesn't appear that anything has changed. But then again, how would I know?\n\nThat's a nice cut; my customer will be pleased. Here is your reward.\n\nCome back tomorrow and I will have another request for you to fulfill." }
WordHunterWoW_QuestEN[11379] = { title = "Super Hot Stew", description = "I'm trying to invent something with some real zing.  But to be honest, I'm more of an idea goblin these days.  I've lost my sense of adventure.\n\nBut you... remind me of my younger days; ready to take on the world with a sword in one hand and a skillet in the other.\n\nI want you to take my beloved cooking pot and head out to Blade's Edge.  Throw in some shortribs and crunchy serpent--already cooked for extra flavor--and broil it over an abyssal's corpse, the only thing hot enough to do the trick.", objectives = "The Rokk in Lower City has asked you to cook up some Demon Broiled Surprise using his cooking pot, two Mok'Nathal Shortribs and a Crunchy Serpent. Return to him when it's done.", progress = "Any luck with my little experiment?", completion = "Now look at that...\n\n<The Rokk takes a sip of the concoction and his face twists into a bizarre mask of pain and delight.>\n\nSweet A'dal that's good!  A cook with your potential shouldn't be without his proper materials.  Take some of my extra stock and make me proud." }
WordHunterWoW_QuestEN[11380] = { title = "Manalicious", description = "Wouldn't you know it, I think my foodstuffs are up to date and someone comes along and requests the unusual: Mana Berry Delight.\n\nUnfortunately, mana berries are only found in the eco-domes of Netherstorm.  Just don't bother looking around Stormspire--it's picked clean.\n\nI could only trust someone trained in the culinary arts to pick the best berries, so don't let me down!", objectives = "The Rokk in Lower City has asked you collect 15 Mana Berries from the Eco-Domes in Netherstorm.", progress = "Any luck, friend?", completion = "Those are the juiciest mana berries I've ever seen.  I think I'm getting smarter just by looking at them.\n\nSince I no longer need most of my meat and fish stock, why don't you take some?  I'm certain you could make something delicious." }
WordHunterWoW_QuestEN[11381] = { title = "Soup for the Soul", description = "Death is in the air.  I've never had so many orders for my famous soup--it lifts your spirits and soothes the soul.\n\nAnd I know a fellow cook when I see one!  Would you like to help me out and get a cut of the profits?\n\nHere, take my cooking pot, gather some clefthoof meat and I'll let you in on a little secret.  What makes my soup so good for the soul?  It's not chicken--I cook it at the Ancestral Grounds in Nagrand to soak up all that spiritual stuff there.", objectives = "The Rokk in Lower City has asked you to cook up some Spiritual Soup using his cooking pot. Return to him when it's done.", progress = "What smells so good?", completion = "That is a fine batch of spiritual soup if I ever did smell one.  Just a pinch of pepper and it's done.\n\nAs promised, here's your cut.  And because you did such a fine job, I'm going to throw in some of my extra stock." }
WordHunterWoW_QuestEN[11382] = { title = "WANTED: Aeonus's Hourglass", description = "I swear that some of my customers are crazy. There are possessions that you go after, and there are ones that you dare not even think of!\n\nMy current client is clearly over-the-top insane. He covets the hourglass that Aeonus holds.\n\nYes, you heard right, Aeonus of the Infinite Dragonflight!\n\nWho am I to argue since he's paying a king's ransom? So, ready to go to the Caverns of Time and travel to the Black Morass to retrieve it for me?", objectives = "Wind Trader Zhareem has asked you to acquire Aeonus's Hourglass. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "If I were you, I would be very careful with time-travel. You wouldn't want to accidentally do something, like kill one of your ancestors, and then accidentally erase yourself from the present!", completion = "Odd that the sands in that thing are still falling upward. I think I will have it delivered to its new owner with all due haste.\n\nI thank you for a job well done, <class>. You have certainly earned your commission.\n\nCome back tomorrow and I will have another request for you to fulfill." }
WordHunterWoW_QuestEN[11383] = { title = "WANTED: Rift Lords", description = "Mah'duun knows where you must go. Mah'duun knows that you must kill rift lords. But, Mah'duun does not know exactly when.\n\nI know that does not make sense, but the voice on the winds was not more specific.\n\nTravel to the Black Morass through the Caverns of Time and the way shall be made clear.", objectives = "Nether-Stalker Mah'duun wants you to kill 4 Rift Lords. Return to him in Shattrath's Lower City once they all lie dead in order to collect the bounty.", completion = "You found your way back in time, and then back again. You must be a great <class>, <race>. The bounty is earned.\n\nReturn again tomorrow and the winds will have whispered once more to Mah'duun." }
WordHunterWoW_QuestEN[11384] = { title = "WANTED: A Warp Splinter Clipping", description = "Not long ago, I was approached by a kaldorei druidess with a touching request. And plenty of gold, of course!\n\nIt would appear that the forces of Darnassus wish to restore an ancient of the arcane known as Warp Splinter. The giant tree has been confused or corrupted, I'm not certain, but you'll find it inside of the Botanica at Tempest Keep.\n\nShe said that all they would need to regrow him was a small clipping.", objectives = "Wind Trader Zhareem has asked you to obtain a Warp Splinter Clipping. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "Did you lose your way to the Botanica? You can't miss it... it's at Tempest Keep off of the eastern edge of the Netherstorm.", completion = "Aw, you did get it! It's so tiny. And yet, when the druids are done with it -- a process I am told will take a very long time -- Warp Splinter will be regrown anew.\n\nAnd here is your reward as promised.\n\nCome back tomorrow and I will have another request for you to fulfill." }
WordHunterWoW_QuestEN[11385] = { title = "WANTED: Sunseeker Channelers", description = "It has been whispered to Mah'duun that the channelers of the military unit known as the Sunseekers must be killed today.\n\nThey are to be found within the Botanica at Tempest Keep.\n\nYou want the bounty, you kill the channelers.", objectives = "Nether-Stalker Mah'duun wants you to kill 6 Sunseeker Channelers. Return to him in Shattrath's Lower City once they all lie dead in order to collect the bounty.", completion = "And now they are dead, channeling no longer. He who whispers upon the nether is satisfied and you have secured the bounty.\n\nReturn again tomorrow and the winds will have whispered once more to Mah'duun." }
WordHunterWoW_QuestEN[11386] = { title = "WANTED: Pathaleon's Projector", description = "I always assumed that Pathaleon the Calculator used magic to project his image across Outland. Apparently I was wrong.\n\nMy latest customer tells me that the blood elf uses a mechanical device for his communication with the leaders of Prince Kael'thas's special projects. As I understand it, he acquired it from the Zaxxis rebels in the Netherstorm.\n\nMy client wishes to obtain the projector. Why don't you pay Pathaleon a visit? He can be found within the Mechanar at Tempest Keep.", objectives = "Wind Trader Zhareem has asked you to acquire Pathaleon's Projector. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "It's not that projector technology is something special in and of itself, but the range of this particular model is a true breakthrough!", completion = "I'm tempted to keep it for myself and return my client's money. It could certainly expand the reach of my business.\n\n<The wind trader sighs.>\n\nHowever, I have a reputation to uphold.\n\nSpeaking of my reputation, thank you for helping me to maintain it. Here is your commission.\n\nCome back tomorrow and I will have another request for you to fulfill." }
WordHunterWoW_QuestEN[11387] = { title = "WANTED: Tempest-Forge Destroyers", description = "There are mechanical constructs within the Mechanar which Mah'duun has been told must be dismantled.\n\nGo to Tempest Keep, find the tempest-forge destroyers and destroy them.\n\nThen you may return to collect the bounty.", objectives = "Nether-Stalker Mah'duun wants you to destroy 5 Tempest-Forge Destroyers. Return to him in Shattrath's Lower City once they all lie dead in order to collect the bounty.", completion = "Mah'duun enjoys fighting constructs; they are less messy than organic beings.\n\nThe bounty is yours.\n\nReturn again tomorrow and the winds will have whispered once more to Mah'duun." }
WordHunterWoW_QuestEN[11388] = { title = "WANTED: The Scroll of Skyriss", description = "Today's client seeks something truly unique.\n\nIt is said that Harbinger Skyriss is a servant of the Old Gods. It is also said that he carries a large scroll that contains their instructions for his domination of life in the universe on their behalf.\n\nMy current buyer wishes to get his hands on that scroll, nevermind that he won't be able to read the language upon it.\n\nTravel to Tempest Keep's Arcatraz and get it for me, will you, {class}?", objectives = "Wind Trader Zhareem has asked you to obtain The Scroll of Skyriss. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", progress = "It must be a very dangerous thing to do to meddle directly in the affairs of the Old Gods.\n\nBetter you than me!", completion = "I dare not touch the scroll lest I too risk the notice of the Old Gods. I will have one of my assistants handle its delivery.\n\nYou have more than earned your reward, <class>, and I wish you all the luck in the known worlds.\n\nCome back tomorrow and I will have another request for you to fulfill." }
WordHunterWoW_QuestEN[11389] = { title = "WANTED: Arcatraz Sentinels", description = "The sentinels within the Arcatraz have gone haywire. The prisoners run rampant and the guards attack those that would help.\n\nMah'duun hears the speaker on the nether winds. The speaker says to destroy the sentinels.\n\nAccomplish this and today's bounty is yours.", objectives = "Nether-Stalker Mah'duun wants you to dismantle 5 Arcatraz Sentinels. Return to him in Shattrath's Lower City once that has been accomplished in order to collect the bounty.", completion = "With the sentinels destroyed, perhaps the naaru will ask the Consortium to replace them? Mah'duun does not know and does not care.\n\nYou have earned the bounty.\n\nReturn again tomorrow and the winds will have whispered once more to Mah'duun." }
WordHunterWoW_QuestEN[11390] = { title = "I've Got a Flying Machine!", description = "Well, what are you waiting for, there's work to be done!\n\nHere's the keys to our flying machine. Grab three sacks of relics and haul them up to the crane platforms on the north and south sides of Steel Gate.  I'll mark them for you.\n\nHurry up! We haven't got all day!", objectives = "The Steel Gate Chief Archaeologist wants you to transport 3 Sacks of Relics from the bottom of the site and take them to the platform on the north or south side of Steel Gate.\n\nUse the grappling hook on the flying machine to do this.\n\nReport back to him after you've done so.", completion = "Good job, though I think ye might be wanting a refresher course in basic piloting.\n\nWell, no matter, one warm body's as good as another. Here's yer haul for the day." }
WordHunterWoW_QuestEN[11391] = { title = "Steel Gate Patrol", description = "Eh? Yer back for another day's work?\n\nWell, alright, here's the keys. We don't need any haulin' today, so just keep an eye out for anything suspicious, okay?\n\nI've hooked her up with some rockets and a machine gun - just in case.", objectives = "You're Steel Gate's ace pilot now, so the Steel Gate Chief Archaeologist wants you to keep patrol around the dig site and fight off anything that attacks.\n\nReport back to him when you're done with your patrol.", completion = "Nice shooting, ace.\n\nHere's your wages. Come back tomorrow for another round, ya hear?" }
WordHunterWoW_QuestEN[11392] = { title = "Call the Headless Horseman", description = "Many dreary candles adorn this pumpkin shrine.", objectives = "Take a Dreary Candle to the Loosely Turned Soil." }
WordHunterWoW_QuestEN[11393] = { title = "Where is Explorer Jaren?", description = "{name}, my betrothed, Jaren, went west with a small group of explorers to check into rumors of artifacts on the Chillmere Coast. But there are murloc down there, and I fear the worst has befallen them.\n\nSurely you have time to see if they're alright? There's a way down to the beach just to the southwest, though watch out for the worgs and other things lurking in the woods.", objectives = "Overseer Irena Stonemantle has asked you to locate her fiance, Explorer Jaren.", completion = "<The explorer beams a smile as you tell him who sent you. He continues in hushed tones.>\n\nIrena was concerned about me?  She gets that from her father you know." }
WordHunterWoW_QuestEN[11394] = { title = "And You Thought Murlocs Smelled Bad!", description = "Originally I came down here to investigate some rumors about artifacts to be dug up. I knew that there were murlocs along the coast here, but I never in a million years thought I'd see this.\n\n<The explorer pokes his head out to look around the tree.>\n\nThe Scourge are out there, and they're changing murlocs, and anything else they can get their hands on, into the walking dead!\n\n{class}, I think it's our duty to do something about this. Think you could take out a good chunk of those Scourge?", objectives = "Explorer Jaren has asked you to kill 15 Scourge of any type along the Chillmere Coast. Return to him once you have done so.", completion = "<Jaren seems very excited about your success, but motions you to keep your conversation to a whisper.>\n\nGreat job, <name>! That's a lot of Scourge goo all over your stuff though. You might want to think about a quick dip in the strait. It's cold, but it'll get you cleaned up right quick." }
WordHunterWoW_QuestEN[11395] = { title = "It's a Scourge Device", description = "The Scourge creature you just destroyed had this device held in its clutches. It has a jewel set into it which looks similar to the one that tops the scourging crystals.\n\nSurely, Explorer Jaren would like to have a look at this.", objectives = "Deliver the Scourge Device to Explorer Jaren on the Chillmere Coast.", progress = "What an odd-looking device you have there, <class>. Let me have a closer look at it.", completion = "I know what this is! <name>, it's a controlling device for those scourging crystals!\n\nI bet anything that it can be used to shut down their force fields. Hmmm." }
WordHunterWoW_QuestEN[11396] = { title = "Bring Down Those Shields", description = "Look at the button on the side of the controller here. I bet if you got close enough to one of those scourging crystals, you could use the controller to bring its shield down. Then it would simply be a matter of destroying the thing before its shield goes back up.\n\nWhat do you say, {name}? You up for it? I can guarantee a nice reward for you if you can bring down those shields and destroy the crystals.\n\nIt's the least we can do to keep the Scourge from making more of their own kind.", objectives = "Explorer Jaren on the Chillmere Coast has asked you to destroy 3 Scourging Crystals.", completion = "Nice!\n\n<Jaren looks around quickly to make sure that nothing noticed his outburst.>\n\nAlright, you certainly earned your pick of one of these things I found while I was down here.\n\nAnd, <name>, if you happen to find yourself back at Steel Gate, give Irena my love and let her know that I'm okay." }
WordHunterWoW_QuestEN[11397] = { title = "And You Thought Murlocs Smelled Bad!", description = "I came here to investigate a rumor about a Scourge presence nearby. I expected murlocs along the coast down below, but I never thought I'd see this!\n\nThe Scourge are down there, and they're changing murlocs, and anything else they can get their hands on, into the walking dead!\n\n{class}, we will not suffer them to create more of their kind, especially not from murlocs! There is a ramp down to the beach just northwest of the camp. See to it that you deal with the Scourge in a timely fashion!", objectives = "Apothecary Anastasia has asked you to destroy 15 Scourge of any type along the Chillmere Coast. Return to her at the Apothecary Camp once you have done so.", completion = "<Anastasia ponders your success for a moment.>\n\nA satisfactory job to be certain, yet somehow I sense that there's something else we should be doing to stop the efforts of the Scourge on that beach." }
WordHunterWoW_QuestEN[11398] = { title = "It's a Scourge Device", description = "The Scourge creature you just destroyed had this device held in its clutches. It has a jewel set into it which looks similar to the one that tops the scourging crystals.\n\nSurely, Apothecary Anastasia would like to have a look at this.", objectives = "Deliver the Scourge Device to Apothecary Anastasia at the Apothecary Camp.", progress = "What's that you have there, <class>? Let me have a closer look at it!", completion = "I can tell you what this is, <name>. It's a controlling device for those scourging crystals down there!\n\nI bet anything that it can be used to shut down their force fields. Hmmm." }
WordHunterWoW_QuestEN[11399] = { title = "Bring Down Those Shields", description = "Look at the button on the side of the controller here. I bet if you got close enough to one of those scourging crystals, you could use the controller to bring its shield down. Then it would simply be a matter of destroying the thing before its shield goes back up.\n\nBrave enough to hazard another trip down there, {name}? I can guarantee a nice reward for you if you can bring down those shields and destroy the crystals.\n\nHow can you refuse if it means less Scourge, especially ones made from murlocs?", objectives = "Apothecary Anastasia at the Apothecary Camp has asked you to destroy 3 Scourging Crystals.", completion = "<Anastasia turns and smiles at her succubus.>\n\nVery well, <name>, I concede that you have certainly earned a choice of one of these." }
WordHunterWoW_QuestEN[11400] = { title = "Brewfest Riding Rams", description = "If you show this hand stamp to Pol Amberstill, the Ram Racing Apprentice, he'll allow you to purchase Brewfest riding rams.", objectives = "Bring the \"Honorary Brewer\" Hand Stamp to Pol Amberstill near the entrance to the Brewfest Grounds in Dun Morogh." }
WordHunterWoW_QuestEN[11401] = { title = "Call the Headless Horseman", description = "Many dreary candles adorn this pumpkin shrine, which grins, taunting...", objectives = "Take a Dreary Candle to the Loosely Turned Soil." }
WordHunterWoW_QuestEN[11402] = { title = "Clayton's Quest: Extreme!!", description = "Clayton wants you to find and slay twenty Evil Squirrels.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Seriously, go slay those Evil Squirrels!" }
WordHunterWoW_QuestEN[11403] = { title = "Free at Last!", description = "Rage was my prison, {name}, and you have freed me.  Though I thought I did right, my soul now weeps for the terror and the death I have caused the good people of Azeroth.\n\nThank you for leading me back to the Light.  May I never again lose my way.\n\nTake this torn prayer book to an orphan matron, so the children will know that I will haunt them no more.", objectives = "Take the Tome of Thomas Thomson to a Masked Orphan Matron in Durotar, Brill or Falconwing Square.", progress = "<name>, it is good to see you again.  I'm sure the children enjoy tales of your heroism.", completion = "What?  This holy tome once belonged to an infamous paladin of the Alliance.  Was he the Headless Horseman?  Does this mean that the Horseman is defeated?\n\nThis is a glorious day, <name>!  Your legend will shine bright, and may it last for twice the years of the Horseman's reign of fear." }
WordHunterWoW_QuestEN[11404] = { title = "Call the Headless Horseman", description = "Many dreary candles adorn this pumpkin shrine, which grins, taunting...", objectives = "Take a Dreary Candle to the Loosely Turned Soil." }
WordHunterWoW_QuestEN[11405] = { title = "Call the Headless Horseman", description = "Many dreary candles adorn this pumpkin shrine, which grins, taunting...", objectives = "Take a Dreary Candle to the Loosely Turned Soil." }
WordHunterWoW_QuestEN[11406] = { title = "Everything Must Be Ready", description = "When the expeditionary force moves north, Captain Adams expects everything to be ready at Fort Wildervar. The scouts and craftsmen there have been tasked with preparing the gear and rations for our men for the climb into the hills.\n\nThe captain's famous for his temper, so I want to send someone ahead to check on the preparations. Fort Wildervar is far to the northeast, beyond Skorn, up in the snow-covered areas near the border with Grizzly Hills. Find Gil Grisert there and make sure he is prepared.", objectives = "Speak with Gil Grisert at Fort Wildervar.", completion = "So the quartermaster sent you?\n\n<Gil seems relieved.>\n\nTo be honest, we're running a bit behind here and we're going to need some help making our goals.\n\n<Gil shudders.>\n\nNone of the men want to brave the wrath of Captain Adams." }
WordHunterWoW_QuestEN[11407] = { title = "Bark for Drohn's Distillery!", description = "So, do you want to help bring strength and honor to Brewfest?  We need you to shout at the flags outside the auction house in the Valley of Strength, in the Valley of Honor, in the Valley of Wisdom and in the Valley of Spirits.\n\nWe'll lend you a racing ram for 4 minutes.\n\nBe careful though, the cheap goblins didn't put any apple crates along the way.", objectives = "Spread the word about Brewfest at the flags outside the auction house in the Valley of Strength, in the Valley of Honor, in the Valley of Wisdom and in the Valley of Spirits.", progress = "Have you finished spreading the word about Brewfest?", completion = "You kept your word and let people know about our brewmasters.  Thank you. We promised you these tokens, and gladly give them to you.  I imagine the trolls are a bit more stingy with handing over their tokens...\n\nCome back another day to help us spread the word about Brewfest." }
WordHunterWoW_QuestEN[11408] = { title = "Bark for T'chali's Voodoo Brewery!", description = "We need to spread the word about the trolls at Brewfest.  Ya need to shout at the flags outside the auction house in the Valley of Strength, in the Valley of Honor, in the Valley of Wisdom and in the Valley of Spirits.\n\nBut I'll make it easy for ya, I'll lend you a racing ram for 4 minutes.\n\nBe careful though, the goblins didn't put any apple crates along the way.  They are cheap like that.", objectives = "Spread the word about Brewfest at the flags outside the auction house in the Valley of Strength, in the Valley of Honor, in the Valley of Wisdom and in the Valley of Spirits.", progress = "Have you finished spreading the word about Brewfest?  But more importantly, did you let people know about the amazing troll brew?", completion = "Ya did it!  We gotta get ready for the flood of customers that are sure to come our way!  Thanks!\n\nOh, that's right, and we promised you a reward.  Can't forget about that...\n\nFeel free to stop by again another day to help us spread the word some more." }
WordHunterWoW_QuestEN[11409] = { title = "Now This is Ram Racing... Almost.", description = "So you want to check out the racing rams? The dwarves think they have got a handle on it, but let's be honest, they are drunk most of the time, so how hard can it really be?\n\nNow before I let you strut your stuff, you'll need to show me that you can handle these fine, legally obtained creatures.\n\nSo here's the deal: I'll lend you the use of a ram. You need to prove to me that you can handle using these rams.\n\nKeep the ram at a trot, canter and gallop for 8 seconds each.", objectives = "You have 4 minutes to ride the ram and maintain 3 different levels of speed for 8 seconds.", progress = "Have you got a handle on riding racing rams?", completion = "Hey, that wasn't too bad... are you sure you're not a dwarf?\n\nSo there's plenty more racing to be had and it's not just from me.  All over the Brewfest grounds you'll find people in need of a decent ram racer.  So go and make yourself useful.\n\nOh and don't forget, these rams were legally obtained.  I just want to make sure we're clear." }
WordHunterWoW_QuestEN[11410] = { title = "The One That Got Away", description = "The barbfish you brought should work well as bait for most fish, but I fear it'll attract a monster!\n\nWhen I first arrived, I put some of Nat Pagle's favorite bait on my hook and cast it into the water. A huge monster latched on, with giant teeth and icicles hanging from its fins!\n\nWould've pulled me into those icy waters if I hadn't cut the line! I can't use the new bait until ol' Frostfin's been dealt with. Use this bait near the sunken boat in the middle of the lake. He won't be able to resist!", objectives = "Christopher Sloan at Fort Wildervar wants you to defeat Frostfin.", completion = "At last, we can finally fish in peace! 'Course, by the time we catch anything, the expedition'll arrive and claim it all for themselves.\n\nYou have our thanks, <name>. Don't be a stranger 'round here." }
WordHunterWoW_QuestEN[11411] = { title = "Camp Winterhoof", description = "In my travels as a courier, I've seen a number of strange denizens of the Howling Fjord, but one group stands out. From a distance, they look like tauren, but upon closer inspection, they're quite different -- sturdier and shaggier.\n\nI found one of their settlements far to the north, beyond Halgrind, Skorn, and the northern forests. Camp Winterhoof, it's called, and it sits in the foothills of Gjalerhorn near the border with Grizzly Hills. Make contact with them, and see if they might be of use to us.", objectives = "Speak to Chieftain Ashtotem at Camp Winterhoof.", completion = "<The chieftain listens as you introduce yourself.>\n\nI am Chieftain Ashtotem, and my people are the taunka, and I will speak truly, outsider. Among my people, trust is earned, not given. You have my leave to walk among them and offer your assistance. Time grows short and some of them may welcome even an outsider's help with their preparations." }
WordHunterWoW_QuestEN[11412] = { title = "There and Back Again", description = "Am I glad you're here. We are in big trouble! There's been a brew accident on the road to Bladefist Bay, and kegs are no longer being transported. You gotta get us that brew!\n\nI'll put you on one of my racing rams and you follow the road to Bladefist Bay.\n\nOnce you get near him he'll toss you a keg, then you run the keg back here and toss the keg to my more capable assistant. For now, all we want are 3 kegs. Do a good job and maybe we'll have another job for you.", objectives = "Get a keg from the goblin stranded on the road to Bladefist Bay and return it to Ram Master Ray's assistant. If you lose your ram, ask Ram Master Ray for another.", progress = "Did you see the mess that goblin made?  I hope you didn't do too much reckless off-roading.", completion = "Thanks for your help!  As long as Brewfest is going, the Dark Iron dwarves are attacking and our supplier is stuck in that canyon, I'll need some help shipping kegs.  So if you want to work for more tokens, talk to me every day.\n\nHere are the tokens we promised you.  Have fun!" }
WordHunterWoW_QuestEN[11413] = { title = "Did Someone Say \"Souvenir?\"", description = "Not only are we supplying brew to everyone, we also have steins to give out!  Beautiful, commemorative steins all obtained by the most legal of means!  Here's a voucher for one.\n\nTalk to Blix near the back of the Brewfest camp.  He's pretty strange, even more so now that he's always wearing those goggles.  He'll handle the voucher for you, and any other Brewfest transaction.", objectives = "Redeem the Brewfest Stein Voucher with Blix Fixwidget in the back of the Brewfest camp." }
WordHunterWoW_QuestEN[11414] = { title = "Brother Betrayers", description = "Watcher Moonleaf is from my dreams! If you are her friend, you are mine.\n\nI was alpha male until the last full moon. Then the strange white worg, Garwal, came from the north, and with the help of my once-brothers, he quickly became alpha worg. There is something unnatural about him.\n\nTo help, you must first kill those who betrayed me.\n\nBjomolf hunts to the northwest of a place called Steel Gate. And look for Varg to the southeast, near the West Spear Tower.\n\nThey will not be fooled by your form.", objectives = "Ulfang has asked you to kill the traitorous worgs, Bjomolf and Varg. Return to him in disguise in the Rivenwood after you have done so.\n\nIf you somehow lose the Worg Disguise, return to Watcher Moonleaf for a replacement.", progress = "<A low growl rises from Ulfang's throat.>\n\nBjomolf and Varg are not dead!", completion = "The smell of their blood upon your muzzle pleases me. Brothers should not turn on each other." }
WordHunterWoW_QuestEN[11415] = { title = "Brother Betrayers", description = "Mistwalker is from my dreams! If you are his friend, you are mine.\n\nI was alpha male until the last full moon. Then the strange white worg, Garwal, came from the north, and with the help of my once-brothers, he quickly became alpha. There is something unnatural about him.\n\nTo help, you must first kill those who betrayed me.\n\nBjomolf hunts to the northwest of a place the two-legs call Steel Gate. And look for Varg to the southeast, near the West Spear Tower.\n\nThey will not be fooled by your form.", objectives = "Ulfang has asked you to kill the traitorous worgs, Bjomolf and Varg. Return to him in disguise in the Rivenwood after you have done so.\n\nIf you somehow lose the Worg Disguise, return to Sage Mistwalker for a replacement.", progress = "<A low growl rises from Ulfang's throat.>\n\nBjomolf and Varg are not dead!", completion = "The smell of their blood upon your muzzle pleases me. Brothers should not turn on each other." }
WordHunterWoW_QuestEN[11416] = { title = "Eyes of the Eagle", description = "Garwal hides himself behind an unnatural magic. None can see him unless he wants you to. There may be one chance we can take, though.\n\nMy enemy, the great eagle, Talonshrike, is said to have eyes that can see anything. If you were to take her eyes, then you would surely be able to see Garwal.\n\nTalonshrike keeps her nest at the base of a waterfall just to the southwest of the vrykul place called Skorn. If you touch the eggs in her nest, she will come down from the sky to kill you.\n\nGet her eyes.", objectives = "Ulfang has asked you to collect the Eyes of the Eagle. Return to him in disguise in the Rivenwood after you have done so.\n\nIf you somehow lose the Worg Disguise, return to Watcher Moonleaf for a replacement.", progress = "You have the eyes of the eagle?", completion = "<Ulfang howls loudly at your defeat of his great eagle enemy.>\n\nThe honor of the kill is yours. I wish that it had been my maw to finally close upon her neck.\n\nLet us not waste the sacrifice that she has made for us. Here, eat them!" }
WordHunterWoW_QuestEN[11417] = { title = "Eyes of the Eagle", description = "Garwal hides himself behind an unnatural magic. None can see him unless he wants you to. There may be one chance we can take, though.\n\nMy enemy, the great eagle, Talonshrike, is said to have eyes that can see anything. If you were to take her eyes, then you would surely be able to see Garwal.\n\nTalonshrike keeps her nest at the base of a waterfall just to the southwest of the vrykul place called Skorn. If you touch the eggs in her nest, she will come down from the sky to kill you.\n\nGet her eyes.", objectives = "Ulfang has asked you to collect the Eyes of the Eagle. Return to him in disguise in the Rivenwood after you have done so.\n\nIf you somehow lose the Worg Disguise, return to Sage Mistwalker for a replacement.", progress = "You have the eyes of the eagle?", completion = "<Ulfang howls loudly at your defeat of his great eagle enemy.>\n\nThe honor of the kill is yours. I wish that it had been my maw to finally close upon her neck.\n\nLet us not waste the sacrifice that she has made for us. Here, eat them!" }
WordHunterWoW_QuestEN[11418] = { title = "We Call Him Steelfeather", description = "We see one brave hippogryph circling over the fort, then swooping down and taking prey. Jethan over there has taken a couple of shots at the creature, but his arrows bounced right off!\n\nWe've taken to calling this remarkable creature Steelfeather, but we can't see why he prefers the area around Fort Wildervar. Most hippogryphs are wary of people.\n\nResearcher Aderan has helped us fashion a charm from one of the creature's feathers. He claims it will allow the user to see through Steelfeather's eyes.", objectives = "Locate Steelfeather circling Fort Wildervar and use the Feathered Charm to discover his secret. Report your findings to Gil Grisert.", progress = "Did Aderan's charm work?", completion = "You saw a nest, with hatchlings? Hmm... so our \"he\" is actually a \"she,\" eh?\n\nI guess that settles it. I suppose I wouldn't want to move a nest full of hatchlings just because of a new neighbor, either.\n\n<Gil favors Trapper Jethan with a mock glare.>\n\nI'm sure we'd get along just fine if ol' Jethan would stop trying to make a trophy of her." }
WordHunterWoW_QuestEN[11419] = { title = "Brewfest Riding Rams", description = "If you show this hand stamp to Driz Tumblequick, the Ram Racing Apprentice, he'll allow you to purchase Brewfest riding rams.", objectives = "Bring the \"Honorary Brewer\" Hand Stamp to Driz Tumblequick near the entrance to the Brewfest Grounds in Durotar." }
WordHunterWoW_QuestEN[11420] = { title = "The Path to Payback", description = "Two weeks ago our chief engineer got his hands on a vrykul harpoon gun - the same type of gun that the vrykul use to take down our ships. By studying that gun he managed to put together a comprehensive operation manual.\n\nUnfortunately he was abducted and taken north of here to Wyrmskull Village. We eventually did find him, but near death and without the manual. His dying words indicated that the manual was lost in the Utgarde Catacombs, located at the northwest end of Wyrmskull. Get me that manual!", objectives = "Guard Captain Zorek at Valgarde in Howling Fjord wants you to recover the Harpoon Operation Manual.", progress = "Did you find the manual?", completion = "<Zorek flips through the manual.>\n\nHrm, interesting...\n\nAccording to the manual, the vrykul have a special tool that allows them to control the harpoon guns with deadly accuracy. It looks a bit like the wheel of one of our ships. Furthermore, it's portable and seems to plug into the harpoon guns like a key. We need to get our hands on one of those!" }
WordHunterWoW_QuestEN[11421] = { title = "It Goes to 11...", description = "We must strike while the vrykul forces are in disarray! Take the harpoon control mechanism to Nifflevar and locate the northernmost harpoon building on the bluff side of the village.\n\nOnce there, commandeer one of the vrykul harpoon guns that are stationed on the building's deck. Use the harpoon gun to rain hell upon Wyrmskull Village! Destroy the longhouse, dockhouse, storage facility and any defenders that the vrykul may send at you!\n\nDo this and Daggercap Bay will become a much safer port!", objectives = "Lieutenant Icehammer in the Howling Fjord wants you to destroy the Dragonflayer Longhouse, Dragonflayer Dockhouse, Dragonflayer Storage Facility and 8 Dragonflayer Defenders.\n\nReturn the Harpoon Control Mechanism to him once the task is complete.", progress = "Is Wyrmskull up in flames?", completion = "Excellent work, <name>! You took out a good chunk of their dragon riders and really pissed off their leadership.\n\nAre you ready to head back to Valgarde and report the good news to Zorek? If so, I've got a crazy idea!" }
WordHunterWoW_QuestEN[11422] = { title = "Trident of the Son", description = "<From the scratches he makes in the rock, you see several symbols: a trident, a mur'ghoul, the sun, a wrecked ship, and a rough stick-figure of yourself.>\n\n<Puzzling out what the murloc is conveying takes a while. Obviously he wants you to get a trident from the Chillmere Coast, but the image of the sun is puzzling. That is until you realize he means his son.>\n\n<His son was changed into a mur'ghoul! He wants you to find him to the south near the wrecked ship and return with his trident.>", objectives = "Old Icefin wants you to obtain Rotgill's Trident. Return it to him on the small island on the Chillmere Coast.", progress = "<One of Old Icefin's dead fish-like eyes studies you, clearly looking for signs of his son's trident.>", completion = "<Reaching out to take his son's trident from you, Old Icefin's hand shakes a little. Could it be that the aged murloc is grieving?>\n\n<Is that just extra moisture pooling at the base of his eye?>" }
WordHunterWoW_QuestEN[11423] = { title = "The Enemy's Legacy", description = "As our armies march through Northrend, our enemies will not suffer mere defeat.  Their houses will burn, their corpses will be devoured by our plagues, all trace of their existence will be lost.\n\nThis worries me as a seeker of knowledge.  The eastern town of Nifflevar will soon be razed by our forces in Vengeance Landing.  The vrykul bard, Helgus, lived there and wrote three sagas: the Saga of the Twins, the Saga of the Winter Curse and the Saga of the Val'kyr.  Obtain them before Nifflevar is destroyed.", objectives = "Go into Nifflevar, north of Ghostblade Post and look for the Saga of the Winter Curse, the Saga of the Val'kyr and the Saga of the Twins.", progress = "The scrolls, <name>?  Did you obtain them?", completion = "This is of tremendous value, <name>.  I must renew my efforts in salvaging and translating vrykul texts.\n\nDon't get me wrong.  Our enemies need to be destroyed... their ancient knowledge doesn't." }
WordHunterWoW_QuestEN[11424] = { title = "Shield Hill", description = "My work should be extremely easy in a time of war.  There ought to be usable body parts everywhere.\n\nIt's not that simple, though.  With these eggheads making all sorts of killer plagues and sending them to enemy towns, most of the material gets contaminated.\n\nThere is a place, though, where usable samples exist.  Shield Hill, south of here, is an ancient vrykul burial ground where the dead walk but are not afflicted with any plague - ours or the Lich King's.  Get me some bones, I'll pay ya well.", objectives = "\"Hacksaw\" Jenny wants you to bring her 5 Ancient Vrykul Bones from the reanimated Vrykul in Shield Hill, south of New Agamand.", progress = "Got my bones then?", completion = "Hmmmmph... these will do for now.  There seems to be some oddness to them.\n\nI tell ya - I've handled body parts for years now and never have I had such a weird feeling in my stomach.  Anyway, a deal is a deal.  Here's your payment." }
WordHunterWoW_QuestEN[11425] = { title = "Test Quest - Craig", description = "Go on a quest!You will receive:", objectives = "Vermin, gotta hate 'em." }
WordHunterWoW_QuestEN[11426] = { title = "Locating the Mechanism", description = "Don't worry, {name}; this is all going to lead to something big! HUGE! You're just going to have to trust me for now and do as I ask of you.\n\nWe need to get the mechanism mentioned in the manual for the next step of the plan. I have a strong suspicion that you'll find one on one of those vrykul that operate the harpoon guns in Wyrmskull Village. You'll find them on the east side of the village, on the docks by the longhouses.", objectives = "Guard Captain Zorek at Valgarde in Howling Fjord wants you to bring him a Harpoon Control Mechanism.", progress = "Did you locate the mechanism?", completion = "Outstanding! Those overgrown apes will soon know what it means to mess with the Alliance!" }
WordHunterWoW_QuestEN[11427] = { title = "Meet Lieutenant Icehammer...", description = "Do you see those vrykul buildings on the bluffs to the northeast? The vrykul call that place Nifflevar. It's where most of their harpoon attacks on our frigates originate.\n\nWell guess what? The time for payback has come, {name}. I need you to take this harpoon control mechanism and meet up with Lieutenant Icehammer, who is hiding out in a vrykul building northwest of Nifflevar.\n\nWhen you're ready I'll place you on the back of one of our gryphons and zip you right to him! \n", objectives = "Guard Captain Zorek wants you to take the Harpoon Control Mechanism to Lieutenant Icehammer stationed outside of Nifflevar.", progress = "What is this? Do I look like a babysitter?", completion = "<Lieutenant Icehammer takes the harpoon control mechanism from you.>\n\nAh, you come bearing gifts!" }
WordHunterWoW_QuestEN[11428] = { title = "Keeper Witherleaf", description = "You have been a great friend and ally to us, {name}. There is one more thing I must ask of you.\n\nYou have seen the corruption of the Twisted Glade and the beasts that dwell there. The blacksouled keepers will continue raising these abominations from the waters and soil of our glade unless we act against them.\n\nThe most powerful of the blacksouled keepers is known as Keeper Witherleaf. Slay him, {name}, and open the way for the redemption of the glade as you once redeemed my sisters.", objectives = "Lurielle at the Frozen Glade wants you to kill Keeper Witherleaf.", completion = "My heart broke when I learned the keepers had turned against us. Once, we considered them our brothers and our closest friends.\n\nI grieve for the brothers and sisters we have lost, but without your help, there would be no hope for our future. You will always be welcome among us, <name>." }
WordHunterWoW_QuestEN[11429] = { title = "Drop It then Rock It!", description = "I'm not about to put the fate of this mission into the hands of some untested scrub.\n\nNow, if you want to prove to me that you've got what it takes to carry out this mission, you'll need to do what I tell you.\n\nTake this battle standard and head over to Baleheim, directly north of here. Once you're at Baleheim, find the center of town and drop our flag. Fight off any vrykul dirt bags that attempt to take down our beloved flag and return to me once you've established Alliance dominance!", objectives = "Lieutenant Icehammer in the Howling Fjord wants you to place the Alliance Banner in Baleheim and then defend the banner against attackers.\n\nReturn to Lieutenant Icehammer with the Alliance Banner should you survive.", progress = "Still alive, I see. Clearly you're not trying hard enough.", completion = "For the Alliance! You're a strong one, <name>. Strong enough to crack some vrykul skull at Nifflevar." }
WordHunterWoW_QuestEN[11430] = { title = "Harpoon Master Yavus", description = "That was a fairly strong showing at Baleheim, {name}. Before you go off patting yourself on the back there's work to be done at Nifflevar.\n\nWe've located the vrykul responsible for the majority of the harpoon attacks on our frigates - goes by the name of Yavus. You'll find him in the main harpoon structure on the bluffs of Nifflevar, southeast of here.\n\nTrack him down and execute him for crimes against the Alliance!\n\nDo me proud, {name}!\n", objectives = "Lieutenant Icehammer in the Howling Fjord wants you to slay Harpoon Master Yavus at Nifflevar.", progress = "Have you taken care of Yavus?", completion = "It'll take them a while to find a replacement for Yavus. Now is the perfect time to unleash Zorek's plan! While they're scurrying to regain control of Nifflevar, you're going to use their own harpoon guns against them!" }
WordHunterWoW_QuestEN[11431] = { title = "Catch the Wild Wolpertinger!", description = "On Draenor, many creatures posed a tough hunt. However, I've never encountered a creature such as the wild wolpertinger of Azeroth!\n\nThese beasts are not to be found most of the year, but the sounds and smells of Brewfest seem to draw them out. If you look around, you still may not see them... which is where these goggles come in handy!\n\nProve to me you are a worthy hunter and bring me five of these wolpertingers alive. If you need some goggles, I have some to spare.", objectives = "Snipehunter Goro has asked you to capture 5 Stunned Wolpertingers using the Wolpertinger Net. You must be wearing Synthebrew Goggles to see them.", progress = "Do you have something for me or are you just looking for some Synthebrew Goggles?", completion = "What!  They really exist!   Now I feel bad for kicking that dwarf in the knee...\n\nI need a minute... and a drink...\n\n<He takes a drink from his stein.>\n\nI guess I could let you keep one... Proof that drunk dwarves (are there any other kind?) actually tell the truth." }
WordHunterWoW_QuestEN[11432] = { title = "Sleeping Giants", description = "I've overheard what you've had to say with Father Levariol. Allow me to suggest that he's not having you go far enough.\n\nYou must also deal with the vrykul that lie dormant in the Waking Halls beneath Gjalerbron!\n\nI have no doubt that the rituals involved with awakening them are the key to their downfall. Most likely the necrolords have some device that you can use to bring the vrykul out of their dormant state prematurely.\n\nSurely such a disruption will prove fatal to the vrykul.", objectives = "Mage-Lieutenant Malister has tasked you with slaying 5 Dormant Vrykul. Return to him at Westguard Keep when you have done so.", completion = "You did what had to be done. Though some might consider it dishonorable to slay the helpless, in this case you would have been a fool to have done otherwise.\n\nAnd we certainly couldn't have just left them standing there to be ritually wakened, now could we?\n\nIt was a brave thing you did for all of us down in those catacombs, <name>." }
WordHunterWoW_QuestEN[11433] = { title = "Sleeping Giants", description = "I've overheard what you've had to say with Greatmother Ankha. With all due respect, she's not having you go far enough.\n\nYou must also deal with the vrykul that lie dormant in the Waking Halls beneath Gjalerbron!\n\nI have no doubt that the rituals involved with awakening them are the key to their downfall. Most likely the necrolords have some device that you can use to bring the vrykul out of their dormant state prematurely.\n\nSurely such a disruption will prove fatal to the vrykul.", objectives = "Ahota Whitefrost has tasked you with slaying 5 Dormant Vrykul. Return to him at Camp Winterhoof when you have done so.", completion = "You did what had to be done. The unwise might consider it dishonorable to slay the helpless while they awaken, but in this case you would have been a fool to have done otherwise.\n\nAnd we certainly couldn't have just left them standing there to be ritually wakened, now could we?\n\nIt was a brave thing you did for all of us down in those catacombs, <race>." }
WordHunterWoW_QuestEN[11434] = { title = "Forgotten Treasure", description = "I've made my fortune by specializing in treasure that regular pirates don't appreciate: art, antiquities, collector's pieces.\n\nBlack Conrad's fleet sank south of here years ago.  All the gold and jewelry was picked clean by divers, but two ancient relics remain there.  One is a museum-quality Amani vase, the other is an eagle figurine.\n\nGo and retrieve them for me and I'll vouch for you with the other pirates.  I'll even throw in something to make your underwater adventure a bit more manageable.", objectives = "Handsome Terry at Scalawag Point wants you to bring him 1 Amani Vase and 1 Eagle Figurine from the shipwreck to the south.", progress = "Did you obtain my relics, <name>?  Nobody gets by in this life on good looks alone... not even me!", completion = "We're going to go places together, <name>.  With my good looks and your... can-do attitude, we're sure to make a killing." }
WordHunterWoW_QuestEN[11435] = { title = "Gathered Pumpkins NYI", description = "Hi, <name>!  Thanks for driving away the Horseman!  Now that he's gone, the matron said we can roam the village!\n\nI found some pumpkins that the Horseman dropped.  They look scary... will you take them and show  them to the matron?You will receive:", objectives = "Take the bunch of jack-o'-lanterns to the Costumed Orphan Matron." }
WordHunterWoW_QuestEN[11436] = { title = "Let's Go Surfing Now", description = "Navigating the steep bluffs of Howling Fjord can be nerve-racking! I've come up with a solution to ease that burden by utilizing vrykul technology and dwarven ingenuity. With just a few adjustments and some fine tuning I've created Icehammer's harpoon controller! Of course it hasn't been tested, but that's what you're here for!\n\nTake the controller to the big gun in Nifflevar and use it to launch yourself into Valgarde. Report your victory to Zorek. Oh yea, you can keep the controller.", objectives = "Use the large Vrykul Harpoon Gun in Nifflevar to launch yourself into Valgarde. Report your victory over the Vrykul to Guard Captain Zorek.", progress = "<Zorek raises an eyebrow at you.>", completion = "You are insane, <name>! What kind of degenerate would actually launch themselves from a harpoon gun as a method of travel?\n\nBut I guess you need to be a little crazy to pull off what you did up there on the bluffs! Fantastic work! We've gotten word that the Dragonflayer leader, Ingvar, is furious! Maybe one day you'll be ready to stomp his face into the dirt - in the name of our beloved Alliance." }
WordHunterWoW_QuestEN[11439] = { title = "Fire Brigade Practice", description = "The brave dwarves of Kharanos can form a fire brigade in an instant, now that the Headless Horseman is around. Do you want to help?\n\nSouth of here, the mountaineers set up a small area to practice fighting fires.  Go there and throw buckets onto the blazes.  You can fill a bucket from the water barrel here.\n\nGood bye, {name}.  When you're done with fire brigade practice, please visit us again!", objectives = "Throw Water Buckets onto 5 fires, and then speak with the Costumed Orphan Matron.", completion = "You're smudged with soot!  You must have been extinguishing fires!\n\nWell done!  As an honorary member of the Fire Brigade, I beg you to return here if ever the village needs you!" }
WordHunterWoW_QuestEN[11440] = { title = "Fire Brigade Practice", description = "With the threat of the Headless Horseman looming, the peacekeepers have been diligent in forming a fire brigade when needed. Do you want to help?\n\nWest of here, toward the Exodar, the peacekeepers set up a small area to practice fighting fires.  Go there and throw buckets onto the blazes.  You can fill a bucket from the water barrel here.\n\nGood bye, {name}.  When you're done with fire brigade practice, please visit us again!", objectives = "Throw Water Buckets onto 5 fires, and then speak with the Costumed Orphan Matron.", completion = "You're wet and smudged with soot!  You must have been extinguishing fires!\n\nWell done!  As an honorary member of the Fire Brigade, I beg you to return here if ever the village needs you!" }
WordHunterWoW_QuestEN[11441] = { title = "Brewfest!", description = "Have you heard? It's time for Brewfest! You should speak to the Brewfest organizer at the grounds just outside of Ironforge--he'll give you a free beer to kick things off!", objectives = "Speak to the Brewfest Organizer.", completion = "Ho ho! Come for your free beer?" }
WordHunterWoW_QuestEN[11442] = { title = "Welcome to Brewfest!", description = "[PH] Speak to the Brewfest Organizer at the Brewfest Grounds outside of Ironforge and receive a free beer.", objectives = "[PH] Speak to the Brewfest Organizer and receive a free beer.", completion = "Ho ho! Come for your free beer?" }
WordHunterWoW_QuestEN[11443] = { title = "Daggercap Divin'", description = "Hey... Uh... What's up? What are you doing down here?\n\nMe? Oh... Well, you see... I'm... Um... I'm trying to clean this place up! Orders from Keller himself! He says to me, \"Harry, I want you to put on a divin' bell and search the shipwrecks of Daggercap for OUR stuff...\"\n\nSay, maybe you could lend me a hand while you're down here. Throughout the bay here are all kinds of goodies, err, I mean supplies. Go out and bring me back whatever you find. Use this diving helm so you don't run out of air and die.", objectives = "Harold Lagras at the bottom of Daggercap Bay wants you to recover 10 Valgarde Supply Crates.", progress = "Did you find those supplies?", completion = "Wow! You sure are efficient. Yep, well, just give me those crates. I'll need to document them and take inventory and some other stuff that you haven't been trained to deal with or understand. Don't worry; I'll be sure to let Keller know what a great job you did down here! Yep. Yea, you can leave now. Skedaddle!" }
WordHunterWoW_QuestEN[11446] = { title = "Brewfest!", description = "Have you heard? It's time for Brewfest! You should speak to the Brewfest organizer at the grounds just outside of Orgrimmar--he'll give you a free beer to kick things off!", objectives = "Speak to the Brewfest Organizer.", completion = "What?! A free beer? Yeah, yeah. I guess we said we'd do that this year." }
WordHunterWoW_QuestEN[11447] = { title = "Welcome to Brewfest!", description = "[PH] Speak to the Brewfest Organizer at the Brewfest Grounds outside of Ironforge and receive a free beer.", objectives = "[PH] Speak to the Brewfest Organizer and receive a free beer.", completion = "What?! A free beer? Yeah, yeah. I guess we said we'd do that this year." }
WordHunterWoW_QuestEN[11448] = { title = "The Explorers' League Outpost", description = "It's all a bunch of cryptic nonsense! Even with this cipher I can't make heads or tails of these tablets. Admittedly, cryptography is not my strong point.\n\nYou'll need to take the cipher and tablets to our cryptographer, Stanwad. Unfortunately, I haven't heard from Stanwad in two weeks. He took a team of twenty scientists to the dig sites on the southeastern bluffs of the fjord and hasn't been heard from since. The best I can do is have McGoyver over there give you a lift with his flying machine.", objectives = "Deliver McSorf's Bundle to Stanwad at the Explorers' League Outpost in Howling Fjord.", progress = "<Stanwad grumbles.>", completion = "<Stanwad takes the bundle from you and begins sorting the data.>\n\nWow. How many people did you say died to get this information?\n\n<Stanwad shakes his head.>\n\nYou'll be happy to know that what McSorf and his crew of bumbling imbeciles discovered is an ancient recipe for tundra stew. Did he not notice the icons of common vegetables and the pictograph of a humanoid mouth chompin' down on said veggies? You don't need a damned cipher to break this code!" }
WordHunterWoW_QuestEN[11449] = { title = "Fire Training", description = "The deathstalkers have set up a fire training area outside the town.  We cannot afford further damage to the buildings of Brill - you should do your duty and train as a fire fighter.\n\nHead west past the graveyard, following the road. You'll find the training area there.", objectives = "Toss Water Buckets on 5 fires, then speak with the Masked Orphan Matron in Brill.", completion = "Well done, <name>.  Children, take a good look at this <class>.  Let him be a strong example to you." }
WordHunterWoW_QuestEN[11450] = { title = "Fire Training", description = "The guards have set up a fire training area outside the town.  We cannot allow the Horseman to destroy what we have worked so hard to rebuild - you should do your duty and train as a fire fighter.\n\nHead south through the gate to the crossroads. You'll find the training area there.", objectives = "Toss Water Buckets on 5 fires, then speak with the Masked Orphan Matron in Falconwing Square.", completion = "Well done, <name>.  Children, take a good look at this <class>.  Let him be a fine example for you to follow." }
WordHunterWoW_QuestEN[11451] = { title = "Alicia's Poem", description = "Hi, I wrote a poem for my friend Caylee.  She likes to hang out with the Aldor in Shattrath City.  You know, in Outland?\n\nCould you take my poem to her?  My mommy says I'm too young to go to Shattrath City!", objectives = "You have been asked to deliver Alicia's Poem to Caylee Dak in Shattrath City in Outland.", progress = "Oh, is that a poem?", completion = "What a touching poem, thank you!" }
WordHunterWoW_QuestEN[11452] = { title = "The Slumbering King", description = "A sheaf of parchment drops from the still hand of the overlord. Upon it you can discern the outline of the rituals that are taking place in the catacombs below.\n\nHowever, it appears that the queen of the vrykul, Angerboda, is having difficulty awakening King Ymiron. The ritual is taking place within the large chamber, known as the Winter's Terrace, on the north end of Gjalerbron.\n\nIf you hurry, you may be able to stop her before it is too late.", objectives = "Defeat Queen Angerboda and stop the ritual to awaken King Ymiron. Should you manage to do so, return to Westguard Keep and report your success to Captain Adams.", completion = "I'm not sure that I like the sound of that one bit! The Lich King absconding with Ymiron can only mean trouble. Unfortunate that you weren't able to kill him along with his queen.\n\nStill, you've put a huge dent in their plans and bought us the valuable time that we need.\n\nAnd who knows, with the way you get around, you'll likely run into King Ymiron again. I'm sure that he won't fare so well the next time you meet." }
WordHunterWoW_QuestEN[11453] = { title = "The Slumbering King", description = "A sheaf of parchment drops from the still hand of the overlord. Upon it you can discern the outline of the rituals that are taking place in the catacombs below.\n\nHowever, it appears that the queen of the vrykul, Angerboda, is having difficulty awakening King Ymiron. The ritual is taking place within the large chamber, known as the Winter's Terrace, on the north end of Gjalerbron.\n\nIf you hurry, you may be able to stop her before it is too late.", objectives = "Defeat Queen Angerboda and stop the ritual to awaken King Ymiron. Should you manage to do so, return to Camp Winterhoof and report your success to Chieftain Ashtotem.", completion = "I'm not sure that I like the sound of that one bit! The Lich King absconding with Ymiron can only mean trouble. Unfortunate that you weren't able to kill him along with his queen.\n\nStill, you've put a huge dent in their plans and bought us the valuable time that we need.\n\nAnd who knows, with the way you get around, you'll likely run into King Ymiron again. I'm sure that he won't fare so well the next time you meet." }
WordHunterWoW_QuestEN[11454] = { title = "Seek the Saboteurs", description = "This scrap of paper seems to have been left behind accidentally by the Dark Iron invaders.\n\nWhile the plans are complicated and written in some form of coded Dwarvish, the signature at the end - \"Coren Direbrew\" - is clear enough, as is mention of the Grim Guzzler deep within Blackrock Depths. You should seek out the instigator and put an end to these raids.", objectives = "Find Coren Direbrew in the Grim Guzzler within Blackrock Depths.This scrap of paper seems to have been left behind accidentally by the Dark Iron invaders.\n\nWhile the plans are complicated and written in some form of coded Dwarvish, the signature at the end - \"Coren Direbrew\" - is clear enough, as is mention of the Grim Guzzler deep within Blackrock Depths. You should seek out the instigator and put an end to these raids.You will receive:" }
WordHunterWoW_QuestEN[11455] = { title = "The Fragrance of Money", description = "Us pirates are known for many things, but hygiene isn't one of them.  Most pirate ships be carrying five or six times as many rats as people.\n\nIt's no wonder all the bears on this island caught the rabies soon after we moved in.  Long story short, the boss wants 'em all dead.\n\nIt just so happens I know a recipe for a bear musk fragrance popular among Stormwind nobles.  We kill the bears and sell the musk.  I see a fine business opportunity for us here.  What say ye?", objectives = "Handsome Terry at Scalawag Point in Howling Fjord wants you to obtain 4 Bear Musk from the Rabid Brown Bears in the surrounding area.", progress = "Ye got the bear musk for me, matey?", completion = "Excellent work!  It might not be quite as daring as plundering the high seas, but I'd be a darned son of a deckswabber if I passed on this opportunity." }
WordHunterWoW_QuestEN[11456] = { title = "Feeding the Survivors", description = "We tuskarr rely mostly on our fish catch for sustenance.  In times of great need, however, we will on occasion hunt land animals.\n\nThe nearby village of Iskaal was recently attacked by pirates and the survivors just keep pouring in.\n\nOur catch has been modest this week, but there are many shoveltusk on the island and their meat is plentiful.\n\nAid my people by hunting these great beasts and obtaining their meat.", objectives = "Elder Atuik at Kamagua in Howling Fjord wants you to obtain 6 pieces of Island Shoveltusk Meat from Island Shoveltusk in the Isle of Spears.", progress = "Have you obtained the meat we need?", completion = "I thank you, <name>.  My people are in a time of great need." }
WordHunterWoW_QuestEN[11457] = { title = "Arming Kamagua", description = "Issliruk, the spirit of war, is depicted as a silver eagle by my people.  Our stories tell of how Issliruk fought against a hundred worgs to save his young.\n\nIt is time for us, too, to fight against our foes to save our brethren.  We will need to craft new weapons.  The horns of the frostwing chimaera that make their home in the snowy parts of the island are sharp and are easily crafted into spear tips.  Bring me the best of these horns that you can find.", objectives = "Elder Atuik wants you to obtain 3 Chimaera Horns.", progress = "It's good to see you again, <race>.", completion = "You continue to prove your worth as an ally, <name>.  Your actions will not be forgotten." }
WordHunterWoW_QuestEN[11458] = { title = "Avenge Iskaal", description = "The totem of Issliruk is ready, {name}, and for that I thank you.  We must cast our peaceful ways for the time being and strike at those who've attacked our land and our kin.\n\nThe pirate slavers that raided Iskaal have lost their minds and slaughtered all their captives.  Go to Iskaal, to the east of here and do what must must be done.  Take this horn and call on my brethren should you need assistance.", objectives = "Elder Atuik wants you to go to Iskaal and slay 8 Northsea Slavers. Use the Horn of Kamagua should you need assistance.", completion = "You are a formidable ally, <name>.  My people will forever be in your debt." }
WordHunterWoW_QuestEN[11459] = { title = "Zeh'gehn Sez", description = "Is like dis, mon.  Ye be wantin' me 'elp spotting some craven bag-o-wire been cardin' da crew?\n\nYe gotta bring me a croaker, matey.  Aft I an' I show ye who da blaggard be, mon.  Nah, nah, croaker show ye.  Ye'll ku fer yerself with yer own deadlights, yahso.\n\nBring us a carver yahso too, 'atsteppa.  Galang, bucko.", objectives = "Return to Handsome Terry to decipher what Zeh'gehn asked of you.", completion = "You didn't understand a thing Zeh'gehn said?  Well, of course not.\n\nLet's see then." }
WordHunterWoW_QuestEN[11460] = { title = "Trust is Earned", description = "The first and most important factor in falconry is the bond between the falconer and his bird. Trust must be earned by the master!\n\n<Hidalgo points to the falcons in the cage at his feet.>\n\nIf you are to earn their trust you will first need to fill their bellies.\n\nThe fjord rock falcon, as these birds are known, primarily eat grubs. Throughout the fjord you will find loose rocks that serve as breeding grounds for these grubs. Find a grub and return here to feed the falcons in the cage.", objectives = "Hidalgo at the Explorers' League Outpost in the Howling Fjord wants you to find a Fjord Grub and feed it to one of the falcons in the cage by his feet.", progress = "This is an important exercise, <name>. If you are to become a falconer you must learn how to feed your bird.", completion = "Yes, <name>. I can see the bond of companionship forming. She has accepted you as master." }
WordHunterWoW_QuestEN[11461] = { title = "DEPRECATED", description = "", objectives = "" }
WordHunterWoW_QuestEN[11462] = { title = "Handsome Terry", description = "Your people paid me good money to infiltrate the Northsea Freebooters and get your foot in the door.\n\nI talked you up to a fellow in Scalawag Point called Handsome Terry.  I told him you come highly recommended.\n\nPut your disguise on and go see him.  Here comes someone to take you there.\n\nYou're going to have to prove yourself a bit before they introduce you to their higher ups.  But that's all up to you.  Remember, <name>, once you're inside you're on your own!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Don the Pirate Disguise and speak to Handsome Terry inside Scalawag point.\n\nProvided item:" }
WordHunterWoW_QuestEN[11463] = { title = "Pirates of the North Seas", description = "The past few weeks have seen an increase in pirate attacks against our supply ships.  We've hired a goblin spy to pave the way for one of our agents to infiltrate the suspected pirates.\n\nThis group of Northsea Freebooters operates out of Scalawag Point, on Garvan's Reef.  We don't know much about them, but we do know that Sylvanas wants their leader's head.\n\nYou come very highly recommended, <name>.  If you take on this task, we can keep our military focused against Arthas' forces.  Are you up to it?You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Find Grezzix Spindlesnap on the northern end of Garvan's Reef off of the Southwestern coast of Howling Fjord.The past few weeks have seen an increase in pirate attacks against our supply ships. We've hired a goblin spy to pave the way for one of our agents to infiltrate the suspected pirates.\n\nThis group of Northsea Freebooters operates out of Scalawag Point, on Garvan's Reef. We don't know much about them, but we do know that Sylvanas wants their leader's head.\n\nYou come very highly recommended, <name>. If you take on this task, we can keep our military focused against Arthas' forces. Are you up to it?You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[11464] = { title = "Gambling Debt", description = "I heard you did a little work for Terry.  I was hoping someone reliable would show up around these parts.\n\nSee, pirates love to gamble.  They, however, do not love to pay their gambling debt.\n\nIf you're interested in collecting some coin on my behalf, I'd be willing to give you a cut.\n\nLet's start you out with an easy one.  \"Silvermoon\" Harry's a bit of an eccentric, keeps all sorts of expensive blood elf knickknacks inside his tent - yet when I see him he always pretends to be broke.  Get my gold.", objectives = "Taruk at Scalawag Point wants you to collect \"Silvermoon\" Harry's Debt.", progress = "You're back.  Did you get what's owed to me?", completion = "A job well done.  Here's your cut, <name>.  There's more where this came from.\n\nThere's no shortage of deadbeat pirates on this island." }
WordHunterWoW_QuestEN[11465] = { title = "The Ransacked Caravan", description = "I was leading a caravan here from Valgarde that was attacked by Dragonflayers. I was the only survivor of that ambush. Unfortunately, I couldn't make it back here with the cargo of fjord turkeys. This is the perfect opportunity for you to get your feet wet with your rock falcon.\n\n<Hidalgo hands you a cage.>\n\nTake this falcon cage and head west down the road leading out of this camp. Use the falcon to capture the loose turkeys and return here when you've gathered enough.\n\nRemember to feed the falcon!", objectives = "Hidalgo at the Explorers' League Outpost in the Howling Fjord wants you to use the Trained Rock Falcon to recover 5 Fjord Turkeys.\n\nReturn to Hidalgo with the cage once you have completed this task.", progress = "Your falcon must be constantly fed or else it will eat the prey that you are sending it to kill.", completion = "Clever fiends. And patient too! We need to stop underestimating our enemy. Those vrykul are deadly hunters!\n\nRegardless, mission accomplished. Perhaps it is time for you to hunt something a bit more elusive than a fat turkey, eh?" }
WordHunterWoW_QuestEN[11466] = { title = "Jack Likes His Drink", description = "Our next customer,  Jack Adams, won't be the pushover that Harry was.  He spends all day drinking with his friends, tough pirates all of them.  Let's not use force this time, could get ugly.\n\nSee if you can use his drinking habit to your advantage.  There's only so much alcohol someone can handle before passing out.\n\nMaybe one of the bar wenches will be of assistance.  Once he's out, see if you can slip your hand into his pocket and get what's mine.", objectives = "Taruk at Scalawag Point in Howling Fjord wants you to collect Jack Adams' Debt.", progress = "Did you get what's mine, <name>?", completion = "I'm impressed, <name>.  And I'm not the type who's easily impressed." }
WordHunterWoW_QuestEN[11467] = { title = "Dead Man's Debt", description = "You might've heard of Black Conrad, he's a famous pirate around these parts.\n\nWell, he had a thing for gambling on my fights.  He had a thing for not paying, too.\n\nI'd love to collect, but trouble is... he's dead.\n\nI was about ready to write the whole thing off, when I came across this...\n\n<Taruk unfolds a map of the Isle of Spears with an X on a northeastern plateau.>\n\nHe hid his treasure on tuskarr land.  I want you to get it.  I'll be damned if I let that bilge sucker get away without paying.", objectives = "Taruk at Scalawag Point wants you to search for Black Conrad's Treasure on the plateau in the northeastern end of the Isle of Spears, just north of Iskaal.", progress = "Did you find the treasure, <name>?", completion = "I'll take the gold, as it is what Conrad owed me.  The rest is for you to keep.\n\nIf you're ever in need of something more permanent, I'm sure I could arrange for something.  In the meantime, may the wind blow strong in your sail, friend." }
WordHunterWoW_QuestEN[11468] = { title = "Falcon Versus Hawk", description = "Do you feel the closeness, {name}? Surely you feel a true bond forming between you and your falcon. Would you believe me if I told you that when the time is right you'll be able to see through the eyes of your bird? Aye, it is the ultimate level of falconry.\n\nBut first you must hunt more! The bird must hone and quicken its reflexes. Send it against a more formidable opponent! The fjord hawks of the region make the tops of the trees around us their homes. They shall be your next target!  ", objectives = "Hidalgo at the Explorers' League Outpost in the Howling Fjord wants you to use your Trained Rock Falcon to capture 10 Fjord Hawks.\n\nReturn to Hidalgo with the cage when you have completed this task.", progress = "Your falcon must be constantly fed or else it will eat the prey you are sending it to kill.", completion = "Aye, the hawks are very territorial and often travel in packs. I suppose I could have told you that before I sent you out into the field." }
WordHunterWoW_QuestEN[11469] = { title = "Swabbin' Soap", description = "Yeah, I got to get the deck swabbed spotless afore Mad Jonah comes 'round. An' I ain't gonna do it on my hands and knees neither!\n\nProblem is, we're all outa soap. That's more your problem than mine though, mate. Being the newbie 'round here, I gots a special trip for ya to make.\n\nUp on the northwest coast of this island, there's a whole mess o' sea lions. Amongst the nearby ice floes you'll find the alpha bull, Big Roy. Bring me back his blubber and I'll magic-up the best soap ya ever seen!", objectives = "Scuttle Frostprow wants you to obtain Big Roy's Blubber as the main ingredient for her magic swabbin' soap. Return to her on the eastern pirate ship at Scalawag Point when you have it.", progress = "Where's that blubber? An' don't try to tell me he ain't got none either.\n\nThat Big Roy's so damned big it's a wonder he can still galumph around!", completion = "Ew, that's a stink if I ever smelled one!\n\nGo on now, put it down right here. I'll cast my spell and she'll be swabbin' soap for sure!" }
WordHunterWoW_QuestEN[11470] = { title = "There Exists No Honor Among Birds", description = "You are most definitely ready for the next step in falconry, {name}.\n\nTake your trained falcon east of here, to the vrykul hawk roost near the Stonewall Lift. From the roost you will send out your falcon to steal the eggs of the hawks. Their nests will be located in remote areas of the cliff walls surrounding the roost. Locate those nests and use your falcon to scavenge for the eggs!\n\nBeware the fjord hawk matriarchs, {name}. Should you come under attack, use your falcon's escape and soar abilities to flee!", objectives = "Hidalgo at the Explorers' League Outpost in the Howling Fjord wants you to use your Trained Rock Falcon to capture 8 Fjord Hawk Eggs.\n\nReturn to Hidalgo with the cage when you have completed this task.", progress = "You are in control now, <name>. Guide your falcon and bring me those eggs.", completion = "Bravo, <name>! Bravo! The bond of kinship between you and your falcon is strong! Perhaps you can run some reconnaissance missions against the vrykul in the not-too-distant future?" }
WordHunterWoW_QuestEN[11471] = { title = "The Jig is Up", description = "I know why you're here, {name}.  You've been sent to kill our leader, Jonah Sterling.\n\nI'd like to offer my help.  Jonah's leadership threatens our operation.\n\nAttacking the Horde and the Alliance fleets simultaneously?  Suicidal.  Trying to sell the tuskarr as slaves when they die days after leaving this climate?  Disastrous.\n\nJonah's hideout is located inside a cave west of here.  Bring me his spyglass as proof of the deed and my first action as leader will be to end all attacks against your allies.", objectives = "Annie Bonn at Scalawag Point wants you to bring her Jonah Sterling's Spyglass.", progress = "Well, <name>.  Did you get Jonah's spyglass?\n\nI can't just take your word for the assassination, you know?  I am a pirate after all.", completion = "Jonah Sterling's days are finally over!  He never thought this \"wench\" would make it.\n\nAs word of Jonah's death spreads among the pirates I will consolidate my leadership.  Your allies won't get any more trouble from my crew, <name>." }
WordHunterWoW_QuestEN[11472] = { title = "The Way to His Heart...", description = "The Northsea Pirates slaughtered the isles' alpha sea lion bull, Big Roy. They made soap from him to clean the decks of their ships!\n\n<Anuniaq sighs.>\n\nNow the sea lions won't mate. Help me to repopulate their numbers.\n\nThe reef bulls can be found at the Twin Shores to the southeast. They crave the tasty reef fish that can be found on the east and west sides of the isles.\n\nTake this net and gather enough fish, at least a dozen -- maybe more, to lure a bull across the strait to a reef cow.", objectives = "Toss Tasty Reef Fish at a Reef Bull to lead it to a Reef Cow. Once you have helped the two to find true love, return to Anuniaq at Kamagua.", progress = "Have you helped a reef bull and cow to get to know each other?", completion = "This is good news! Now more bulls will swim across the strait to mate with the cows. Soon there will be plenty of new reef pups on the isles.\n\nThank you, <race>. Whatever you might have done in the past, know that you have helped with Kamagua's future!\n\nWe'll have to keep up the good work if we're going to see to it that their numbers are replenished. Please come back again tomorrow so that we can help another couple find each other." }
WordHunterWoW_QuestEN[11473] = { title = "A Traitor Among Us", description = "Our second in command, Annie Bonn, has been acting rather paranoid as of late.  She seems sure we have an infiltrator in our ranks, can ye believe it?\n\nAnyhow, we have a foolproof way of uncovering rats around these parts.  See, good ole' Zeh'gehn over here happens to be an authentic witch doctor.  His family hails all the way from Zul... something or other.\n\nGo let him know that we're in need of his divination skills.  I must warn ye, {name}, only one or two of us can understand anything Zeh'gehn says.", objectives = "Speak to Zeh'gehn at Scalawag Post.", completion = "Ku here, mate.  Ye come fe see I an' I, aye?" }
WordHunterWoW_QuestEN[11474] = { title = "Problems on the High Bluff", description = "As usual, the real work is left up to me and my crew. Thankfully McSorf's team didn't die for nothin'. The cipher they recovered will help us crack the stuff we've found up here - that is if we can ever get back to it! Damned iron dwarves have sprung up like leaks all over the place and are now attemptin' to bury the sites! Can you believe it? Bastards want to bury our finds!\n\nAnyhow, talk to Walt over yonder. He'll get you started.", objectives = "Speak with Walt.", completion = "Over half our team is dead or missing, junior. This is our last stand up here on the high bluffs. Those damned iron dwarves pushed us out of both Ivald's Ruin and Baelgun's. Now I've got a plan to get us back inside before they bury up all our goodies and we lose that data forever." }
WordHunterWoW_QuestEN[11475] = { title = "Tools to Get the Job Done", description = "I've been studying this deactivated construct for days, {name}. I think I can create a reasonable facsimile of the golem that would have room inside to fit one passenger. The idea being that it would fool those iron dwarves and allow us to get inside Baelgun's.\n\nNow I'm not gonna be able to make anything with a hammer and poker. I need my tools! Unfortunately I left those behind at Ivald's Ruin when the iron dwarves first attacked. Get me my tools!\n\nIvald's Ruin is located far to the northeast.", objectives = "Walt at the Explorers' League Outpost in the Howling Fjord wants you to recover his Building Tools.", progress = "Step 1: Get Walt his tools.", completion = "Now that I've got my tools, the building can begin. Well, as soon as I have some materials. You'll be getting those for me next." }
WordHunterWoW_QuestEN[11476] = { title = "A Carver and a Croaker", description = "Some of the pirates around here... we have our own special way of talking.  Zeh'gehn has... many different special ways of talking... all mixed together.\n\nFrom what I can tell he wants a frog and a knife.\n\n\"Silvermoon\" Harry might have a knife on the cheap.  There's frogs all over town, just grab one and bring it to him along with the knife.\n\nI'd hate to be in the poor critter's shoes, if you know what I mean.", objectives = "Get a Shiny Knife from \"Silvermoon\" Harry and capture a Scalawag Frog. Bring these to Zeh'Gehn at Scalawag Point.", progress = "Ye get the croaker and carver, mon?", completion = "Much obliged, bucko.  Croaker's lookin' real cris!" }
WordHunterWoW_QuestEN[11477] = { title = "Out of My Element?", description = "Keep it down, {race}. These iron dwarves are quick on the trigger. Now don't let the activities down in the dig fool you. Those steel-skinned abominations aren't digging anything up! No sir - on the contrary - they're burying the site! For whatever whacked out reason, they don't want anyone finding this place.\n\nWhat kind of dwarf buries ancient relics and dig sites? I'll tell you what kind: the kind you kill with reckless abandon! Get in there and take 'em out!", objectives = "Donny at Ivald's Ruin in the Howling Fjord wants you to kill 10 Iron Rune Destroyers, 5 Iron Rune Laborers and 2 Iron Rune Sages.", completion = "Good job, <name>. That'll slow down the burial process a little." }
WordHunterWoW_QuestEN[11478] = { title = "Outpost Over Yonder...", description = "I see that you haven't visited my brothers at the Explorers' League Outpost south of here. Why don't you do Donny a favor and deliver this message to Stanwad. He'll be interested to hear about the activities of the iron dwarves up here.\n\nLike I said, mount up and start heading south. You'll see the outpost right before you get to Baelgun's.", objectives = "Deliver Donny's Letter to Stanwad at the Explorers' League Outpost.", progress = "News from Donny?", completion = "Yea, this isn't anything we don't already know. At least Donny's still alive." }
WordHunterWoW_QuestEN[11479] = { title = "\"Crowleg\" Dan", description = "Croaker's spoken, matey. \"Crowleg\" Dan's on da ship yonder.\n\nBest go trace that blaggard, mon.  Show'im dis set's not fe be crossed.  Gaan back fe Terry when ye keelhaul 'is behind.", objectives = "Confront \"Crowleg\" Dan, who is in one of the ships at Scalawag Point. Speak to Handsome Terry when you've completed this task.", progress = "I can't believe it was Dan.  Did you take care of it yet?", completion = "That's some sad news.  Dan was me old friend... AND he owed me money.  Either way, if he was working with the Southsea mongrels he got what he deserved.\n\nAs for you, my friend.  You're on your way up.  Literally." }
WordHunterWoW_QuestEN[11480] = { title = "Meet Number Two", description = "All the good work you've done for us hasn't gone unnoticed, {name}.  Our second in command, the delightful Annie Bonn, is incredibly impressed with what you've done so far and wants to meet you.  ", objectives = "Speak to Annie Bonn at Scalawag Point.", completion = "Well, well, well.  If it isn't <name>.  You show up at Scalawag point, no one's heard of you except some goblin friend of that half-wit Terry.\n\nLet's just say I'm a bit... skeptical... of your intentions here." }
WordHunterWoW_QuestEN[11481] = { title = "Crisis at the Sunwell", description = "By the naaru, I thank you, {race}, for your efforts.\n\nOur work is far from finished, however, and I must request that you undertake a critical mission - one as important as any I've issued.\n\nOur forces are spread thinly. To compound the strain, we've had to dispatch a contingent to Azeroth to investigate developments at the Sunwell Plateau.\n\nYou are needed there, {name}. Report to Larethor. Tell him that I wish we could spare more men.", objectives = "Adyen the Lightwarden on the Aldor Rise in Shattrath City has requested that you travel to Sunwell Plateau and speak with Larethor.", completion = "Another soldier from Shattrath? A welcome sight!\n\nWish there were more of you, but we'll make due with what we have. Whatever's going on out here won't wait for us to make ready.\n\nHave a look around, <class>. There's much that needs doing. Pitch in and do your share." }
WordHunterWoW_QuestEN[11482] = { title = "Duty Calls", description = "Hear me, {race}.\n\nDuty requires that you return to Azeroth. Every able person is to report to the Sunwell Plateau immediately.\n\nI'm afraid I have no more information to share, except this:\n\nYou'll be joining forces with the Aldor for this mission. Speak with a draenei by the name of Larethor when you arrive.\n\nApparently, the situation calls for us to set our differences aside and join forces.\n\nPrepare yourself, friend. This sounds serious.", objectives = "Dathris Sunstriker on Scryer's Tier in Shattrath City has insisted that you travel to Azeroth at once and report to Larethor at the Sunwell.", completion = "Welcome to Sunwell Plateau, cryer - What's that? Oh Scryer, yes of course. Isn't that what I said?\n\nWell, now, let's get a few things straight. There's some serious business going on behind those walls and it's in the interest of both of our people to address it. And since neither of us have the forces to go it alone, we're going to work - TOGETHER. Got that?\n\nNow let's get started, shall we?" }
WordHunterWoW_QuestEN[11483] = { title = "We Can Rebuild It", description = "Tools? Check. Materials? Negative.\n\nIf we're going to build this thing, you're going to have to get me the materials.\n\nFirst things first, {name}. For the skeletal structure I'm going to need a large barrel from Nifflevar, some dark iron ingots from Valgarde, and industrial strength rope from Baleheim.\n\nNifflevar and Baleheim are vrykul towns northwest of here. Valgarde is located in Daggercap Bay, also to the northwest. Speak with McGoyver to get the ingots. He'll fly you back here once you're all done.", objectives = "Walt at the Explorers' League Outpost in the Howling Fjord wants you to bring him a Large Barrel, Industrial Strength Rope and Dark Iron Ingots.", progress = "Have you got the infrastructure materials?", completion = "Excellent. These combined with the skin will make for a flawless clone of the constructs the iron dwarves use." }
WordHunterWoW_QuestEN[11484] = { title = "We Have the Technology", description = "While the infrastructure for a piece of machinery like this is important, we can't underestimate the appearance of the construct. If we're to fool the iron dwarves the clone must be exact!\n\nI can make this happen.\n\nBring me a pristine shoveltusk hide from the shoveltusk of this region and steel ribbing from vrykul in Nifflevar or Baleheim to the northwest.", objectives = "Walt at the Explorers' League Outpost in the Howling Fjord wants you to bring him a Pristine Shoveltusk Hide and Steel Ribbing.", progress = "We'll be back collecting our relics in no time!", completion = "I'll have the construct all ready to go as soon as the infrastructure is complete." }
WordHunterWoW_QuestEN[11485] = { title = "Iron Rune Constructs and You: Rocket Jumping", description = "Alright, {name}; the time has come for you to climb inside this thing and learn how to use its basic abilities. When you're ready, get on the work bench and I'll get you situated inside the construct.\n\nYour first lesson is going to be using the construct's transportation system. You'll notice that the iron dwarves have set up special rune carvings around the dig site. Their constructs use those rune carvings to power up and fly from point to point. Try it with the rune carving I built here.\n", objectives = "Walt at the Explorers' League Outpost in the Howling Fjord wants you to use the Iron Rune Construct's Rocket Jump ability at Walt's Iron Rune Carving.\n\nDismiss your construct by dismissing it from the pet window once you have completed the quest.", progress = "Don't take any lip from these naysayers!", completion = "You're almost ready to take this work of art into the field, <name>!" }
WordHunterWoW_QuestEN[11486] = { title = "The Best of Brews", description = "I know a bright lad like ya wants to stop the hostilities on the surface, eh? Ya want yer nice and merry Brewfest to go off without a hitch. I'll make ya a deal.\n\nTake this keg of our finest brew to the Brewfest Organizer outside Ironforge, so that we Dark Iron dwarves can be rightly represented! The best brew in all of Azeroth comes from right here in this mountain, and don't ya ferget it!", objectives = "Take the Dark Iron Ale Keg to Ipfelkofer Ironkeg in Dun Morogh." }
WordHunterWoW_QuestEN[11487] = { title = "The Best of Brews", description = "I know a bright lad like ya wants to stop the hostilities on the surface, eh? Ya want yer nice and merry Brewfest to go off without a hitch. I'll make ya a deal.\n\nTake this keg of our finest brew to the Brewfest Organizer outside Orgrimmar, so that we Dark Iron dwarves can be rightly represented! The best brew in all of Azeroth comes from right here in this mountain, and don't ya ferget it!", objectives = "Take the Dark Iron Ale Keg to Tapper Swindlekeg in Durotar." }
WordHunterWoW_QuestEN[11488] = { title = "Magisters' Terrace", description = "Welcome to the Sunwell, <class>. Get yourself settled in and contribute however you can - there's much to do!\n\nMe? Yes, I have a little something that needs doing, but I'm not sure you're up to the task.\n\nWe've had a contact embedded in Magisters' Terrace gathering intelligence for us. He's recently failed to report and I'm growing concerned.\n\nThe terrace is just up the rise to the east. The information he was collecting is vital to our mission.\n\nThink you can handle it, <race>?", objectives = "Exarch Larethor at the Shattered Sun Staging Area wants you to search Magisters' Terrace and find Tyrith, a blood elf spy.", completion = "...Come closer, <race>... Listen carefully to my words...." }
WordHunterWoW_QuestEN[11489] = { title = "Iron Rune Constructs and You: Collecting Data", description = "The most important part of your job while controlling the construct is the collection of data. I've placed an iron dwarf relic in the cart over yonder. It's the floating, lightning infused crystal.\n\nGet on the work bench and I'll put you back in the construct. Once you're back in the driver's seat, use the construct's data collection ability to pick up the test data.", objectives = "Walt at the Explorers' League Outpost in the Howling Fjord wants you to use the Iron Rune Construct's Collect Data ability while standing near the Iron Dwarf Relic.\n\nDismiss your construct by dismissing it from the pet window once you have completed the quest.", completion = "Perfect! Works like a charm!" }
WordHunterWoW_QuestEN[11490] = { title = "The Scryer's Scryer", description = "Go to the terrace... use the orb.\n\n<Tyrith gasps for breath.>\n\nHurry... they must be stopped... before they can....\n\n<Tyrith dies.>", objectives = "Tyrith wants you to use the orb on the balcony in Magisters' Terrace.", completion = "I consider it to be no coincidence that our paths cross this day.\n\nI sense the tendrils of destiny...." }
WordHunterWoW_QuestEN[11491] = { title = "Iron Rune Constructs and You: The Bluff", description = "You always gotta have a contingency plan in case your main plan backfires! That's why I've built in some anti-intelligence systems into the construct.\n\nYour shiny new ride might rouse some suspicion while you're at Baelgun's excavation site. That's what your bluff ability is for! Just use that any time you're confronted and you'll be safe from harm.\n\nTest it out on Lebronski by walking on his rug. Once he starts huffin' and puffin', use the bluff!\n\nGet on the work bench when you're ready to begin.", objectives = "Walt at the Explorers' League Outpost in the Howling Fjord wants you to use the Iron Rune Construct's Bluff ability on Lebronski after you've walked on his rug.\n\nDismiss your construct by dismissing it from the pet window once you have completed the quest.", progress = "Don't worry about him, <name>. He'll get over it...", completion = "You showed him! Now it's time to put you in the field.\n\nFeeling confident, I hope..." }
WordHunterWoW_QuestEN[11492] = { title = "Hard to Kill", description = "Welcome to the Sunwell, mortals. Your arrival is indeed timely.\n\nAs you've now witnessed, the Legion forces work tirelessly, manipulating the Sunwell's power to achieve their malevolent ends.\n\nKael'thas has risen from the ashes of defeat and once more leads them in their efforts. Find him, mortals. He must again be stopped.\n\nOther, equally urgent matters require my immediate attention. I shall leave Kael's fate to you. Do not fail.\n\nWith luck, we shall speak again.", objectives = "Kalecgos has asked you to defeat Kael'thas in Magisters' Terrace. You are to take Kael's head and report back to Larethor at the Shattered Sun Staging Area.", progress = "Well, <class>, I must admit, I wasn't sure I'd see you again.\n\nWhat news do you bring?", completion = "<Larethor listens intently as you explain your deeds in Magisters' Terrace.>\n\nTyrith will be missed - good man, that one. Thanks to you though, his death wasn't in vain.\n\nI've underestimated you, <race>. Please, accept this on behalf of the Sunwell Offensive - a gift worthy of a hero such as yourself." }
WordHunterWoW_QuestEN[11493] = { title = "UNUSED", description = "", objectives = "" }
WordHunterWoW_QuestEN[11494] = { title = "Lightning Infused Relics", description = "Your construct is ready to go. All abilities have been given a once over and I've programmed the machine to both comprehend and speak the language of the titans.\n\nTake the construct to Baelgun's Excavation Site, due south of here, and collect data from the lightning infused relics that litter the site. Remember to bluff any iron dwarves that suspect your construct to be a fake. And don't forget about rocket jumping from rune to rune to get around in there!\n\nGet on the table when you're ready!", objectives = "Walt at the Explorers' League Outpost in the Howling Fjord wants you to use the Iron Rune Construct's Collect Data ability to collect 15 sets of Iron Rune Data.\n\nDismiss your construct by dismissing it from the pet window once you have completed the quest.", completion = "And once again Walt proves that he is indeed the top dwarf! What do you think of my construct now, Lebronski!\n\nThank you, <name>. This data will undoubtedly prove to be invaluable - as soon as I figure out how to get it out of the construct." }
WordHunterWoW_QuestEN[11495] = { title = "The Delicate Sound of Thunder", description = "The cavern that we opened at Baelgun's was the one place that most steered clear of... Can't say I blame 'em. The sound of thunder shot out of that cave, {name}! Loud, booming thunder!\n\nI think near the end, it was abandoned by all. Bad, bad things happened to any that went in to explore - most never coming back.\n\nI want you to check that cave out while you're at Baelgun's. Explore around the titan statue inside and report back with your findings.", objectives = "Walt at the Explorers' League Outpost in the Howling Fjord wants you to use the Iron Rune Construct to explore the thundering cave at Baelgun's Excavation Site.\n\nDismiss your construct by dismissing it from the pet window once you have completed the quest.", progress = "Any luck?", completion = "Incredible! What could those iron menaces be up to? What are they doing in the Storm Peaks? And what is this Loken!? I'll forward this information to our central base of operations in the Dragonblight, <name>. I'll also let 'em know that you were invaluable in the acquisition of said info." }
WordHunterWoW_QuestEN[11496] = { title = "The Sanctum Wards", description = "Our first priority is to capture the Sun's Reach Sanctum.  Once we've secured it, we'll be able to use its energy to open a portal from Shattrath.\n\nThe sanctum is overrun with the Wretched - former blood elves who've devolved into mindless husks of their former selves.  Its defenses would've normally prevented this intrusion, but the Wretched have stolen the power sources from the protective wards.\n\nHunt down the Wretched and get the mana remnants they carry.  Use them to energize the sanctum wards.", objectives = "Captain Theris Dawnhearth at the Shattered Sun Staging Area wants you to obtain 4 Mana Remnants from Wretched Fiends and Wretched Devourers and use them to energize one of the Crystal Wards surrounding the Sun's Reach Sanctum to the east." }
WordHunterWoW_QuestEN[11497] = { title = "Learning to Fly", description = "Though it may end up hurting my business in the long run, you look the sort that dreams of flying his own mount through the skies, rather than being flown from place to place.\n\nI understand the feeling completely.\n\nYou, my friend, need to head to Wildhammer Stronghold in the southwest corner of Shadowmoon Valley. When you get there, speak with Ilsa Blusterbrew about some flight instruction. Mind you, her training's not cheap. But, I think that you'll find it worth your while.", objectives = "Speak with Ilsa Blusterbrew at Wildhammer Stronghold in Shadowmoon Valley.Though it may end up hurting my business in the long run, you look the sort that dreams of flying <his/her> own mount through the skies, rather than being flown from place to place.\n\nI understand the feeling completely.\n\nYou, my friend, need to head to Wildhammer Stronghold in the southwest corner of Shadowmoon Valley. When you get there, speak with Ilsa Blusterbrew about some flight instruction. Mind you, her training's not cheap. But, I think that you'll find it worth your while.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[11498] = { title = "Learning to Fly", description = "Though it may end up hurting my business in the long run, you look the sort that dreams of flying his own mount through the skies, rather than being flown from place to place.\n\nI understand the feeling completely.\n\nYou, my friend, need to head to Shadowmoon Village in the northwest corner of Shadowmoon Valley. When you get there, speak with Olrokk about some flight instruction. Mind you, his training's not cheap. But, I think that you'll find it worth your while.", objectives = "Speak with Olrokk at Shadowmoon Village in Shadowmoon Valley.Though it may end up hurting my business in the long run, you look the sort that dreams of flying <his/her> own mount through the skies, rather than being flown from place to place.\n\nI understand the feeling completely.\n\nYou, my friend, need to head to Shadowmoon Village in the northwest corner of Shadowmoon Valley. When you get there, speak with Olrokk about some flight instruction. Mind you, his training's not cheap. But, I think that you'll find it worth your while.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[11499] = { title = "WANTED: The Signet Ring of Prince Kael'thas", description = "{class}, today I ask the impossible. Today, you must obtain the signet ring of Kael'thas Sunstrider, lord of the blood elves!\n\nIt's true, the rumors of his death within Tempest Keep were ill-founded. He has appeared once more, this time at the Magisters' Terrace on the Isle of Quel'Danas. What he is doing there is a tale for someone else to tell you. What I know is that I have innumerable collectors interested in his princely ring, and I mean to acquire it for them.\n\nOr rather, I mean for you to do so.", objectives = "Wind Trader Zhareem has asked you to obtain The Signet Ring of Prince Kael'thas. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed at the Magisters' Terrace on Heroic difficulty.", progress = "The Magisters' Terrace must be a very dangerous place indeed being so close to the Sunwell.\n\nI trust that you're not having second thoughts?", completion = "So, the blood elf prince is truly dead this time? A pity, I always thought he had class. To think that one so lofty could be brought down for such a paltry sum.\n\nBut as they say, business is business. Your reward is earned, adventurer.\n\nCome back tomorrow and I will have another request for you to fulfill." }
WordHunterWoW_QuestEN[11500] = { title = "WANTED: Sisters of Torment", description = "It has been whispered to Mah'duun that the sisters of torment are to be sent back to the hells from which they sprang.\n\nMah'duun knows that these demons can be found at the Magisters' Terrace on the Isle of Quel'Danas.\n\nYou will do this thing to earn the bounty, or you will not.", objectives = "Nether-Stalker Mah'duun wants you to slay 4 Sisters of Torment. Return to him in Shattrath's Lower City once you have done so in order to collect the bounty.", completion = "Who can say why the demonic sisters needed to be slain? Do you care?\n\nMah'duun thinks you care enough to collect the bounty, though.\n\nReturn again tomorrow and the winds will have whispered once more to Mah'duun." }
WordHunterWoW_QuestEN[11501] = { title = "News From the East", description = "Westguard needs to know what's going on here, {name}. I want you to personally deliver the news to Captain Adams.\n\nWhenever you're ready, let me know and I'll put you back in the construct for one final flight. It'll take you to Westguard Keep, but more than likely blow up in the process.\n\nIt's been a pleasure...", objectives = "Speak with Captain Adams at Westguard Keep.", completion = "Wonderful... As if having the Scourge all up our you-know-whats wasn't enough, now we got some angry ancient titan construct to deal with!\n\nI'll need some time to chew on this information, <race>. In the meantime there's plenty of work that needs doing here." }
WordHunterWoW_QuestEN[11502] = { title = "In Defense of Halaa", description = "We are not a warlike race, {race}.  However when war comes to our lands, we do not run away from it.\n\nThe Alliance and the Horde wage war in the city of Halaa, to the northwest. We do not know what the blood elves are scheming, but any victory for the Horde would be disastrous.  The history between our people and the orcs is one of bloodshed and betrayal.\n\nGo and slay the enemy in Halaa and you will be rewarded in coin, honor and renown.", objectives = "Defeat 10 enemy players in Halaa and return to Lakoor in Telaar.", completion = "I thank you, <name>.  Your efforts will not be ignored." }
WordHunterWoW_QuestEN[11503] = { title = "Enemies, Old and New", description = "Our ancient enemy, the draenei, have returned with powerful allies.  They wage war in Halaa, southwest of here.\n\nWe cannot allow them a victory there as Garadar would be next without a doubt.\n\nGo and slay those who would aid our ancient enemy.", objectives = "Defeat 10 enemy players in Halaa and return to Karrtog in Garadar.", completion = "You bring great honor to our people.  You have our thanks." }
WordHunterWoW_QuestEN[11504] = { title = "The Dead Rise!", description = "The path east of us is a primary hunting trail of the tuskarr. At least that's what it used to be...\n\nMore recently our hunters have been returning to Kamagua claiming that the dead have risen and are out for blood! That is what has brought my son and me here. Elder Atuik asks that we find resolution in the bluffs.\n\nWill you assist us in our time of need? I seek heroes willing to brave the perils of Shield Hill, southeast of here. Search the desecrated graves for clues and return your findings to me.", objectives = "Orfus of Kamagua at the Ancient Lift in the Howling Fjord wants you to find Fengir's Clue, Rodin's Clue, Isuldof's Clue and Windan's Clue.", progress = "The tuskarr need your help!", completion = "<Orfus's whiskers bristle.>\n\nPirates... Is there no end to the depths of their depravity?\n\nWe must recover the stolen artifacts and return them to this cursed place so that my people may once more know peace." }
WordHunterWoW_QuestEN[11505] = { title = "Spirits of Auchindoun", description = "Auchindoun's spirits have no stake in the conflict between the Alliance and the Horde, but incurring their favor will give our side an edge in the region.\n\nAncient custom directs the living to pay their respects at spirit towers in the Bone Wastes - though only at specific times of the day.  If you can help secure a tower during these times, you will have helped bring the spirits to our side.\n\nShould we succeed in gaining the spirits' favor, they will grant us a boon that will aid us in our endeavors.", objectives = "Help the Alliance secure a tower in the Bone Wastes.", completion = "The spirits are one step closer to resting in peace.  It is good to incur their favor, especially when waging war so close to their place of rest." }
WordHunterWoW_QuestEN[11506] = { title = "Spirits of Auchindoun", description = "The draenei might be our enemies, but the spirits of their ancestors in Auchindoun are restless and have no allegiance.\n\nThe draenei's custom required them to pay their respects at spirit towers at various times during the day.  If you can help secure a tower during these times, you will help the spirits return to peace in Auchindoun.\n\nThe Alliance will try to capture the towers in order to secure the dead's favor.   We must ensure that our side succeeds instead.", objectives = "Help the Horde secure a Spirit Tower in the Bone Wastes.", progress = "The spirits of Auchindoun are all around us.  Will they grant us their boon?", completion = "The spirits are closer to finding peace and have bestowed their favor onto us.\n\nA humiliating blow to our enemy that their own ancestors would side against them, even if only temporarily." }
WordHunterWoW_QuestEN[11507] = { title = "Elder Atuik and Kamagua", description = "<Orfus bundles up the clues you brought him.>\n\nMy people are bitterly entrenched in a war with the Northsea Freebooters. If any tuskarr could help us in our quest to right the wrongs of the pirates, it will be Elder Atuik of Kamagua. You must take these clues to him at once.\n\nTo get to Kamagua you must take the Ancient Lift, behind me. Take the lift directly to Kamagua and find Elder Atuik.", objectives = "Orfus of Kamagua in the Howling Fjord wants you to deliver Orfus's Bundle to Elder Atuik at Kamagua.", progress = "News from Orfus?", completion = "Orfus is a good tuskarr - one of our strongest warriors. I knew he would not let us down.\n\nAllow me to see what it is that you have brought." }
WordHunterWoW_QuestEN[11508] = { title = "Grezzix Spindlesnap", description = "The pirate thieves have set up port at Scalawag Point, far to the south. Unfortunately, they have fortified their camp with many deadly defenses.\n\nThere is someone that might be able to assist us in infiltrating Scalawag.\n\nA pirate mercenary by the name of Grezzix Spindlesnap recently came to our village in search of food and shelter. In exchange he gives us information about our enemies and feeds them misinformation about our attack plans. Seek him out at his ship just off the coast here - southwest.", objectives = "Speak with Grezzix Spindlesnap.", completion = "Yarr, matey. Grezzix never did like to get his hands dirty! A pirate's life for Grezzix is a good one, so long as Grezzix doesn't have to do any of the work.\n\nI've seen those artifacts. It's the reason I'm here and not at Scalawag myself! Bad, bad things those are...\n\nHey, it's your life though, right? You wanna get inside Scalawag and Grezzix can help." }
WordHunterWoW_QuestEN[11509] = { title = "Street \"Cred\"", description = "The Northsea Freebooters all fear and respect Grezzix. I'm thinking they recognize my special talents and envy my amazing ship. All you need to do is tag along with my cabin boy, Lou, and you'll be in like... In like tin. Pirates love tin.\n\nJust talk to Lou when you're ready to go and he'll take you to Scalawag.\n\nOh yea, you'll want to talk to \"Silvermoon\" Harry first. He'll have more information on the stuff they pilfered. Just watch what you say around him. He's a freak... crazy for blood elves.", objectives = "Speak with \"Silvermoon\" Harry at Scalawag Point about the missing Vrykul artifacts.", completion = "<Harry raises an eyebrow at you.>\n\nSo you're like me, eh? A little eccentric.\n\n<Harry whispers.>\n\nNobody dresses like that around here.\n\nAbout those artifacts... Everyone that came into contact with that stuff has ended up dead, missing or both.\n\nIf you're still interested in learning more, I can help - but it'll cost you.\n\n<Harry winks.>\n\nYou scratch my back and I'll try to not stick a dagger in yours." }
WordHunterWoW_QuestEN[11510] = { title = "\"Scoodles\"", description = "One of the first things Jonah Sterling did after he went crazy was to take my prized sin'dorei scrying crystal and feed it to the bane of my existence, \"Scoodles\" the orca.\n\nNo I didn't name the damned thing. I just know that she swims out past the ships directly southeast of Scalawag. Kill that overinflated goldfish and rip out my beautiful sin'dorei crystal from its stomach.\n\nDo this and we can get down to business.", objectives = "\"Silvermoon\" Harry at Scalawag Point wants you to recover his Sin'dorei Scrying Crystal from the orca, \"Scoodles.\"", progress = "Are you lost?", completion = "<Harry takes the crystal from you and gently pets it.>\n\nOh my precious! Did the big, mean whale hurt you? It'll be ok. I'll never let you out of my sight again!\n\n<Harry looks up at you.>\n\nSo, where were we?" }
WordHunterWoW_QuestEN[11511] = { title = "The Staff of Storm's Fury", description = "Those artifacts are cursed and you'd be crazy to go looking for them, {race}. I know for certain that anyone that's come into direct contact with any of those items has either gone mad or been killed.\n\nTake that staff, for example. Last I heard the ship that held it was abandoned and left to rot on the coast of the Isle of Spears, north of here.\n\nIf you want that thing, check the ship's hold.\n\nWhatever you do, don't bring that staff back here! And steer clear of Abdul! He'll tear your heart out.", objectives = "Recover the Staff of Storm's Fury and deliver it to Orfus of Kamagua in the Howling Fjord.", progress = "You have the staff?", completion = "We must return all of the artifacts, <name>. When all four are gathered, you will put them back in their graves." }
WordHunterWoW_QuestEN[11512] = { title = "The Frozen Heart of Isuldof", description = "Some say Jonah was never quite right in the head, but I know the truth. It was the heart. That damned frozen heart! I saw the change in him the second he pulled it from the grave. I could see the blood freeze in his veins... It was then that the madness truly took over.\n\nHe left us to hole up in his cave on the north side of this island. Last I heard he had thrown the heart in the back of his bear den. Too little, too late...\n\nI'll kill you myself if you even think about bringing that heart back here!", objectives = "Recover the Frozen Heart of Isuldof and deliver it to Orfus of Kamagua in the Howling Fjord.", progress = "The... The Frozen Heart of Isuldof?", completion = "We must return all of the artifacts, <name>. When all four are gathered, you will put them back in their graves." }
WordHunterWoW_QuestEN[11513] = { title = "Intercepting the Mana Cells", description = "I have devised a plan to acquire a power source strong enough for the creation of our portal.\n\nThe ethereal forces at Bash'ir Landing, atop the northwestern Blade's Edge Mountains, have been smuggling mana cells out of Tempest Keep and transporting them to the Sunwell for Kael'thas.\n\nThey have hidden the cells, but there is a way for you to find them; the ethereal carry phase devices that you can use to see the smuggled goods.\n\nJust beware the mana cells' phase wyrm guardians.", objectives = "Obtain 10 Smuggled Mana Cells and return them to Exarch Nasuun on the Terrace of Light in Shattrath City." }
WordHunterWoW_QuestEN[11514] = { title = "Maintaining the Sunwell Portal", description = "We must maintain the energy to our portal or it will collapse. The mana cells that the ethereals at Bash'ir Landing have hidden will continue to serve our purposes. The landing sits atop the northwestern corner of the Blade's Edge Mountains, far to the north.\n\nRemember, acquire a phase device from one of the ethereals and then use it to locate the smuggled goods.\n\nJust be cautious of the phase wyrms that they use to guard the mana cells.", objectives = "Obtain 10 Smuggled Mana Cells and return them to Exarch Nasuun on the Terrace of Light in Shattrath City.", progress = "<name>, how fare your efforts to obtain mana cells for us this day?", completion = "These mana cells will continue to power the portal.\n\nReturn tomorrow and I will send you out to obtain more." }
WordHunterWoW_QuestEN[11515] = { title = "Blood for Blood", description = "When Kael's forces retreated through that portal, his most loyal lackeys were rewarded with an abominable gift.  They  stayed behind and gorged themselves on the blood of demons for days.\n\nThe blood has changed them, given them new powers.  It will also prove their undoing.\n\nObtain blood samples from other demons.  Use them to power this fel siphon and deprive these arrogant fools of their new powers.  Slay them in their weakened state and return to me.", objectives = "Magistrix Seyla at the Throne of Kil'jaeden wants you to kill 4 Emaciated Felbloods by using the Fel Siphon on them. You will need Demonic Blood from nearby Wrath Heralds to power the Fel Siphon.", progress = "These freaks are a disgrace to our race.  You must destroy them, <name>.", completion = "Fools.  They learned to drain fel energy but did not learn how to retain it.\n\nWe were lucky, <name>.  An experienced felblood would've surely been a formidable opponent." }
WordHunterWoW_QuestEN[11516] = { title = "Blast the Gateway", description = "We have to shut down this gateway to stop Legion reinforcements to the Isle of Quel'Danas.\n\nTake these embers, they contain one of my creations: a living flare.  It is designed to act as a powerful destructive force - as long as it has been provided enough energy.\n\nFind the fel sparks that wander the area and slay them near the living flare.  The flare will grow in power each time, until it becomes unstable.\n\nOnce you've achieved this bring the flare to the gateway.  It will know what to do.", objectives = "Magistrix Seyla at the Throne of Kil'jaeden wants you to use the Sizzling Embers to summon a Living Flare and slay Incandescent Fel Sparks near it until it becomes an Unstable Living Flare. Return to the Legion Gateway with the Unstable Living Flare to destroy it.", progress = "Is it done, <name>?  We must stop further Legion forces from reinforcing Kael'thas.", completion = "Excellent work, <name>.  The demons might repair the gateway in due time.  I suppose we'll just have to blow it up again." }
WordHunterWoW_QuestEN[11517] = { title = "Report to Nasuun", description = "I am most glad that you are here, {class}! Now that we have taken this sanctum, we must hurry to create a magical portal that will lead to here from Shattrath City in the Outland.\n\nMy liege lord, Exarch Nasuun, is heading up the Offensive's efforts to do just that. He asked me to send along any promising candidates who have what it takes to help with the portal's creation.\n\nPlease, travel to Shattrath City and speak with him inside A'dal's chamber on the Terrace of Light.", objectives = "Tradesman Portanuus has asked you to speak with Exarch Nasuun on the Terrace of Light in Shattrath City.I am most glad that you are here, <class>! Now that we have taken this sanctum, we must hurry to create a magical portal that will lead to here from Shattrath City in the Outland.\n\nMy liege lord, Exarch Nasuun, is heading up the Offensive's efforts to do just that. He asked me to send along any promising candidates who have what it takes to help with the portal's creation.\n\nPlease, travel to Shattrath City and speak with him inside A'dal's chamber on the Terrace of Light.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[11518] = { title = "Sunwell Daily Portal Flag", description = "", objectives = "" }
WordHunterWoW_QuestEN[11519] = { title = "The Lost Shield of the Aesirites", description = "If you listen real close you can hear cannon fire coming from the northeast. That's Captain Ellis's ship, Sister Mercy. Thing is, Ellis and his entire crew were killed 'bout a month ago.\n\n<Harry nods.>\n\nGhost ship...\n\nIf it's info you be wantin' 'bout the shield, Ellis is the man to ask.\n\nSister Mercy docks on the small island between here and Sorlof's Strand to pick up more souls for the ship's crew 'bout once every five minutes. There be no shortage of souls 'round these parts...", objectives = "Speak with Captain Ellis aboard the Sister Mercy.", completion = "Arrr, me'n'me crew pilfered that thar shield! We be tryin' to get her back from that no good, landlubbin' scallywag, Sorlof! Ye come to help, arrr?\n\nWell, as ye can see we be runnin' a skeleton crew!\n\n<Captain Ellis laughs.>\n\nSister Mercy be needin' another powder monkey to man the big'uns o'er on the poop deck. Think ye be up to the job, me hearty?\n\nHelp me crew take Sorlof down and we'll split the booty! Ye can have the shield, me'n'me crew gets the rest!" }
WordHunterWoW_QuestEN[11520] = { title = "Discovering Your Roots", description = "Greetings, {race}.\n\nI'm afraid I have little to offer here until my reagents are stocked.\n\nOf the supplies I require, there is a special reagent, razorthorn root, that is particularly difficult to harvest.\n\nFortunately, I know a secret....\n\nUsing the glands of the Razorthorn flayers, one can control a ravager there and use it to expose a root.\n\nTo find the roots, travel to Outland and fly northeast from Shattrath until you reach Razorthorn Rise.", objectives = "Mar'nah at Sun's Reach Harbor wants you to travel to Razorthorn Rise in Outlands, collect 5 Razorthorn Roots, and return to her." }
WordHunterWoW_QuestEN[11521] = { title = "Rediscovering Your Roots", description = "My stocks are presently sufficient, but I'll need plenty of razorthorn roots to keep up with the demand.\n\nCollecting the roots is difficult, but I know a special method of extraction.\n\nUsing the glands of the Razorthorn flayers, one can control a ravager there and use it to expose a root.\n\nTo find the roots, travel to Outland and fly northeast from Shattrath until you reach Razorthorn Rise.\n\nReturn to me, {name}, once you have collected five of the roots.", objectives = "Mar'nah at Sun's Reach Harbor wants you to travel to Razorthorn Rise in Outlands, collect 5 Razorthorn Roots, and return to her.", progress = "Really, <name>, I'm far too busy for idle chatter.\n\nLet me know when you've gathered those roots.", completion = "Excellent work, <name>.\n\nThank you again for your help!" }
WordHunterWoW_QuestEN[11523] = { title = "Arm the Wards!", description = "We've succeeded in reactivating the crystal wards around the sanctum, but why stop there?  We'll build defenses around the other structures, but the Wretched are stubborn and continue to steal power from the crystal wards.\n\nHunt them down and get the mana remnants they carry.  Use the remnants to energize the sanctum wards; the safety of our operation depends on it.", objectives = "Captain Theris Dawnhearth at the Shattered Sun Staging Area wants you to obtain 4 Mana Remnants from Wretched Fiends and Wretched Devourers and use them to energize one of the Crystal Wards surrounding the structures in Sun's Reach.", progress = "Have you reactivated a crystal ward, <name>?", completion = "Good work, <name>.  The wards are slowly regaining their power.  Sun's Reach will be ours in no time!" }
WordHunterWoW_QuestEN[11524] = { title = "Erratic Behavior", description = "We lack the numbers to capture the Sanctum at Sun's Reach, but I've a plan that will tip the scales in our favor.\n\nThe loose energy from the Sunwell has caused the sentries that patrol this island to malfunction.  The crystal cores that control their behavior are damaged beyond repair.\n\nI've crafted new crystals that will bring them under our control; place them inside of the hulls of defeated sentries.  We will need all the help we can get.", objectives = "Vindicator Xayanna at the Shattered Sun Staging Area wants you to place the Attuned Crystal Cores inside 5 defeated Erratic Sentries to turn them into friendly units." }
WordHunterWoW_QuestEN[11525] = { title = "Further Conversions", description = "My plan to replace the damaged crystals on the erratic sentries has been a success.  We've managed to take the Sun's Reach Sanctum with their help.\n\nI've crafted new crystals that will bring more of them under our control; place them inside the hulls of defeated sentries.  We'll deploy them to other locations once they're converted.", objectives = "Vindicator Xayann at the Shattered Sun Staging Area wants you to place the Attuned Crystal Cores inside 5 defeated Erratic Sentries to turn them into friendly units.", progress = "Have you converted the sentries, <name>?", completion = "Excellent.  The converted sentries will help to secure our perimeter." }
WordHunterWoW_QuestEN[11526] = { title = "The Missing Magistrix", description = "We sent one of our operatives to investigate the fel portal in the middle of Dawning Square, south of here.  She never returned.\n\nTake this scroll we found on one of the enemy corpses.  We believe it will grant you access through the portal.  Once through, find Magistrix Seyla and aid her in any way you can.", objectives = "Use the Captured Legion Scroll near the portal at Dawning Square. Once you've gone through the portal, find Magistrix Seyla.", progress = "Keep quiet, <class>.  The Legion's forces watch the south of the gate.", completion = "It's very sweet of Theris to worry about my hide, but we've got bigger problems here.  Much bigger." }
WordHunterWoW_QuestEN[11527] = { title = "Mutiny on the Mercy", description = "Aye, we got problems, matey. Me gunners have mutinied! M'n'the crew up top be tryin' to kick Sorlof's keester while dealin' with the mutinous gunners down'blo.\n\nYe're gonna have to go down'blo and deal with those mutinous sea dogs and take their blastin' powder for the big'un o'er on the poop deck.\n\nWith ye mannin' the big'un, Sorlof is sure to die and give up the booty!", objectives = "Captain Ellis aboard the Sister Mercy in the Howling Fjord has asked that you recover 5 Barrels of Blasting Powder from the ship's hold.", progress = "Mutinous sea dogs and giants abound!", completion = "Here's to hopin' those treacherous bilge rats learned their lessons! Now it be time to man the big'un, matey!" }
WordHunterWoW_QuestEN[11528] = { title = "A Winter Veil Gift", description = "", objectives = "A small tag on this present reads:\n\nHappy holidays, <name>!" }
WordHunterWoW_QuestEN[11529] = { title = "Sorlof's Booty", description = "Me crew is gonna get the big'un all primed an'ready for ya, matey. She's restin' snuggly on the bow, o'er on the other side of the ship. Go'n man it and be ready to fire when Sorlof is in our sights!\n\nOnce we take that landlubber down, ye'll have to recover the booty for us, seein' as how we can't leave the damned ship! Bring that booty back to me and ye'll get your cut - the shield...", objectives = "Slay Sorlof using the Big Gun and recover Sorlof's Booty. Return Sorlof's Booty to Captain Ellis aboard the Sister Mercy.", progress = "Smartly, me hearty!", completion = "A deal's a deal, me hearty!" }
WordHunterWoW_QuestEN[11530] = { title = "The Shield of the Aesirites", description = "Here's yer shield. Me hopes it doesn't curse ye like it did me'n'me crew. Ye don't have to go home, but ye can't stay here... I be certain that thar be some that would be interested in getting' it back.\n\nNow get that thing off me ship!", objectives = "Return the Shield of the Aesirites to Orfus of Kamagua at the Ancient Lift in the Howling Fjord.", progress = "You have returned!", completion = "We must return all of the artifacts, <name>. When all four are gathered, you will put them back in their graves." }
WordHunterWoW_QuestEN[11531] = { title = "Strange Engine Part", description = "This strange engine part doesn't look like it fits in a steam pump, much less anything else you've seen.  Perhaps K. Lee Smallfry might know something about it.", objectives = "Take the Strange Engine Part to K. Lee Smallfry in Telredor.", progress = "Oh goodness!  What've you got there, <name>?", completion = "<K. Lee looks at the engine part and then stares off into the distance for a moment.>\n\nThis is somethin' real special.  Difficulty to say where it's from--like it just fell out of the sky.  I'm gonna hold on to this and pay you for your troubles.\n\nBetween you and me though, I think it's best if we didn't mention this to anyone.\n\n<K. Lee puts on her most charming smile.>" }
WordHunterWoW_QuestEN[11532] = { title = "Distraction at the Dead Scar", description = "The Legion will move against us as soon as their forces to the south are freed up.  The Scourge at the Dead Scar are keeping their forces occupied at the moment.  It won't last long, however.\n\nI want you to fly a dragonhawk over to the scar and put a dent in the demons' numbers with these arcane charges.\n\nIf all goes well, they won't even notice us taking the armory from Kael's lackeys.  Talk to Ayren, the dragonhawk master in the west part of the harbor, when you're ready to fly there.", objectives = "Battlemage Arynna wants you to speak to Ayren Cloudbreaker when you're ready to fly over the Dead Scar. Once there, use the Arcane Charges to kill 2 Pit Overlords, 3 Eredar Sorcerers and 12 Wrath Enforcers." }
WordHunterWoW_QuestEN[11533] = { title = "The Air Strikes Must Continue", description = "We've taken the armory from the enemy thanks to our aerial attacks against the Legion's forces in the Dead Scar.\n\nAs a matter of fact, it's gone so well that we're going to continue our air strikes against them.  Take these arcane charges and use them against their forces.\n\nTalk to Ayren Cloudbreaker at the Sun's Reach Harbor when you're ready for flight.", objectives = "Battlemage Arynna wants you to speak to Ayren Cloudbreaker when you're ready to fly over the Dead Scar. Once there, use the Arcane Charges to kill 2 Pit Overlords, 3 Eredar Sorcerers and 12 Wrath Enforcers.", completion = "Any demons we kill today are demons that we do not have to fight tomorrow.  Keep it up." }
WordHunterWoW_QuestEN[11534] = { title = "Report to Nasuun", description = "I am most glad that you are here, {class}! When we took this sanctum from the wretched, we hurried to create a magical portal that leads here from Shattrath City in the Outland.\n\nMy liege lord, Exarch Nasuun, is heading up the Offensive's efforts to maintain that portal. He asked me to send along any promising candidates who have what it takes to help with acquiring more energy to fuel it.\n\nPlease, travel to Shattrath City and speak with him inside A'dal's chamber on the Terrace of Light.", objectives = "Tradesman Portanuus has asked you to speak with Exarch Nasuun on the Terrace of Light in Shattrath City.", completion = "Portanuus sent you? Good, we haven't any time to spare!" }
WordHunterWoW_QuestEN[11535] = { title = "Making Ready", description = "Supplies are inbound, or so I'm told.\n\nRegardless, we can ill afford to wait around hoping that help arrives before our offensive stalls. We must make the best of what we have.\n\nAs for me, I need ore to fashion an anvil so I can begin to upgrade our armor and weapons.\n\nThere are a group of naga on the coast to the east of here collecting ore and placing it in chests for shipment to the Legion.\n\nRelieving them of their ore will help our efforts in more ways than one....", objectives = "Smith Hauthaa in Sun's Reach Armory wants you to kill Darkspine Myrmidon to the east and use their keys to steal three pieces of the ore from their chests." }
WordHunterWoW_QuestEN[11536] = { title = "Don't Stop Now....", description = "Now that we have an anvil, I can really get to work.\n\nNo matter how many supplies we receive, I'll always be able to put the Darkspine Iron Ore to good use. We'll need a constant supply of weapons and armor if we're to be successful here.\n\nThere are a group of naga on the coast to the east of here. They're collecting ore and placing it in chests for shipment to the Legion. Relieving them of their ore will help our efforts in more ways than one....", objectives = "Smith Hauthaa in Sun's Reach Armory wants you to kill Darkspine Myrmidon to the east and use their keys to steal three pieces of the ore from their chests.", progress = "Have you gathered the ore I asked for?", completion = "Excellent! This will help me keep our soldiers in weapons and armor.\n\nYour help is truly making a difference!" }
WordHunterWoW_QuestEN[11537] = { title = "The Battle Must Go On", description = "We must continue to defeat and demoralize the armies of the Legion.\n\nThe emissaries of hate are Legion shocktroopers deployed to reinforce tactical Legion positions.  The enemy rallies around them for they fear them more than they fear us.\n\nToday we will change that.  Take this banner and slay the demons of the Legion.  When you meet the emissary, slay and impale him.", objectives = "Harbinger Inuuro wants you to slay 6 Burning Legion Demons and the Emissary of Hate in Dawning Square. Use the Shattered Sun Banner to impale the Emissary of Hate's corpse.", progress = "Have you succeeded, <name>?", completion = "Your dedication is exemplary, <name>.  We will show the forces of the Burning Legion what we're capable of." }
WordHunterWoW_QuestEN[11538] = { title = "The Battle for the Sun's Reach Armory", description = "The Burning Legion holds the Sun's Reach Armory, which is of tactical importance to our operation.  As long as their morale remains high we will not wrest the building from their control.\n\nThe emissaries of hate are Legion shocktroopers deployed to reinforce tactical Legion positions.  The enemy rallies around them for they fear them more than they fear us.\n\nToday we will change that.  Take this banner and slay the demons of the Legion.  When you meet the emissary, slay and impale him.", objectives = "Harbinger Inuuro wants you to slay 6 Burning Legion Demons and the Emissary of Hate in Dawning Square or the Sun's Reach Armory. Use the Shattered Sun Banner to impale the Emissary of Hate's corpse." }
WordHunterWoW_QuestEN[11539] = { title = "Taking the Harbor", description = "One of Kael's most elite forces, the Dawnblade army, has been stationed at the Sun's Reach Harbor and Dawnstar Village.\n\nThe harbor is of critical importance to our plans, so any Dawnblade casualties you inflict will be of tremendous help.  Kael'thas will rue the day that he turned his back on his people and sided with the Burning Legion.", objectives = "Magister Ilastar at Sun's Reach Armory wants you to slay 6 Dawnblade Summoners, 6 Dawnblade Blood Knights and 3 Dawnblade Marksmen." }
WordHunterWoW_QuestEN[11540] = { title = "Crush the Dawnblade", description = "We've driven the Dawnblade army out of the Sun's Reach Harbor.  Sun's Reach is ours in its entirety.  Yet somehow... I'm not entirely satisfied.\n\nI want you to go to Dawnstar Village, west of here, and slay any surviving Dawnblade combatants.  They sealed their fate when they followed Kael to this place.", objectives = "Magister Ilastar at Sun's Reach Armory wants you to slay 6 Dawnblade Summoners, 6 Dawnblade Blood Knights and 3 Dawnblade Marksmen.", completion = "What thoughts go through Prince Kael'thas Sunstrider's head when he hears of his armies' defeats?\n\nDoes he feel despair?  Helplessness?  Fear?\n\nI sure hope so." }
WordHunterWoW_QuestEN[11541] = { title = "Disrupt the Greengill Coast", description = "The naga have taken the Greengill Coast to the southeast. Their females, the Darkspine sirens, are using magic to enslave the indigenous murlocs.\n\nIt's my responsibility to see to it that whatever the naga are up to over there is disrupted. That's where you come in.\n\n{class}, I want you to get the controlling orbs from the female naga and throw them near the Greengill slaves, breaking the orb and setting the murlocs free.\n\nMy guess is that the murlocs will be incensed and turn on their masters.", objectives = "Captain Valindria wants you to free 10 Greengill Slaves. Return to her onboard the Silvermoon's Pride at Sun's Reach Harbor once you have done so.", completion = "That's enough for today. Slow and steady is the key here. Too much disruption and they'd turn their attention directly upon us; something that we don't want.\n\nCome back again tomorrow and we'll work on it some more." }
WordHunterWoW_QuestEN[11542] = { title = "Intercept the Reinforcements", description = "We're making a push to solidify our control of Sun's Reach by capturing the harbor next.  Unfortunately a fleet of Dawnblade reservists is on its way to reinforce Kael's forces there.\n\nTake this oil and secure a dragonhawk from Ayren Cloudbreaker.    You should be able to fly within reach of the ships' sails; once you're close enough, set them on fire.\n\nLand in one of the ships and attack the reservists.  With their ship sails on fire they won't be able to mount much of a defense.", objectives = "Vindicator Kaalan at the Sun's Reach Armory wants you to speak to Ayren Cloudbreaker and fly over the Dawnblade reinforcement fleet. Use the Flaming Oil to set the ship sails on fire as you fly and once you land, slay 6 Dawnblade Reservists." }
WordHunterWoW_QuestEN[11543] = { title = "Keeping the Enemy at Bay", description = "We've managed to capture Sun's Reach in its entirety.  Unfortunately a fleet of Dawnblade reservists is on its way to take back the harbor.\n\nTake this oil and secure a dragonhawk from Ayren Cloudbreaker.  You should be able to fly within reach of the ships' sails; once you're close enough, set them on fire.\n\nLand in one of the ships and attack the reservists.  With their ship sails on fire they won't be able to mount much of a defense.", objectives = "Vindicator Kaalan at the Sun's Reach Armory wants you to speak to Ayren Cloudbreaker and fly over the Dawnblade reinforcement fleet. Use the Flaming Oil to set the ship sails on fire as you fly and once you land, slay 6 Dawnblade Reservists.", completion = "Well done, <name>.  It should be a long time before the harbor receives any reinforcements." }
WordHunterWoW_QuestEN[11544] = { title = "Ata'mal Armaments", description = "The Ata'mal Terrace in eastern Shadowmoon Valley is holy to the draenei, but is now overrun by fel orcs. They have dug up the special ore from that place and created corrupted weapons and armor.\n\nI need the armaments to form an alloy with the naga ore. Our anchorites have blessed my anvil with the ability to cleanse them.\n\nRetrieve the armaments from the Shadowmoon chosen, slayers and darkweavers. Return them here, breaking down and purifying them upon my anvil, and then hand me the cleansed results.", objectives = "Smith Hauthaa needs you to produce 5 Cleansed Ata'mal Metal. Do so by breaking down Ata'mal Armaments on her anvil at the Sun's Reach Armory on the Isle of Quel'Danas.", progress = "I need all of the cleansed Ata'mal metal that I can get my hands on, <class>.", completion = "Thank you, my friend. Now I will be able to fashion more of the special alloy that is going into the creation of our forces' weapons and armor.\n\nAnd, I have some leftover extract from the process, which you'll likely find handy for use on your weapons. Please, take your pick of whichever will serve your purposes.\n\nReturn to me again on the morrow. No doubt I will need more armaments." }
WordHunterWoW_QuestEN[11545] = { title = "A Charitable Donation", description = "We've taken Sun's Reach from the enemy and our final victory is at hand.  The cost was high and many brave combatants gave their lives so we could achieve this.\n\nIt is my goal to ensure that those who perished in combat are not forgotten.  I ask that you take a moment to consider making a donation towards a memorial fund.  Any leftover gold will go to the widows and orphans of the fallen.", objectives = "Anchorite Ayuri at Sun's Reach in Sunwell Isle wants you to donate 10 gold." }
WordHunterWoW_QuestEN[11546] = { title = "Open for Business", description = "Welcome, {name}.\n\nThere are a number of ways I can assist you in your efforts here.\n\nFor example, I've recently discovered a recipe for a unique elixir.\n\nThe bloodberry grows wild in many regions of Azeroth and has long been considered nothing more than a nuisance. I've learned though, that when exposed to the Sunwell's power this plant takes on special properties that can be distilled and imbibed to magnify one's abilites.\n\nBring me a sample from the nearby bushes and I'll show you what I mean.", objectives = "Mar'nah at the Sun's Reach Harbor wants you to gather 5 Bloodberries from the bushes found on Quel'Danas.", progress = "Have you gathered those berries yet?", completion = "Excellent, <name>.\n\nI hope this will aid you in your efforts here." }
WordHunterWoW_QuestEN[11547] = { title = "Know Your Ley Lines", description = "Freeloaders!\n\nYou all want instant gratification - never giving thought to the effort required to create even the simplest of portals.\n\nPerhaps a little education will instill a bit of gratitude for my ceaseless efforts.\n\nTake this crystal. Attune it to the Bloodcrystal to the west, at the Dawning Square portal just south of here, and at the naga shrine at Greengill Coast to the southeast.\n\nPerhaps then you'll appreciate your precious translocations....", objectives = "Astromancer Darnarian in the Sun's Reach Sanctum wants you to use the Astromancer's Crystal at the Bloodcrystal, the Dawning Square portal, and the naga shrine at Greengill Coast.", progress = "Have you attuned the crystal yet, <class>?", completion = "Yes, yes. Let's have a look now, shall we?\n\nThings seem to be in order. Very well. Here is your translocator.\n\nIf any of your readings are faulty, there's no telling where you'll end up, and mind you, you'll only have yourself to blame." }
WordHunterWoW_QuestEN[11548] = { title = "Your Continued Support", description = "We've built a memorial to honor those slain in battle.  It's but a small consolation to the families that lost their loved ones.\n\nI am taking up a collection to aid the orphans and spouses of our war heroes.  If you can spare a small donation it would go a long way.", objectives = "Anchorite Ayuri at Sun's Reach in Sunwell Isle wants you to donate 10 gold.", progress = "Do you wish to make a donation?", completion = "You are a virtuous soul, <name>.  It is easy to forget the fallen amidst the turmoil of war and the euphoria of victory.  The friends and families of the dead thank you." }
WordHunterWoW_QuestEN[11549] = { title = "A Magnanimous Benefactor", description = "You've done so much for us, {name}.  We greatly appreciate your assistance.\n\nYou might have noticed Anchorite Ayuri's efforts outside.  She has a big heart and is very convincing, but the donations do not quite add up to what she had expected.\n\nIf you were to make a large contribution to her cause, I will make sure that word of your deeds in this war spreads far and wide.  What do you say?", objectives = "Anchorite Kairthos wants you to donate 1000 gold to aid in Anchorite Ayuri's efforts. You will be known as <name> of the Shattered Sun if you complete this quest.", progress = "Are you ready to make the contribution?", completion = "You truly are a generous person and a worthy ally.  From now on you shall be known as <name> of the Shattered Sun and all who fought here will know of your deeds!" }
WordHunterWoW_QuestEN[11550] = { title = "Enter, the Deceiver...", description = "Despite our best efforts, Kael'thas's sinister plans have been carried out. The Sunwell has been re-ignited in preparation for the Deceiver's arrival.\n\nThe object that stands before me and below A'dal is a representation of the current status of the Sunwell's defenses. Mighty barriers have been raised, stymieing our attacks against the inner chambers. If ever there were a time that our world needed assistance, it would be now.\n\nReport to Archmage Ne'thul at the Isle of Quel'Danas, north of Quel'Thalas.", objectives = "Report to Archmage Ne'thul on the Isle of Quel'Danas, north of Quel'Thalas.\n\nFlight masters in Ironforge and Silvermoon City will get you to your destination.", completion = "Kil'jaeden bears down upon this world with the full force of the Burning Legion. Should the summoning complete, our world will once more be flung into the throes of chaos. Your assistance on the Isle of Quel'Danas is critical to our success against the Burning Legion.\n\nOur mages are working on bringing down the barriers blocking access to the Sunwell. Do your part in battling the forces of the Legion by helping the Shattered Sun Offensive." }
WordHunterWoW_QuestEN[11551] = { title = "Agamath, the First Gate", description = "", objectives = "" }
WordHunterWoW_QuestEN[11552] = { title = "Rohendor, the Second Gate", description = "", objectives = "" }
WordHunterWoW_QuestEN[11553] = { title = "Archonisus, the Final Gate", description = "", objectives = "" }
WordHunterWoW_QuestEN[11554] = { title = "A Friend in the Frontlines", description = "", objectives = "Your aid in the offensive has not gone unnoticed, <name>.  The combined forces of the Aldor and Scryers offer you their thanks." }
WordHunterWoW_QuestEN[11555] = { title = "Honored by Your Allies", description = "", objectives = "You continue to prove yourself in this most important battle, <name>.  Please accept this as a token of our continued gratitude." }
WordHunterWoW_QuestEN[11556] = { title = "Revered in the Field of Battle", description = "", objectives = "We couldn't have gotten where we are without you, <name>.  The combined might of the Aldor and Scryers is not enough to crush the Legion and Kael.  We are thankful to have allies of your caliber among us." }
WordHunterWoW_QuestEN[11557] = { title = "Exalted Among All Combatants", description = "", objectives = "You are one of our very best, <name>.  Your name will be known throughout our ranks for a long time to come.\n\nPlease accept this small gift on the behalf of our forces." }
WordHunterWoW_QuestEN[11558] = { title = "Dangerous Love", description = "There's something unnatural about this epidemic of love. It's disgusting, and as it lowers our defenses, it could be a threat to the all of us.\n\nIt's bad enough that so many of our people are caught up in this ridiculous behavior. But I think that it has spread even to our guardians, who should be immune to such things.\n\nFind one of our guardians and see if they've been caught up in this foolishness.", objectives = "Get a Guardian's Moldy Card and bring it to Fenstad Argyle in the Undercity." }
WordHunterWoW_QuestEN[11559] = { title = "Winterfin Commerce", description = "Now that you can speak with the Winterfin, it is time for you to let them get to know you. One of the best ways to do that is to conduct business with them.\n\nThe murlocs prize clams over any other object and their only surviving merchant is Ahlurglgr. If I were you, I'd collect a handful of Winterfin clams and give them to him as a gift.\n\nThe clams can be found all over down in the trench, as well as across it in the Winterfin village and their caverns.", objectives = "Collect 5 Winterfin Clams and deliver them to Ahlurglgr at Winterfin Retreat.", progress = "What's this? Who are you?\n\nYou're one of those <race> things! How can you speak our tongue?", completion = "These are for me? Is this some sort of <race> trick? No?\n\nWell then, thank you! Come back any time that you have more clams, and we'll do business!" }
WordHunterWoW_QuestEN[11560] = { title = "Oh Noes, the Tadpoles!", description = "Oh good, you're back!\n\nWhen the landslide at the village across the water exposed the caverns, a malevolent lobstrok, known as Claximus, came out of the caves and stole the Winterfin tadpoles away.\n\nSomething happened to all of the murlocs that followed him in there, and when they re-emerged, they were under his control.\n\n{class}, you must swim across the waters and rescue the Winterfin tadpoles in the village and caverns.\n\nThe future of the Winterfin tribe depends upon you!", objectives = "King Mrgl-Mrgl has asked you to rescue 20 Winterfin Tadpoles. Return to him at Winterfin Retreat once you have done so.", completion = "Now no matter what happens, the Winterfin murlocs have a secure future.\n\nYou are to be commended, and rewarded, for your selflessness, <name>!" }
WordHunterWoW_QuestEN[11561] = { title = "Them!", description = "Our brothers and sisters across the water are now our mortal enemies. They have kidnapped our tadpoles, driven us out of our village, and killed more of us than I can count.\n\nProve yourself, {race}! Swim across the rift and slay them!\n\nDespite the favor that the new king has shown you, only then will we consider accepting you here. Fail to do so, and you might as well leave now and never return!", objectives = "Brglmurgl at Winterfin Retreat has asked you to kill 15 Winterfin murlocs. Any combination of warriors, oracles, and shorestrikers will do.", progress = "If you have killed so many of the Winterfin betrayers, why is it that when I look out across the water, I still see too many of them?", completion = "I am pleased. I can smell the coppery tang of their blood on your hands.\n\nThis is a good start for you, <race>." }
WordHunterWoW_QuestEN[11562] = { title = "I'm Being Blackmailed By My Cleaner", description = "I have something embarrassing to admit: I'm being blackmailed!\n\nMrmrglmr agreed to clean some of my things, and got hold of my spare murloc costume. He's threatening to reveal my true nature to the other murlocs.\n\nI need not explain to you what a disaster that would be! Besides, I have a plan that's going to require that we get that costume back.\n\nPlease, {name}, go to Mrmrglmr at the other end of the Retreat to the north and do whatever he asks of you.", objectives = "King Mrgl-Mrgl has asked you to speak with Mrmrglmr at the northwest end of Winterfin Retreat.", completion = "Aw, so you must be the so-called King Mrgl-Mrgl's lackey. I suppose that night elf has sent you to appease me?\n\nGood, I have just the thing that needs doing for someone as powerful as you!" }
WordHunterWoW_QuestEN[11563] = { title = "Grmmurggll Mrllggrl Glrggl!!!", description = "If your pathetic little eyes were any good, you'd see that we're being slaughtered by the orcas to the north in the bay!\n\nAssuming your precious night elf king wants his spare costume back, I think you'll do me a favor and bring back the head of the king of the orcas, Glrggl: he who swims against the tides of fate -- eradicating the hope of life for all those who hear the siren song of death upon the waves!\n\nBe quick about it, {race}, Winterfin murlocs are losing their lives even as we waste time talking!", objectives = "Mrmrglmr wants you to return to him at Winterfin Retreat with Glrggl's Head.", progress = "If you don't have Glrggl's head, don't waste my time!", completion = "Not bad. This will make a nice feast!\n\nWith the king of the orcas dead the attacks upon us should diminish while the whales fight amongst themselves for dominance." }
WordHunterWoW_QuestEN[11564] = { title = "Succulent Orca Stew", description = "Word is, strange {race}, that you might be going after the king of the orcas, Glrggl.\n\nThat's all fine and good, but if you want to taste the stew that makes life worth living, then you'll bring me back the succulent blubber of the orcas that swim in Glimmer Bay.\n\nHurry... I have quite a bit of cutting to do on this carcass if you want to reap the benefits of your efforts.", objectives = "Cleaver Bmurglbrm has tasked you with acquiring 7 Succulent Orca Blubber. Return with them to him at Winterfin Retreat.", progress = "Do you have all of the orca blubber that I require?", completion = "Ah yes, these will do nicely.\n\nJust plop them down anywhere. You can have some of my leftover stew from last night." }
WordHunterWoW_QuestEN[11565] = { title = "The Spare Suit", description = "Very well, your king's secret is safe with me as long as he continues to help us against our enemies.\n\nHere, take this to him. I cleaned it up nicely, though I have no idea why he needs a second disguise.\n\nMaybe he has something in mind for you?", objectives = "Return King Mrgl-Mrgl's Spare Suit to him at Winterfin Retreat.", progress = "Do you have my spare suit, <name>?", completion = "<Upon seeing the spare murloc suit, the king rubs his costumed appendages together.>\n\nNicely done. Now, back to the pressing matter at hand. I've got something of great importance for you to do." }
WordHunterWoW_QuestEN[11566] = { title = "Surrender... Not!", description = "The time has come to put an end to this unnatural situation, {name}. For the Winterfin murlocs to have a chance at a future, Claximus must die!\n\nI want you to take my spare murloc suit and enter the Winterfin Caverns under the pretext of surrender. With the white flag in hand, the murlocs won't attack you.\n\nYou'll find him in the southwestern most corner of the caverns. Once you get close enough, deal with Claximus. Bring me one of his claws as proof that the grisly deed has been done.", objectives = "King Mrgl-Mrgl at Winterfin Retreat has asked you to bring him a Claw of Claximus.", progress = "Have you done it, <class>? Is Claximus dead?", completion = "Regrettable, but necessary. I'll take the claw, <name>.\n\nThank you for all of the help you've given us. With Claximus defeated, maybe we'll be able to reunite the remaining murlocs and seal off those caverns.\n\nPlease, my friend, take this... it's the least I can do for all of the help you have rendered us!" }
WordHunterWoW_QuestEN[11567] = { title = "The Ancient Armor of the Kvaldir", description = "I was on the vessel that was bringing in the armor. We'd just boarded the ship and were headin' back here when we were attacked by a Forsaken destroyer.\n\nThey boarded our ship, took all the booty for themselves, and then sunk her.\n\nThat was the last I'd seen of that armor. If you want, you can take my bomber from Scalawag to the dreaded isle that the destroyer be docked. Talk to my woman, Alanya, outside. She'll get you on the bomber.\n\nIf you manage to find the stuff, don't you dare bring it back!", objectives = "Recover the Ancient Armor of the Kvaldir and deliver it to Orfus of Kamagua in the Howling Fjord.", progress = "Have you found the armor?", completion = "We must return all of the artifacts, <name>. When all four are gathered, you will put them back in their graves." }
WordHunterWoW_QuestEN[11568] = { title = "A Return to Resting", description = "<Orfus hands you a satchel.>\n\nWithin this satchel are the artifacts that you recovered. Locate the burial mounds of Shield Hill, far to the southeast, where the items were originally stolen from and return the artifacts. It is my hope that this gesture will quell the spirits that now haunt our hunting grounds.\n\nBe strong, {name}...", objectives = "Use the Bundle of Vrykul Artifacts at the ransacked burial mounds of Shield Hill to return the Frozen Heart of Isuldof, the Shield of the Aesirites, the Staff of Storm's Fury and the Ancient Armor of the Kvaldir.\n\nReturn to Orfus of Kamagua at the Ancient Lift should you succeed.", completion = "Grim tidings, <name>. My people are in danger and must be warned. These sea faring aberrations will take no mercy upon the Kalu'ak." }
WordHunterWoW_QuestEN[11569] = { title = "Keymaster Urmgrgl", description = "I have to get out of these caverns! There's magic stuff seeping in from Coldarra, above, and affecting everyone's minds.\n\nI don't intend to be controlled like these others!\n\nKeymaster Urmgrgl is in the cave below and to the south. He holds the key to my cage. Get it from him and bring it back so that I can unlock my cage and get out of here.\n\nHurry!", objectives = "Glrglrglr inside the Winterfin Caverns has asked you to retrieve Urmgrgl's Key.", progress = "Do you have the key?\n\nNo, I don't care about any of these others. I just want to get out of here!", completion = "Quickly, hand it here!" }
WordHunterWoW_QuestEN[11570] = { title = "Escape from the Winterfin Caverns", description = "The lock on my cage doesn't look too solid, but I'm not foolish enough to try to leave without assistance.\n\nWill you help me safely get out of these caverns? There's no time to waste, {race}.\n\nWhen you get back to the retreat, please let the king know that I'm okay. He's sure to give you a reward.", objectives = "Escort Lurgglbr to safety and then report to King Mrgl-Mrgl at Winterfin Retreat with the good news.", completion = "This is wonderful news! And you say that Lurgglbr discovered that the emanations from the caverns are what caused this insanity?\n\nIt must be that the magic from Coldarra is growing stronger. The Nexus War... the battle between the blue dragonflight and all of the other dragons, is spilling over.\n\nSoon, we will all be embroiled in it!" }
WordHunterWoW_QuestEN[11571] = { title = "Learning to Communicate", description = "To help, you must learn how to speak the Winterfin dialect. We'll work with the forces of nature and magic to do that.\n\nTake this empty conch shell. At the bottom of the watery trench below exists Scalder, an elemental of air and watery fury.\n\nOnce she is defeated, use the conch upon her remains to capture her magical steam. Return the full conch to me, and I'll imbue my knowledge of the Winterfin tongue into you.\n\nLuckily, a friend taught me a water breathing spell, which I will cast upon you.", objectives = "King Mrgl-Mrgl has given you a conch to use upon Scalder's remains. Return The King's Filled Conch to him at Winterfin Retreat.", progress = "Have you managed to fill the conch with Scalder's steam?", completion = "Now I will be able to use Scalder's essence to impart my understanding of the Winterfin murloc tongue to you." }
WordHunterWoW_QuestEN[11572] = { title = "Return to Atuik", description = "Return to Elder Atuik at Kamagua. He and the rest of my people must be warned of this impending doom that approaches from the sea.\n\n<Orfus shivers.>\n\nUse the Ancient Lift to reach him. Please hurry!", objectives = "Deliver the bad news to Elder Atuik at Kamagua.", completion = "The Kalu'ak thank you for all that you have done, <name>. We must now prepare for battle and warn our brothers and sisters across the sea of what is to come.\n\nI hope it is not too late..." }
WordHunterWoW_QuestEN[11573] = { title = "Orfus of Kamagua", description = "Hail, traveler. I am Lunk-tusk of the Kalu'ak. We are known as tuskarr to your people. My partner and I were recently sent up to investigate strange happenings along one of our hunting trails. It was when we approached the graveyard known as Shield Hill that we were attacked by the undead. I was lucky to make it to this camp, but I am uncertain as to what became of Orfus.\n\nWe parted ways at the Ancient Lift, southeast of here along the cliff edge. Will you go see if he is ok?", objectives = "Find Orfus of Kamagua at the Ancient Lift in Howling Fjord.", completion = "Lunk-tusk lives? At least there is some good news to be had on this day..." }
WordHunterWoW_QuestEN[11574] = { title = "Too Close For Comfort", description = "I told them all that I remember. Why don't they believe me?\n\nI was gathering herbs by the rift. They came from nowhere, dark wizards with magical beasts - I was surrounded!\n\nA magical box appeared above me, opened up and pulled me inside. Just as it began to close around me, my rescuers swooped in on the backs of red drakes. It was breathtaking!\n\nI never thanked them for saving me. Please, {class}, find them, and pass on my gratitude.", objectives = "Endorah wants you to go to Amber Ledge north of Warsong Hold and thank those there for rescuing her.", completion = "You can tell your friend that her rescue was our pleasure, as well as our duty.\n\nHer encounter was but a small piece in what I believe to be a large puzzle.\n\nDalaran is sparing no effort in solving this mystery and to be honest, we could use a bit of assistance...." }
WordHunterWoW_QuestEN[11575] = { title = "Nick of Time", description = "I told them all that I remember. Why don't they believe me?\n\nI was gathering herbs by the rift. They came from nowhere, dark wizards with magical beasts. I was surrounded!\n\nA huge magical cube appeared above me. It opened up and pulled me inside. I swear it's true!\n\nJust as it began to close around me, my rescuers swooped in on the backs of drakes - It was amazing! My captors scattered and I was able to escape.\n\nI never thanked them for saving me. Please, {class}, if you see them, pass on my gratitude.", objectives = "Midge in Valiance Keep wants you to go to Amber Ledge to the north and thank those there for rescuing her.", completion = "You can tell your friend that her rescue was our pleasure, as well as our duty.\n\nHer encounter was but a small piece in what I believe to be a large puzzle.\n\nDalaran is sparing no effort in solving this mystery and to be honest, we could use a bit of assistance...." }
WordHunterWoW_QuestEN[11576] = { title = "Monitoring the Rift: Cleftcliff Anomaly", description = "Greetings, {race}. I am Garren of Dalaran.\n\nNot long ago, the rift was a peaceful place - geothermally speaking at least.\n\nRecently though, earthquakes have occurred with alarming frequency and scars in the earth have appeared, exposing unique energy fields of chaotic power.\n\nMy mission here is to chart and monitor these anomalies. My instruments indicate that another has appeared on the cliff face to the southwest.\n\nTake this device with you and use it when you locate the new disruption.", objectives = "Garren on Amber Ledge wants you to use the Arcanometer at the Cleftcliff Anomaly.", progress = "Have you taken the readings I requested, <class>?", completion = "Fascinating! This is the largest disruption yet.\n\nThough the worst is yet to come, I fear." }
WordHunterWoW_QuestEN[11577] = { title = "WoW Collector's Edition: - DEM - E - FLAG", description = "", objectives = "" }
WordHunterWoW_QuestEN[11578] = { title = "The \"Chow\" Quest (123)aa COPY", description = "$Tpunk;!  Kill Kobold Vermin, 2 of em.You will receive:", objectives = "Kill Kobold Vermin, 2 of em." }
WordHunterWoW_QuestEN[11579] = { title = "The \"Chow\" Quest (123)aa COPY", description = "$Tpunk;!  Kill Kobold Vermin, 2 of em.You will receive:", objectives = "Kill Kobold Vermin, 2 of em." }
WordHunterWoW_QuestEN[11580] = { title = "Desecrate this Fire!", description = "", objectives = "Desecrate the Horde's Silverpine bonfire!" }
WordHunterWoW_QuestEN[11581] = { title = "Desecrate this Fire!", description = "", objectives = "Desecrate the Alliance's Westfall bonfire!", progress = "Desecrate the Alliance's Westfall bonfire!", completion = "Desecrate the Alliance's Westfall bonfire!" }
WordHunterWoW_QuestEN[11582] = { title = "Monitoring the Rift: Sundered Chasm", description = "Did you feel that?! That was just an aftershock... you should've been here a few minutes ago!\n\nI'm afraid I must call upon your services again. My instruments indicate that there is an immense disruption just west of here, far beneath the water's surface.\n\nJust as before, I need you to take the arcanometer and capture the anomaly's data.\n\nI'll cast a spell that will enable you to breathe underwater. If it wears off before you find it, come let me know and I'll renew its effects.", objectives = "Garren at Amber Ledge wants you to use the Arcanometer at the Sundered Chasm anomaly and return to him with the readings.", completion = "It was how big?\n\nThat's impossible! I need to report to Dalaran at once!" }
WordHunterWoW_QuestEN[11583] = { title = "Honor the Flame", description = "", objectives = "Honor the Westfall flame." }
WordHunterWoW_QuestEN[11584] = { title = "Honor the Flame", description = "", objectives = "Honor the Silverpine Forest flame." }
WordHunterWoW_QuestEN[11585] = { title = "Hellscream's Vigil", description = "Throm-Ka, {race}! Welcome to Warsong Hold. My heart swells with pride to see that such a distinguished hero of the Horde has answered the call of duty!\n\nThis impregnable fortress is a testament to the tenacity of the Horde. Through much we have battled to establish this foothold in Northrend. It is from here that our journey to Icecrown begins and it is through the leadership of the son of Hellscream that we will succeed!\n\nGarrosh awaits your arrival below.\n\nLok'tar ogar!", objectives = "Speak with Garrosh Hellscream in Warsong Hold.", completion = "A hero of the Horde, eh?\n\n<Garrosh sniffs at the air around you.>\n\nFear...\n\n<Garrosh spits.>\n\nYou won't last long." }
WordHunterWoW_QuestEN[11586] = { title = "Hellscream's Vigil", description = "Throm-Ka, {race}! Welcome to Warsong Hold. My heart swells with pride to see that such a distinguished hero of the Horde has answered the call of duty!\n\nThis impregnable fortress is a testament to the tenacity of the Horde. Through much we have battled to establish this foothold in Northrend. It is from here that our journey to Icecrown begins and it is through the leadership of the son of Hellscream that we will succeed!\n\nGarrosh awaits your arrival below.\n\nLok'tar ogar!", objectives = "Speak with Garrosh Hellscream in Warsong Hold.", completion = "Do not think that I have forgotten what you did for my people in Nagrand, <name>. Hellscream never forgets.\n\nFor that I am indebted to you and it is why I give you this chance now: run. Leave this place and never look back.\n\nReturn to your home and say a prayer for the dying." }
WordHunterWoW_QuestEN[11587] = { title = "Prison Break", description = "Greetings, {class}. I am Donathan, a loyal representative of Dalaran.\n\nForgive my abruptness, but we find ourselves in the midst of a crisis. Mages all across Azeroth are being abducted and I have been authorized to conscript anyone able to assist in the unraveling of this mystery.\n\nThe camp just south of ours is where our investigation begins. I call upon you to rescue one of the imprisoned mages held there. You must obtain a key from one of the mage hunters and use it to open an arcane prison.", objectives = "Librarian Donathan on Amber Ledge wants you to collect the Beryl Prison Key from one of the Beryl Mage Hunters at Beryl Point and use it to release a trapped mage from an arcane prison.", progress = "I trust you are working diligently to rescue an imprisoned mage....", completion = "You have done well, <name>.\n\nThe Kirin Tor graciously accept the assistance you have rendered. Know that any service you provide us will not go unrewarded.\n\nPlease, accept this humble offering as a token of Dalaran's appreciation." }
WordHunterWoW_QuestEN[11588] = { title = "REUSE", description = "Stop Ahune from coming to Azeroth and inciting an elemental war!", objectives = "Destroy the elemental Ahune within Blackfathom Deeps.Stop Ahune from coming to Azeroth and inciting an elemental war!" }
WordHunterWoW_QuestEN[11589] = { title = "REUSE", description = "Stop Ahune from coming to Azeroth and inciting an elemental war!", objectives = "Destroy the elemental Ahune within Blackfathom Deeps.Stop Ahune from coming to Azeroth and inciting an elemental war!" }
WordHunterWoW_QuestEN[11590] = { title = "Abduction", description = "{name}, we have a situation.\n\nI've just learned that one of our archmages en route from Dalaran has gone missing. Naturally, we suspect the mage hunters are behind her disappearance.\n\nTime is clearly of the essence. We must know what has become of Lady Evanor at once if we are to have any hope of rescuing her.\n\nTake this device. Return to Beryl Point and use it on a Beryl sorcerer when he is near death. It should bind him long enough for you to bring him here for questioning.", objectives = "Donathan wants you to use the Arcane Binder on a wounded Beryl Sorcerer at Beryl Point and return to Amber Ledge with him.", completion = "Excellent work, <name>.\n\nWe'll have him prepared for his interrogation at once." }
WordHunterWoW_QuestEN[11591] = { title = "Report to Steeljaw's Caravan", description = "That dimwitted cur, Steeljaw, tried to take our caravan of supplies on a shortcut through a taunka graveyard!\n\nWe just struck up relations with them!\n\nNow the caravan lies in ruins, overrun by the taunka spirits that rose out of their graves as he was trampling them.\n\nHead south and see if you can salvage the situation, {class}. I sent Grunt Ragefist and a few others down there with him to help out.\n\nWhy don't you see if you can lend a hand.", objectives = "Speak with Grunt Ragefist at Steeljaw's Caravan.", completion = "This isn't good, <class>.\n\nLongrunner Proudhoof says that these are the burial grounds of his honored ancestors." }
WordHunterWoW_QuestEN[11592] = { title = "We Strike!", description = "One of your orcs named Steeljaw tried to save some time by taking a shortcut through our burial grounds. This had better not be how your Horde normally acts, {race}, or you will find the taunka to be the end of you!\n\nBut, you look as if you want to help fix this situation. Good!\n\nSteeljaw's cursed spirit now haunts this place and disturbs the remains of my ancestors. We must put an end to him!\n\nIf we live through this, tell your Overlord Bor'gorok at the outpost to the north.\n\nAre you with me?", objectives = "Help Longrunner Proudhoof and his Warsong raiders to survive the assault upon Steeljaw's Caravan and finish off the spirit of Force-Commander Steeljaw.\n\nIf successful, report to Overlord Bor'gorok at Bor'gorok Outpost.", completion = "Blood and thunder! You've salvaged our newborn relations with the taunka.\n\nThank you for putting the situation to rights. Aka'Magosh, <name>!" }
WordHunterWoW_QuestEN[11593] = { title = "The Honored Dead", description = "Our fallen deserve a hero's funeral, but we cannot bury them here on sacred taunka ground.\n\nI'll not ask you to drag their bodies back here, but take this and head further into the cemetary.  When you come across our dead caravan guards and workers, put them to the torch.\n\nHonor our dead, {class}!", objectives = "Grunt Ragefist at Steeljaw's Caravan has asked you to use Ragefist's Torch to burn any combination of 10 Dead Carvan Guards and Workers.", completion = "Thank you, <class>. We are the Horde, we do not leave our dead behind!\n\nIt should never have been necessary in the first place. Steeljaw was a fool!" }
WordHunterWoW_QuestEN[11594] = { title = "Put Them to Rest", description = "Force-Commander Steeljaw's idiocy caused this mess. What was he thinking taking a caravan through a taunka burial mound?\n\nStill, what's done is done. Now it is up to us to deal with the consequences.\n\nOverlord Bor'gorok asked me to help Longrunner Proudhoof in any way that I can. The longrunner has asked that we lay to rest the spirits of his ancestors.\n\nWhat do you say, {class}? Are you man enough to handle such a simple task?", objectives = "Put 20 taunka spirits, either Ghostly Sages or Risen Longrunners, to rest and then report back to Grunt Ragefist at Steeljaw's Caravan.", completion = "Well done, <class>! You must have a great deal of experience fighting the undead. And, if you didn't before, you have some now.\n\nYou'll need it if you're going to survive in Northrend." }
WordHunterWoW_QuestEN[11595] = { title = "The Defense of Warsong Hold", description = "Hellscream has the weight of the Horde upon his shoulders. Do not be dissuaded from your duties because of his temperament, {name}.\n\n<Saurfang nods.>\n\nDid you think that I would forget the name of a hero of Orgrimmar? It is not every day that I have the pleasure of putting the head of Nefarian on a pike!\n\nThe Scourge have begun their assault upon this fortress. Our soldiers steady the line, but are in desperate need of backup. Report to Razgor. He is stationed directly outside of Warsong Hold.", objectives = "Report to Overlord Razgor at the hut on the south side of Warsong Hold.", completion = "<Overlord Razgor salutes.>\n\nYour reputation precedes you, <name>." }
WordHunterWoW_QuestEN[11596] = { title = "The Defense of Warsong Hold", description = "Do not let Hellscream dissuade you from your duties as a soldier of the Horde, {race}. He bears a terrible burden in these frozen wastes, with the outcome of his charge resulting in victory over the Scourge or the extinction of all life on Azeroth. It is for this reason that we require your strength and wisdom.\n\nThe Scourge have begun their assault upon this fortress. Our soldiers steady the line, but are in desperate need of backup. Report to Razgor. He is stationed directly outside of Warsong Hold.", objectives = "Report to Overlord Razgor at the hut on the south side of Warsong Hold.", completion = "Just in time... The Nerubians have seemingly doubled in number in just a week's time. We could use all the help we can get out here." }
WordHunterWoW_QuestEN[11597] = { title = "The Defense of Warsong Hold", description = "It seems that we always meet in the direst of circumstances, Scarab Lord. Were you not saving the world from certain destruction the last time we met?\n\n<Saurfang chuckles.>\n\nYour assistance is most welcome in Northrend, despite what the young chieftain might say.\n\nIf we had even a dozen more soldiers with your power, we would be sitting in Orgrimmar right now, hunched over a warm fire.\n\nReport to Overlord Razgor, right outside the main entry to Warsong Hold, to the south.", objectives = "Report to Overlord Razgor at the hut on the south side of Warsong Hold." }
WordHunterWoW_QuestEN[11598] = { title = "Taking Back Mightstone Quarry", description = "While Warsong is protected by 10 feet of steel and stone on all sides, this quarry is soft and primed for attacks by the Nerubians.\n\n<Razgor points west.>\n\nBeyond this quarry stand thousands of Scourge, awaiting orders to attack. Should the Nerubians take down our inner defenses, we will be overrun by the undead legions of Arthas.\n\nWe can't let that happen - which is why you're going on the offensive and slaughtering the Nerubians in the quarry.\n\nBlood and thunder, soldier! Take 'em both with you.", objectives = "Overlord Razgor at Warsong Hold wants you to kill 15 Nerub'ar Nerubians.", progress = "We didn't build on the Nerubian tunnel system, those monsters tunneled to us!", completion = "You've slowed them down, but more are sure to join the fight. Were you able to locate any of their egg sacs while in the quarry?" }
WordHunterWoW_QuestEN[11599] = { title = "Thassarian, My Brother", description = "I recently received word from William Allerton, a family friend, that my brother enlisted here in Valiance Keep on the same day he did.  Thing is... my brother's been dead for years.\n\nI sold everything I owned to come looking for Thassarian, only to be stonewalled by the local bureaucracy.  I've even been threatened with arrest if I keep snooping around.\n\nI need someone in the good graces of the higher-ups... someone like you.  If you can help me, I heard that William's stationed at the Farshire mine.", objectives = "Look for William Allerton inside the Farshire mine.", completion = "The corpse matches the description that Leryssa gave you of William Allerton.  Oddly enough, there are no bite or claw marks on him." }
WordHunterWoW_QuestEN[11600] = { title = "The Late William Allerton", description = "William's neck has been cut by a sharp object.\n\nFurther inspection reveals a single clue to bring to Leryssa - an enlistment card bearing the name of William Allerton.", objectives = "Bring the Enlistment Card to Leryssa at Valiance Keep in Borean Tundra.", progress = "You spoke to William, <name>?", completion = "Do you think William's death was a random killing by the Scourge?  Things sure seem fishy.\n\nSomething's up.  We must find Thassarian." }
WordHunterWoW_QuestEN[11601] = { title = "Lost and Found", description = "Poor Mr. Allerton might yet help us find my brother.\n\n<Leryssa unveils a voluminous book, not unlike an army recruitment ledger.>\n\nI borrowed it, ok?  Let's see, does that enlistment card have a date?\n\nWilliam saw Thassarian at the enlistment line.  Their entries must be near each other... here it is!\n\nHe was assigned to... Unit S?  All the other military units are named after Alliance towns.\n\nWho's in the unit?  Where are they deployed?  We need rumors.  See if the innkeeper's heard anything.", objectives = "Speak to James Deacon at the inn in Valiance Keep.", completion = "Can't say I can help you friend.  But I might know someone who can." }
WordHunterWoW_QuestEN[11602] = { title = "Cutting Off the Source", description = "Aerial reconnaissance of the quarry reports that the Nerubians are storing their eggs on the scaffolding surrounding the base. Smart beasts these are... They're keeping the eggs high and dry, away from the epicenter of conflict.\n\nYou're going to have to go back out there and track down their eggs. Find 'em, smash 'em, and trash 'em.\n\nEach egg destroyed means twenty less Nerubians feeding on our corpses.\n", objectives = "Overlord Razgor at Warsong Hold wants you to destroy 10 Nerub'ar Egg Sacs.", completion = "They just keep on coming, despite our best efforts. Something's gotta give, <name>." }
WordHunterWoW_QuestEN[11603] = { title = "In Wine, Truth", description = "The military was all that old man Colburn had.  After he retired, he still clung to it like a lifeline.\n\nHe knows the name of every general, unit, brigade, detachment... you name it.  He's the man you need.\n\nProblem is, his mind is scarred.  He won't talk to anyone unless he gets his Kul Tiras wine.  Takes him back to the times he was a marine.\n\nI haven't received a shipment in months.  The last merchant ship out of Kul Tiras sunk northeast of here.  See if you can salvage a bottle to bring Colburn.", objectives = "Salvage a bottle of Kul Tiras Wine from the underwater shipwreck northeast of Valiance Keep and bring it to Old Man Colburn in the Valiance Keep inn.", progress = "<The old man looks up at you with a blank look on his face.>", completion = "Mmmmm... not too bitter... not too dry... it's just like the old days, with the lads at the barracks." }
WordHunterWoW_QuestEN[11604] = { title = "A Deserter", description = "Unit S... Unit S.... hmmmpph.... don't make any sense... it oughta be named after a town...\n\nDarkshire was sent to Dragonblight.  The Goldshire boys were sent to the Fjord.   Where did I hear...\n\nOh, yes... the deserter!  There's a turn-tail in the barracks prison.  Got thrown in not too long ago.  Kept saying that \"S\" stood for suicide.\n\nLook for the deserter.  He might have some information for you.", objectives = "Find the prison inside Inner Hold in Valiance Keep and speak to the deserter.", completion = "Whad'ya want?  I have enough problems as it is!" }
WordHunterWoW_QuestEN[11605] = { title = "The Honored Ancestors", description = "<A distant voice echoes in your head as you regard the stone statue.>\n\nDo not be startled, stranger. I am Elder Atkanok, an ancient ancestor of the tuskarr people, a skilled craftsman in my own time and the guardian of this quarry for centuries.\n\nThe quarry has been overrun, leaving many statues unfinished while the ancestors' spirits wander the world. Will you aid me in righting this wrong?\n\nFirst, I must know the names of these wandering ancestors. Look for the markers near their statues.", objectives = "Elder Atkanok outside Coldrock Quarry wants you to identify the statues of Elder Kesuk, Elder Sagani, and Elder Takret.", progress = "<The distant voice returns.>\n\nHave you recovered the names of the wandering elders?", completion = "<Elder Atkanok's voice greets you as you approach his statue.>\n\nWell done, <name>. With the names of the wandering elders, we can continue the ceremonies disrupted during the attack. However, before the elders' spirits can be led to their stones, we must calm the spirits of the murdered craftsmen and shaman. Otherwise, the ancestor spirits may never hear the ceremony's call." }
WordHunterWoW_QuestEN[11606] = { title = "Patience is a Virtue that We Don't Need", description = "We can kill all the Nerubians that we see and destroy all the eggs that we find, but those things won't stop coming until we blow their tunnels and passageways up. Of course, we can't do that without some heavy grade munitions. Unfortunately, most of our stockpile is being used up by the goblins and blacksmiths for our siege tanks and weaponry.\n\nWe do happen to have a pretty good supply of the stuff out in Mightstone Quarry - underneath all the Nerubian crap. You'll just have to go out and get it for me.", objectives = "Quartermaster Holgoth at Warsong Hold wants you to recover 15 crates of Warsong Munitions.", progress = "We're running out of time here, <class>.", completion = "If my calculations are correct - and they're often not - you're gonna need about 10-20 seaforium depth charges.\n\nOh yea, you'll be planting these mothers into their sinkholes." }
WordHunterWoW_QuestEN[11607] = { title = "The Lost Spirits", description = "In the attack on the quarry, the shaman and craftsmen working here were slain. The violence threw the spirit world into utter chaos and we'll be unable to guide the ancestors home unless we find a way to soothe the spirits of the murdered.\n\nThe aggressors themselves pay no heed to the spirits, but their companions, the beryl hounds, sense the spirits and hold them in thrall.\n\nKill the beryl hounds, and using the raw energy left behind, break the imprisonment of the spirits of the innocent.", objectives = "Elder Atkanok, on the outskirts of Coldrock Quarry, wants you to free the spirits of 3 Kaskala Craftsmen and 3 Kaskala Shaman.", progress = "How fare the spirits of the innocent?", completion = "I can sense the upheaval in the spirit world beginning to calm. You have done well, <name>. The spirits of the ancestors are fortunate to have your help in this time of need." }
WordHunterWoW_QuestEN[11608] = { title = "Bury Those Cockroaches!", description = "North, south, east and west. Those are the locations that you should be concerned about. Surrounding this fortress, within Mightstone Quarry, are four perfectly situated Nerub'ar sinkholes.\n\n<Holgoth hands you a bundle.>\n\nBe very careful with that package, {name}. Mishandle it and you'll be dog meat.\n\nInside the bundle are seaforium depth charges. Get to each of those Nerub'ar sinkholes and plant a depth charge at their center point. If all goes well, the tunnels will collapse.\n\nGet a move on!", objectives = "Quartermaster Holgoth at Warsong Hold wants you to use the Seaforium Depth Charge Bundle to destroy the Nerub'ar sinkholes to the south, east, west and north of Warsong Hold.", completion = "That'll stop 'em - at least I think it'll stop 'em. Either way, you've done your part. That's all an orc can ask for, no?" }
WordHunterWoW_QuestEN[11609] = { title = "Picking Up the Pieces", description = "With the spirits of the murdered craftsmen and shaman at rest, the way is clear for us to complete the ceremonies interrupted by the attack. You must perform a role traditionally reserved for a tuskarr shaman, and you must possess all the necessary ritual items.\n\nThere is no time to craft new ones, so you will need to scour the quarry for those left by the victims of the attack. Handle these objects with care, {name}, for some are centuries old. You may need to wrest them from the hands of the invaders.", objectives = "Bring 6 Tuskarr Ritual Objects to Elder Atkanok, who stands outside Coldrock Quarry.", progress = "Have you recovered a full set of ritual items?", completion = "<You hold the objects before the statue of Elder Atkanok.>\n\nThose will suffice, although they are in a sad state. Some of them have survived centuries of use, only to be battered and stolen by barbarians." }
WordHunterWoW_QuestEN[11610] = { title = "Leading the Ancestors Home", description = "With your help, the ancestor spirits can now be guided to their rightful homes, the statues lovingly prepared by Kaskala's craftsmen and shaman.\n\nThe ceremonies for these ancestors were interrupted during the attack on the quarry, and you will need to complete them. Take with you the objects that you recovered from the quarry, stand in front of the statues with the name markers, and recite this chant.\n\n<Words in a strange language flood your head, but you have no difficulty recalling them.>", objectives = "Elder Atkanok wants you to guide the spirits of Elder Kesuk, Elder Sagani, and Elder Takret to their stone monuments.", progress = "Have you completed the ceremonies for the ancestors?", completion = "The ancestors have found their statues, and they have you to thank, <name>. The craftsmen of Kaskala will return to the quarry and ensure that the line of ancestors continues unbroken. For our part, the ancestors will continue to observe you with interest, as it seems your path is just beginning." }
WordHunterWoW_QuestEN[11611] = { title = "Taken by the Scourge", description = "<Mortuus sighs.>\n\nPeons... We may as well post up a sign offering the Nerub'ar a free meal.\n\nSee, the problem with a peon is that: (1) they're dumber than dirt; and (2) they're weaker than a leper gnome. Of course they're the first to be taken by the Scourge!\n\nThis puts me in a bit of a predicament, you see. Without peons, manual labor comes to a halt. No peons, no construction.\n\nFind and release my peons, {race}. If they're alive, you'll find 'em spun up in webbing throughout Mightstone Quarry.\n", objectives = "Foreman Mortuus at Warsong Hold wants you to free 5 Warsong Peons.", progress = "No peons, no buildings. And no, we're not going to replace them with goblins. Too damned expensive...", completion = "Most of them made it back. The ones smart enough to know that we're inside the gigantic metal and stone building, anyway...\n\nRegardless, a job well done. I hear you sprung more than a couple peons loose.\n\nOh yes, you're the talk of the... um... fortress." }
WordHunterWoW_QuestEN[11612] = { title = "Reclaiming the Quarry", description = "You're a welcome sight, {class}. My name is Etaruk, and I used to be a craftsman here at the Coldrock Quarry.\n\nMy companions and I were preparing a new set of statues for their last set of rites when we saw those mysterious blue platforms come flying over the plateau.\n\nWhen they landed, the mages they carried swarmed the quarry, murdering my fellows and plundering the quarry. If we don't stop them, they'll destroy our statues and make off with our artifacts. Will you help me defeat the invaders?", objectives = "Etaruk, camped near the entrance to the Coldrock Quarry, wants you to kill 12 Beryl Treasure Hunters.", completion = "Now that these strange mages know that the people of Kaskala and their allies will not give up the quarry so easily, we must maintain our efforts and defeat them completely.\n\nMy brothers in Kaskala have also come under attack and will not be able to support us, but with your help, <name>, we can overcome these pillagers." }
WordHunterWoW_QuestEN[11613] = { title = "Karuk's Oath", description = "They call themselves the Kvaldir.  My people have legends about them; we call them the tuk-hariq - walkers of the fog.\n\nMy village was destroyed by these giant mist-men.  Everyone I knew was slain, including my father Ariut.\n\nBy tuskarr law I must seek retribution against those who shed my kin's blood.\n\nI am but a fisherman and I've not yet passed the test of manhood... I cannot stand toe-to-toe with the vile Kvaldir.\n\nIf you were to carry out my blood duty for me, I will be in great debt to you.", objectives = "Karuk wants you to slay 6 Skadir Raiders and 5 Skadir Longboatsmen.", progress = "Did you succeed, <race>?  The Kvaldir are cruel warriors.  Do not expect any quarter from them.", completion = "You've done my people a great favor, <name>.  I must ask one more thing of you, however." }
WordHunterWoW_QuestEN[11614] = { title = "Untold Truths", description = "We are here by order of Varimathras! The mission of the Shadowstalkers is a simple one: spy. Well, spy with a little assassination on the side.\n\nOne of my best field agents has gone missing. I haven't heard from him in days, which has left me fearing the worst. No, not death! Death would be ideal. I fear he may have gone rogue... turned traitor even.\n\nHis last known location was northern Mightstone Quarry. He was gathering intelligence on the Nerubians. Find him.\n\nHe better be dead...", objectives = "Find Shadowstalker Luther in Mightstone Quarry.", completion = "It doesn't get much deader than this... Strangely, the Nerubians did not devour the corpse.\n\nAfter careful examination you see that Luther's death was self inflicted - deadly poison. Smart. Nerubians won't come near this toxic corpse.\n\nYou notice that Luther is holding a journal." }
WordHunterWoW_QuestEN[11615] = { title = "Nerub'ar Secrets", description = "You skim through the pages of the book, looking for anything of importance. On the last page you discover what appears to be frantic scribbling:\n\nNecrolords. At least a dozen by my count.\n\nFarms to west being used as some sort of horrible spawning glade for Scourge.\n\nRow upon row of victims.\n\nI think they're on to me. Made a dash for the hold. I won't be captured alive.\n\nDreadvenom hemotoxin. If they decide to bite into me, they'll be in for a surprise.\n\nTake this information back to Barthus.", objectives = "Take Luther's Journal to Shadowstalker Barthus at Warsong Hold.", progress = "Is he dead?", completion = "<Barthus flips to the last page of the journal and begins reading.>\n\nThis is very bad news. Hellscream must be notified at once." }
WordHunterWoW_QuestEN[11616] = { title = "Message to Hellscream", description = "<Barthus tears out the last page and rolls it up.>\n\nTake this to Hellscream at once! In the meantime, I'm going to send a team to scout out the farms.\n\nBe sure to tell Hellscream that we're going to need reinforcements. ", objectives = "Take Barthus's Note to Garrosh Hellscream at Warsong Hold.", progress = "What is the meaning of this interruption? Do not burden me with nonsense!", completion = "<Hellscream reads the journal entry.>\n\nIs that all?" }
WordHunterWoW_QuestEN[11617] = { title = "Hampering Their Escape", description = "I'm sure you've seen those blue and white platforms hovering over the quarry. They're the transportation the mage hunters used to land their forces here, and now they're loading them up with our artifacts and fragments of our statues.\n\nWe must stop them before they leave the quarry.\n\nThe small creatures digging in the quarry carry explosives. Take them and use them to destroy the three floating platforms. The leader keeps watch from a fourth, grounded platform, but we'll deal with him afterward.", objectives = "Etaruk, outside the Coldrock Quarry, wants you to destroy the North Platform, the East Platform, and the West Platform.", progress = "Have you succeeded in destroying the mage hunters' flying platforms?", completion = "The mage hunters won't find it as easy to plunder our quarry and steal our artifacts as they'd imagined. With your help, we'll win back the quarry and set things right again." }
WordHunterWoW_QuestEN[11618] = { title = "Reinforcements Incoming...", description = "<Hellscream shakes his head.>\n\nYou may not have noticed that we're trying to win a war here, {race}. I need all available soldiers at the primary points of conflict. This means that we don't have any real soldiers to spare for these minor incursions.\n\n<Hellscream pauses to think.>\n\nIf Barthus wants reinforcements at the farm...\n\n<Hellscream claps his hands together.>\n\n...he shall have them! Report to Barthus's assassins at the farms, west of here. Let them know that reinforcements have arrived.", objectives = "Seek out Shadowstalker Ickoris at the Warsong Farms Outpost west of Warsong Hold.", completion = "This is it? Hellscream sent a single <race> boy?\n\nIf I still had a jaw it would be on the floor right now." }
WordHunterWoW_QuestEN[11619] = { title = "Gamel the Cruel", description = "My own father was slain by the leader of this raiding party, Gamel the Cruel.  He has made his abode inside a cave on the beach.\n\nYou've dealt with his men already.  Finish what you've started, {name}.  Avenge my father and I will share with you what little I still have.", objectives = "Karuk wants you to defeat Gamel the Cruel at Riplash Strand.", progress = "Did you defeat Gamel, <class>?", completion = "You did it, <name>!  The spirits of the slain tuskarr can now rest in peace - their deaths have been avenged!" }
WordHunterWoW_QuestEN[11620] = { title = "A Father's Words", description = "There is someone who might shed light on this mystery, {race}.  It is rumored that the Kvaldir have kept a naga priestess alive at the temple on the west side of the shore.\n\nShe will no doubt have great reason to resent her uninvited Kvaldir guests.  Perhaps my father is expecting her to cooperate with you in some way.", objectives = "Look for Veehja at the Shrine of Scales on Riplash Strand.", completion = "Hsssssssssssss!  Have you come to mock me, <race>?" }
WordHunterWoW_QuestEN[11621] = { title = "The Tablet of Leviroth", description = "You scour through the tablet's etchings, looking for any text you can understand.  You finally find the following fragment:\n\n\"The sons of the fog will claim a thousand souls for the one who dwells in darkest waters.  His emissary will then awake.\"\n\nKaruk might be interested in this information.", objectives = "Return to Karuk with the information you found on the tablet.You scour through the tablet's etchings, looking for any text you can understand. You finally find the following fragment:\n\n\"The sons of the fog will claim a thousand souls for the one who dwells in darkest waters. His emissary will then awake.\"\n\nKaruk might be interested in this information.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[11622] = { title = "Secrets of Riplash", description = "There is someone who might shed light on this mystery, {race}.  It is rumored that the kvaldir have kept a handful of naga priestesses alive inside the temple.\n\nThe high priestess, Veehja, will no doubt have great reason to resent her uninvited kvaldir guests.  Perhaps she can tell you more about what the writing on the tablet means.", objectives = "Find Veehja at the ruins of Riplash in Borean Tundra.There is someone who might shed light on this mystery, <race>. It is rumored that the kvaldir have kept a handful of naga priestesses alive inside the temple.\n\nThe high priestess, Veehja, will no doubt have great reason to resent her uninvited kvaldir guests. Perhaps she can tell you more about what the writing on the tablet means.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[11623] = { title = "A Visit to the Curator", description = "The leader of the mage hunter forces is a fearsome creature called Curator Insivius. My people have hunted the beasts of the seas and land for countless generations, but I've never seen anything like this curator before.\n\nHe's landed one of those flying disks on the upper rim of the quarry and oversees the operation from there. {name}, I can only believe the ancestors themselves sent you to my rescue and I hope you will help me drive the mage hunters from this quarry once and for all.", objectives = "Etaruk, on the outskirts of the Coldrock Quarry, wants you to kill Curator Insivius.", progress = "Have you done away with the curator?", completion = "The curator and his men must've thought the quarry an easy target for their looting, but you've shown them otherwise, <name>. I am deeply grateful for your help and I'm certain the ancestors will continue to watch over you." }
WordHunterWoW_QuestEN[11624] = { title = "The Sky Will Know", description = "I must find out what happened to my master, Farseer Grimwalker!\n\nEarlier, he was observing the magnataur at nearby Magmoth. But one of his grunts just returned, saying that the group had been crushed, and that the farseer was dragged into the depths of the place.\n\nBefore I send you on a suicide mission, I wish to consult with the spirits to learn more.\n\nThere is an air elemental known as Imperean in the ruins of Eldra'nath to the west. She is wise and may give you the information we seek.", objectives = "Speak with Imperean at the Ruins of Eldra'nath.", completion = "You are foolish to come here, little <race>.\n\nWhat is it that you seek?" }
WordHunterWoW_QuestEN[11625] = { title = "The Trident of Naz'jan", description = "Five hundred years ago, Azshara imprisoned a being named Leviroth in the waters below.  Now these barbarians seek to undo our queen's work!\n\nThey took over our city and began to sacrifice my brethren to awaken him!  When they ran out of naga, they began to take tuskarr.  Their spirits will know no peace!\n\nI will help you, for it will go a long way towards quelling my vengeance.  Their captain, Ragnar, dwells deep inside northeastern Riplash.  He has in his possession a golden trident.  Bring it to me!", objectives = "Veehja in Riplash wants you to go to the far northeastern end of the Riplash Ruins. Once there slay Ragnar Drakkarlund and obtain the Trident of Naz'jan from him.", progress = "Do you have the trident?", completion = "Yesssssss!  We will slay the Kvaldir's beast!  I will show these brutes to never cross a priestess of the scale!" }
WordHunterWoW_QuestEN[11626] = { title = "The Emissary", description = "Raj Naz'jan was the emperor of Riplash when Leviroth was imprisoned.  Azshara herself blessed his trident so it would slay the beast should it ever escape.\n\nNow you wield it, {race}.  As much as it disgusts me, I will have my revenge on these barbaric giant-men.\n\nTake the trident to the depths beneath Riplash.  You will find Leviroth below an iceberg closest to northern Riplash.\n\nDrive the trident into his flesh and slay him!  Return to whomever sent you when you're done; I wish to see no more of you.", objectives = "Find Leviroth in the waters below the iceberg floating among the northern edge of Riplash Ruins. Use the Trident of Naz'jan to slay him and return to Karuk to the north of Riplash Strand.", completion = "My people's spirits can rest in peace.  You've helped me honor my father... perhaps I will one day be as strong as you are." }
WordHunterWoW_QuestEN[11627] = { title = "Boiling Point", description = "Ah, it is information that you crave: the whereabouts and condition of your 'farseer'. He did not see so far as to avoid the trouble which befell him.\n\nNevertheless, I will give you the means to acquire the knowledge. But first, you will do some things for me.\n\nNo doubt you have seen the war between fire and water to the south. Simmer keeps boiling Churn's pool, and the two have been battling for ages.\n\nGo to the Charred Rise and Blistering Pool, and convince each of them to stop their bickering.", objectives = "Imperean wants you to beat Simmer and Churn into submission. Return to her at the Ruins of Eldra'nath when they have submitted.", completion = "I am pleased, though no doubt they will still continue to quarrel a bit longer.\n\nHowever, there is something else that you will need to accomplish before you can return to your spirit talker." }
WordHunterWoW_QuestEN[11628] = { title = "Shrouds of the Scourge", description = "To the northeast looms the Temple City of En'kilah, the Scourge's seat in Borean Tundra. From behind its walls, the Scourge commander has sent his Nerubians to surround us.\n\nRemaining on the defensive would doom my people, but my advisors differ in their strategies. Durm would charge in blindly, while Sage Aeire favors stealth.\n\nThe Temple City has blighted the nearby lands and the native creatures. Aeire believes the pelts of the scourged mammoths can serve as a cloak that may hide an infiltrator.", objectives = "Chieftain Wintergale at Taunka'le Village wants you to bring him 5 Scourged Mammoth Pelts.", progress = "Have you brought the mammoth pelts?", completion = "As much as I dislike bringing such disease-ridden things into the village, they may give us an advantage over our foes.\n\n<The chieftain gestures to Sage Aeire and waves dismissively at the pelts.>\n\nWhile she is preparing the pelts, there is one other element we need to create the cloak." }
WordHunterWoW_QuestEN[11629] = { title = "Return to the Spirit Talker", description = "You have done what was asked, and now I give you that which you desire.\n\nDeliver this primal to the spirit talker back at your Bor'gorok Outpost. If she is wise, she will know a ritual to gain you the information which you seek.", objectives = "Deliver Imperean's Primal to Spirit Talker Snarlfang at Bor'gorok Outpost.", progress = "<name>, you have returned. What did you learn?\n\nWhat is that sound?", completion = "Imperean gave you a primal essence of herself? I can hear its howling winds!\n\nI know a ritual we can make use of it in. We must hurry before her primal rips itself apart!" }
WordHunterWoW_QuestEN[11630] = { title = "The Bad Earth", description = "By curing the hides with the blighted earth outside the Temple City, Sage Aeire believes she can create a cloak which will cause most of the Scourge minions to ignore your presence. You should blend right in, she says.\n\nShe'd best be correct. It's our only chance to gather information and plan our counterattack.\n\nYou should be able to find the earth she needs poking in the areas to the south and west of the fortress. Bring it to me when you've finished gathering it.", objectives = "Bring 8 clods of Scourged Earth to Chieftain Wintergale at Taunka'le Village.", progress = "Do you have the earth Sage Aeire needs to complete the cloak?", completion = "<Chieftain Wintergale gingerly accepts the clods of soil you gathered.>\n\nWe should get these into Sage Aeire's hands as soon as possible.\n\n<The chieftain grunts, pretending not to be disturbed by the tainted dirt.>\n\nWe can never know when the Scourge commander will launch the final assault on the village." }
WordHunterWoW_QuestEN[11631] = { title = "Vision of Air", description = "Here, {name}, I've attuned the primal to you.\n\nOpen your soul to it in the presence of my totem of air and concentrate upon the fate of Farseer Grimwalker.\n\nThe spirit of the wind touches all; with any luck you will be granted a vision.", objectives = "Use Imperean's Primal to perform a ritual at Snarlfang's Totem at Bor'gorok Outpost to gain information concerning Farseer Grimwalker.\n\nAfterward, speak with Spirit Talker Snarlfang.", progress = "When you feel that you have seen enough, return the primal to me.", completion = "They've shackled his spirit. <name>, we have to put an end to his torture!\n\nYou must descend into the bowels of Magmoth and find a way to free him!" }
WordHunterWoW_QuestEN[11632] = { title = "What the Cold Wind Brings...", description = "You hold the carapace fragment of Ith'rix the Harvester and realize that this is only the beginning. Even now you sense that victory is fleeting. Surely the Lich King has a thousand more beasts like Ith'rix, waiting to be unleashed upon the Horde.\n\nTake your trophy and present it to High Overlord Saurfang, inside Warsong Hold. He should be notified of your victory over a powerful Scourge agent.", objectives = "Take Ith'rix's Hardened Carapace to High Overlord Saurfang at Warsong Hold.", progress = "What have you got there?", completion = "<Saurfang grins.>\n\nIt looks familiar... The Might of Kalimdor trampled a thousand bugs like this one in the desert of Silithus.\n\nThis is a different place - a different environment - but the result will be the same.\n\n<Saurfang looks you over.>\n\nYou will bring pride and honor to the Horde in Northrend, <name>." }
WordHunterWoW_QuestEN[11633] = { title = "Blending In", description = "Sage Aeire has finished the shroud. Take it with you and travel to the Temple City of En'kilah. Don the cloak within the city's bounds to hide yourself from most of the Scourge there. This will be our best opportunity to gather information about the enemy's fortifications and leaders.\n\nWhile wearing the cloak, scout the three large spires on the grounds of the city. While the shroud will shield you from most of the Scourge, the En'kilah abominations will be able to find you if you get too close.", objectives = "Chieftain Wintergale at Taunka'le Village wants you to wear the Imbued Scourge Shroud in the Temple City of En'kilah and scout the Spire of Blood, the Spire of Pain, and the Spire of Decay.", completion = "<Chieftain Wintergale listens as you describe your observations.>\n\nThe information you've gathered will help us to plan our assault on the Temple City. We'll need to find a way to defeat the officers you identified and get into that necropolis." }
WordHunterWoW_QuestEN[11634] = { title = "Wind Master To'bor", description = "You're a tough mother, {name}. I think your talents are better suited elsewhere - like the root of the whole damn problem!\n\n<Razgor points to the west.>\n\nA thousand Scourge, at least four full sized floating death machines and who knows what else.\n\nBut you're gonna find out and then you're gonna handle it... That's right, you're gonna beat the hell out of the Scourge army that's currently beating down our door.\n\nGet to the top of Warsong Hold and report to Wind Master To'bor. He'll be expecting you.", objectives = "Report to Wind Master To'bor at Warsong Hold.", completion = "Ay, mon. I been expectin' you.\n\n<To'bor points west.>\n\nTake a peek. Across dat tundra be death, mon... death." }
WordHunterWoW_QuestEN[11635] = { title = "Farseer Grimwalker's Spirit", description = "You must go to Magmoth to the east.\n\nYou must descend into the depths of their caverns.\n\nYou must speak with Farseer Grimwalker's spirit!", objectives = "Speak with Farseer Grimwalker's Spirit inside of Magmoth.", completion = "Thank you for the reprieve, <class>. If only my true freedom were so easy to attain." }
WordHunterWoW_QuestEN[11636] = { title = "Magic Carpet Ride", description = "Tanks, mon. I be talkin' bout siege machines! We got heavy tanks stationed at Garrosh's Landing on da west coast. We gonna get you to da tank and you gonna use da tank to lay down some Horde justice on da Scourge!\n\nDa only tricky part be getting' you der. No way we be sendin' you on our wind riders. Too risky.\n\nYou see dat pixie o'er der? Dat blondie elf? Yanni be his name, mon. He can get you to da coast, safely. Once der, talk to Annihilator Grek'lor!", objectives = "Talk to Yanni at Warsong Hold to arrange safe travel to the coast. Speak to Annihilator Grek'lor once you arrive at Garrosh's Landing.", completion = "NO MERCY FOR THE DEAD!\n\nNone of 'em had the guts to stay behind to defend our glorious tanks after Hellscream deemed the coast 'condemned.' It's mostly quiet here, seein' as how the Scourge are formin' up ranks to assault Warsong Hold. Sometimes I get a stray zombie or ghoul, but they don't last very long.\n\n<Gorge strokes his axe.>\n\n'Course, there's the mist...\n\n<Gorge shudders.>" }
WordHunterWoW_QuestEN[11637] = { title = "Kaganishu", description = "After my small force of grunts were killed, I was dragged down here and ritually murdered. The snobold who did this is known as Kaganishu.\n\nThough you have vanquished his shaman helpers, my spirit is still tethered to this place. After he slew me, he created a fetish from my body, which anchors me here. Kaganishu is using it to learn all that I know of shamanism.\n\nYou must retrieve the fetish from him and use it upon my spirit. Kaganishu is nearby in the caves.\n\nOnly then will I truly be free.", objectives = "Retrieve Kaganishu's Fetish and use it upon Farseer Grimwalker's Remains.\n\nYou will need to give the fetish to Farseer Grimwalker's Spirit inside of Magmoth.", progress = "Hurry, <class>, use the fetish upon me before it is too late.", completion = "I am freed. Thank you, <name>.\n\nAnd now, I have one final request of you." }
WordHunterWoW_QuestEN[11638] = { title = "Return My Remains", description = "{name}, now that my spirit has been freed would you do me the honor of returning my remains to Spirit Talker Snarlfang? They lay upon the ground beneath me.\n\nI sense that the spirit talker is still at Bor'gorok Outpost to the west where last I saw her.", objectives = "Deliver Farseer Grimwalker's Remains, which are resting below his spirit, to Spirit Talker Snarlfang at Bor'gorok Outpost.", progress = "You return sooner than I expected. What did you learn?", completion = "Thank you for freeing his spirit from Kaganishu and returning with his remains. We have little to reward you with, but you may take whatever catches your eye.\n\nAnd now, I will return him to the living where he belongs." }
WordHunterWoW_QuestEN[11639] = { title = "Revenge Upon Magmoth", description = "The overlord refuses to allow the shaman to heal my wounds. He says that it will be a good lesson for me and give me time to reflect upon my failure.\n\nBut you could get revenge for me and the others who fell at Magmoth!\n\nI know that the spirit talker wants you to go in there to save the farseer.\n\nIt's just to the east. Go, {class}... go slay the magnataur and their snobold servants. Regain the outpost's honor!", objectives = "Kill 10 Magmoth Shaman, 5 Magmoth Foragers, 3 Magmoth Crushers, and 3 Mates of Magmothregar. Then, return to Ortrosh at Bor'gorok Outpost.", completion = "The dead are honored by your actions, <name>.\n\n\n\nPerhaps now I can find my way back to being the warrior I once was." }
WordHunterWoW_QuestEN[11640] = { title = "Words of Power", description = "Within the spires you described dwell the main lieutenants of the Scourge leader, the high priests. Not only do they command the Scourge forces, but they hold the key to the necropolis above, and their master.\n\nAn endless stream of Scourge minions will overrun us if we can't find and defeat their leader. I cannot leave my people defenseless, however much Durm might want to bring the fight to the enemy. It falls to you, {name}, to slay the high priests and take the scrolls they hold.", objectives = "Bring High Priest Naferset's Scroll, High Priest Talet-Kha's Scroll, and High Priest Andorath's Scroll to Chieftain Wintergale at Taunka'le Village.", progress = "We must get into that necropolis if we're to break through the Scourge and clear a path for the villagers.", completion = "<Chieftain Wintergale reads the words written on the scrolls.>\n\n'Shabtir bakh sokhen.'\n\nWords of the ancient, harsh language used by the Nerubians, and apt ones at that.\n\n'The servant bows to the master's authority.' These are the words that will gain you entry into the necropolis." }
WordHunterWoW_QuestEN[11641] = { title = "A Courageous Strike", description = "From the beginning, I've counseled that Chieftain Wintergale should assemble our mighty warriors and attack our enemy at their base. My advice has fallen on deaf ears and he has proven that he'd rather tip-toe around according to Sage Aeire's plans.\n\nI'll wait no longer. If Chieftain Wintergale is too cowardly to send our warriors into battle, perhaps you'd be willing to show him that a direct attack can succeed. Storm the Temple City of En'kilah and slay all in your path, {name}.", objectives = "Slay 15 En'kilah Ghouls and 5 En'kilah Necromancers and report back to Durm Icehide at Taunka'le Village.", completion = "You have proven your fearlessness and demonstrated your prowess in combat. I believe you would make a fine taunka warrior. I only wish the chieftain had the same understanding.\n\nWe are fortunate to count you as an ally in our struggle to evacuate the village before it is overrun by the Scourge." }
WordHunterWoW_QuestEN[11642] = { title = "Tank Ain't Gonna Fix Itself", description = "We need to get these tanks back up and runnin'! They ain't gonna fix themselves. Mobu's gonna be the one to handle that stuff. Talk to him and see what he needs. Maybe you can shut him up before he finally drives me into a berserker frenzy and I cleave him in two!", objectives = "Speak with Mobu at Garrosh's Landing.", completion = "You're the new tank driver, buddy? Fine by me! We just need to get these things up and running again. Yea, you try to go out into the Plains of Nasam without a tank and you're as good as dead." }
WordHunterWoW_QuestEN[11643] = { title = "Mobu's Pneumatic Tank Transjigamarig", description = "These wrenches are useless, buddy. I need my pneumatic tank transjigamarig to get these things up and running! Unfortunately, I left it at my old digs, on the other side of this landing. It's the beat down hut next to the stables. You're gonna have to go and get it for me, because I sure as hellfire am not going to go anywhere near the mist.\n\nOh yea, buddy, watch out for the mist. The mist is what tore up these shores.\n", objectives = "Mobu at the Coast of Echoes in the Borean Tundra wants you to recover his Pneumatic Tank Transjigamarig.", progress = "Did you find the P.T.T.?", completion = "Great work, buddy! Now where'd I put those spare parts..." }
WordHunterWoW_QuestEN[11644] = { title = "Super Strong Metal Plates!", description = "I need metal to patch these tanks up! Super strong metal plates can be found scattered about all across Garrosh's Landing and at the bottom of the bay.\n\nJust be careful when you're out there searching for plates. The mist is... um... AGGRESSIVE! The mist is what took out the landing and the adjoining tuskarr town. Poor little tuskarr...", objectives = "Mobu at the Coast of Echoes in the Borean Tundra wants you to collect 10 Super Strong Metal Plates.", progress = "Remember, the mist is bad!", completion = "Great work, buddy! Now where'd I put that pneumatic tank transjigamarig." }
WordHunterWoW_QuestEN[11645] = { title = "Dirty, Stinkin' Snobolds!", description = "Those dirty, stinkin' snobolds... they stole all of my supplies!\n\nWhat's a snobold you ask? It's like a kobold, 'cept they serve the magnataur; kinda take care of them. I know, weird!\n\nAnywho, wanna help me out? I know the little creeps stole off with all of my stuff. Stupid me thinkin' that it'd be nice and safe, packed up on the north side of the airstrip.\n\nWhy don'tcha do me a favor and head north to their stupid Magmoth. There's a cash reward if you bring all my stuff back quick!", objectives = "Retrieve 10 boxes of Crafty's Stuff and return them to Crafty Wobblesprocket at Fizzcrank Airstrip.", progress = "Ya got all of my supplies, <class>? I just can't do ANYTHING without all of my stuff!", completion = "Oh, <name>, you're just the best!\n\nHere's your coin as promised." }
WordHunterWoW_QuestEN[11646] = { title = "The Borean Inquisition", description = "Listen closely, {name}, for there is not a moment to spare.\n\nYour prisoner is being prepared for interrogation here in our tower. In the event that he is less than forthcoming, your assistance may be required.\n\nMake your way up to where he is being detained and tell Librarian Normantis that I've sent you to assist him.", objectives = "Donathan ordered you to offer your assistance to Librarian Normantis in the mage tower on Amber Ledge.", completion = "It was wise of Donathan to send you, <class>.\n\nAs it turns out, I am in need of someone outside the Kirin Tor." }
WordHunterWoW_QuestEN[11647] = { title = "Neutralizing the Cauldrons", description = "The presence of plague cauldrons within the Temple City of En'kilah worries me greatly, {name}. It's clear that Chieftain Wintergale trusts your judgment and your knowledge of our enemy. Would you help me deal with the cauldrons as you help the chieftain carry out his plans in the Temple City?\n\nI've prepared a totem which will attack and neutralize the contents of the cauldrons. All you must do is locate the cauldrons and use the totem near each. Each Scourge weapon we destroy brings us closer to victory.", objectives = "Sage Aeire at Taunka'le Village wants you to use her totem to neutralize the East Cauldron, the Central Cauldron, and the West Cauldron in the Temple City of En'kilah.", completion = "<Sage Aeire accepts the totem from you.>\n\nDid the totem work? Its preparation required ancient magics the sages haven't used in generations. Of all the knowledge passed down, only a fraction of it remains in use today." }
WordHunterWoW_QuestEN[11648] = { title = "The Art of Persuasion", description = "It is fortunate you're here, {race}.\n\nYou see, the Kirin Tor code of conduct frowns upon our taking certain 'extreme' measures - even in desperate times such as these.\n\nYou, however, as an outsider, are not bound by such restrictions and could take any steps necessary in the retrieval of information.\n\nDo what you must. We need to know where Lady Evanor is being held at once!\n\nI'll just busy myself organizing these shelves here. Oh, and here, perhaps you'll find this old thing useful....", objectives = "Librarian Normantis on Amber Ledge wants you to use the Neural Needler on the Imprisoned Beryl Sorcerer until he reveals the location of Lady Evanor.", progress = "Well? Do you know where Lady Evanor is being held?", completion = "Excellent! It was crucial that we collect that intelligence.\n\nWell done, friend." }
WordHunterWoW_QuestEN[11649] = { title = "Motes of the Enraged", description = "Now that their little squabble is dealt with, there is still the matter of helping you and your spirit talker.\n\nAs you can see, my vassals have been enraged by the ongoing war between fire and water. This will not change anytime soon, but it will serve to your advantage.\n\nIn order to assist you, what we need are their motes. Head further into the ruins and retrieve them from the tempests.", objectives = "Obtain 5 Tempest Motes and deliver them to Imperean at the Ruins of Eldra'nath.", progress = "Once you have the necessary motes, I will combine a portion of my essence with theirs. The result will get you what you need.", completion = "I regret the loss of those tempests, but my word is my bond... even to a mortal such as yourself.\n\nNow, let us see if we can fashion something of use to you." }
WordHunterWoW_QuestEN[11650] = { title = "Just a Few More Things...", description = "As you may have noticed, we created the airstrip on the southern border of a magnataur den!\n\n<Crafty says something uncharitable about Fizzcrank under her breath.>\n\nThe old man has put me in charge of finding a... ahem... creative solution to this situation: if we don't deal with them soon, they'll come down here and tear us limb from limb!\n\nThat's where you come in. I want you to get me everything on this shopping list. Please.", objectives = "Collect Crafty's Tools, an Overcharged Capacitor, and a Handful of Rocknar's Grit. Deliver them to Crafty Wobblesprocket at Fizzcrank Airstrip.", progress = "Why is it that I don't believe you've collected everything on my list?", completion = "Alright, that's more like it! Now all we gots to do is put all this together.\n\nYeah, as if you're going to help me with that.\n\nHold your horses, this'll just take a second now that I've got my tools back!" }
WordHunterWoW_QuestEN[11651] = { title = "Tanks a lot...", description = "Thanks for all your help, buddy. You can let Grek'lor know the tanks are ready for action. Hopefully you can clean up this place once and for all!", objectives = "Speak to Annihilator Grek'lor at the Coast of Echoes.", completion = "With the current state of our transports and shipping lanes, we haven't been able to get a damned siege engine to Warsong. These tanks are all that we have left from the original expedition. Now that they're operational, you're gonna use 'em to stomp the Scourge offensive at the Plains of Nasam." }
WordHunterWoW_QuestEN[11652] = { title = "The Plains of Nasam", description = "Once you're ready, jump into one of the tanks and drive it out to the Plains of Nasam, southeast of here.\n\nUse the tank's weapon arsenal to take down the Scourge army. If you get in a jam, the \"Meatpounder\" will tear 'em up and the land mines will finish 'em off! If you find any of our soldiers, grab 'em! One last thing, fuel tanks can be found all over the field.\n\nTry to get close enough to that structure in the center and see what's going on.\n\nIf you do all of this and live, go to Hellscream!", objectives = "Use the Horde Siege Tank to destroy 100 Scourge Soldiers and rescue 3 Injured Warsong Soldiers on the Plains of Nasam. You must also discover the identity of the leader of the Scourge assault.\n\nReport to Garrosh Hellscream at Warsong Hold should you succeed.", completion = "Kel'Thuzad? So it's true - Naxxramas returns...\n\nPerhaps I underestimated you, <name>. You've done the Horde a great service. The Warchief would be proud!\n\n\n\nIf Kel'Thuzad is controlling these Scourge, there's no telling what else the Lich King has in store for us... I'll need time to think through this new information, <name>. You are dismissed." }
WordHunterWoW_QuestEN[11653] = { title = "Hah... You're Not So Big Now!", description = "That'll do her, chief! So, here's what I want ya to do....\n\nTake my blaster and head north to Magmoth. If we're gonna have a chance at all against those monsters, we need to cut them down to size... so to speak.\n\nIn order to gauge its effectiveness, I need you to slay the magnataur while the blaster's effects are still on it. Any of the crushers or mates will do, but don't bother with the offspring... they're too small to worry about.", objectives = "Test out Crafty's Ultra-Advanced Proto-Typical Shortening Blaster on 5 Magmoth Crushers or Mates of Magmothregar. After you have done so, return to her at Fizzcrank Airstrip.", completion = "Whadya mean it didn't work?!\n\nBut... but...\n\n<Crafty begins to sob.>\n\nOkay, we can deal with this. I'm a big girl. Time to think outside the box!" }
WordHunterWoW_QuestEN[11654] = { title = "The Spire of Blood", description = "As you inspect the captured blood vial, you realize its contents are still warm. The victim must have just been bled and may still be alive.\n\nWhat use would the Scourge have for blood? They've never shown an interest in live prisoners in the past. Perhaps if you can locate the source of the blood, you'll be able to discover what the Scourge is planning.", objectives = "Search the Spire of Blood for more information about the Vial of Fresh Blood.", progress = "How... how did you find me?", completion = "<The taunka snow tracker appears weak and barely responds to you.>\n\nI haven't... long. Maybe... maybe you can stop them... before..." }
WordHunterWoW_QuestEN[11655] = { title = "Into the Mist", description = "Across the mist to the north you will find Garrosh's Landing. To the south are the ruins of my old home, Pal'ea. Both have been ransacked by an ancient force known as the Kvaldir.\n\nThese fearsome savages slew all of my people without mercy and drove your people inland.\n\nAll that remains of the tuskarr of Pal'ea are our personal effects, taken as relics by the Kvaldir. While we are not a vengeful race, justice must be served. The tuskarr relics must be returned to me. Enter the mist and find them...", objectives = "Waltor of Pal'ea at the Coast of Echoes in the Borean Tundra wants you to kill Kvaldir and recover 8 Tuskarr Relics.", progress = "By blood and honor you must serve... Return the tuskarr relics.", completion = "<Sadness overcomes Waltor.>\n\nRuin... That is all they leave in their wake. They must be taught a lesson." }
WordHunterWoW_QuestEN[11656] = { title = "Burn in Effigy", description = "Tuskarr magic is similar to what your people call shamanism. While we serve the elements differently than you, the power that we are able to call forth is formidable.\n\n<Waltor waves a torch-like baton in front of you.>\n\nWith this tuskarr torch I want you to return to the mist and strike at the Kvaldir vessels. You will find three of their vessels docked behind the mist at Garrosh's Landing, north of here, and one docked off the shores of Pal'ea, to the south. Burn their ships in effigy! For all to see!", objectives = "Waltor of Pal'ea at the Coast of Echoes in the Borean Tundra wants you to use the Tuskarr Torch to burn the Kvaldir ships at Pal'ea and Garrosh's Landing. You must destroy the following ships: The Serpent's Maw, The Kur Drakkar, Bor's Hammer and Bor's Anvil.", progress = "Is it done? Are the ships ablaze?", completion = "A show of resistance to the Kvaldir savages might be what is needed to save my people at the other encampments. Perhaps the Kvaldir will rethink their actions should they believe that retribution will come." }
WordHunterWoW_QuestEN[11657] = { title = "Torch Catching", description = "Now that you can throw a torch, let's see if you can catch one!\n\nTake this stack of unlit torches. Go to the bonfire and throw a torch high into the air.  Catch it before it hits the ground... then throw it back up! Catch four then come back to me.\n\nCareful! They're dangerous if they hit the ground! Good luck!", objectives = "Catch 4 torches then speak with the Master Fire Eater.", progress = "Torch catching is a lot of fun, don't you think?  But have care!  You don't want to get singed!", completion = "Did you get burned?  If you did, then maybe you'll think twice before playing with fire...\n\nJust kidding!  Well done!  It's official.  You're a bona fide fire juggler.  Now get out there and have some fun!" }
WordHunterWoW_QuestEN[11658] = { title = "Plan B", description = "Okay, don't panic! The blaster might not've worked, but we still have options.\n\n<Crafty snaps her fingers.>\n\nWe're going to divert attention away from the airstrip! To make this work, we'll need a few things first.\n\n<Wobblesprocket looks you up and down appraisingly.>\n\nSteeljaw's caravan, just to the west, stupidly took a shortcut through a taunka graveyard and was destroyed by their risen spirits.\n\nHead over there and get some outfits off of the dead orcs. Pick up one of their banners, too!", objectives = "Collect 10 Warsong Outfits and a Warsong Banner. Bring them back to Crafty Wobblesprocket at Fizzcrank Airstrip.", progress = "We'll need lots of their clothes if this is going to work. I'm no seamstress... we'll just have to find something to fit you!\n\nAnd then I'll just add a touch of my engineer genius, and poof, you'll look the part you need to play.", completion = "Nice, but those clothes reek!\n\nPersonally, you'd never catch me dead in such rags. But we're going to have to sort through them and find some that fit your, um... figure." }
WordHunterWoW_QuestEN[11659] = { title = "Shatter the Orbs!", description = "They're... bleeding the prisoners... putting the blood... in those globes.\n\n<Grumm's eyes close momentarily and he leans his head back.>\n\nThe blood... taken up to necropolis... to feed blood prince...\n\n<Grumm gasps for breath.>\n\nP-promise... you'll... destroy blood... globes... bring word... to Junek.\n\n<The snow tracker collapses into unconsciousness.>", objectives = "Destroy 5 Blood Globes and report to Snow Tracker Junek at Taunka'le Village.", completion = "I feared they might've captured Grumm, but I never thought they'd do such horrific things to him. I've never seen a warrior survive a losing battle with the Scourge.\n\nThank you for bringing word of his fate, <name>. He was a mighty warrior and we will remember him as such." }
WordHunterWoW_QuestEN[11660] = { title = "Horn of the Ancient Mariner", description = "A Kvaldir lieutenant known as Orabus directed the initial incursion against my people at Pal'ea, He oversaw the destruction of both villages and then disappeared into the mist.\n\nIn those early days there was talk of a horn that Orabus gifted to the Kvaldir mistweavers. This horn could be used to summon him should the need arise.\n\nWe need to get that horn from the Kvaldir mistweavers and call forth Orabus. If he is destroyed, these savages might retreat.\n\nSeek out mistweavers at Pal'ea, to the south.", objectives = "Waltor of Pal'ea at the Coast of Echoes in the Borean Tundra wants you to bring him the Horn of the Ancient Mariner.", progress = "Find the Horn of the Ancient Mariner!", completion = "You must call for Orabus using the Horn of the Ancient Mariner." }
WordHunterWoW_QuestEN[11661] = { title = "Orabus the Helmsman", description = "Take the horn and travel west to the Warsong Jetty. Make your way to the end of the jetty and blow into the horn. The sound should rouse Orabus.\n\nSlay the foul beast and return to me!", objectives = "Waltor of Pal'ea at the Coast of Echoes in the Borean Tundra wants you to use the Horn of the Ancient Mariner to summon Orabus the Helmsman. Once summoned, slay Orabus the Helmsman.", progress = "Orabus must be destroyed!", completion = "It seems that the loss of their lieutenant has only stirred the nest. They are more angry and aggressive than before!\n\n<Waltor sighs.>\n\nYou've done what you can here, friend. At the very least you deserve some form of compensation for thinning their numbers." }
WordHunterWoW_QuestEN[11662] = { title = "Seek Out Karuk!", description = "A fellow survivor of Pal'ea known as Karuk has made his way to the main base of the Kvaldir in the Borean Tundra - far to the south where the snow was once bountiful. Karuk hides along the bluffs overlooking Riplash Strand.\n\nSeek out Karuk and let him know what you did for my people here at the Coast of Echoes.\n\nThe safest route to Karuk is through your fortress. From Warsong Hold, take the road south and follow it around until you reach Riplash Strand.", objectives = "Seek out Karuk at Riplash Strand.", completion = "Waltor was wise in sending you to me, <race>. The gods smile down upon those that mete justice. You will be he that doles out punishment to the wicked!" }
WordHunterWoW_QuestEN[11663] = { title = "Sharing Intelligence", description = "Thank you, {class}! The information you've extracted is of vital importance to the Kirin Tor.\n\nReturn at once to Donathan as we make plans for the rescue of Lady Evanor.", objectives = "Normantis has asked you to report to Librarian Donathan on Amber Ledge.", completion = "Forgive me, <name>. I know that was unpleasant work.\n\nWere it not for the desperation of our circumstance I'd never have asked you to assist us in such a manner.\n\nSo... what have you discovered?" }
WordHunterWoW_QuestEN[11664] = { title = "Escaping the Mist", description = "I can hear the mist creatures outside. Their yells are driving me mad, but I dare not try to escape. And where would I even go? How long would it be until they caught up with me and executed me like the others?\n\nI wonder, how far has the mist crept, stranger? Has it overtaken this whole continent?\n\nWould you be willing to help me try and escape the mist? I think I can lead us back toward my father. I still sense his life spirit. He is close.", objectives = "Follow Mootoo the Younger out of the mist. Speak to Elder Mootoo should you successfully save Mootoo the Younger.", progress = "You found my daughter?", completion = "It is whispered in the winds, friend. Your name is known to the elements. You have done a great service to Mootoo on this day and you shall be rewarded." }
WordHunterWoW_QuestEN[11665] = { title = "Crocolisks in the City", description = "Hello lad.  I'm glad you've stopped by to talk to this old man--there's trouble back home.\n\nA traveling merchant recently sold a batch of baby crocolisks to some gullible children.  Crocolisks are wild beasts, and many have escaped and now lurk in city waterways.\n\nGrab your strongest fishing pole and drop a line in Stormwind or Orgrimmar and bring one of the little devils back to me.  I'm anxious to see one.", objectives = "Bring a Baby Crocolisk to Old Man Barlo. You can find him fishing northeast of Shattrath City by Silmyr Lake.", progress = "Catch any crocs in the sewers yet?", completion = "What a mean little creature!  I'm sure the Rokk will make something tasty with him.\n\nI'm just kidding, of course.\n\n<Old Man Barlo winks slyly.>" }
WordHunterWoW_QuestEN[11666] = { title = "Bait Bandits", description = "You probably know all about the golden darter--they're fairly common in the rivers of Terokkar Forest and a delicacy for priests.  But here's one you haven't heard of: the blackfin darter.\n\nThe fish is notoriously crafty and difficult to catch.  You have to pull your line at the last possible second, because they nibble at the bait before they take it.\n\nDrop your line in the rivers of Terokkar and bring me a blackfin darter.  Avoid the lakes, as the blackfin only thrive in moving water.", objectives = "Bring a Blackfin Darter to Old Man Barlo. You can find him fishing northeast of Shattrath City by Silmyr Lake.", progress = "How's the fishing today, lad?", completion = "Well look at that... you caught a big one!  This old man is eating in style tonight." }
WordHunterWoW_QuestEN[11667] = { title = "The One That Got Away", description = "Figluster's mudfish is a surprisingly quick bottom feeder found in the waters of Nagrand.  They grow their entire lives and are well known as fighters.\n\nYears ago, I caught what I'm certain was the world's biggest mudfish... until it snapped my line and escaped.\n\nA fisherman of your caliber doesn't need to be told what to do--your destiny awaits in the lakes of Nagrand.", objectives = "Catch the World's Largest Mudfish and bring it to Old Man Barlo. You can find him fishing northeast of Shattrath City by Silmyr Lake.", progress = "Tell me you caught him.  Please tell me you caught that son of a carp.", completion = "There he is!  I'd know that scar anywhere.\n\nTo be completely honest, I thought he'd be... bigger.  Well, I suppose I'll let him go and try again another day." }
WordHunterWoW_QuestEN[11668] = { title = "Shrimpin' Ain't Easy", description = "There's a lot of big fish in the Zangarmarsh lakes.  Ever wonder what they eat?\n\nShrimp.  Giant freshwater shrimp.  The Rokk tells me the dishes you can make with shrimp are nearly endless.\n\nBut shrimp are too small to catch with a fishing line.  So here's the trick: cut open the bloated barbed gill trout and you'll find a shrimp or two if you're lucky.", objectives = "Bring 10 Giant Freshwater Shrimp to Old Man Barlo. You can find him fishing northeast of Shattrath City by Silmyr Lake.", progress = "What's the catch of the day, lad?", completion = "You are skilled with both the hook and knife.  Hand those sweet tidbits over, and I'll let you have a taste." }
WordHunterWoW_QuestEN[11669] = { title = "Felblood Fillet", description = "This old man is going hunting soon.  I'm gonna take down a mammoth shark off the coast of Azshara.\n\nThe thing is, I need a toxin that'll stay on a spear tip while it's underwater.  To make that kind of stuff, I need the glands from a poisonous fish: the felblood snapper.\n\nSuch a vile fish only thrives in the waters of Hellfire Peninsula and Shadowmoon Valley.  Bring me back a whopper and I'll be a happy old man.", objectives = "Bring a Monstrous Felblood Snapper to Old Man Barlo. You can find him fishing northeast of Shattrath City by Silmyr Lake.", progress = "The felblood is a marvel of evolution.  It can survive in any water and even lava, and fishermen are its only natural predator.\n\nAny luck with your prey?", completion = "That is the biggest, ugliest fish I've seen.  I can't even imagine what you used for bait.\n\nJust set the beast on the ground, and I'll deal with it once I'm sure it's dead." }
WordHunterWoW_QuestEN[11670] = { title = "It Was The Orcs, Honest!", description = "With all of those outfits you, er, recovered, I fashioned a Warsong orc disguise. I had the genius idea of combining it with some old stuff that I had left hanging around from last Hallows' End, so it should be foolproof!\n\nHere, in this sack is the disguise and the banner you recovered. Head down into the bowels of Magmoth and slay the magnataur chieftain, Magmothregar.\n\nIf you're going to convince them to turn their attention on the Warsong orcs, you'll need to plant the banner while disguised.", objectives = "While disguised as a Warsong orc, plant the Warsong Banner in the corpse of Magmothregar. Then, return with the disguise to Crafty Wobblesprocket at Fizzcrank Airstrip.", progress = "It's all over then? You've done the dirty deed and framed the orcs at Bor'gorok Outpost?", completion = "Holey moley, you did it!\n\nAlright, now those pesky magnataur and their snobold flunkies should turn their attentions on the Horde.\n\nHow can I ever repay you, <name>?" }
WordHunterWoW_QuestEN[11671] = { title = "A Race Against Time", description = "So it's true. They have her.\n\nIt's clear what must be done, {race}. She WILL be saved.\n\nI must remain here and aid in the rescue preparations. I call upon you again; this time to collect the prison key. All we know of this Salrand figure is that she cannot be harmed so long as her shield is intact.\n\nWe've customized a special explosive that should strip her of this protection, allowing you to perform your duty. Return to me when you've collected the key.\n\nHurry, {name}. Lady Evanor is suffering!", objectives = "Donathan on Amber Ledge has tasked you with using the Beryl Shield Detonator to bring down the shield at Beryl Point. You are then to defeat Salrand and collect the key she holds.", progress = "Have you collected Salrand's key?", completion = "Broken? \n\nLet me have a look...." }
WordHunterWoW_QuestEN[11672] = { title = "Enlistment Day", description = "You've come to enlist, right?  Normally you'd have to stand in line like the other recruits.  Normally you'd be out of luck because the recruitment ledger's gone missing and I can't process anyone until the new books get here.\n\nFortunately for you, {name}, I've heard about you and what you did in Outland.  To be honest, you're a cut above these poor saps.  Lines aren't for you.\n\nGo to the barracks and speak to General Arlos.  He'll be more than happy to meet with someone of your caliber.", objectives = "Meet with General Arlos inside the barracks in Valiance Keep.", completion = "We've been expecting your arrival, <name>.  Welcome to Northrend." }
WordHunterWoW_QuestEN[11673] = { title = "Get Me Outa Here!", description = "I knew they'd send someone for me sooner or later... turned out to be later, of course.\n\nI came in here to parlay with the snobolds, but their main shaman, Kaganishu, decided instead that I'd make a tasty snack for Magmothregar.\n\nWait... what?! They didn't send you?!\n\nDID THEY FORGET ABOUT ME?!\n\nOkay, you're here now and that's all that matters.\n\nAs soon as you break this chain we'll make our way back to the airstrip. Then you can tell Fizzcrank I'm safely back.\n\nIf he remembers me, that is.", objectives = "Escort Bonker Togglevolt to safety and then report in with Fizzcrank Fullthrottle at Fizzcrank Airstrip.", completion = "Huh? What?\n\nBonker who?\n\nI've no idea who you're talking about, but I'll take your word for it. If you rescued him or her from the pit of Magmoth then I suppose you deserve a reward.\n\nLet me see what I've got lying around in here...." }
WordHunterWoW_QuestEN[11674] = { title = "Sage Highmesa is Missing", description = "There are many new mysteries walking the lands now. One of our sages, Highmesa, has foolishly gone north with only one longrunner to investigate something strange near the Dens of Dying.\n\nWhat are the dens, you ask? They are a sacred place to the magnataur, where they go in their old age to die. She saw something fall from the sky near them a few days ago.\n\nIf you would be friend to the taunka, I would have you find and help her. She is not so stubborn that she will not accept your aid.", objectives = "Find Sage Highmesa near the Dens of Dying.", completion = "The greatmother sent you. She must be disappointed in me.\n\nBut when I saw the great object fall from the sky, I could not wait for a full group of longrunners and snow trackers to accompany me. Knowledge waits for no one." }
WordHunterWoW_QuestEN[11675] = { title = "A Proper Death", description = "The magnataur at the Dens of Dying have contracted a plague. We must find the cause, but first we must put them out of their misery.\n\n{race}, you must go north onto the slopes in front of us and destroy as many of the poor creatures as you can.", objectives = "Destroy 10 Plagued Magnataur and then return to Sage Highmesa south of The Dens of Dying.", progress = "I still see too many of them for your efforts to have been very effective. A true <class> would finish the job.", completion = "What else can we do but ease their suffering? In any case, they came here to die, so do not mourn them. At least you have given them some dignity.\n\nNow we must put an end to that which is causing the plague." }
WordHunterWoW_QuestEN[11676] = { title = "Merciful Freedom", description = "The soldiers that they didn't kill are being held in cages scattered across this farmland. Through some thievery we've managed to find a few keys, but we're unable to get close enough to any prisoners without being attacked.\n\nWe need your \"talents\" in securing those keys and freeing the prisoners. Bash in the brains of the necrolords and aberrations and take their keys. Use those keys to free Scourge prisoners.", objectives = "Shadowstalker Canarius at Warsong Farms Outpost wants you to free 5 Scourge Prisoners.", completion = "Each prisoner saved is one less undead aberration that we have to deal with, <name>. You've done a great service for the Horde." }
WordHunterWoW_QuestEN[11677] = { title = "Stop the Plague", description = "I'm convinced that the plague is being caused by something in the caves up there.\n\n{class}, I want you to take these seeds. I normally use them as a ward against the Scourge, though perhaps they can be used to disrupt whatever foulness is happening in the dens.\n\nFind the source of the plague and throw them into it.", objectives = "Sage Highmesa, standing just south of The Dens of Dying, has asked you to use Highmesa's Cleansing Seeds at a Den of Dying Plague Cauldron to neutralize it.", progress = "Either cave should do, <class>. Quickly, use the seeds to end the plague!", completion = "<The sage hangs her head and sighs in relief.>\n\nThis is a good start. If only that were our only problem." }
WordHunterWoW_QuestEN[11678] = { title = "Find Bristlehorn", description = "Bristlehorn should have returned by now.\n\nThe other reason why we came up here was to investigate that Scourge structure to the west, which fell from the sky. He's impetuous and has likely gotten himself into trouble.\n\n{name}, go to that place and find him, please.", objectives = "Find Longrunner Bristlehorn at Talramas.", completion = "I am... not... long for this... world, little <race>." }
WordHunterWoW_QuestEN[11679] = { title = "Reforging the Key", description = "Delays, delays... the one thing we cannot afford right now!\n\nAs much as I hate to disturb Lord Surristrasz, he's our only hope of saving our beloved Evanor.\n\nBring him the key fragments and hope that his mood is favorable.\n\nHurry, {class}, our assault team is waiting.", objectives = "Donathan wants you to speak to Surristrasz on Amber Ledge.", progress = "You dare approach me, mortal?\n\nFor the sake of your unborn children, pray that your cause is worthwhile.", completion = "The frivolous games you play here are of no consequence....\n\nYou and your Dalaran allies pick at loose threads while the fabric of this world's future is being shredded.\n\nStill, this may provide my drakes some needed amusement.\n\nShow me this key...." }
WordHunterWoW_QuestEN[11680] = { title = "Taking Wing", description = "The key is forged anew.\n\nNow heed my counsel, {race}. Succeed in your endeavor or die trying, for if a single scale falls from one of my drakes I shall hold you personally accountable.\n\nNow, off with you.", objectives = "Give Salrand's Key to Warmage Anzim when you are ready to free Evanor.\n\nProvided item:", completion = "This is it, the key is ours!" }
WordHunterWoW_QuestEN[11681] = { title = "Rescuing Evanor", description = "At last, we attack!\n\nOnce we've cleared the platform I'll use the key.\n\nYou are to ensure that Lady Evanor remains safe after her release.\n\nHurry now, let us be off!", objectives = "Anzim on Amber Ledge wants you to fly with his war mages to free Lady Evanor at Beryl Point. You are then to report to her in the mage tower on Amber Ledge.", completion = "Your heroic efforts shall not be forgotten, <class>.\n\nPlease, accept this with my sincere gratitude." }
WordHunterWoW_QuestEN[11682] = { title = "Dragonspeak", description = "I am aware of your recent deeds here, {name}, and again I thank you.\n\nAs for this local menace, we've learned all we need to know from them. They'll be dealt with in short order. On now to more important issues....\n\nAzeroth needs you. The region just west of here is the center of an urgent crisis.\n\nI'll leave the details to Lord Surristrasz. You must speak with him at once.\n\nGood luck, friend of Dalaran.", objectives = "Lady Evanor has sent you to speak with Surristrasz on Amber Ledge.", completion = "So, <race>, we speak again.\n\nWhen you've heard my words you may wish we had not." }
WordHunterWoW_QuestEN[11683] = { title = "Fallen Necropolis", description = "The fallen necropolis to the west can only be assumed to still be filled with Scourge.\n\nWhile you are at Talramas, {class}, I would ask that you dispatch all of the Lich King's servants that you find within and in the surrounding pools where it fell.", objectives = "Destroy 20 Scourge of any type at Talramas and the Festering Pools. Then, return to Sage Highmesa just to the south of The Dens of the Dying.", completion = "Thank you, <name>.\n\nThe Lich King and his Scourge are a blight upon Northrend. We must not stop until they are all truly dead, and his existence is put to an end!" }
WordHunterWoW_QuestEN[11684] = { title = "Scouting the Sinkholes", description = "Can you feel the tremors in the earth?\n\nThe Scourge's nerubians are on the move deep beneath the ground. They've emerged to the southwest in the Geyser Fields, and are harassing the patrols Chieftain Wintergale sent out.\n\n<The taunka elder offers you a worn map.>\n\nPerhaps a single person can succeed where the patrols have failed. Take this with you to the Geyser Fields and map out the locations of the Nerubian sinkholes.", objectives = "Greatfather Mahan at Taunka'le Village wants you to use the Map of the Geyser Fields to mark the locations of the South Sinkhole, the Northwest Sinkhole, and the Northeast Sinkhole.", progress = "Have you marked the locations of the sinkholes?", completion = "<Greatfather Mahan accepts the map, but makes no move to examine it..>\n\nWe'll be able to use your information later, once we're prepared to carry out the plan." }
WordHunterWoW_QuestEN[11685] = { title = "The Heart of the Elements", description = "Now that we know the exact locations of the nerubian sinkholes, we can collapse them to halt the Scourge offensive and cripple their force. Wind Tamer Barah knows a way to harness elementals to destroy the tunnels the Nerubians are using, but she will require your help.\n\nSoutheast of the village, near the coast beyond the Frozen Reach, you'll find an area dominated by frozen earth elementals. The hearts of these elements are exactly what Wind Tamer Barah will need.", objectives = "Bring 5 Elemental Hearts to Wind Tamer Barah at Taunka'le Village.", progress = "Greatfather Mahan tells me you have agreed to help collapse the tunnels.", completion = "These should be enough to form the core of a mighty elemental, but stone alone will not give my elemental life." }
WordHunterWoW_QuestEN[11686] = { title = "The Warsong Farms", description = "According to Luther's notes the Scourge is now using this place as a breeding ground for those monsters you see lumbering across the field.\n\n<Ickoris shudders.>\n\nThose monsters were once orcs... tauren...\n\nWe need more information before a plan can be devised. I want you to investigate three sites that are heavily trafficked by Scourge: the Warsong Granary, southwest of us, Torp's Farm, directly west of us, and the old Warsong Slaughterhouse, north of us.\n\nReturn to me once you've scouted 'em out.", objectives = "Shadowstalker Ickoris at Warsong Farms Outpost wants you to scout Warsong Granary, Torp's Farm, and Warsong Slaughterhouse.", progress = "Have you searched the farms?", completion = "This is far worse than what was noted in Luther's journal. They've got this place covered in Scourge and are infecting everything they touch.\n\n<Ickoris nods.>\n\nIt gets worse - if you can imagine such a thing..." }
WordHunterWoW_QuestEN[11687] = { title = "The Doctor and the Lich-Lord", description = "There are two... that must... be killed.\n\nThe doctor and... the lich-lord... are above. Find them... destroy them... before....\n\n...it is too... late....", objectives = "Destroy Doctor Razorgrin and Lich-Lord Chillwinter. Then, return to Sage Highmesa just to the south of The Dens of Dying.", completion = "Bristlehorn is dead?!\n\nI should never have let him go there by himself." }
WordHunterWoW_QuestEN[11688] = { title = "Damned Filthy Swine", description = "Just look at 'em! My beautiful kodos are helpless to defend themselves against those filthy swine! I need you to buy me some time, {race}. I think I can cure the kodo of the sickness, but you need to keep the unliving swine off 'em, else there'll be nothin' left to cure!\n\nGet out there and send those swine to their graves - permanently!", objectives = "Farmer Torp at Warsong Farms Outpost wants you to kill 10 Unliving Swine.", progress = "I need more time! Keep those swine off my kodos!", completion = "I think I've got it, <race>!" }
WordHunterWoW_QuestEN[11689] = { title = "Return with the Bad News", description = "The greatmother will need to know, {name}.\n\nWill you please return to Taunka'le? Tell her that I will be following shortly.", objectives = "Speak with Greatmother Taiga at Taunka'le Village.", completion = "What word do you bring from Highmesa?\n\n<You explain what you know and give the greatmother the bad news concerning Longrunner Bristlehorn.>\n\nMy... my grandson!\n\n<The greatmother fights to keep control of her emotions.>\n\nHe died an honorable death like a true taunka!\n\nYou were the last to be with him, <name>, so he shall always be a part of you. I give you my thanks for completing his last wishes." }
WordHunterWoW_QuestEN[11690] = { title = "Bring 'Em Back Alive", description = "Take this riding snaffle, {name}. You'll notice that I've placed a tiny medicine dispenser in the mouthpiece. That thing will cure the infection as soon as a kodo bites down. Once you've cured the sick out of 'em, you'll need to ride 'em home. They'll be weak so you'll need to gently direct 'em here.\n\nBring my babies back, {name}!\n\nOne last thing, you've got ten minutes! That's how long the antidote will remain effective inside that snaffle.", objectives = "Farmer Torp at Warsong Farms Outpost wants you to rescue 8 Infected Kodo Beasts.", progress = "Get them out of those Scourge infested fields!", completion = "You're a true hero, <name>. My kodos would have died out there without you. You have my thanks and the thanks of all the soldiers and journeymen that will use these kodos to strengthen our presence in Northrend!" }
WordHunterWoW_QuestEN[11691] = { title = "Summon Ahune", description = "I and my Shamans have gathered our powers for the coming battle with the Lord of Frost.  {name}, you will be the fist of the Earthmother.\n\nTake this magma totem.  Use it against the Ice Stone, to the northeast.  Ahune is channeling his power through this stone; it is our hope that the totem will disrupt him and cut off his link to the elemental planes.\n\nIf fortune is with us, then, perhaps, we can defeat him.\n\nPrepare yourself, {name}.  If Ahune comes to face us, then his fury will be great.", objectives = "Bring the Earthen Ring Magma Totem to the Ice Stone." }
WordHunterWoW_QuestEN[11692] = { title = "Check in With Bixie", description = "You're a proven hero. I have another problem!\n\nMy boss, Tinky, went east with Bixie Wrenchshanker and I CAN'T get the outgoing on this thing to work! Tinky's the only one that can fix it and we really need it working one-hundred percent.\n\nYou think you could find them? Bixie said something about following some old magnataur to a place called The Dens of Dying.\n\nI'm guessing that's where you'll find them.\n\nYou can catch a ride out there by talking with Kara Thricestar at the runway.", objectives = "Mordle Cogspinner has asked you to find Bixie Wrenchshanker to the south of The Dens of Dying.", completion = "What do you need, <class>?" }
WordHunterWoW_QuestEN[11693] = { title = "Oh Great... Plagued Magnataur!", description = "Tinky and I came out here stalking some old magnataur. Apparently those caves up there are where they go to die.\n\nOf course, we had no idea that they were going to get plagued when they went in there. We can't have plagued things just roaming about; it's not healthy.\n\nSay, why don't you put down a number of those things while I figure out what our next step should be?", objectives = "Kill 10 Plagued Magnataur and then return to Bixie Wrenchshanker to the south of The Dens of Dying.", progress = "Doesn't look like enough of the plagued magnataur have been put down yet, <class>.\n\nThink you could take care of a few more before coming back?", completion = "Nice work, but I'd grab a shower the next chance you get.\n\nNow, let's really deal with the problem out here." }
WordHunterWoW_QuestEN[11694] = { title = "There's Something Going On In Those Caves", description = "So, while you were out taking care of those plagued beasts, I took a peek inside the caves up there.\n\nThere are cultists in there plaguing them!\n\nThey have some sort of noxious concoction brewing in a cauldron. I have a powder that I normally use as an anti-poison, and I mixed it up with some other stuff. I think it'll neutralize their brew!\n\nTake it up to one of those caves and see if it works.", objectives = "Bixie Wrenchshanker, skulking just to the south of The Dens of Dying, has asked you to use Bixie's Inhibiting Powder at a Den of Dying Plague Cauldron to neutralize it.", progress = "Time's wasting, <class>. The last thing we need is to have to face plagued magnataur.\n\nThe normal ones are bad enough as it is!", completion = "I knew you had it in you. Now there's something else that I need to ask you to take care of." }
WordHunterWoW_QuestEN[11695] = { title = "The Horn of Elemental Fury", description = "I can fashion the likeness of an elemental from these pieces of inanimate stone, but breathing life into it is different. For that, we'll need help and a bit of luck.\n\nLegend tells of an ancient artifact called the Horn of Elemental Fury, sought after by a great hero. I'll lend you a scroll with a copy of the tale. I don't know if the legend is true, but it's our best bet. If the legend is right, the parts of the horn may be in the Flood Plains surrounding the village to the north and southwest.", objectives = "Reclaim the Lower Horn Half and Upper Horn Half from Chieftain Burblegoggle and Chieftain Gurgleboggle and bring them to Wind Tamer Barah at Taunka'le Village.", progress = "Were you able to find the horn? Was the legend true?", completion = "<Barah accepts the pieces of the horn from you and begins trying to fit them together.>\n\nStormhoof would be proud of you, <name>. Perhaps when we've dealt with the Scourge, I will take the horn with me on a pilgrimage to Stormhoof's tomb." }
WordHunterWoW_QuestEN[11696] = { title = "Ahune is Here!", description = "{name}, your presence is a blessing.  Ahune lies within these caverns, gathering strength for his assault.  Earthen Ring forces were sent ahead, but they alone cannot defeat him.\n\nExplore, {name}.  Find our Earthen Ring Shamans and speak with their leader, Luma Skymother.  Perhaps, with your added strength, we can beat Ahune before it's too late.", objectives = "Find Luma Skymother in the Slave Pens.<name>, your presence is a blessing. Ahune lies within these caverns, gathering strength for his assault. Earthen Ring forces were sent ahead, but they alone cannot defeat him.\n\nExplore, <name>. Find our Earthen Ring Shamans and speak with their leader, Luma Skymother. Perhaps, with your added strength, we can beat Ahune before it's too late.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[11697] = { title = "Rats, Tinky Went into the Necropolis!", description = "I told Tinky not to go off on her own, but she just HAD to check out that crashed necropolis to the west.\n\nI'm 100% certain that those cultists came from inside that thing, which means I'm now 100% certain that Tinky's in trouble!\n\nShe's the airstrip's number one engineer. Without her we're doomed!\n\nI'd find her myself, but one of those things got in a swipe on my leg before I could vanish again. {name}, if anyone can get her out, it's you!", objectives = "Find Tinky Wickwhistle inside Talramas.", completion = "Hey there! Who are you?\n\nBixie sent you? Excellent, let's get me out of here!" }
WordHunterWoW_QuestEN[11698] = { title = "Might As Well Wipe Out the Scourge", description = "If the cultists up in those caves survived the crash, then that fallen necropolis to the west can only be assumed to still be filled with Scourge. There're probably lots of them out in front of it in the pools, too!\n\nWhile you're at Talramas, {class}, do you think you could dispatch all of the Lich King's flunkies that you find there?", objectives = "Destroy 20 Scourge of any type at Talramas and the Festering Pools. Then, return to Bixie Wrenchshanker just to the south of The Dens of the Dying.", progress = "There's no way that you could have killed so many Scourge in such a short time!", completion = "Thanks, <name>.\n\nThe Lich King and his Scourge are really scary, but we can't stop until they are all lying still in new graves!" }
WordHunterWoW_QuestEN[11699] = { title = "I'm Stuck in this Damned Cage... But Not For Long!", description = "The cultists magicked me into this cage and there's no door to it. Little did they know that I'm the chief transmatter engineer for the airstrip!\n\nWith your help, and a little elbow-grease, I won't be in here for long.\n\nI'm going to need an engine-core crystal from one of the ghouls in here, a magical gyroscope from their doctor, and a piloting scourgestone from the lich-lord up top.\n\nWith all of that stuff, I should be able to make a port device to get back to Fizzcrank's and escape the gnome way!", objectives = "Collect an Engine-Core Crystal, a Magical Gyroscope, and a Piloting Scourgestone. Deliver them to Tinky Wickwhistle at Talramas.", progress = "You got all of that stuff?", completion = "Outstanding! Now just a little modification here, and a tweak there...." }
WordHunterWoW_QuestEN[11700] = { title = "Let Bixie Know", description = "My evil twin's out there somewhere now.\n\nI'm pretty sure that she's not back at the airstrip. In fact, wherever she ended up, it's colder there than here. But I could only 'feel' her for a moment.\n\nOh well, I'll reconfigure this thing and port myself back to the airstrip soon enough. In the meantime, do you think you could go east and let Bixie know that I'll meet her back there?\n\nThanks, {name}!", objectives = "Speak with Bixie Wrenchshanker just south of The Dens of Dying.", completion = "Tinky's got an evil twin?!\n\nWell, if she says she's okay, and that she'll be able to get herself back to the airstrip soon, that's good enough for me." }
WordHunterWoW_QuestEN[11701] = { title = "Back to the Airstrip", description = "Okay, I think I'm going to start making my way back to the airstrip, too. Of course, I'm moving a little slower with this leg injury.\n\nSay, do you think you could get there ahead of me and pass on the good news to Ol' Fizzcrank? I bet anything that there'll be a reward in it for you.\n\nThanks, {name}!", objectives = "Speak with Fizzcrank Fullthrottle at Fizzcrank Airstrip in Borean Tundra.", completion = "That's quite a tale, <name>. With all of the problems out here, it's a wonder that the airstrip hasn't been wiped out already.\n\nBut, thanks to you, there's one less adversary to worry about.\n\nI put aside some special things for just such an occasion as this. Why don't you take your pick?" }
WordHunterWoW_QuestEN[11702] = { title = "King Mrgl-Mrgl", description = "Dis is gonna sound weird, {class}, but dere be a murloc askin' for our help!\n\nHe goes by da name of King Mrgl-Mrgl, leader of da Winterfin murlocs. Him and his people been run outa dere village and wantin' you to come save dem.\n\nYou find him by headin' west and go down da cliffs. He hangin' out on da south side of da Winterfin Retreat.", objectives = "Speak with King Mrgl-Mrgl at Winterfin Retreat.", completion = "Finally, help! And by the looks of you, Horde.\n\nThat's alright... your people are very skilled in the art of combat. We're going to need a lot of that." }
WordHunterWoW_QuestEN[11703] = { title = "Get to Getry", description = "The Scourge agent that's overseeing the abduction and transformation of Horde soldiers into undead monsters is using the northwest farm as a spawning glade. Shadowstalker Getry has been staking out that monster for the past week and has gathered some vital information that might allow us to end this menace.\n\nGet to Getry and see if you can help him put a stop to this Scourge assembly line. You'll find Getry at the abandoned tower on the northwest border of these farms.", objectives = "Find Shadowstalker Getry at Warsong Farms.", completion = "<Getry looks you over.>\n\nThis is all Ickoris could send?" }
WordHunterWoW_QuestEN[11704] = { title = "King Mrgl-Mrgl", description = "This is the weirdest thing, {class}, but there's a murloc asking for our help!\n\nHe goes by the name of King Mrgl-Mrgl, leader of the Winterfin murlocs. It would seem that he and his people have been run out of their village and they want someone to come save them.\n\nThat someone is you!\n\nYou'll find Winterfin Retreat, and the king, by heading west down the road until you come to the cliffs. Head down to the water line near the Blistering Pool.", objectives = "Speak with King Mrgl-Mrgl at Winterfin Retreat.", completion = "Finally, help! And by the looks of you, Alliance.\n\nThat's good... your people are very skilled in the art of combat. We're going to need a lot of that." }
WordHunterWoW_QuestEN[11705] = { title = "Foolish Endeavors", description = "This is madness. How do they expect us to take on a Scourge necrolord and an unknown number of his minions?\n\n<Getry sighs.>\n\nIf Ickoris sent you he must think that you are capable of great feats. Perhaps you will call down a miracle today, eh?\n\nWhen you're ready we will descend and face Varidus.\n\nIf we make it out of this mess in one piece, report back to Hellscream in Warsong Hold.", objectives = "Help Getry defeat Varidus the Flenser at Warsong Farms.\n\nReport to Garrosh Hellscream should you succeed.", completion = "And you returned victorious, just as I thought! I told Saurfang you'd be fine.\n\n<Hellscream grunts knowingly.>\n\nPerhaps this will show that old dog that he doesn't have all the answers, eh?" }
WordHunterWoW_QuestEN[11706] = { title = "The Collapse", description = "I have created and bound Alluvius using the Horn of Elemental Fury. He will respond to the horn's call when you stand near the southernmost sinkhole in the Geyser Fields.\n\nThe quake Alluvius will unleash should collapse the Nerubian tunnels and put an end to their flanking attack. I wouldn't be surprised if the Nerubian commander showed himself after the quake. If the collapse of the tunnels doesn't break the back of their assault, the defeat of their leader surely will.", objectives = "Wind Tamer Barah at Taunka'le Village wants you to collapse the Nerubian sinkholes using the Horn of Elemental Fury and defeat Lord Kryxix.", progress = "Have you unleashed Alluvius and destroyed the Nerubian assault?", completion = "Your efforts against the Nerubians have given us a reprieve from the overwhelming Scourge assault. Thanks to your accomplishments, we can strike at the Scourge fortress to the northeast without fear of attack from the west.\n\nAs for the horn, I will safeguard it until next we need its power. Stormhoof gave his life to secure the horn and we cannot suffer its loss again." }
WordHunterWoW_QuestEN[11707] = { title = "Distress Call", description = "Oh good, you're {name}, right?\n\nWe need your help up north at Fizzcrank Airstrip, like yesterday! The magnataur, and the Scourge... and the pumping station!\n\nIt's madness I tell you, madness!\n\nYou've got to head up there and talk to old man Fullthrottle a.s.a.p.!", objectives = "Speak with Fizzcrank Fullthrottle at Fizzcrank Airstrip.", completion = "I see that Skyhopper finally got around to sending help. And none too soon I might add!\n\nWelcome, brother, we need your help badly!" }
WordHunterWoW_QuestEN[11708] = { title = "The Mechagnomes", description = "Now that you're here, it's time for me to tell you the full story of what's going on.\n\nAfter you've heard my tale, go outside and find my second-in-command, Jinky Wingnut. She'll handle everything from here on out.", objectives = "Listen to Fizzcrank Fullthrottle's tale and then find Jinky Wingnut at Fizzcrank Airstrip.", progress = "Hello there.", completion = "The old man sent you to me, huh? He tell you everything that's going on out here?\n\nGood... let's take care of business then!" }
WordHunterWoW_QuestEN[11709] = { title = "Nork Bloodfrenzy's Charge", description = "While you have done much to secure our foothold in these frozen wastes, other dangers still lurk in the shadows. I want you to assist Warden Nork Bloodfrenzy, stationed at the internment camp just outside and immediately southeast of Warsong Hold. Seek him out and offer your assistance for prisoner transport and exchange.\n\nYou are dismissed, {name}. ", objectives = "Speak to Warden Nork Bloodfrenzy at Warsong Hold in Borean Tundra.", completion = "<Nork scoffs.>\n\nPrisoners? These aren't prisoners. They're cowardly dogs! Just look at 'em. Did you know that without exception, every single one of these yellow-bellied \"soldiers\" came to our gates and surrendered their arms and armor?\n\nFrom what we've been able to gather, these men and women are discharged and sent back to their homes if captured by us.\n\n<Nork spits.>\n\nPathetic..." }
WordHunterWoW_QuestEN[11710] = { title = "What's the Matter with the Transmatter?", description = "There're spare parts strewn all over to the east in the Scalding Pools, the Geyser Fields... heck, probably even up on the pumping station still, too. Bring back a whole bunch. Maybe then I'll be able to get outgoing teleport on this thing working, not to mention getting the incoming transmatter ports aligned.\n\nI'd hate to see another accident....", objectives = "Collect 15 Fizzcrank Spare Parts and deliver them to Mordle Cogspinner at Fizzcrank Airstrip.", progress = "It's going to take a lot of spare parts to keep this thing running.\n\nPlease tell me that you've returned with everything we need.", completion = "That's great, <class>! These parts look like they're in serviceable condition.\n\nNow if I could only figure out how to fix this blasted thing...." }
WordHunterWoW_QuestEN[11711] = { title = "Coward Delivery... Under 30 Minutes or it's Free", description = "We're seeing more deserters show up at our gates with each passing day. We simply do not have enough room to keep all of these maggots caged up. Especially not if we want to keep the pigs happy.\n\n<Nork snorts as he laughs.>\n\nI want you to escort one of these cowards to the crossroads east of here and fire this flare gun. One of their captains will show up when they see the flare and take the coward off your hands.\n\nReport to Scout Tungok on the east road once the delivery has been made.\n", objectives = "Take the Alliance Deserter to the crossroads east of Warsong Hold and fire your Warsong Flare Gun to signal the Alliance.\n\nReport to Scout Tungok once you have successfully delivered the Alliance Deserter to their destination.", progress = "<Tungok grunts.>\n\nDid you take care of the deserter?", completion = "Good job, <name>. That's one less filthy, useless, Alliance scum-bag that we'll have to provide for...\n\nIf you're lookin' for more work, the tauren and blood elf nearby need some help.\n\n'Course we've got our own set of problems to deal with out here as well..." }
WordHunterWoW_QuestEN[11712] = { title = "Re-Cursive", description = "If you listened to the old man, then you know that we have gnomes out there that were changed. Gearmaster Mechazod infected them with something that reversed the \"Curse of the Flesh\", and now they're robots!\n\nWe think we have a way to re-curse them back to normal. We want you to take this re-cursive transmatter injection and use it on the corpses of any mechagnomes you come across.\n\nWe're hoping that this stuff will cure them and allow us to lock onto them to port 'em out of there.\n\nWhaddya say, {name}?", objectives = "Jinky Wingnut at Fizzcrank Airstrip has asked you to use the Re-Cursive Transmatter Injection on 6 Fizzcrank Mechagnomes.", completion = "You did it... it worked!\n\nI can't believe you were able to save so many. We're fortunate to have you around here!" }
WordHunterWoW_QuestEN[11713] = { title = "Scouting the Sinkholes", description = "Fizzcrank sent out an aerial surveillance team to map the Nerubian sinkholes in the southern part of the Geyser Fields, but they haven't yet returned. I can't afford to wait any longer for their information, so I'm going to need someone to check out the sinkholes on foot.\n\nI understand the dangers involved, and I'll compensate you accordingly. Take this map with you and record the vital information about each of the sinkholes you encounter out there.", objectives = "Abner Fizzletorque at Fizzcrank Airstrip wants you to use the Map of the Geyser Fields to mark the locations of the South Sinkhole, the Northwest Sinkhole, and the Northeast Sinkhole.", progress = "Have you marked the locations of the sinkholes?", completion = "<Abner accepts the map from you, then examines it closely.>\n\nGreat! This is all the information we need to begin the operation." }
WordHunterWoW_QuestEN[11714] = { title = "Vermin Extermination", description = "Perhaps you'd be interested in helping me clean up these fields? They're littered with dirty little rat men! Kobolds, snobolds, whatever you wanna call 'em, they're all over the damned place. The stink alone is making my life hell!\n\nTake care of the vermin for me and I'll make it worth your while, {name}.\n", objectives = "Scout Tungok at the Bloodspore Plains in the Borean Tundra wants you to kill 8 Bloodspore Harvesters, 5 Bloodspore Firestarters and 2 Bloodspore Roasters.", completion = "A job well done, <name>! Thank you!" }
WordHunterWoW_QuestEN[11715] = { title = "Fueling the Project", description = "I plan to build a machine that will collapse the tunnels the Scourge is using to deploy their Nerubians, but with the main drilling rig out of order, we'll have to collect the fuel for the device some other way.\n\nOut in the Geyser Fields to the southeast, small pools of oil bubble up away from the main rig. If you can collect enough of the oil from those pools, I can make a crude fuel to power the machine.\n\nSimply deploy the collector near the rig, and it will pump and store the oil in its tank.", objectives = "Abner Fizzletorque at Fizzcrank Airstrip wants you to collect 8 Barrels of Oil using the Portable Oil Collector.", progress = "Do you have that fuel?", completion = "<Abner sets about draining the fuel tank of the collector.>\n\nDistilling this by hand is going to be messy, but I'll have it taken care of soon. In the meantime, we'll need one more material to complete the machine." }
WordHunterWoW_QuestEN[11716] = { title = "The Wondrous Bloodspore", description = "We are witnessing something amazing here, {race}. A whole undiscovered ecology lives and breathes not more than a few paces from us! I surmise it is the bloodspore plant that sets this environment abuzz.\n\nI have collected some pollen from the nearby male species of bloodspore plant but still lack female receptors for pollination. Fetch me a bushel of the bloodspore carpels. You'll find them near the larger plants surrounding us.\n\nBe wary of their guardians! The kobolds won't give them up easily!", objectives = "Bloodmage Laurith at the Bloodspore Plains in the Borean Tundra wants you to recover 10 Bloodspore Carpels.", progress = "The tests must continue!", completion = "Lovely! Just lovely!\n\n<Laurith applies a sprinkling of pollen to one of the bloodspore carpels and then utters an incantation.>\n\nHrmph... I don't understand. Unless... Why of course!" }
WordHunterWoW_QuestEN[11717] = { title = "Pollen from the Source", description = "It's obvious! The bloodspore moths are the entities responsible for pollination on these plains. It must be something that happens within the moth's internal system that acts as a catalyst for this pollen to work. It's all starting to make sense now, {name}. That's why the kobolds don't kill the moths and instead go to great lengths to protect them! Those stupid little rats have it all figured out!\n\nWell we'll just have to get our own moth pollen! What do you say? Fetch me some in the name of science?", objectives = "Bloodmage Laurith at the Bloodspore Plains in the Borean Tundra wants you to recover 5 Bloodspore Moth Pollen.", progress = "The pollen is the key!", completion = "A-ha!\n\n<Laurith sprinkles the moth pollen onto the bloodspore carpels.>\n\nLook at that!" }
WordHunterWoW_QuestEN[11718] = { title = "A Bot in Mammoth's Clothing", description = "I've reconfigured the skeleton of an old bot to create an earthquake large enough to collapse the tunnels, but the machinery is delicate and sensitive to Northrend's biting cold.\n\nI've devised a means of insulating it using the thickest hides of the native mammoths. They roam the plains south of the airstrip and adjacent to the Geyser Fields. Bring back enough of the hides for me to finish the machine and then we'll be able to unleash it on the Nerubians!", objectives = "Abner Fizzletorque at Fizzcrank Airstrip wants you to bring him 6 Thick Mammoth Hides.", progress = "Bring those hides as quickly as possible! I won't be able to finish the machine without them!", completion = "<Abner inspects the hides, coughing at all the dust rising from them.>\n\nDon't these animals even try to keep clean? Some of these are absolutely filthy. Well, I guess I'd better get started cleaning them. It's not like anyone's got spare time around here." }
WordHunterWoW_QuestEN[11719] = { title = "A Suitable Test Subject", description = "<Laurith looks you over as if to size you up.>\n\nSo we've got this pollinated bloodspore flower and nobody to test its effects on. Say, would you perhaps be interested in rubbing this on your skin and letting me observe? What's the worst that could happen anyway?\n\nDon't you worry, {name}! Just take this sample and rub it all over your face. ", objectives = "Bloodmage Laurith at the Bloodspore Plains in the Borean Tundra has asked that you use the Pollinated Bloodspore Flower and allow her to observe the results.", progress = "Don't be afraid.", completion = "Primal Mighthorn will be delighted! This is better than even I expected!\n\nPerhaps it's time that I told you the truth." }
WordHunterWoW_QuestEN[11720] = { title = "The Invasion of Gammoth", description = "Hellscream assigned Mighthorn and I with the daunting task of magnataur extermination on the southern front of Warsong Hold. With us came an entire platoon of seasoned Horde soldiers. Our initial foray into the nearby magnataur dens proved quite unsuccessful as our entire squad was wiped out by the lair defenders. We're the only ones left...\n\nWe aren't scientists or researchers. We're soldiers of the Horde, just like you. Soldiers on a mission that cannot fail...\n\nSpeak to Primal Mighthorn now.", objectives = "Speak to Primal Mighthorn at the Bloodspore Plains in the Borean Tundra.", completion = "The bloodspore that you collected might just be enough to give us an edge against the magnataurs of Gammoth - with your help, of course." }
WordHunterWoW_QuestEN[11721] = { title = "Gammothra the Tormentor", description = "Magnataur live in prides, much like lions: one or two dominant males and several females along with their offspring. In the case of Gammoth, the magnataur den west of here, Gammothra is the leader. It is Gammothra that controls this magnataur population and therefore it is Gammothra that must be slain to prevent any type of magnataur uprising.\n\nTake this pouch of crushed bloodspore flower to Gammoth. Use the powder from the pouch to weaken Gammothra and then slay him! Return his head to me as proof.", objectives = "Slay Gammothra and return the Head of Gammothra to Primal Mighthorn at the Bloodspore Plains in the Borean Tundra.", progress = "The powder can be used to weaken all magnataur. It is why the rat men of the area guard it so closely.", completion = "A job well done, <name>! Would you honor Laurith and I by taking the head of the beast and presenting it to Hellscream? He will be extremely pleased." }
WordHunterWoW_QuestEN[11722] = { title = "Trophies of Gammoth", description = "We cannot take all of the credit for this Horde victory, {name}. It was you who risked your life to test the bloodspore and it was you who ultimately put an end to Gammothra.\n\nHonor us by returning to Warsong Hold and presenting the head of Gammothra to Lord Hellscream.", objectives = "Take the Head of Gammothra to Garrosh Hellscream in Warsong Hold.", progress = "Back so soon?", completion = "<Hellscream picks up the head of Gammothra with one arm and spits in its face.>\n\nThey will learn, <name>... They will all learn. The Horde is not to be trifled with..." }
WordHunterWoW_QuestEN[11723] = { title = "Deploy the Shake-n-Quake!", description = "Behold, the machine that will save us from the Nerubian threat!\n\n<Abner beams with pride as he presents the finished bot.>\n\nTake this remote control with you, and go out to the southernmost of the Nerubian sinkholes in the Geyser Fields. Use the remote to activate the Shake-n-Quake 5000. It will do the rest on its own.\n\nDon't be surprised if the quake it creates attracts the attention of a Nerubian leader. In fact, it would be a great opportunity to finish off the Nerubian offensive.", objectives = "Abner Fizzletorque at Fizzcrank Airstrip wants you to use the Shake-n-Quake 5000 to collapse the Nerubian tunnels and defeat Lord Kryxix.", completion = "<Abner listens eagerly as you report your success and the success of the Shake-n-Quake 5000.>\n\nFizzcrank will be delighted to hear the news! And who knows, perhaps we'll make a mechanic of you yet!" }
WordHunterWoW_QuestEN[11724] = { title = "Massive Moth Omelet?", description = "This egg was obviously important to somebody, as the corpse nearby can attest. As you look the egg over you notice that it has already been tagged for shipment to the Bloodspore Plains, care of Bloodmage Laurith. That's just east of here!\n\nCollect the egg and take it to the expectant Bloodmage.", objectives = "Take the Massive Glowing Egg to Bloodmage Laurith at the Bloodspore Plains in the Borean Tundra.", progress = "Greetings!", completion = "Alkor is no more, eh? A pity... As for the egg, we have no real use for it anymore. We've got much bigger problems to deal with now." }
WordHunterWoW_QuestEN[11725] = { title = "Finding Pilot Tailspin", description = "I should've flown the mission myself. It's not that I don't trust Tailspin. Far from it. Heck, he was the best wingman I ever flew with.\n\nNo, it's just that it's my responsibility to lead a mission of such import.\n\nI sent Tailspin out with our fastest recon squadron to gather information about the Nerubian infestation in the middle of the Geyser Fields.\n\nThe last report we received placed his squadron in the pools to the far south and just west of the Nerubian sinkholes.\n\nFind Tailspin, {name}.", objectives = "Locate Iggy \"Tailspin\" Cogtoggle in the Geyser Fields.", completion = "Thank goodness. It was terrible.\n\nThere was a bright flash on the ground, and then, the next thing I know, the squadron's going down! I'm hurt pretty badly, so I haven't had a chance to comb the site for other survivors, but something tells me I don't think there will be many.\n\n<Iggy grimaces in pain.>\n\nWill you help me complete my mission?" }
WordHunterWoW_QuestEN[11726] = { title = "A Little Bit of Spice", description = "The wolves have been pawing through the wreckage ever since the crash and I'm afraid they consumed the microfilm from our mission in the process.\n\nI have a plan to recover that microfilm, but I need your help to make it work.\n\nTo the south and east, in the Flood Plains, live creatures called gorlocs. They prepare their foods with noxious spices, which would sicken any other creature. If you can gather enough of the spice pouches from gorloc steam belchers or gorloc waddlers, I can make the wolf bait.", objectives = "Iggy \"Tailspin\" Cogtoggle in the Scalding Pools wants you to gather 4 Gorloc Spice Pouches.", progress = "Do you have those spice pouches?", completion = "<Iggy holds his nose as he empties the spice pouches and addresses you in a nasal voice.>\n\nNow that we have what we need, I'll combine it with my emergency rations to create a bait for the wolves." }
WordHunterWoW_QuestEN[11727] = { title = "A Time for Heroes", description = "It's good to have you among us, {name}.  We've all heard of your past deeds.\n\nAs you know, King Wrynn is moving great armies into Northrend to meet those of Arthas.  But armies are nothing without true heroes to inspire and lead them.\n\nI want you to be that hero for my men.  Fight alongside them against the Scourge that lays siege to our stronghold.\n\nReport to Sergeant Hammerhill outside the inner hold.  Valiance Keep cannot fall.  The future of our campaign depends on it.", objectives = "Report to Sergeant Hammerhill at Valiance Keep.", completion = "By Magni's beard!  Looks like the heavy artillery's arriving." }
WordHunterWoW_QuestEN[11728] = { title = "Lupus Pupus", description = "Whatever you do, don't eat this bait yourself. Just set it down in the vicinity of an oil-soaked wolf. If they're desperate enough to eat the microfilm, they'll come running when they smell the bait.\n\nSimply wait for nature to take its course and then all you need to do is search the, uh... byproduct for the film.\n\nI'd offer you my special lupus pupus scupus for the job, but I left it back at the airstrip. I'm afraid you'll have to conduct the... err... search the old-fashioned way.", objectives = "Iggy \"Tailspin\" Cogtoggle in the Scalding Pools wants you to bring him 8 pieces of Microfilm.", progress = "Have you recovered the microfilm?", completion = "<Iggy holds his nose as he accepts the microfilm from you.>\n\nYuck, well, we've complied with section 8.2, paragraph B of the emergency protocol here and recovered the film. Nothing in the protocol says I'm responsible for cleaning it, though." }
WordHunterWoW_QuestEN[11729] = { title = "The Ultrasonic Screwdriver", description = "The unit you just dismantled had this inside of its mechanical innards.\n\nIt looks pretty complicated... certainly someone back at the airstrip would want to take a look at it. Maybe Crafty Wobblesprocket?", objectives = "Deliver the Ultrasonic Screwdriver to Crafty Wobblesprocket at Fizzcrank Airstrip.", progress = "Hey!", completion = "My screwdriver... you found my screwdriver! I'd been wondering where that thing got lost.\n\nHmm, you found it inside one of their robots, you say? That gives me an idea...." }
WordHunterWoW_QuestEN[11730] = { title = "Master and Servant", description = "The Ultrasonic Screwdriver is the ultimate tool. It can do anything to mechanical stuff!\n\nHead back into the pools and dismantle a number of Mechazod's robots. Then all you have to do is use the screwdriver on their remains, and I'm betting that they'll turn to our side, for a short time anyway.\n\nI'm pretty sure it won't work on the mechagnomes, so don't even bother with them.\n\nOh, and if you want to take anything from the robot's insides, you'll want to do so before using the screwdriver!", objectives = "Use the Ultrasonic Screwdriver to reprogram 15 robots and then return to Crafty Wobblesprocket at Fizzcrank Airstrip.\n\nMake sure to loot the dead robot before you reprogram it.", completion = "Woo hoo! And you brought back the screwdriver intact, too!\n\nReprogramming those robots is going to turn out to be a huge advantage in our favor in the fight against Gearmaster Mechazod. I think you've earned a little something for that." }
WordHunterWoW_QuestEN[11731] = { title = "Torch Tossing", description = "So you want to be a fire juggler?  Do you have what it takes?  The dexterity?  The reflexes?  ...the courage?  If you think so, then let's give you a little practice!\n\nTake these torches and run near the bonfire.  You'll see  braziers with markers flashing above them.  Toss a torch at a marked brazier.  Be quick! Do it before the mark fades if you want credit for the toss!\n\nHit enough marked braziers before the time limit, then come back here... for your next lesson.", objectives = "Win the torch tossing game, then speak with the Master Fire Eater.", progress = "Quick!  There's no time to waste!", completion = "Well done!  You'll be a fire juggler faster than the fuse on a ground flower!  Now gird yourself!  The next test is when things really heat up..." }
WordHunterWoW_QuestEN[11732] = { title = "Desecrate this Fire!", description = "", objectives = "Desecrate the Horde's Arathi Highlands bonfire!", progress = "Desecrate the Horde's Arathi Highlands bonfire!", completion = "Desecrate the Alliance's Arathi Highlands bonfire!" }
WordHunterWoW_QuestEN[11733] = { title = "Traversing the Rift", description = "I've been mindful of your efforts, mortal. Do not feign surprise. Surely you've felt my eye upon you.\n\nThe time has come to peel back a layer of darkness from your mind. There are stark truths that you have grown ready to accept.\n\nBefore hearing the tale, you shall be shown firsthand what we face.\n\nPut your affairs in order, {class}....", objectives = "Surristrasz wants you to travel to Coldarra. Once there, you are to speak with Archmage Berinand.", completion = "Welcome to Coldarra, <class>.\n\nUnder the Transitus Shield we lie hidden just a stone's throw from the Nexus, fortress of the great aspect Malygos and his blue dragonflight.\n\nDo make yourself comfortable." }
