WordHunterWoW_QuestEN[11863] = { title = "Honor the Flame", description = "", objectives = "Honor the Zangarmarsh flame.You will receive:" }
WordHunterWoW_QuestEN[11864] = { title = "A Mission Statement", description = "", objectives = "The demon has many names and each name has held special meaning at one time or another. While the details were sometimes insignificant, the end result was always the same: death.\n\nBut it is now, nearly fifty years after it all began, that the details will find the devil and lead to his downfall.\n\nThis time, we have him... There will be no escape for Nesingwary.\n\nNorthrend will be the battleground for our war. The hunter will become the hunted!" }
WordHunterWoW_QuestEN[11865] = { title = "Unfit for Death", description = "Just south of us the caribou used to roam freely, peacefully. Then Nesingwary showed up and everything changed. Now the caribou are in a perpetual state of frenzy, always in a panic. They are stalked by the hunters and trappers hidden in the field.\n\nNesingwary's executioners are unfit for death. They must feel the torture that they put the caribou through!\n\nTake this pile of fake furs and lay it upon their caribou traps to the south. Watch as the hunters are caught in their own deadly traps!", objectives = "Zaza at the D.E.H.T.A. Encampment in the Borean Tundra wants you to use the Pile of Fake Furs to trap 8 Nesingwary Trappers.", completion = "You do the Earth Mother's work, <name>, but do not revel in this victory for too long. We have discovered the hiding place of the trapper leader." }
WordHunterWoW_QuestEN[11866] = { title = "Ears of Our Enemies", description = "Whether they be treasure seekers or bloodthirsty hunters of the wastes, any being that supports Nesingwary and dares to strike at our beloved wildlife shall be considered an enemy of D.E.H.T.A.\n\nShould you slay these filthy Nesingwary sympathizers, bring me proof of their demise and you shall be rewarded with a blessing from the druids of D.E.H.T.A.\n", objectives = "Arch Druid Lathorius at the D.E.H.T.A. Encampment in the Borean Tundra has said that he will reward you should you bring him 15 Nesingwary Lackey Ears.", progress = "Ears will do quite nicely...", completion = "These will hang around my neck. Let them hear our message and let these ears be the vessels that carry our truths!" }
WordHunterWoW_QuestEN[11867] = { title = "Can't Get Ear-nough...", description = "Whether they be treasure seekers or bloodthirsty hunters of the wastes, any being that supports Nesingwary and does dare strike at our beloved wildlife shall be considered an enemy of D.E.H.T.A. Should you slay these filthy Nesingwary sympathizers, bring me proof of their demise and you shall be rewarded with a blessing from the druids of D.E.H.T.A.", objectives = "Arch Druid Lathorius at the D.E.H.T.A. Outpost in the Borean Tundra has said that he will reward you should you bring him 15 Nesingwary Lackey Ears.", progress = "Whether they be treasure seekers or bloodthirsty hunters of the wastes, any being that supports Nesingwary and dares to strike at our beloved wildlife shall be considered an enemy of D.E.H.T.A.\n\nShould you slay these filthy Nesingwary sympathizers, bring me proof of their demise and you shall be rewarded with a blessing from the druids of D.E.H.T.A.", completion = "These will hang around my neck. Let them hear our message and let these ears be the vessels that carry our truths!" }
WordHunterWoW_QuestEN[11868] = { title = "The Culler Cometh", description = "Near the southern end of this bluff is where you will find the treacherous leader of the caribou trappers. She is a savage like no other, making a mockery out of the carcasses of the slain animals: drinking from their blood and howling to the moons!\n\nFind this murderer, Karen, and end her worthless existence.\n\nPrepare yourself properly, {name}. Karen the Culler has indulged in the riches that Nesingwary has lavished upon her!", objectives = "Zaza at the D.E.H.T.A. Encampment in the Borean Tundra wants you to kill Karen the Culler.", completion = "Perhaps her death will serve as an example to others that dare slay animals for sport and riches." }
WordHunterWoW_QuestEN[11869] = { title = "Happy as a Clam", description = "To the west of us you will find Lake Kum'uya. It is, as far as we know, the only freshwater giant clam habitat in the world.\n\nOf course Nesingwary's lackeys are now using the lake as a giant pearl farm. They must be stopped! A lesson must be taught to those that would think to endanger an entire species.\n\nGo to Lake Kum'uya and locate the loot crazed divers. Slay them until the water runs red! Return to me when a proper example has been made!", objectives = "Hierophant Cenius at the D.E.H.T.A. Encampment in the Borean Tundra wants you to kill 10 Loot Crazed Divers.", progress = "It is gruesome work that we do, <name>.", completion = "Now let us see how their nerve holds up when they see what became of their companions!" }
WordHunterWoW_QuestEN[11870] = { title = "The Abandoned Reach", description = "We have just gotten word from Liandra that mercenaries hired by Nesingwary are moving goods off the beach and onto the main Nesingwary shipping vessel. No doubt they plan on making a fortune from their murderous trade!\n\nShe has asked that we send assistance to the Abandoned Reach, directly south of here on the beachfront of the Borean Tundra.\n\nMake haste, Liandra awaits you there!\n", objectives = "Seek out Hierophant Liandra at the Abandoned Reach.", completion = "Cenius sent you? Well you're not a moment too soon!" }
WordHunterWoW_QuestEN[11871] = { title = "Not On Our Watch", description = "Strewn across this beach, amidst the flotsam and jetsam, are crates and sacks of animal parts. It would seem that Nesingwary is in cahoots with the Northsea Freebooters. Those dirty pirates are transporting the goods that Nesingwary's murderous lackeys gather offshore. No doubt they will end up in the homes and on the backs of wealthy, unscrupulous individuals across Azeroth.\n\nThis won't happen. Not on our watch. Bring me all shipments that you find upon this beach. They'll never have them!", objectives = "Hierophant Liandra at the Abandoned Reach in the Borean Tundra wants you to recover 12 Shipments of Animal Parts.", progress = "We will give those animals a proper burial.", completion = "A job well done, <name>. Now we strike at the pirate leader!" }
WordHunterWoW_QuestEN[11872] = { title = "The Nefarious Clam Master...", description = "It's despicable, really, to anoint one's self as the \"Clam Master,\" as if they hold mastery over the creatures of the sea. None may make such claims!\n\nThis \"Clam Master\" must be found and slain. He was last seen at the wreckage just off the coast of the Abandoned Reach. Find him and kill him.\n\nOnce this is done, return to Hierophant Cenius at the D.E.H.T.A. Encampment, north of here, and let her know that the mission was a success.", objectives = "Slay Clam Master K and return to Hierophant Cenius at the D.E.H.T.A. Encampment.", completion = "Excellent work, <name>. We are closing in on Nesingwary!" }
WordHunterWoW_QuestEN[11873] = { title = "Give Fizzcrank the News", description = "Would you be willing to head back to the airstrip and let Fizzcrank know that I'll be along shortly to give my formal report? I've got to deal with the wreckage of my flying machine, and then I'll be on my way.\n\nI'll be certain that Fizzcrank knows that he has you to thank for my survival and the recovery effort.\n\nI only wonder what the old man would've done himself if he'd been flying with us. I miss those days.", objectives = "Make your way back to Fizzcrank Airstrip and speak with Fizzcrank Fullthrottle.", completion = "<Fizzcrank listens to your report, looking somewhat relieved.>\n\nI should've gone with them. We might've been able to complete the mission without losing any pilots.\n\nTailspin is right, though, we have you to thank for what you've been able to salvage. Your efforts may just make the difference in the fight against the Nerubians." }
WordHunterWoW_QuestEN[11874] = { title = "Upper Deck Promo - Rocket Mount", description = "", objectives = "" }
WordHunterWoW_QuestEN[11875] = { title = "Gaining the Advantage", description = "The troops of the Shattered Sun Offensive will need every advantage they can get to beat back the allies of Kil'Jaeden. My colleagues in Stormwind have created oils which will strengthen the blades and armor of our troops.\n\nThe key ingredient, nether residue, pervades Outland  -- if you know where to look. Any master herbalist, skinner, or miner who knows the signs can gather it while plying his trade. Those herbs, ores, and beasts native to Outland may all bear the residue.", objectives = "Bring 8 Nether Residue to Emissary Mordin in Shattrath City.", progress = "Have you any residue for me?", completion = "Thank you for your help, <name>. No contribution to the war effort is too small. Our men are going to need every advantage they can get in this battle." }
WordHunterWoW_QuestEN[11876] = { title = "Help Those That Cannot Help Themselves", description = "They're majestic beasts, aren't they?\n\n<Lathorius points towards the mammoths of the northern tundra.>\n\nWith each passing day their numbers diminish. Demons that call themselves hunters slay the beasts for sport and riches.\n\n<Lathorius' face contorts with anger.>\n\nIt's the whimpers that drive me to madness, {name}. You can hear them, carried by the wind. The mammoth calves, trapped in the hunters' vile traps, call out to us.\n\nTake this hammer and smash those traps. Free the calves!", objectives = "Arch Druid Lathorius at the D.E.H.T.A. Encampment in the Borean Tundra wants you to use the D.E.H.T.A. Trap Smasher to free 8 Mammoth Calves.", completion = "<Arch Druid Lathorius wipes away his tears.>\n\nThey never stood a chance. Now orphaned, they will surely die on their own." }
WordHunterWoW_QuestEN[11877] = { title = "Sunfury Attack Plans", description = "As we press the offensive on Quel'Danas, we've discovered that Kael'thas' minions are planning a counterattack. By ordering the Sunfury blood elves, based in Netherstorm, to attack our operations in Outland, he hopes to draw troops and attention away from the Sunwell.\n\nWe must not allow this to happen, {name}. Each and every blade is needed on the front lines.\n\nGo to Netherstorm and capture their attack plans. Any of the Sunfury blood elves up there could be in possession of the plans. Good luck, {name}.", objectives = "Lord Torvos in Shattrath wants you to capture the Sunfury Attack Plans.", progress = "Have you returned with the plans?", completion = "<Lord Torvos accepts the plans and looks over them.>\n\nYou've done the offensive a great service, <name>, but we should not rest. I wouldn't put it beyond our foes to plan more mischief in the future." }
WordHunterWoW_QuestEN[11878] = { title = "Khu'nok Will Know", description = "Although you have acted valiantly in freeing the trapped calves, many of them will still die. You see, without a caretaker, these calves must fend for themselves in the wild.\n\nBut there is a way! Hope yet remains!\n\nNorth of here in the mammoth fields, bordering the Scalding Pools, you will find Khu'nok the Behemoth: a mammoth as wise as he is ancient. Take this mammoth orphan and present it to Khu'nok. He will know what to do.", objectives = "Take the Orphaned Mammoth Calf to Khu'nok the Behemoth in the Borean Tundra.", completion = "<You hear a voice in your head. It is Khu'nok.>\n\nYour name has been heard in the whistling winds, <name>. You have done a great thing for my kin. For this we will consider you an ally. Alas, our torment cannot end without bloodshed and violence.\n\nThe price of peace for the mammoths will be the death of Kaw..." }
WordHunterWoW_QuestEN[11879] = { title = "Kaw the Mammoth Destroyer", description = "You cannot defeat the being responsible for the slaughter of my kind by yourself. The mammoths of the tundra will help you!\n\nVenture forth to the plains and find a mammoth bull. He will allow you to mount him and control his movements and actions. Ride upon his back and find Kaw, north of here at Kaw's Roost. Together, you will be the instrument of Kaw's demise.\n\nDestroy Kaw's armies and take from Kaw his coveted war halberd. Return to Lathorius at the D.E.H.T.A. Encampment should you succeed.", objectives = "Kill Kaw the Mammoth Destroyer and recover Kaw's War Halberd. Deliver Kaw's War Halberd to Arch Druid Lathorius at the D.E.H.T.A. Encampment in the Borean Tundra.", progress = "What happened?", completion = "<Lathorius takes the halberd from you.>\n\nIs this what I think it is?\n\n<Lathorius grins.>\n\nSmashing! Outstanding! Another of Nesingwary's lackeys brought to justice!" }
WordHunterWoW_QuestEN[11880] = { title = "The Multiphase Survey", description = "I'm sure that 'gnomish inventor' is a crackpot. He was babbling about some dark distortions that have begun to appear in the Spirit Fields around Oshu'gun in Nagrand.\n\nAccording to him, these, uh, multiphase... um, spectro-goggles will allow the wearer to see the distortions and take readings from them. He insisted that recording this data was fundamental to our campaign at the Sunwell. I think he's nuts, but I'm under orders to investigate anything that might help. Would you mind taking some readings?", objectives = "Harbinger Haronem in Shattrath City wants you to use the Multiphase Spectrographic Goggles to take 6 Multiphase Readings.", progress = "Did you get those readings? That gnome will scream at me again if I don't get his precious data.", completion = "Thanks for your help. You don't know what it's like to have to deal with \"Doctor\" Wafflefry over there. In between his \"checkups\" on my progress, he's busy hawking some gadget or another derived from his military inventions." }
WordHunterWoW_QuestEN[11881] = { title = "Load'er Up!", description = "Have you seen the flying machines buzzing around? That's gnomish innovation at its finest.\n\nI've long waited to get my hands on some of their technology and a perfect opportunity has presented itself. One of their recon wings crashed in the Scalding Pools, in the southwest part of the Geyser Fields.\n\nBlow this whistle near one of the crashed machines and my trusty mule, Jenny will answer. She'll follow you and carry the salvage, but you must keep her safe. She'll begin to drop the cargo if attacked.", objectives = "Help Jenny make her way from the crash site to Fezzix Geartwist at Taunka'le Village without losing all her cargo.", progress = "Don't fail! I'm counting on you.", completion = "<Fezzix looks over the salvage.>\n\nJenny's a little roughed up, but she'll be fine. As for the salvage, it's a bit more... piecemeal than I had hoped, but I should be able to find a use for it. You're not off the hook yet, though. We're going to rebuild this baby." }
WordHunterWoW_QuestEN[11882] = { title = "Playing with Fire", description = "Are you interested in learning some hot new skills?\n\nI don't know if you'll ever be able to match my own considerable skill, but you can probably pick up a trick or two if you're an attentive student. Speak to a Master Fire Eater at any Alliance capital. They should be able to help you.", objectives = "Speak to a Master Fire Eater in any Alliance capital.", completion = "Well met. You've come to learn some new ways to handle fire?" }
WordHunterWoW_QuestEN[11883] = { title = "Fire Dancing?", description = "You wish the learn the art of fire dancing?\n\nWell, then. Speak to a Master Fire Dancer at any Horde capital. They should be able to help you.\n", objectives = "Speak to a Master Fire Dancer in any Horde capital.You wish the learn the art of fire dancing?\n\nWell, then. Speak to a Master Fire Dancer at any Horde capital. They should be able to help you.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[11884] = { title = "Nedar, Lord of Rhinos...", description = "West of here, on the high bluffs above Lake Kum'uya, roams a despicable being known as Nedar. The self proclaimed \"Lord of Rhinos\" hunts the wastes for the injured or young - rhinos unable to defend themselves against his cowardly attacks. To add insult to injury, Nedar has raised a rhino of his own to become his mount and bodyguard.\n\nIt is a rare thing that D.E.H.T.A. would ever call for the death of an animal, but Nedar's tainted rhino must be disposed of... Kill them both and return to me. ", objectives = "Killinger the Den Watcher at the D.E.H.T.A. Encampment in the Borean Tundra wants you to kill Nedar, Lord of Rhinos and his companion, \"Lunchbox.\"", completion = "At least for now the rhinos will know peace. Thank you, <name>." }
WordHunterWoW_QuestEN[11885] = { title = "Adversarial Blood", description = "The descendants held prisoner by the Skettis talonpriests are listed in this book: Gezzarak the Huntress, Karrog the crystal giant, the heretic known as Darkscreecher Akkarai and Vakkiz the Windrager.  They will all need to be slain before Terokk returns to this world.\n\nYou will need the scrolls carried by the time-lost arakkoa to call them forth at the summoning circles in Skettis.  These are powerful beings you will be facing; you would do well to bring friends.", objectives = "Find the Skull Piles in the middle of the summoning circles of Skettis. Summon and defeat each of the descendants by using 10 Time-Lost Scrolls at the Skull Pile. Return to Hazzik at Blackwind Landing.", progress = "Have you completed your task, <name>?", completion = "Excellent!  Take this.  I've prepared this bundle with items symbolizing the foes you've defeated.  They will allow you to summon Terokk.\n\nBeware, <name>.  He is the most powerful arakkoa to ever exist.  Do not underestimate him!" }
WordHunterWoW_QuestEN[11886] = { title = "Unusual Activity", description = "While celebration has its place, {class}, some of us must look to graver matters.\n\nWhen the festival began, we received reports from Zoram Strand about a sharp increase in Twilight Cult activity. The origins of this holiday are steeped in the very powers those madmen revere; this cannot be coincidence. Go to the camp just south of the Blackfathom Deeps entrance, in the ruins, and see if the cultists will part with information - forcefully if need be. Use this beacon to summon a guide when you find it.", objectives = "Go to the new Twilight Camp south of the Blackfathom Deeps entrance on the Zoram Strand of Ashenvale and retrieve Twilight Correspondence from the cultists, then call upon the Earthen Ring Guide using the Totemic Beacon.", progress = "What have you uncovered?", completion = "This is worrisome, friend. It hints at a much larger plot beyond simple agitation of the local fire and water elements, and something here bears investigation..." }
WordHunterWoW_QuestEN[11887] = { title = "Emergency Supplies", description = "Rifling through the dead gnome's possessions, you come across a small packet filled with rations, tools, and a handy roll of gnomish duct tape. The contents of these kits might prove helpful to Fezzix Geartwist when it comes time for him to reassemble the wreckage of the gnomish flying machines.\n\nBringing a few of these kits to Fezzix might just be worth a nice bonus.", objectives = "Collect 7 Gnomish Emergency Toolkits from the bodies of crashed Fizzcrank Recon Pilots and bring them to Fezzix Geartwist at Taunka'le Village.", progress = "What is it you have there?", completion = "Gnomish tools? For me? These should make rebuilding that flying machine even easier than I expected." }
WordHunterWoW_QuestEN[11888] = { title = "Ride to Taunka'le Village", description = "{race}, the chieftain is making me wait... time that Taunka'le does not have!\n\nThere has been talk of your prowess. Rather than wait for Garrosh to send help, I ask you to go and help my people.\n\nTaunka'le village lies far to the northeast. Follow the road east out of the hold, turning north at the intersection. Not long after, you will come to another intersection. Follow the path east, passing south and then east of the great pools along the flood plains.\n\nSpeak with Sage Earth and Sky when you arrive.", objectives = "Speak with Sage Earth and Sky at Taunka'le Village.", completion = "It does not surprise me that the orc chieftain does not have time to hear of our troubles. The ambassador's efforts will likely be like so much mist blowing in the wind.\n\nBut you are here now. We shall see if he chose well in sending you." }
WordHunterWoW_QuestEN[11889] = { title = "Death From Above", description = "We're doing a good job of holding the front lines against these bugs.  Some of these cheeky fiends, however, can fly over the aforementioned front lines and are really beating down on our inner defenses.\n\nI've requisitioned reinforced fishing nets from our civilian ships.  If you've got a good enough throwing arm, they'll help you knock the enemy out of the sky.  Thin their numbers so that our defenses can hold the keep.", objectives = "Sergeant Hammerhill wants you to use the Reinforced Net to help you slay 6 Scourged Flamespitters outside of Valiance Keep.", completion = "We'll beat them if they come by land and we'll beat them if they come by air.  If these motherless undead come by sea we're going to give them the beating of their lives." }
WordHunterWoW_QuestEN[11890] = { title = "What Are They Up To?", description = "The gnomes have run into some trouble in the pools to the west. It serves them right as they have been fouling up the land with their so-called inventions.\n\nI want you to go out to their pumping station and observe what has befallen them. Return to me after.", objectives = "Investigate the area surrounding the Fizzcrank Pumping Station. Then, return to Sage Earth and Sky at Taunka'le Village.", progress = "What did you find out, <race>?", completion = "Troubling news indeed.\n\nMy people are leaving this place soon. We are going to break through the Scourge lines to get to our capital, Icemist, in the Dragonblight.\n\nBut, before we do that, we must deal with what the gnomes in their insanity have wrought." }
WordHunterWoW_QuestEN[11891] = { title = "An Innocent Disguise", description = "According to this, it seems there is another encampment of the cultists to the northwest of the large gathering on the Zoram Strand, and they are speaking with... guests?\n\nMuch could be learned from listening to these proceedings, {race}. Take this orb; it will allow you to appear as one of the native crawlers on the beach. Spy on the conversation with these \"guests\" of the cultists at the northwestern camp and report back to me when you are successful.", objectives = "Use the Orb of the Crawler to spy upon the new Twilight camp to the west of the Blackfathom Deeps entrance on the Zoram Strand in Ashenvale, then summon the Earthen Ring Guide using the Totemic Beacon.", progress = "Have you learned their secrets?", completion = "They seek to summon a frost lord into our world? No! They cannot tip the balance!" }
WordHunterWoW_QuestEN[11892] = { title = "The Assassination of Harold Lane", description = "You have done much for the animals of the Borean Tundra, {name}. Nesingwary's lackeys have been beaten back and taught a lesson that they will not soon forget.\n\nHarold Lane, the primary agent responsible for the mass slaughters in Nagrand, has been identified as the man in charge of Nesingwary operations in the tundra. He is stationed at Lake Kum'uya, west of here.\n\n<Lathorius hands you an intricately carved oak horn.>\n\nFind Lane and kill him. Use this horn should you require our aid.\n", objectives = "Arch Druid Lathorius at the D.E.H.T.A. Encampment in the Borean Tundra wants you to kill Harold Lane.", completion = "Alas, Nesingwary is gone. Perhaps he was never here to begin with...\n\n<Lathorius sighs.>\n\nThe demon is a slippery one, but his days are numbered. We will find him and when we do..." }
WordHunterWoW_QuestEN[11893] = { title = "The Power of the Elements", description = "I kept trying to tell that silly goblin his machines are unreliable.\n\nBut the power of the elements; that is deep and abiding. When my apprenticeship is over, I will wield their full power. What I know now should be sufficient to help out our friend Fezzix, though.\n\nTake this windsoul totem and plant it near any of the steam ragers to the west of the village. The totem will gather up the energies of slain elementals. Return the fully charged totem to me and I'll do the rest.", objectives = "Dorain Frosthoof at Taunka'le Village wants you to use the Windsoul Totem to gather the energy of 10 Steam Ragers.", completion = "<Dorain nods.>\n\nGood. This should be sufficient to show Fezzix exactly what I've been trying to tell him." }
WordHunterWoW_QuestEN[11894] = { title = "Patching Up", description = "Remember all that gnomish duct tape you brought me?\n\nWell, I've found a use for it. The body of this flying machine is so banged up in places, that I'm going to need to reinforce it if I ever hope to fly.\n\nDorain over there has been telling me that the taunka use steam cured caribou leather for making watertight containers. Marsh caribou live all around the village and in the Flood Plains to the south. Get the best hides you can find and cure them over the steam vents in the Geyser Fields.", objectives = "Fezzix Geartwist at Taunka'le Village wants you to bring him 5 Steam Cured Hides.", progress = "Did you get that cured caribou hide for me?", completion = "Fantastic! A few more tweaks and I'll be an airborne goblin!" }
WordHunterWoW_QuestEN[11895] = { title = "Master the Storm", description = "From what you describe, the creatures of metal should be easy to deal with. But first, you must master the storm.\n\nBehind me in the lodge is a totem. When you are ready, focus your will upon it and the storm will come. You must defeat the storm and in so doing take its essence into yourself.\n\nIf others are there, it is enough that you all work together to defeat it. Return to me after, {class}.", objectives = "Defeat the Storm Tempest and then return to Sage Earth and Sky at Taunka'le Village.", progress = "Have you mastered the storm yet?", completion = "I feel the power of the storm coursing through you!\n\nYou are ready, <name>. Let us begin." }
WordHunterWoW_QuestEN[11896] = { title = "Weakness to Lightning", description = "You now have the power of the storm within you. I will give you the means to focus that power and weaken the robots in the pools.\n\nTake this lightning rod. Use it against the robotic creations of the mechagnomes you find within the greater pools area to the west. Do not worry about using it against the mechagnomes themselves; Greatmother Taiga has other plans for them.\n\nOnce the robots are weakened by the power of the storm, dismantle them utterly!", objectives = "While weakened by the Power of the Storm, destroy any 15 of the robotic units, except the mechagnomes, in the greater pools area surrounding the Fizzcrank Pumping Station.\n\nAfterward, return to Sage Earth and Sky at Taunka'le Village.", completion = "With their robotic minions dealt with, it is time for us to move on to bigger prey. Unfortunately, even now I feel the power of the storm waning from within you.\n\nNevertheless, it served its purpose, and I think that you're more than capable of taking the next step without it." }
WordHunterWoW_QuestEN[11897] = { title = "Plug the Sinkholes", description = "The Scourge are showing no sign of letting up, {name}.  It's those blasted sinkholes; they connect to tunnels all the way to Icecrown for all we know.  Giant undead worms burrow under the ground to create them.\n\nIf there's something years of mining has taught me it's that without support beams, tunnels will cave in easily after an explosion.\n\nTake these explosives and place them at the entrance to the sinkholes up on the ridge beyond the beach to the west.  Come back after you've collapsed them.", objectives = "Sergeant Hammerhill wants you to use the Incendiary Explosives to collapse the sinkholes southwest and northwest of Valiance Keep.", progress = "Did you succeed, <name>?  We need to slow down the Scourge or Valiance Keep will be overrun.", completion = "Excellent work, <name>.  Without you, Valiance Keep might've not held against the attackers.  Thanks to your help we'll live to fight another day." }
WordHunterWoW_QuestEN[11898] = { title = "Breaking Through", description = "On the lowest tier of the Temple City, there is a gray altar bathed in light. Step into it to gain entry to the dread necropolis Naxxanar.\n\nBe cautious, {name}. Prince Valanar will certainly be defended by his personal retainers, who will give their lives to keep you from ascending to the top level of the necropolis.\n\nYou must find your way through the necropolis to the prince's seat. If you fail to defeat him, {name}, I fear my people will never know the safety Icemist offers.", objectives = "Defeat Prince Valanar and his lieutenants, Vanthryn the Merciless and Luthion the Vile, then report to Chieftain Wintergale at Taunka'le Village.", completion = "With the prince defeated, the Scourge presence in Borean Tundra is broken. I have no illusions that they will stay away for long, which is why I must focus on preparing Durm to lead the villagers on their way to Icemist.\n\n<The chieftain shakes his head slowly.>\n\nFor all the disagreements I've had with Durm, I trust his judgment and his abilities. I cannot bring myself to abandon Taunka'le, so I will defend it until I am slain." }
WordHunterWoW_QuestEN[11899] = { title = "Souls of the Decursed", description = "The mechagnomes in the pools to the west are a great mystery to us. They appeared not long after the gnomes disappeared from their pumping station and its environs.\n\nThey are an unnatural danger and must be dealt with.\n\nTake this soulcatcher and use it on the remains of the mechagnomes to capture their souls. When you return, we will set them free so that we might find out what happened.", objectives = "Use The Greatmother's Soulcatcher to capture the souls of 10 Fizzcrank mechagnomes. Then, return to Greatmother Taiga at Taunka'le Village once you have done so.", completion = "Now we must free the souls that you have captured." }
WordHunterWoW_QuestEN[11900] = { title = "Reading the Meters", description = "I had hoped that the Nexus' impact was limited to this region. Recently though, reports have flooded in from all over Azeroth suggesting that geologic instability is growing exponentially!\n\nI need the Nexus monitored regularly as I work to develop a solution.\n\nI've placed sensitive instruments around Coldarra, disguised as Malygos' scrying orbs. One lies in the trench near the Nexus, and three are hidden in the structures around the valley's perimeter. Visit each and return to me with their readings.", objectives = "Archmage Berinand at the Transitus Shield has asked you to collect the readings from his instruments in Coldarra.", completion = "This is worse than I expected.\n\nMalygos is channeling too much power to this place. If he's not stopped, Azeroth will be the next Outlands!\n\nFortunately, I believe that I've engineered a temporary solution...." }
WordHunterWoW_QuestEN[11901] = { title = "Military?  What Military?", description = "There's Scourge everywhere, {class}.  We've organized the farmers and miners into a militia, but this just won't cut it.\n\nThe one detachment of troops that Valiance Keep sent is defending the mine.  We haven't heard from them in days!\n\nIf you really wish to help us, why don't you go to the mine and see what's going on?  Maybe we can get them to send us some reinforcements.", objectives = "Gerald Green in Farshire wants you to go into the mine to the north and find out what happened to the military detachment that was sent there.", completion = "Your stomach feels uneasy as you approach the grain.  The smell is nearly unbearable." }
WordHunterWoW_QuestEN[11902] = { title = "Pernicious Evidence", description = "The sacks of grain emanate the foul stench you've come to associate with the Plague.  This probably explains what happened to the footmen defending the mine.\n\nYou'd best bring word back to Gerald Green.", objectives = "Return to Gerald Green in Farshire.", completion = "Those poor lads... they never had a chance!\n\nThis sure sounds like an inside job.  Probably a Cult of the Damned infiltrator.  Curse those madmen!" }
WordHunterWoW_QuestEN[11903] = { title = "It's Time for Action", description = "Well, {name}.  With the last of our military in Farshire dead or worse, we can do but one thing: fight these Scourge ourselves.\n\nWe have deployed militia in what remains of Farshire.  Without your help, they've but little hope of winning.  Go and lend them a hand.  Me and the lads will watch this path.  We can't let the Scourge break through!", objectives = "Gerald Green in Farshire wants you to kill 14 Plagued Scavengers.", progress = "You giving those ghouls a good beating, I hope?", completion = "You've communicated with the Scourge in the only language they understand: violence and death.  Unfortunately they just keep coming!" }
WordHunterWoW_QuestEN[11904] = { title = "Fruits of Our Labor", description = "The Scourge just keeps coming... but we can't give up!  Listen, {name}.  Inside that mine there's a cart with the last of the ore the Alliance is going to see on this side of the continent for a long time.\n\nThe problem is the cart release is locked.  When the military went in there, Captain Jacobs commandeered all the important equipment, including the cart release key.\n\nThe plague that affected the soldiers in the mine must also have affected Jacobs.  Get the key from him and salvage the ore.", objectives = "Go to the mine in Farshire, obtain the Cart Release Key from Captain Jacobs and use it to release the ore cart. Return to Gerald Green in Farshire when you've completed this task.", progress = "The ore, <name>, is it safe?", completion = "I thank you, <name>.  This ore will be of vital importance to the Alliance in the times to come.  I'd like to think we've made a difference today." }
WordHunterWoW_QuestEN[11905] = { title = "Postponing the Inevitable", description = "Azeroth's ley lines are being redirected to the Nexus.\n\nThe influx of arcane energies is tearing a rift between dimensions.\n\nI cannot stop it, but I've discovered a way to slow it down.\n\nTake this and activate it near the forming rift.", objectives = "Image of Warmage Kaitlyn in the Nexus wants you to use the Interdimensional Refabricator near the rift.", progress = "Have you been to the rift?", completion = "Excellent work, <name>. The tremors have already begun to subside.\n\nWith any luck, your efforts have granted us sufficient time to find a way to thwart Malygos' efforts." }
WordHunterWoW_QuestEN[11906] = { title = "Cleaning Up the Pools", description = "<A single tear rolls down the face of Iron Eyes.>\n\nI have heard that you are heading back into the pools to the west. I have something for you to do while you are out there, {race}.\n\nThe gnomes, who care nothing for the land, have polluted it with their machinery. I want you to pick up any spare parts that you come across.\n\nReturn them to me here. I will see to it that they are properly disposed of before we leave this place for good.", objectives = "Collect 15 Fizzcrank Spare Parts and deliver them to Iron Eyes at Taunka'le Village.", progress = "If we do not take care of the land, she will not suffer us to live for long.", completion = "It is the taunka way to leave the land pristine before we move on.\n\nWe will be traveling to our capital, Icemist, very soon. You have helped by allowing us to depart that much more quickly.\n\nThank you." }
WordHunterWoW_QuestEN[11907] = { title = "The Sub-Chieftains", description = "It is known that Gearmaster Mechazod has four sub-chieftains that manage the robots in the pools.\n\nWe must put an end to them!\n\nOur longrunners and snow trackers say that if you were to turn the valves at the west point, north point, mid point and south point stations, each of his sub-chieftains would come quickly to prevent you from fouling their operations.\n\nThe stations are centered on the spinning lights in the pools surrounding the pumping station.\n\nHurry, {name}!", objectives = "Defeat Twonky, ED-210, Max Blasto, and The Grinder, and then report back to Sage Earth and Sky at Taunka'le Village.", completion = "Thank you, <name>.\n\nWith these odd creatures destroyed, dealing with the rest of the pools should now be a simple matter.\n\nWe owe you a debt of gratitude." }
WordHunterWoW_QuestEN[11908] = { title = "Reference Material", description = "I was in charge of the harvest golems - an important job until the Scourge destroyed most of our farmlands.  I've an idea that would make the golems useful again, however.\n\nI think I can rewire the harvest collectors so they'll give us a hand fighting the Scourge.\n\nI'm not an expert at this just yet, so I'm going to need my manual.  The problem is, I left it at the workshop... which happens to be that burning building next to the mine.  Think you could go salvage it?", objectives = "Jeremiah Hawning wants you to retrieve the book \"Fields, Factories and Workshops\" from the burning building next to the mine in Farshire.", progress = "Did you get my book back?", completion = "Excellent!  The information I need should be in here." }
WordHunterWoW_QuestEN[11909] = { title = "Defeat the Gearmaster", description = "Clearly this Gearmaster Mechazod creature is not in his right mind. If his offer of a cure and immortality means all of us becoming robotic slaves then he must be stopped!\n\nThe winds that guide me whisper that he's atop the pumping station out in the middle of the pools to the west.\n\nMost likely, he'll be found in the command hut on top of the structure. Go inside and research his works.\n\n{name}, you must confront Mechazod if we are to survive!", objectives = "Research the Gearmaster's Manual and return Mechazod's Head to Greatmother Taiga at Taunka'le Village.", progress = "Is it over then? Has the threat of Gearmaster Mechazod been eliminated?", completion = "<The greatmother breathes a heavy sigh of relief.>\n\nIt is done then... you have saved us! If you hadn't stopped him here, then who knows how far this mistake of the gnomes would have spread?\n\nWith the threats from the blue dragons and the Nexus War, not to mention the Lich King, the last thing we need is a mad creation of the Titans running loose!\n\nThank you, <name>." }
WordHunterWoW_QuestEN[11910] = { title = "Secrets of the Ancients", description = "It's become clear that the instability in the region has had an effect on its indigenous creatures.\n\nI've taken a particular interest in the Glacial Ancients and their recent adaptations. I suspect that their transformation into these 'Magic-bound' Ancients may hold clues to our predicament here.\n\nFor my studies, I'll need samples from both. Do hurry....", objectives = "Archmage Berinand in the Transitus Shield wants you to collect 3 Glacial Splinters and 3 Magic-Bound Splinters from the Ancients in Coldarra.", progress = "Have you collected the samples I requested?", completion = "Yes, yes. These shall do nicely.\n\nThank you, <race>." }
WordHunterWoW_QuestEN[11911] = { title = "Quickening", description = "I've learned more in my short time here than in decades of studies.\n\nThe ancients here are being exposed to incredible levels of arcane energy. It's literally transforming them into something...\n\nI'm confident that there's a final stage in their metamorphosis. Find me some evidence of their final state.", objectives = "Image of Warmage Kaitlyn in the Nexus wants you to collect 5 Arcane Splinters from Crystalline Protectors.", progress = "The crystalline ancients... Do they exist?", completion = "Fascinating!\n\nAnd they're aggressive too, you say. That would suggest that some intelligence is behind this manipulation.\n\nIt may not be natural at all...." }
WordHunterWoW_QuestEN[11912] = { title = "Nuts for Berries", description = "Oh! What a relief it is to see a fresh face. I was beginning to feel we had been forsaken.\n\nOur supply lines were cut off days ago, and things have been looking - well, bleak. To be honest, this was a suicide mission to begin with if you ask me.\n\nMaybe I'm simply not cut out for all of this violence - to say nothing of the bitter cold! I'd much rather be back in Dalaran studying ancient texts.\n\nTo the point, our food supply is nearly spent. Please, gather what you can and bring it to me.", objectives = "Librarian Serrah in the Transitus Shield wants you to gather 10 Frostberries from the Frostberry Bushes in Coldarra.", progress = "Have you been able to find any food?", completion = "Well, it's not much, but it should keep us alive for another day.\n\nI believe you'll find this to be a fair price for your efforts." }
WordHunterWoW_QuestEN[11913] = { title = "Take No Chances", description = "I heard what you told Gerald and I don't like it one bit.  If cultists managed to poison the grain in the mines with their foul plague, they could've easily done the same with the grain outside.\n\nWe don't have time to sort the good grain from the bad.  We must act quickly and burn it all.\n\nTake this torch and set fire to any sacks of grain you find out here.  It would be a tragedy if we survived this attack only to succumb to the plague afterwards.", objectives = "Wendy Darren wants you to use Wendy's Torch to burn 8 sacks of Farshire Grain.", progress = "Have you done what I asked of you, <name>?", completion = "I thank you, <name>.  I would hate to see survivors of the attack on Farshire stumble upon plagued grain." }
WordHunterWoW_QuestEN[11914] = { title = "Keep the Secret Safe", description = "Our existence here depends entirely upon staying hidden. Should the shield fail, even for a moment, Malygos' minions would have us.\n\nOne of my responsibilities is to rejuvenate the warmages' mana levels so their focus doesn't falter. With our supply lines lost, I've been forced to improvise.\n\nI could use your help, {name}.\n\nVery near the Nexus, Arcane Serpents feast on the abundant magical energies. Once defeated, they will yield a mana essence that I can make use of.", objectives = "Librarian Serrah in the Transitus Shield needs you to kill Arcane Serpents near the Nexus and collect 5 Nexus Mana Essences from them.", progress = "Do you have the mana essences I asked for?", completion = "Your service to Dalaran will not go unnoticed, <race>.\n\nI hope you find this payment sufficient." }
WordHunterWoW_QuestEN[11915] = { title = "Playing with Fire", description = "Are you interested in learning some hot new skills?\n\nI don't know if you'll ever be able to match my own considerable skill, but you can probably pick up a trick or two if you're an attentive student. Speak to a Master Flame Eater at any Horde capital. They should be able to help you.", objectives = "Speak to a Master Flame Eater in any Horde capital.", completion = "Greetings. You've come to learn some new ways to handle fire?" }
WordHunterWoW_QuestEN[11916] = { title = "Hellscream's Champion", description = "You have faced all challenges that have been set before you and squashed them beneath your boot heel. It is because of you, {name}, that the Horde is now firmly entrenched in Northrend.\n\nBut our work has only just begun. We must march to Icecrown and we must tear down its walls!\n\nYour next assignment begins to the east, at Taunka'le Village. Our taunka allies are in dire straits and require aid. Secure transport from the stable master, Durkot Wolfbrother, and seek out Chieftain Wintergale at Taunka'le.", objectives = "Seek out Chieftain Wintergale at Taunka'le Village.", completion = "I fear that you may be too late, champion. Many of my brothers and sisters have already abandoned Taunka'le, seeking shelter in the Dragonblight, far to the east.\n\nThere is much work left to be done here and few willing to lend us their strength..." }
WordHunterWoW_QuestEN[11917] = { title = "Striking Back", description = "We must act to preserve the balance! Time is against us.\n\nReturn to the camp on the Zoram Strand with the large ice stones. They use them to communicate with the elementals, as they do in Silithus. Much as I am loath to do this, the spirits will understand - you must summon one of this Ahune's lieutenants and destroy it. Perhaps this forestalling action will be enough...", objectives = "Slay the Frostwave Lieutenant summoned from the Ice Stone located on Zoram Strand in Ashenvale, then return to the Earthen Ring Elder in a capital city.", completion = "You have done well. It may seem a small act, but even this can aid the fight as a whole. Take this with my blessing, and return later, as I may have more for you to do." }
WordHunterWoW_QuestEN[11918] = { title = "Basic Training", description = "This is war, mortal, and we are the tip of the spear.\n\nYour little spats over land or currency pale in comparison to this conflict. We face the aspect Malygos and his entire blue dragonflight. All you need to know is that if he is victorious, this world shall be no more.\n\nWe are but few here, and we fly against many. Our deaths are all but a certainty, and our ultimate success lies in merely delaying our enemy.\n\nGo now. Busy yourself while I decide what to do with you.", objectives = "Raelorasz at the Transitus Shield wants you to slay 10 Coldarra Spellweavers.", progress = "Have you acquainted yourself with our enemy, <class>?", completion = "Alright, <class>, now that you've become familiar with the enemy it's time for you to get to work." }
WordHunterWoW_QuestEN[11919] = { title = "Drake Hunt", description = "The blues have begun to cover their drakes in mysterious runes. I must discover their significance.\n\n<Raelorasz pokes his hand with a spear and coats the tip with his blood.>\n\nTake this and use it on one of them. Wait for it to become subdued, then bring it here to me before it expires.\n\nTheir hatchlings feed around the northwest edge of the valley.", objectives = "Raelorasz wants you to use Raelorasz's Spear to subdue a Nexus Drake Hatchling and return it to him at the Transitus Shield.", progress = "Have you managed to capture one of the Nexus Drakes?", completion = "The fate of these young drakes need not burden your conscience, <race>. Malygos alone is accountable for this.\n\nI am working ceaselessly to discover the secrets of these runes. We shall take no more lives than we must." }
WordHunterWoW_QuestEN[11920] = { title = "Cultists Among Us", description = "This altar bears all the markings of the Cult of the Damned.  It appears fanatics from the mainland have made it into Northrend.  It might be prudent to notify the captain of the ship.\n\nPerhaps he is to be found above deck.", objectives = "Speak to Captain \"Lefty\" Lugsail above the Stormbreaker in Valiance Keep.", completion = "Cultists?  Below deck?  I ought to have my whole crew flogged!\n\nListen... why don't we have Admiral Cantlebree take care of this... situation?" }
WordHunterWoW_QuestEN[11921] = { title = "More Torch Tossing", description = "Hello, fire juggler!  Are you having fun and making fiery mayhem?  That's what I like to hear!  Now, do you think you're an expert at torch tossing?  Then I have a test for you...\n\nYou know the rules: toss torches at the marked braziers.  This time, however, you have a little more time and a LOT more braziers to hit.\n\nReady?", objectives = "Win the torch tossing game, then speak with the Master Fire Eater.", completion = "Wow, you did it!  You are great!  Maybe next year you can apply for a job at the festival!" }
